	internal sealed class BufferManager : IBufferManager, IDisposable
	{
		private readonly VsCodeWorkspace workspace;

		private readonly IDictionary<string, DocumentId> transientDocuments = new ConcurrentDictionary<string, DocumentId>();

		private readonly Lazy<ConcurrentDictionary<Uri, SourceText>> temporaryDocumentStore = new Lazy<ConcurrentDictionary<Uri, SourceText>>(() => new ConcurrentDictionary<Uri, SourceText>());

		private readonly ConcurrentSet<DocumentId> transientDocumentIds = new ConcurrentSet<DocumentId>();

		private bool isDisposed;

		private ConcurrentDictionary<Uri, SourceText>? temporaryDocuments
		{
			get
			{
				if (!temporaryDocumentStore.IsValueCreated)
				{
					return null;
				}
				return temporaryDocumentStore.Value;
			}
		}

		internal bool ContainsTemporaryDocuments
		{
			get
			{
				if (!temporaryDocumentStore.IsValueCreated)
				{
					return false;
				}
				return !temporaryDocumentStore.Value.IsEmpty;
			}
		}

		internal BufferManager(VsCodeWorkspace workspace)
		{
			this.workspace = workspace;
		}

		public void RemoveTrackedDocumentOrDirectory(string uri, bool handleRad)
		{
			string filePath = uri.GetFilePath();
			CleanupTemporaryDocuments(filePath);
			if (transientDocuments.ContainsKey(filePath))
			{
				RemovedTrackedDocument(filePath, handleRad);
				return;
			}
			filePath += (filePath.EndsWith("/", StringComparison.Ordinal) ? string.Empty : "/");
			foreach (string key in transientDocuments.Keys)
			{
				if (key.StartsWith(filePath, StringComparison.Ordinal))
				{
					RemovedTrackedDocument(key, handleRad);
				}
			}
		}

		private void CleanupTemporaryDocuments(string filePath)
		{
			ConcurrentDictionary<Uri, SourceText>? concurrentDictionary = temporaryDocuments;
			if (concurrentDictionary == null || concurrentDictionary.IsEmpty || !Uri.TryCreate(filePath, UriKind.Absolute, out Uri result) || temporaryDocuments.TryRemove(result, out SourceText value))
			{
				return;
			}
			foreach (Uri key in temporaryDocuments.Keys)
			{
				if (result.IsBaseOf(key))
				{
					temporaryDocuments.TryRemove(key, out value);
				}
			}
		}

		public void RemovedTrackedDocument(string filePath, bool handleRad)
		{
			DocumentId documentId = workspace.GetDocumentId(filePath);
			if (documentId != null && transientDocumentIds.Contains(documentId))
			{
				transientDocumentIds.Remove(documentId);
				transientDocuments.Remove(filePath);
				workspace.RemoveDocument(documentId, handleRad);
			}
		}

		public bool TryApplyChangesToInMemoryFile(DidChangeTextDocumentRequest updateRequest, CancellationToken cancellationToken)
		{
			if (updateRequest == null || string.IsNullOrEmpty(updateRequest.TextDocument?.Uri))
			{
				return false;
			}
			if (Uri.TryCreate(updateRequest.TextDocument?.FileName ?? string.Empty, UriKind.Absolute, out Uri result))
			{
				ConcurrentDictionary<Uri, SourceText>? concurrentDictionary = temporaryDocuments;
				if (concurrentDictionary != null && concurrentDictionary.TryGetValue(result, out SourceText value))
				{
					SourceText newValue = ApplyChanges(updateRequest, value, Path.GetFileName(updateRequest.TextDocument?.FileName ?? string.Empty));
					return temporaryDocuments?.TryUpdate(result, newValue, value) ?? false;
				}
			}
			return false;
		}

		public async Task UpdateBuffer(DidChangeTextDocumentRequest updateRequest, CancellationToken cancellationToken)
		{
			if (updateRequest != null && !string.IsNullOrEmpty(updateRequest.TextDocument?.Uri))
			{
				string filePath = updateRequest.TextDocument?.FileName ?? string.Empty;
				Document document = workspace.GetDocument(filePath);
				if (document != null)
				{
					SourceText newText = ApplyChanges(updateRequest, await document.GetTextAsync(cancellationToken).ConfigureAwait(continueOnCapturedContext: false), document.Name, cancellationToken);
					workspace.OnDocumentTextChanged(document.Id, newText, PreservationMode.PreserveValue);
				}
			}
		}

		private static SourceText ApplyChanges(DidChangeTextDocumentRequest updateRequest, SourceText documentContent, string? documentName = null, CancellationToken cancellationToken = default(CancellationToken))
		{
			TextDocumentContentChangeEvent[] contentChanges = updateRequest.ContentChanges;
			foreach (TextDocumentContentChangeEvent textDocumentContentChangeEvent in contentChanges)
			{
				cancellationToken.ThrowIfCancellationRequested();
				if (!textDocumentContentChangeEvent.Range.HasValue)
				{
					string text = textDocumentContentChangeEvent.Text;
					if (documentContent.Length > textDocumentContentChangeEvent.Text.Length)
					{
						text = text.PadRight(documentContent.Length);
					}
					documentContent = documentContent.WithChanges(new TextChange(new TextSpan(0, text.Length), text));
					break;
				}
				LinePosition position = new LinePosition(textDocumentContentChangeEvent.Range.Value.Start.Line, textDocumentContentChangeEvent.Range.Value.Start.Character);
				LinePosition position2 = new LinePosition(textDocumentContentChangeEvent.Range.Value.End.Line, textDocumentContentChangeEvent.Range.Value.End.Character);
				bool num = documentContent.Lines.IsValidLinePosition(position);
				bool flag = documentContent.Lines.IsValidLinePosition(position2);
				if (!num || !flag)
				{
					LocalMachineLogger.LogError(string.Format(CultureInfo.CurrentCulture, "Content {0} starting at line {1} ending at line {2} is an invalid text update for document {3}.", textDocumentContentChangeEvent.Text, textDocumentContentChangeEvent.Range.Value.Start.Line, textDocumentContentChangeEvent.Range.Value.End.Line, documentName));
					throw new InvalidOperationException(string.Format(CultureInfo.CurrentCulture, ProtocolResources.InvalidateTextBufferUpdate, documentName));
				}
				int position3 = documentContent.Lines.GetPosition(position);
				int position4 = documentContent.Lines.GetPosition(position2);
				documentContent = documentContent.WithChanges(new TextChange(new TextSpan(position3, position4 - position3), textDocumentContentChangeEvent.Text));
			}
			return documentContent;
		}

		public void Dispose()
		{
			if (!isDisposed)
			{
				isDisposed = true;
			}
		}

		public void Clear()
		{
			temporaryDocuments?.Clear();
			transientDocuments.Clear();
			transientDocumentIds.Clear();
		}

		public bool AddOrUpdateInMemoryFile(string filePath, string text)
		{
			if (!Uri.TryCreate(filePath, UriKind.Absolute, out Uri result))
			{
				return false;
			}
			temporaryDocumentStore.Value[result] = SourceText.From(text);
			return true;
		}

		public bool TryAddTransientDocument(ProjectId targetProjectId, string filePath, string text, bool handleRad, out DocumentId documentId)
		{
			documentId = null;
			if (string.IsNullOrWhiteSpace(filePath))
			{
				return false;
			}
			if (transientDocuments.TryGetValue(filePath, out documentId))
			{
				Document document = workspace.CurrentSolution.GetDocument(documentId);
				if (document != null)
				{
					documentId = document.Id;
					if (text != null)
					{
						SourceText sourceText = SourceText.From(text);
						SourceText text2;
						SourceText sourceText2 = (document.TryGetText(out text2) ? text2 : document.GetTextAsync().GetAwaiter().GetResult());
						if (document != null && !sourceText2.ContentEquals(sourceText))
						{
							workspace.OnDocumentTextChanged(document.Id, sourceText, PreservationMode.PreserveValue, handleRad: false);
						}
					}
				}
				return true;
			}
			if (text != null || !TryConsumeInMemoryDocumentIfExists(filePath, out SourceText sourceText3))
			{
				string text3;
				try
				{
					text3 = text ?? File.ReadAllText(filePath);
				}
				catch (IOException)
				{
					return false;
				}
				sourceText3 = SourceText.From(text3);
			}
			VersionStamp version = VersionStamp.Create();
			TextLoader loader = TextLoader.From(TextAndVersion.Create(sourceText3, version));
			DocumentId documentId2 = DocumentId.CreateNewId(targetProjectId);
			DocumentInfo documentInfo = DocumentInfo.Create(documentId2, filePath, null, loader, filePath);
			transientDocuments.Add(filePath, documentId2);
			transientDocumentIds.Add(documentId2);
			documentId = workspace.AddDocument(documentInfo, handleRad).Id;
			return true;
		}

		private bool TryConsumeInMemoryDocumentIfExists(string filePath, out SourceText? sourceText)
		{
			sourceText = null;
			if (Uri.TryCreate(filePath, UriKind.Absolute, out Uri result))
			{
				ConcurrentDictionary<Uri, SourceText>? concurrentDictionary = temporaryDocuments;
				if (concurrentDictionary != null && concurrentDictionary.TryRemove(result, out sourceText))
				{
					return true;
				}
			}
			return false;
		}
	}
	internal class ClientStartup : IClientStartup
	{
		private const int WaitForIntermediateProcessInMilliseconds = 5000;

		public Uri? OpenStartupObject(Uri? webEndpointUri, ConnectionOptions connectionOptions, IEmitLogger logger, int? startupObjectId = null, StartupObjectType? startupObjectType = null, string? startupCompany = null, Guid? extensionId = null, IDictionary<string, string>? debuggingContext = null, BrowserInfo? browserInfo = null)
		{
			if (webEndpointUri == null)
			{
				logger.Error(ProtocolResources.StartupPageError);
				return null;
			}
			Uri uri = BuildUriForOpeningInBrowser(webEndpointUri, connectionOptions, startupObjectId, startupObjectType, startupCompany, extensionId, debuggingContext);
			OpenBrowserAtLocation(browserInfo, uri.AbsoluteUri, logger);
			return uri;
		}

		public void OpenBrowserAtLocation(BrowserInfo? browserInfo, string uri, IEmitLogger logger)
		{
			try
			{
				bool useShellExecute = false;
				string fileName;
				string arguments;
				if (RuntimeInformation.IsOSPlatform(OSPlatform.Windows))
				{
					fileName = "cmd";
					arguments = "/c " + GetWindowsStartupCommand(uri, browserInfo);
				}
				else
				{
					if (!RuntimeInformation.IsOSPlatform(OSPlatform.OSX))
					{
						if (RuntimeInformation.IsOSPlatform(OSPlatform.Linux))
						{
							logger.OpenUri(uri.ToString());
							return;
						}
						logger.Error(ProtocolResources.BrowserLaunchError);
						ExternalTelemetryLogger.TrackError(FormattableString.Invariant($"Unknown OS: {RuntimeInformation.OSDescription}"));
						return;
					}
					(string fileName, string arguments) macOSStartupCommand = GetMacOSStartupCommand(uri, browserInfo);
					fileName = macOSStartupCommand.fileName;
					arguments = macOSStartupCommand.arguments;
					useShellExecute = true;
				}
				Process.Start(new ProcessStartInfo
				{
					FileName = fileName,
					Arguments = arguments,
					UseShellExecute = useShellExecute
				}).WaitForExit(5000);
			}
			catch (Win32Exception ex)
			{
				logger.Error(ProtocolResources.BrowserLaunchError);
				ExternalTelemetryLogger.TrackError("BrowserLaunchError", new Dictionary<string, string> { 
				{
					"Exception",
					ex.GetType().Name
				} });
			}
		}

		private static Uri BuildUriForOpeningInBrowser(Uri webEndpointUri, ConnectionOptions connectionOptions, int? startupObjectId, StartupObjectType? startupObjectType, string? startupCompany, Guid? extensionId, IDictionary<string, string>? debuggingContext)
		{
			UriBuilder uriBuilder = new UriBuilder(webEndpointUri);
			Dictionary<string, string> dictionary = new Dictionary<string, string>();
			if (startupObjectId.HasValue)
			{
				string key = startupObjectType.GetValueOrDefault().ToString().ToLowerInvariant();
				dictionary[key] = startupObjectId.Value.ToString(CultureInfo.InvariantCulture);
				if (startupCompany != null)
				{
					dictionary["company"] = startupCompany;
				}
			}
			if (connectionOptions.IsOnPremise())
			{
				if (!string.IsNullOrWhiteSpace(connectionOptions.Tenant))
				{
					dictionary["tenant"] = Uri.EscapeDataString(connectionOptions.Tenant);
				}
			}
			else
			{
				dictionary["noSignUpCheck"] = "1";
			}
			if (extensionId.HasValue)
			{
				dictionary["extension"] = extensionId.ToString();
			}
			if (debuggingContext != null)
			{
				foreach (KeyValuePair<string, string> item in debuggingContext)
				{
					dictionary[item.Key] = item.Value;
				}
			}
			uriBuilder.Query = UriHelper.CreateQueryString(dictionary, prependQuestionMark: false);
			return uriBuilder.Uri;
		}

		private static string GetWindowsStartupCommand(string uri, BrowserInfo? browserInfo)
		{
			switch (browserInfo?.Browser)
			{
			case Browser.Chrome:
			{
				string text2 = FormattableString.Invariant($"start chrome \"{uri}\"");
				if (browserInfo.Incognito)
				{
					text2 += " --incognito";
				}
				return text2;
			}
			case Browser.Firefox:
			{
				string result = FormattableString.Invariant($"start firefox \"{uri}\"");
				if (browserInfo.Incognito)
				{
					result = FormattableString.Invariant($"start firefox -private-window \"{uri}\"");
				}
				return result;
			}
			case Browser.Edge:
			case Browser.EdgeBeta:
			{
				string text = FormattableString.Invariant($"start msedge \"{uri}\"");
				if (browserInfo.Incognito)
				{
					text += " --inprivate";
				}
				return text;
			}
			case null:
			case Browser.SystemDefault:
				return FormattableString.Invariant($"start \"\" \"{uri}\"");
			default:
				throw new Exception(FormattableString.Invariant($"Unknown browser {browserInfo.Browser.ToString()}"));
			}
		}

		private static (string fileName, string arguments) GetMacOSStartupCommand(string uri, BrowserInfo? browserInfo)
		{
			string text = FormattableString.Invariant($"\"{uri}\"");
			switch (browserInfo?.Browser)
			{
			case Browser.Chrome:
				if (browserInfo.Incognito)
				{
					text += " --incognito";
				}
				return (fileName: "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome", arguments: text);
			case Browser.Firefox:
				if (browserInfo.Incognito)
				{
					text = " -private-window " + text;
				}
				return (fileName: "/Applications/Firefox.app/Contents/MacOS/firefox", arguments: text);
			case Browser.Edge:
				if (browserInfo.Incognito)
				{
					text = " -inprivate " + text;
				}
				return (fileName: "/Applications/Microsoft Edge.app/Contents/MacOS/Microsoft Edge", arguments: text);
			case Browser.EdgeBeta:
				if (browserInfo.Incognito)
				{
					text = " -inprivate " + text;
				}
				return (fileName: "/Applications/Microsoft Edge Beta.app/Contents/MacOS/Microsoft Edge Beta", arguments: text);
			case null:
			case Browser.SystemDefault:
				return (fileName: "open", arguments: text);
			default:
				throw new Exception(FormattableString.Invariant($"Unknown browser {browserInfo.Browser}"));
			}
		}
	}
	[DebuggerDisplay("{ToString(), nq}")]
	internal class CpuProfileCallFrameDefinition : IEquatable<CpuProfileCallFrameDefinition>, IComparable<CpuProfileCallFrameDefinition>
	{
		internal SnapshotLineDefinition? LineDefinition { get; set; }

		internal CpuProfileCallFrameDefinition? ParentCallerFrameDefinition { get; set; }

		internal int ExecutionIndex { get; set; }

		internal List<int> CalledFrameIndexes { get; }

		internal int HitCount { get; set; }

		internal HashSet<int> HitIndexes { get; }

		internal long AggregatedExecutionTime { get; set; }

		internal int FrameIdentifier { get; set; }

		internal CpuProfileCallFrameDefinition()
		{
			CalledFrameIndexes = new List<int>();
			HitIndexes = new HashSet<int>();
		}

		public bool Equals(CpuProfileCallFrameDefinition? other)
		{
			if ((object)other == null)
			{
				return false;
			}
			if (ExecutionIndex == other.ExecutionIndex)
			{
				return LineDefinition == other.LineDefinition;
			}
			return false;
		}

		public override int GetHashCode()
		{
			return Hash.Combine(LineDefinition?.GetHashCode() ?? 0, ExecutionIndex.GetHashCode());
		}

		public static bool operator ==(CpuProfileCallFrameDefinition left, CpuProfileCallFrameDefinition right)
		{
			if ((object)left != right)
			{
				return left?.Equals(right) ?? false;
			}
			return true;
		}

		public static bool operator !=(CpuProfileCallFrameDefinition left, CpuProfileCallFrameDefinition right)
		{
			return !(left == right);
		}

		public override bool Equals(object obj)
		{
			if (obj == null)
			{
				return false;
			}
			if (!(obj is CpuProfileCallFrameDefinition other))
			{
				return false;
			}
			return Equals(other);
		}

		public override string ToString()
		{
			return string.Format(CultureInfo.InvariantCulture, "{0}:{1}:{2}", ExecutionIndex, LineDefinition, HitCount);
		}

		public int CompareTo(CpuProfileCallFrameDefinition? other)
		{
			if (other == null)
			{
				return 1;
			}
			return ExecutionIndex - other.ExecutionIndex;
		}
	}
	internal class CpuProfileGenerator
	{
		private class DeclaringApplicationComparer : IEqualityComparer<(string Name, string Publisher, string Version)>
		{
			public static IEqualityComparer<(string Name, string Publisher, string Version)> Instance { get; } = new DeclaringApplicationComparer();


			public bool Equals((string Name, string Publisher, string Version) x, (string Name, string Publisher, string Version) y)
			{
				var (text, _, _) = x;
				if (text != null && text.Equals(y.Name, StringComparison.OrdinalIgnoreCase))
				{
					string item = x.Publisher;
					if (item != null && item.Equals(y.Publisher, StringComparison.OrdinalIgnoreCase))
					{
						return x.Version?.Equals(y.Version, StringComparison.OrdinalIgnoreCase) ?? false;
					}
				}
				return false;
			}

			public int GetHashCode((string Name, string Publisher, string Version) obj)
			{
				return Hash.Combine(obj.Name?.GetHashCode() ?? 0, obj.Publisher?.GetHashCode() ?? 0, obj.Version?.GetHashCode() ?? 0);
			}
		}

		private static int UndefinedId = -1;

		private static readonly List<SnapshotLineDefinition> NoCallers = new List<SnapshotLineDefinition>();

		private static readonly CpuProfile EmptyProfile = new CpuProfile();

		private static readonly CpuProfileNode EmptyProfileNode = new CpuProfileNode();

		private const int startupMaxPercent = 75;

		private const int generateProfileMaxPercent = 80;

		private const int finishingProfileGenerationMaxPercent = 95;

		private static readonly CpuProfileCallFrame EmptyCpuProfileCallFrame = new CpuProfileCallFrame();

		private readonly IEmitLogger logger;

		private readonly IList<MethodContext> methodContexts = new List<MethodContext>();

		private readonly IList<CpuProfileCallFrameDefinition> callFrames = new List<CpuProfileCallFrameDefinition>();

		private readonly IDictionary<SnapshotLineDefinition, (int Index, PositionTickInfo TickInfo)> linesWithHits = new Dictionary<SnapshotLineDefinition, (int, PositionTickInfo)>();

		private readonly IDictionary<int, (SnapshotLineDefinition CallerLine, SnapshotLineDefinition CalledLine)> methodContextsToCallerAndCalledLineDefinition = new Dictionary<int, (SnapshotLineDefinition, SnapshotLineDefinition)>();

		private readonly CancellationToken cancellationToken;

		private readonly VsCodeWorkspace workspace;

		private readonly IDictionary<ApplicationObjectIdWrapper, ApplicationDefinition> applicationDefinitionCache = new Dictionary<ApplicationObjectIdWrapper, ApplicationDefinition>();

		private readonly IDictionary<(string Name, string Publisher, string Version), Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.LanguageServerContract.DeclaringApplication> declaringApplicationCache = new Dictionary<(string, string, string), Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.LanguageServerContract.DeclaringApplication>(DeclaringApplicationComparer.Instance);

		private readonly IResponseQueue responseQueue;

		private readonly ProgressNotificatonResponse progressNotificationResponse = new ProgressNotificatonResponse
		{
			Owner = ProgressNotificationOwner.Profiler,
			Percent = 0
		};

		internal CpuProfileGenerator(IEmitLogger logger, VsCodeWorkspace workspace, IResponseQueue responseQueue, CancellationToken cancellationToken)
		{
			this.logger = logger;
			this.workspace = workspace;
			this.responseQueue = responseQueue;
			this.cancellationToken = cancellationToken;
		}

		internal static ZipArchive? OpenZipArchive(string filePath, IEmitLogger logger)
		{
			ZipArchive zipArchive = null;
			try
			{
				return ZipFile.OpenRead(filePath);
			}
			catch (Exception ex) when (ex is IOException || ex is InvalidDataException || ex is UnauthorizedAccessException)
			{
				logger.Error(string.Format(CultureInfo.CurrentCulture, ProtocolResources.ProfileGenerationFailedInvalidSnapshotFile, filePath));
				return null;
			}
		}

		internal async Task<bool> Initialize(string snapshotFilePath)
		{
			if (!File.Exists(snapshotFilePath))
			{
				logger.Error(string.Format(CultureInfo.CurrentCulture, ProtocolResources.ProfileGenerationFailedWrongsnapshotFileParameter, snapshotFilePath));
				return false;
			}
			using ZipArchive archive = OpenZipArchive(snapshotFilePath, logger);
			if (archive == null)
			{
				logger.Error(string.Format(CultureInfo.CurrentCulture, ProtocolResources.ProfileGenerationFailedInvalidSnapshotFile, snapshotFilePath));
				return false;
			}
			System.Version version = await archive.GetVersionFromSnapshotFile(CancellationToken.None).ConfigureAwait(continueOnCapturedContext: false);
			IList<ZipArchiveEntry> list = (from entry in archive.Entries.Where((ZipArchiveEntry e) => SnapshotDebuggerService.MethodDebugContextFileExtension.Equals(Path.GetExtension(e.FullName), StringComparison.OrdinalIgnoreCase)).AsParallel()
				orderby int.Parse(Path.GetFileNameWithoutExtension(entry.Name), CultureInfo.InvariantCulture)
				select entry).ToList();
			SendProgressNotificationResponse(7);
			if (list.Count == 0)
			{
				logger.Error(string.Format(CultureInfo.CurrentCulture, ProtocolResources.ProfileGenerationFailedInvalidSnapshotFile, snapshotFilePath));
				return false;
			}
			if (version < SnapshotApiVersions.Version2_0)
			{
				logger.Error(string.Format(CultureInfo.CurrentCulture, ProtocolResources.ProfileGenerationNotSupported, snapshotFilePath, version));
				return false;
			}
			ExtractMethodContexts(list, 7, 37);
			SendProgressNotificationResponse(75);
			return true;
		}

		internal async Task<CpuProfile> GenerateProfile()
		{
			CpuProfile profile = new CpuProfile();
			if (methodContexts.Count == 0)
			{
				return profile;
			}
			profile.StartTime = methodContexts[0].ExecutionSpan?.StartTime ?? 0;
			profile.EndTime = methodContexts[methodContexts.Count - 1].ExecutionSpan?.EndTime ?? 0;
			profile.Nodes = new CpuProfileNode[callFrames.Count];
			profile.Samples = new int[callFrames.Count];
			profile.TimeDeltas = new long[callFrames.Count];
			profile.SampleExecutionTimes = new long[callFrames.Count];
			await GenerateProfile(profile.Samples, profile.TimeDeltas, profile.SampleExecutionTimes, profile.Nodes).ConfigureAwait(continueOnCapturedContext: false);
			if (profile.Nodes.Length != 0)
			{
				profile.Nodes = profile.Nodes.OrderBy((CpuProfileNode n) => n.Id).ToArray();
			}
			SendProgressNotificationResponse(95);
			return profile;
		}

		internal void SendProgressNotificationResponse(int percent)
		{
			progressNotificationResponse.Percent = percent;
			responseQueue.Add(ResponseFactory.ProgressNotification(progressNotificationResponse), CancellationToken.None);
		}

		private async Task GenerateProfile(IList<int> samples, IList<long> timeDeltas, IList<long> sampleExecutionTimes, IList<CpuProfileNode> profileNodes)
		{
			if (callFrames.Count == 0)
			{
				return;
			}
			for (int i = 0; i < callFrames.Count; i++)
			{
				CpuProfileCallFrameDefinition cpuProfileCallFrameDefinition = callFrames[i];
				samples[i] = ToProfileIndex(cpuProfileCallFrameDefinition.ExecutionIndex);
				sampleExecutionTimes[i] = cpuProfileCallFrameDefinition.AggregatedExecutionTime;
				if (i == 0)
				{
					timeDeltas[0] = sampleExecutionTimes[0];
				}
				else
				{
					timeDeltas[i] = Math.Abs(sampleExecutionTimes[i] - sampleExecutionTimes[i - 1]);
				}
				int index = i;
				profileNodes[index] = await CreateCpuProfileNode(cpuProfileCallFrameDefinition).ConfigureAwait(continueOnCapturedContext: false);
				SendProgressNotificationResponseFromGeneratingProfileNodes(i);
			}
		}

		private async Task<CpuProfileNode> CreateCpuProfileNode(CpuProfileCallFrameDefinition profileCallFrameDefinition)
		{
			CpuProfileCallFrameDefinition profileCallFrameDefinition2 = profileCallFrameDefinition;
			MethodContext methodContext = methodContexts[profileCallFrameDefinition2.ExecutionIndex];
			(ApplicationObjectIdWrapper?, string) tuple = methodContext.ToApplicationObjectDefinition();
			ApplicationObjectIdWrapper? applicationObjectId = tuple.Item1;
			string name = tuple.Item2;
			Microsoft.Dynamics.Nav.AL.Common.SnapshotDebuggerSerializer.DeclaringApplication? bufferedDeclaringApplication = methodContext.App;
			long startTime = (methodContext.ExecutionSpan.HasValue ? methodContext.ExecutionSpan.Value.StartTime : 0);
			long endTime = (methodContext.ExecutionSpan.HasValue ? methodContext.ExecutionSpan.Value.EndTime : 0);
			CpuProfileNode cpuProfileNode = new CpuProfileNode
			{
				Id = ToProfileIndex(profileCallFrameDefinition2.ExecutionIndex),
				Children = (from i in profileCallFrameDefinition2.CalledFrameIndexes
					select ToProfileIndex(i) into a
					orderby a
					select a).ToArray(),
				HitCount = profileCallFrameDefinition2.HitCount,
				PositionTicks = (from t in (from i in linesWithHits.Values
						where i.Index == profileCallFrameDefinition2.ExecutionIndex || (profileCallFrameDefinition2?.HitIndexes.Contains(i.Index) ?? false)
						select i into p
						select p.TickInfo).ToList()
					orderby t.Line
					select t).ToArray()
			};
			CpuProfileNode cpuProfileNode2 = cpuProfileNode;
			cpuProfileNode2.CallFrame = await CreateCpuProfileCallFrame(methodContext).ConfigureAwait(continueOnCapturedContext: false);
			cpuProfileNode.ApplicationDefinition = GetOrAddApplicationDefinition(applicationObjectId, name);
			cpuProfileNode.DeclaringApplication = GetOrAddDeclaringApplication(bufferedDeclaringApplication);
			cpuProfileNode.IsBuiltinCodeUnitCall = methodContext.IsBuiltinCodeUnitCall == 1;
			cpuProfileNode.IsIncompleteMeasurement = methodContext.IsIncompleteMeasurement == 1;
			cpuProfileNode.FrameIdentifier = CreateCallFrameIdentifier(profileCallFrameDefinition2);
			cpuProfileNode.StartTime = startTime;
			cpuProfileNode.EndTime = endTime;
			if (cpuProfileNode.IsIncompleteMeasurement)
			{
				logger.Info(string.Format(ProtocolResources.IncompleteProfiledStackTrace, methodContext.MethodName));
			}
			return cpuProfileNode;
		}

		private ApplicationDefinition GetOrAddApplicationDefinition(ApplicationObjectIdWrapper? wrapper, string objectName)
		{
			if (!wrapper.HasValue)
			{
				return ApplicationDefinition.Default;
			}
			if (applicationDefinitionCache.TryGetValue(wrapper.Value, out ApplicationDefinition value))
			{
				return value;
			}
			value = new ApplicationDefinition
			{
				ObjectId = wrapper.Value.ObjectNumber,
				ObjectType = (wrapper.Value.ObjectType.ToString() ?? string.Empty),
				ObjectName = objectName.QuoteIdentifierIfNeeded()
			};
			applicationDefinitionCache.Add(wrapper.Value, value);
			return value;
		}

		private Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.LanguageServerContract.DeclaringApplication GetOrAddDeclaringApplication(Microsoft.Dynamics.Nav.AL.Common.SnapshotDebuggerSerializer.DeclaringApplication? bufferedDeclaringApplication)
		{
			if (!bufferedDeclaringApplication.HasValue)
			{
				return Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.LanguageServerContract.DeclaringApplication.Default;
			}
			(string, string, string) key = (bufferedDeclaringApplication.Value.AppName, bufferedDeclaringApplication.Value.AppPublisher, bufferedDeclaringApplication.Value.AppVersion);
			if (declaringApplicationCache.TryGetValue(key, out Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.LanguageServerContract.DeclaringApplication value))
			{
				return value;
			}
			value = new Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.LanguageServerContract.DeclaringApplication
			{
				AppId = (bufferedDeclaringApplication.Value.AppId ?? string.Empty),
				AppName = (bufferedDeclaringApplication.Value.AppName ?? string.Empty),
				AppPublisher = (bufferedDeclaringApplication.Value.AppPublisher ?? string.Empty),
				AppVersion = (bufferedDeclaringApplication.Value.AppVersion ?? string.Empty)
			};
			declaringApplicationCache.Add(key, value);
			return value;
		}

		private void ExtractMethodContexts(IList<ZipArchiveEntry> entries, int startPercent, int endPercent)
		{
			int num = 0;
			for (int i = 0; i < entries.Count; i++)
			{
				MethodContext? methodContext = entries[i].ReadContent<MethodContext>((ByteBuffer byteBuffer) => MethodContext.GetRootAsMethodContext(byteBuffer));
				if (methodContext.HasValue)
				{
					MethodContext value = methodContext.Value;
					methodContexts.Add(value);
					SnapshotLineDefinition callerLine = value.GetCallerLine();
					SnapshotLineDefinition calledLine = value.GetCalledLine();
					methodContextsToCallerAndCalledLineDefinition.Add(num++, (callerLine, calledLine));
					if (i % 100 == 0)
					{
						SendProgressNotificationResponse(startPercent + (endPercent - startPercent) * i / entries.Count);
					}
				}
			}
			CreateCallFrameDefinitions(37, 50);
		}

		private async Task<CpuProfileCallFrame> CreateCpuProfileCallFrame(MethodContext methodContext)
		{
			Microsoft.Dynamics.Nav.AL.Common.SnapshotDebuggerSerializer.StackFrame? thisFrame = methodContext.GetThisFrame();
			if (!thisFrame.HasValue)
			{
				return EmptyCpuProfileCallFrame;
			}
			Microsoft.Dynamics.Nav.AL.Common.SnapshotDebuggerSerializer.StackFrame value = thisFrame.Value;
			CpuProfileCallFrame cpuProfileCallFrame = new CpuProfileCallFrame
			{
				FunctionName = value.MethodName,
				ScriptId = value.Id.FromBufferedApplicationObjectId().ToString(),
				LineNumber = value.StatementSpan.Value.From.Line,
				ColumnNumber = value.StatementSpan.Value.From.Column
			};
			CpuProfileCallFrame cpuProfileCallFrame2 = cpuProfileCallFrame;
			cpuProfileCallFrame2.Url = await CreateUri(methodContext).ConfigureAwait(continueOnCapturedContext: false);
			return cpuProfileCallFrame;
		}

		private async Task<string> CreateUri(MethodContext methodContext)
		{
			ApplicationObjectIdWrapper appIdWrapper = methodContext.Id.FromBufferedApplicationObjectId().Value;
			Guid? appId = null;
			if (methodContext.App?.AppId != null && Guid.TryParse(methodContext.App?.AppId, out var result))
			{
				appId = result;
			}
			Project currentProject = workspace.GetCurrentProject();
			Compilation compilation = await currentProject.GetCompilationAsync(cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
			if (compilation == null)
			{
				return FilePathHelper.GetPreviewFileUri(currentProject.ProjectFolder, appIdWrapper.ToString(), appIdWrapper, appId);
			}
			SymbolKind kind = DebugHelper.MapToSymbolKind(appIdWrapper.ObjectType);
			ApplicationObjectTypeSymbol applicationObjectTypeSymbol = compilation.GetApplicationObjectTypeSymbolsByIdAcrossModules(kind, appIdWrapper.ObjectNumber).FirstOrDefault() as ApplicationObjectTypeSymbol;
			if (applicationObjectTypeSymbol != null)
			{
				Microsoft.Dynamics.Nav.CodeAnalysis.Text.Location location = applicationObjectTypeSymbol.GetLocation();
				if (location != null && location.IsInSource)
				{
					return location.SourceTree.FilePath.GetUri();
				}
			}
			return FilePathHelper.GetPreviewFileUri(currentProject.ProjectFolder, appIdWrapper.ToString(), appIdWrapper, appId);
		}

		private void CreateCallFrameDefinitions(int startPercent, int endPercent)
		{
			PooledDictionary<SnapshotLineDefinition, int> instance = PooledDictionary<SnapshotLineDefinition, int>.GetInstance();
			try
			{
				for (int i = 0; i < methodContexts.Count; i++)
				{
					ApplicationObjectIdWrapper? applicationObjectIdWrapper = methodContexts[i].Id.FromBufferedApplicationObjectId();
					if (applicationObjectIdWrapper.HasValue && methodContextsToCallerAndCalledLineDefinition.TryGetValue(i, out (SnapshotLineDefinition, SnapshotLineDefinition) value))
					{
						CpuProfileCallFrameDefinition cpuProfileCallFrameDefinition = new CpuProfileCallFrameDefinition
						{
							LineDefinition = value.Item2,
							ExecutionIndex = i,
							HitCount = 1,
							AggregatedExecutionTime = GetExecutionTime(i),
							ParentCallerFrameDefinition = GetCallerCallFrameDefinition(value.Item1, instance)
						};
						int startIndex = Math.Min(i + 1, methodContexts.Count - 1);
						int nextSiblingIndex = GetNextSiblingIndex(value.Item1, startIndex);
						TraverseLinesAndCreateCalledFrameIndexes(i, nextSiblingIndex, applicationObjectIdWrapper.Value, cpuProfileCallFrameDefinition, instance);
						callFrames.Add(cpuProfileCallFrameDefinition);
						if (i % 100 == 0)
						{
							SendProgressNotificationResponse(startPercent + (endPercent - startPercent) * i / methodContexts.Count);
						}
					}
				}
			}
			finally
			{
				instance.Free();
			}
			UpdateStatementExecutionTimeWithFrameExecutionTime();
			AggregateFrames(50, 75);
		}

		private CpuProfileCallFrameDefinition? GetCallerCallFrameDefinition(SnapshotLineDefinition callerLine, PooledDictionary<SnapshotLineDefinition, int> linesWithIndexes)
		{
			if (callerLine == null)
			{
				return null;
			}
			if (linesWithIndexes.TryGetValue(callerLine, out var value))
			{
				return callFrames[value];
			}
			return null;
		}

		private int GetNextSiblingIndex(SnapshotLineDefinition callerLine, int startIndex)
		{
			SnapshotLineDefinition callerLine2 = callerLine;
			GetParallelOptions(methodContexts.Count - startIndex + 1);
			int nextSiblingIndex = methodContexts.Count - 1;
			Parallel.For(startIndex, methodContexts.Count, delegate(int k, ParallelLoopState state)
			{
				if (methodContextsToCallerAndCalledLineDefinition.TryGetValue(k, out (SnapshotLineDefinition, SnapshotLineDefinition) value) && value.Item1 == callerLine2 && (!state.ShouldExitCurrentIteration || !(state.LowestBreakIteration < k)))
				{
					Interlocked.Exchange(ref nextSiblingIndex, k);
					state.Break();
				}
			});
			return nextSiblingIndex;
		}

		private void AggregateFrames(int startPercent, int endPercent)
		{
			IDictionary<int, CpuProfileCallFrameDefinition> dictionary = callFrames.ToDictionary((CpuProfileCallFrameDefinition k) => k.ExecutionIndex);
			PooledHashSet<int> instance = PooledHashSet<int>.GetInstance();
			try
			{
				int num = 0;
				foreach (CpuProfileCallFrameDefinition value2 in dictionary.Values)
				{
					if (!instance.Contains(value2.ExecutionIndex))
					{
						AggregateIntoFrame(value2, instance, dictionary);
						if (num++ % 100 == 0)
						{
							SendProgressNotificationResponse(startPercent + (endPercent - startPercent) * num / callFrames.Count);
						}
					}
				}
				foreach (int item in instance)
				{
					if (dictionary.TryGetValue(item, out var value) && value != null)
					{
						callFrames.Remove(value);
						RemoveFrameFromAllCallers(item);
					}
				}
				foreach (CpuProfileCallFrameDefinition callFrame in callFrames)
				{
					VerifyForMissingCallerLink(callFrame, instance, dictionary);
				}
			}
			finally
			{
				instance.Free();
			}
		}

		private void VerifyForMissingCallerLink(CpuProfileCallFrameDefinition frameDefinition, HashSet<int> aggregatedFrames, IDictionary<int, CpuProfileCallFrameDefinition> callFramesAsDictionary)
		{
			if (frameDefinition.ParentCallerFrameDefinition == null || !callFramesAsDictionary.TryGetValue(frameDefinition.ParentCallerFrameDefinition.ExecutionIndex, out CpuProfileCallFrameDefinition value) || !(value != null) || value.CalledFrameIndexes.Contains(frameDefinition.ExecutionIndex))
			{
				return;
			}
			CpuProfileCallFrameDefinition cpuProfileCallFrameDefinition = value;
			if (aggregatedFrames.Contains(frameDefinition.ParentCallerFrameDefinition.ExecutionIndex))
			{
				cpuProfileCallFrameDefinition = FindCallerFrameForChildFrame(frameDefinition.ParentCallerFrameDefinition, aggregatedFrames, callFramesAsDictionary);
			}
			if (!(cpuProfileCallFrameDefinition != null))
			{
				return;
			}
			cpuProfileCallFrameDefinition.CalledFrameIndexes.Add(frameDefinition.ExecutionIndex);
			cpuProfileCallFrameDefinition.CalledFrameIndexes.Sort();
			CpuProfileCallFrameDefinition cpuProfileCallFrameDefinition2 = cpuProfileCallFrameDefinition;
			while (cpuProfileCallFrameDefinition2 != null && cpuProfileCallFrameDefinition2.ExecutionIndex != 0)
			{
				cpuProfileCallFrameDefinition2.AggregatedExecutionTime += frameDefinition.AggregatedExecutionTime;
				PositionTickInfo item = GetCallerPositionTickInfo(cpuProfileCallFrameDefinition2).TickInfo;
				if (item != null)
				{
					item.ExecutionTime += frameDefinition.AggregatedExecutionTime;
				}
				cpuProfileCallFrameDefinition2 = cpuProfileCallFrameDefinition2.ParentCallerFrameDefinition;
			}
		}

		private static CpuProfileCallFrameDefinition? FindCallerFrameForChildFrame(CpuProfileCallFrameDefinition callFrameDefinition, HashSet<int> aggregatedFrames, IDictionary<int, CpuProfileCallFrameDefinition> callFramesAsDictionary)
		{
			if (callFrameDefinition.ParentCallerFrameDefinition == null)
			{
				return null;
			}
			if (aggregatedFrames.Contains(callFrameDefinition.ParentCallerFrameDefinition.ExecutionIndex))
			{
				return null;
			}
			if (callFramesAsDictionary.TryGetValue(callFrameDefinition.ParentCallerFrameDefinition.ExecutionIndex, out CpuProfileCallFrameDefinition value) && value != null)
			{
				foreach (int calledFrameIndex in value.CalledFrameIndexes)
				{
					if (callFramesAsDictionary.TryGetValue(calledFrameIndex, out CpuProfileCallFrameDefinition value2) && value2 != null && value2.LineDefinition == callFrameDefinition.LineDefinition)
					{
						return value2;
					}
				}
			}
			return null;
		}

		private void AggregateIntoFrame(CpuProfileCallFrameDefinition to, HashSet<int> aggregatedFrames, IDictionary<int, CpuProfileCallFrameDefinition> callFramesAsDictionary)
		{
			if (aggregatedFrames.Contains(to.ExecutionIndex))
			{
				return;
			}
			PooledHashSet<int> instance = PooledHashSet<int>.GetInstance();
			try
			{
				foreach (CpuProfileCallFrameDefinition item in GetAggregationContextForFrame(to, aggregatedFrames, callFramesAsDictionary))
				{
					if (aggregatedFrames.Add(item.ExecutionIndex))
					{
						instance.AddAll(item.CalledFrameIndexes);
						AggregateIntoFrame(item, to);
					}
				}
				if (to.CalledFrameIndexes.Contains(to.ExecutionIndex))
				{
					to.CalledFrameIndexes.Remove(to.ExecutionIndex);
					if (to.CalledFrameIndexes.Count > 0)
					{
						to.CalledFrameIndexes.Sort();
					}
				}
				AggregateCalledFrames(to.CalledFrameIndexes, aggregatedFrames, callFramesAsDictionary);
				if (instance.Count > 0)
				{
					int count = to.CalledFrameIndexes.Count;
					foreach (int item2 in instance)
					{
						if (!aggregatedFrames.Contains(item2) && !to.CalledFrameIndexes.Contains(item2) && callFramesAsDictionary.TryGetValue(item2, out CpuProfileCallFrameDefinition value) && value.ParentCallerFrameDefinition?.LineDefinition == to.LineDefinition)
						{
							to.CalledFrameIndexes.Add(item2);
						}
					}
					if (count < to.CalledFrameIndexes.Count)
					{
						to.CalledFrameIndexes.Sort();
					}
				}
				AdjustFrameExecutionTime(to, callFramesAsDictionary);
			}
			finally
			{
				instance.Free();
			}
		}

		private void AggregateCalledFrames(IList<int> calledFrameIndexes, HashSet<int> aggregatedFrames, IDictionary<int, CpuProfileCallFrameDefinition> callFramesAsDictionary)
		{
			for (int i = 0; i < calledFrameIndexes.Count; i++)
			{
				int num = calledFrameIndexes[i];
				if (!aggregatedFrames.Contains(num) && callFramesAsDictionary.TryGetValue(num, out CpuProfileCallFrameDefinition value))
				{
					AggregateIntoFrame(value, aggregatedFrames, callFramesAsDictionary);
				}
			}
		}

		private IList<CpuProfileCallFrameDefinition> GetAggregationContextForFrame(CpuProfileCallFrameDefinition aggregateInto, HashSet<int> aggregatedFrames, IDictionary<int, CpuProfileCallFrameDefinition> callFramesAsDictionary)
		{
			HashSet<int> aggregatedFrames2 = aggregatedFrames;
			IDictionary<int, CpuProfileCallFrameDefinition> callFramesAsDictionary2 = callFramesAsDictionary;
			CpuProfileCallFrameDefinition aggregateInto2 = aggregateInto;
			PooledList<CpuProfileCallFrameDefinition> aggregationList = PooledList<CpuProfileCallFrameDefinition>.GetInstance();
			NonReentrantLock mutex = new NonReentrantLock(useThisInstanceForSynchronization: true);
			try
			{
				GetParallelOptions(methodContexts.Count - aggregateInto2.ExecutionIndex);
				Parallel.For(aggregateInto2.ExecutionIndex + 1, methodContexts.Count, delegate(int index)
				{
					if (!aggregatedFrames2.Contains(index) && callFramesAsDictionary2.TryGetValue(index, out CpuProfileCallFrameDefinition value) && value != null && value.ParentCallerFrameDefinition == aggregateInto2.ParentCallerFrameDefinition && value.LineDefinition == aggregateInto2.LineDefinition)
					{
						using (mutex.DisposableWait())
						{
							aggregationList.Add(value);
						}
					}
				});
				aggregationList.Sort();
				return aggregationList.ToArray();
			}
			finally
			{
				aggregationList.Free();
			}
		}

		private void AggregateIntoFrame(CpuProfileCallFrameDefinition from, CpuProfileCallFrameDefinition to)
		{
			if (from.ExecutionIndex == to.ExecutionIndex)
			{
				return;
			}
			int executionIndex = from.ExecutionIndex;
			bool flag = methodContexts[executionIndex].IsIncompleteMeasurement == 1;
			bool aggregateHitCounts = flag;
			if (!flag)
			{
				if (from.CalledFrameIndexes.Contains(from.ExecutionIndex))
				{
					aggregateHitCounts = true;
					flag = false;
				}
				else
				{
					aggregateHitCounts = true;
					flag = true;
				}
			}
			AggregateHitCountAndExecutionTime(from, to, flag, aggregateHitCounts);
		}

		private void UpdateStatementExecutionTimeWithFrameExecutionTime()
		{
			foreach (CpuProfileCallFrameDefinition callFrame in callFrames)
			{
				PositionTickInfo item = GetCallerPositionTickInfo(callFrame).TickInfo;
				if (item != null)
				{
					item.ExecutionTime += callFrame.AggregatedExecutionTime;
				}
			}
			PooledHashSet<SnapshotLineDefinition> instance = PooledHashSet<SnapshotLineDefinition>.GetInstance();
			try
			{
				foreach (KeyValuePair<SnapshotLineDefinition, (int, PositionTickInfo)> linesWithHit in linesWithHits)
				{
					if (linesWithHit.Value.Item2.ExecutionTime == 0L)
					{
						instance.Add(linesWithHit.Key);
					}
				}
				foreach (SnapshotLineDefinition item2 in instance)
				{
					linesWithHits.Remove(item2);
				}
			}
			finally
			{
				instance.Free();
			}
		}

		private (int Index, PositionTickInfo? TickInfo) GetCallerPositionTickInfo(CpuProfileCallFrameDefinition callFrame)
		{
			if (methodContextsToCallerAndCalledLineDefinition.TryGetValue(callFrame.ExecutionIndex, out (SnapshotLineDefinition, SnapshotLineDefinition) value) && value.Item1 != null && linesWithHits.TryGetValue(value.Item1, out (int, PositionTickInfo) value2) && callFrame.HitCount > 0)
			{
				return value2;
			}
			return (Index: UndefinedId, TickInfo: null);
		}

		private void RemoveFrameFromAllCallers(int callFrameExecutionIndex)
		{
			ParallelOptions parallelOptions = GetParallelOptions(callFrames.Count);
			NonReentrantLock nonReentrant = new NonReentrantLock(useThisInstanceForSynchronization: true);
			Parallel.For(0, callFrames.Count, parallelOptions, delegate(int counter)
			{
				CpuProfileCallFrameDefinition cpuProfileCallFrameDefinition = callFrames[counter];
				if (cpuProfileCallFrameDefinition.CalledFrameIndexes.Contains(callFrameExecutionIndex))
				{
					using (nonReentrant.DisposableWait())
					{
						cpuProfileCallFrameDefinition.CalledFrameIndexes.Remove(callFrameExecutionIndex);
					}
				}
			});
		}

		private void AdjustFrameExecutionTime(CpuProfileCallFrameDefinition frame, IDictionary<int, CpuProfileCallFrameDefinition> callFramesAsDictionary)
		{
			CpuProfileCallFrameDefinition frame2 = frame;
			IDictionary<int, CpuProfileCallFrameDefinition> callFramesAsDictionary2 = callFramesAsDictionary;
			long calledFramesExecutionTime = 0L;
			ParallelOptions parallelOptions = GetParallelOptions(frame2.CalledFrameIndexes.Count);
			Parallel.For(0, frame2.CalledFrameIndexes.Count, parallelOptions, delegate(int counter)
			{
				int key = frame2.CalledFrameIndexes[counter];
				if (callFramesAsDictionary2.TryGetValue(key, out CpuProfileCallFrameDefinition value))
				{
					Interlocked.Add(ref calledFramesExecutionTime, value.AggregatedExecutionTime);
				}
			});
			if (frame2.AggregatedExecutionTime < calledFramesExecutionTime)
			{
				long num = calledFramesExecutionTime - frame2.AggregatedExecutionTime;
				frame2.AggregatedExecutionTime += num;
				PositionTickInfo item = GetCallerPositionTickInfo(frame2).TickInfo;
				if (item != null)
				{
					item.ExecutionTime += num;
				}
			}
		}

		[Conditional("DEBUG")]
		private void CheckCallFrameDefinitions()
		{
			IDictionary<int, CpuProfileCallFrameDefinition> dictionary = callFrames.ToDictionary((CpuProfileCallFrameDefinition k) => k.ExecutionIndex);
			PooledDictionary<SnapshotLineDefinition, (int, int)> instance = PooledDictionary<SnapshotLineDefinition, (int, int)>.GetInstance();
			try
			{
				foreach (CpuProfileCallFrameDefinition callFrame in callFrames)
				{
					if (callFrame.CalledFrameIndexes != null)
					{
						foreach (int calledFrameIndex in callFrame.CalledFrameIndexes)
						{
							DebugAssertHelper.Assert(dictionary.ContainsKey(calledFrameIndex), $"Index {calledFrameIndex} is an unaccounted child for frame {callFrame.ExecutionIndex}, line {callFrame.LineDefinition}");
						}
					}
					if (methodContexts[callFrame.ExecutionIndex].LineContextsLength > 0)
					{
						if (instance.ContainsKey(callFrame.LineDefinition))
						{
							(int, int) tuple = instance[callFrame.LineDefinition];
							instance[callFrame.LineDefinition] = (tuple.Item1 + callFrame.HitCount, tuple.Item2);
						}
						else
						{
							instance[callFrame.LineDefinition] = (callFrame.HitCount, callFrame.ExecutionIndex);
						}
					}
				}
				foreach (KeyValuePair<SnapshotLineDefinition, (int, int)> item in instance)
				{
					if (linesWithHits.TryGetValue(item.Key, out (int, PositionTickInfo) value))
					{
						DebugAssertHelper.Assert(value.Item2?.Ticks == item.Value.Item1, $"The  hit count for frame  {item.Value.Item2} starting on line {item.Key} does not match the statement hit count");
					}
				}
			}
			finally
			{
				instance.Free();
			}
		}

		private void TraverseLinesAndCreateCalledFrameIndexes(int index, int nextSiblingIndex, ApplicationObjectIdWrapper appId, CpuProfileCallFrameDefinition cpuProfileCallFrameDefinition, Dictionary<SnapshotLineDefinition, int> linesWithIndexes)
		{
			MethodContext methodContext = methodContexts[index];
			PooledHashSet<SnapshotLineDefinition> instance = PooledHashSet<SnapshotLineDefinition>.GetInstance();
			PooledHashSet<int> instance2 = PooledHashSet<int>.GetInstance();
			try
			{
				for (int i = 0; i < methodContext.LineContextsLength; i++)
				{
					Microsoft.Dynamics.Nav.AL.Common.SnapshotDebuggerSerializer.LineContext? lineContext = methodContext.LineContexts(i);
					if (!lineContext.HasValue)
					{
						continue;
					}
					Microsoft.Dynamics.Nav.DebuggerService.SourceSpan? sourceSpan = lineContext.Value.StatementSpan.FromBufferedSourceSpan();
					if (!sourceSpan.HasValue)
					{
						continue;
					}
					SnapshotLineDefinition snapshotLineDefinition = new SnapshotLineDefinition
					{
						StatementSpan = sourceSpan.Value,
						Id = appId
					};
					if (instance.Add(snapshotLineDefinition))
					{
						if (!linesWithIndexes.ContainsKey(snapshotLineDefinition))
						{
							linesWithIndexes.Add(snapshotLineDefinition, index);
						}
						IList<int> calledIndexesForLine = GetCalledIndexesForLine(index, nextSiblingIndex, snapshotLineDefinition);
						if (calledIndexesForLine.Count > 0)
						{
							instance2.AddAll(calledIndexesForLine);
						}
					}
					UpdateStatementExecutionTimeAndLineHitCount(snapshotLineDefinition, index);
				}
				IEnumerable<int> collection = from c in instance2.ToList()
					orderby c
					select c;
				cpuProfileCallFrameDefinition.CalledFrameIndexes.AddRange(collection);
			}
			finally
			{
				instance2.Free();
				instance.Free();
			}
		}

		private void UpdateStatementExecutionTimeAndLineHitCount(SnapshotLineDefinition lineDefinition, int index)
		{
			if (linesWithHits.TryGetValue(lineDefinition, out (int, PositionTickInfo) value))
			{
				value.Item2.Ticks++;
				return;
			}
			linesWithHits.Add(lineDefinition, (index, new PositionTickInfo
			{
				Line = lineDefinition.StatementSpan.From.Line,
				Column = lineDefinition.StatementSpan.From.Column,
				Ticks = 1,
				ExecutionTime = 0L
			}));
		}

		private IList<int> GetCalledIndexesForLine(int startIndex, int endIndex, SnapshotLineDefinition lineDefinition)
		{
			PooledList<int> instance = PooledList<int>.GetInstance();
			try
			{
				SnapshotLineDefinition snapshotLineDefinition = null;
				for (int i = startIndex; i <= endIndex; i++)
				{
					if (methodContextsToCallerAndCalledLineDefinition.TryGetValue(i, out (SnapshotLineDefinition, SnapshotLineDefinition) value))
					{
						if (value.Item1 == lineDefinition && value.Item2 != snapshotLineDefinition)
						{
							instance.Add(i);
						}
						snapshotLineDefinition = value.Item2;
					}
				}
				return instance.ToArray();
			}
			finally
			{
				instance.Free();
			}
		}

		private static int ToProfileIndex(int executionIndex)
		{
			return executionIndex + 1;
		}

		private static ParallelOptions GetParallelOptions(int length)
		{
			return new ParallelOptions
			{
				MaxDegreeOfParallelism = ((length > Environment.ProcessorCount || length == 0) ? Environment.ProcessorCount : length)
			};
		}

		private void AggregateHitCountAndExecutionTime(CpuProfileCallFrameDefinition from, CpuProfileCallFrameDefinition to, bool aggregateExecutionTime, bool aggregateHitCounts)
		{
			if (from.ExecutionIndex != to.ExecutionIndex)
			{
				if (aggregateHitCounts)
				{
					to.HitCount += from.HitCount;
					to.HitIndexes.AddAll(from.HitIndexes);
				}
				if (aggregateExecutionTime)
				{
					to.AggregatedExecutionTime += from.AggregatedExecutionTime;
				}
			}
		}

		private static int CreateCallFrameIdentifier(CpuProfileCallFrameDefinition cpuProfileCallFrameDefinition)
		{
			int num = cpuProfileCallFrameDefinition.GetHashCode();
			CpuProfileCallFrameDefinition parentCallerFrameDefinition = cpuProfileCallFrameDefinition.ParentCallerFrameDefinition;
			while (parentCallerFrameDefinition != null)
			{
				num = Hash.Combine(num, parentCallerFrameDefinition.GetHashCode());
				parentCallerFrameDefinition = parentCallerFrameDefinition.ParentCallerFrameDefinition;
			}
			return num;
		}

		private long GetExecutionTime(int index)
		{
			MethodContext methodContext = methodContexts[index];
			return (methodContext.ExecutionSpan?.EndTime - methodContext.ExecutionSpan?.StartTime).GetValueOrDefault();
		}

		private void SendProgressNotificationResponseFromGeneratingProfileNodes(int counter)
		{
			if (callFrames.Count != 0 && (counter == callFrames.Count / 4 || counter == callFrames.Count / 2 || counter == 3 * callFrames.Count / 4))
			{
				SendProgressNotificationResponse(75 + 5 * counter / callFrames.Count);
			}
		}
	}
	public sealed class DependencyPackageOutputter
	{
		private readonly VsCodeWorkspace workspace;

		internal DependencyPackageOutputter(VsCodeWorkspace workspace)
		{
			this.workspace = workspace;
		}

		internal void CreateDependencyOutputPackage(IFileSystem fileSystem, IList<(ProjectId Id, string Path)> outputFiles, Project currentProject, string currentProjectOutputFile)
		{
			Solution currentSolution = workspace.CurrentSolution;
			string path = CreateDependentOutputFileName(currentProjectOutputFile);
			using Stream stream = fileSystem.CreateFile(path);
			using NavAppPackageWriter writer = NavAppPackageWriter.Create(stream);
			ArrayBuilder<ProjectDependencyModelDefinition> instance = ArrayBuilder<ProjectDependencyModelDefinition>.GetInstance(outputFiles.Count);
			try
			{
				foreach (var outputFile in outputFiles)
				{
					Project project = currentSolution.GetProject(outputFile.Id);
					ProjectDependencyModelDefinition item = CreateProjectDependencyModelDefinition(project);
					instance.Add(item);
					AddPackage(fileSystem, writer, outputFile.Path, project.ProjectDefinition.Name);
				}
				AddPackage(fileSystem, writer, currentProjectOutputFile, currentProject.ProjectDefinition.Name);
				ProjectDependencyModelDefinition startupProject = CreateProjectDependencyModelDefinition(currentProject);
				AddProjectDependencySet(writer, instance.ToArray(), startupProject);
			}
			finally
			{
				instance.Free();
			}
		}

		private static void AddProjectDependencySet(NavAppPackageWriter writer, ProjectDependencyModelDefinition[] projectDependencyModelDefinitions, ProjectDependencyModelDefinition startupProject)
		{
			ProjectDependencySet value = new ProjectDependencySet
			{
				ProjectReferences = projectDependencyModelDefinitions,
				StartupProject = startupProject
			};
			using StringWriter stringWriter = new StringWriter(CultureInfo.InvariantCulture);
			Newtonsoft.Json.JsonSerializer.Create(SymbolReferenceJsonWriter.StandardSerializerSettings).Serialize(stringWriter, value);
			writer.WriteString(stringWriter.GetStringBuilder().ToString(), "/projectDependencySet.json");
		}

		private static void AddPackage(IFileSystem fileSystem, NavAppPackageWriter writer, string filePath, string packageName)
		{
			if (fileSystem.Exists(filePath))
			{
				using (Stream stream = fileSystem.OpenFile(filePath, FileMode.Open, FileAccess.Read))
				{
					writer.WriteStream(stream, PackageCommon.CreateDependencyPackageName(packageName));
				}
			}
		}

		private ProjectModelDefinition[] CreateProjectModelDefinition(IList<ProjectId> projectIds)
		{
			ArrayBuilder<ProjectModelDefinition> instance = ArrayBuilder<ProjectModelDefinition>.GetInstance(projectIds.Count);
			try
			{
				foreach (ProjectId projectId in projectIds)
				{
					ProjectModelDefinition projectModelDefinition = workspace.CreateProjectModelDefinition(projectId);
					if (projectModelDefinition != null)
					{
						instance.Add(projectModelDefinition);
					}
				}
				return instance.ToArray();
			}
			finally
			{
				instance.Free();
			}
		}

		private ProjectDependencyModelDefinition CreateProjectDependencyModelDefinition(Project project)
		{
			DebugAssertHelper.Assert(project != null);
			ProjectDependencyGraph projectDependencyGraph = workspace.CurrentSolution.GetProjectDependencyGraph();
			if (projectDependencyGraph == null)
			{
				return null;
			}
			return new ProjectDependencyModelDefinition
			{
				ThisProject = workspace.CreateProjectModelDefinition(project.Id),
				ProjectsThatDirectlyDependOnThisProject = CreateProjectModelDefinition(projectDependencyGraph.GetProjectsThatDirectlyDependOnThisProjectTopologicallySorted(project.Id)),
				ProjectsThatThisProjectDirectlyDependsOn = CreateProjectModelDefinition(projectDependencyGraph.GetProjectsThatThisProjectDirectlyDependsOnTopologicallySorted(project.Id)),
				ProjectsThatThisProjectTransitivelyDependsOn = CreateProjectModelDefinition(projectDependencyGraph.GetProjectsThatThisProjectTransitivelyDependsOnTopologicallySorted(project.Id)),
				ProjectsThatTransitivelyDependOnThisProject = CreateProjectModelDefinition(projectDependencyGraph.GetProjectsThatTransitivelyDependOnThisProjectTopologicallySorted(project.Id))
			};
		}

		internal static string CreateDependentOutputFileName(string outputFile)
		{
			string? directoryName = Path.GetDirectoryName(outputFile);
			string? fileNameWithoutExtension = Path.GetFileNameWithoutExtension(outputFile);
			string extension = Path.GetExtension(outputFile);
			string path = fileNameWithoutExtension + ".dep" + extension;
			return Path.Combine(directoryName, path);
		}
	}
	internal static class DocumentHelper
	{
		internal static async Task<(ApplicationObjectIdWrapper? ApplicationObjectId, Position position)> GetDeclaringApplicationObjectAndAdjustLineNumberFromServerPositionsAsync(this Document document, Position position, CancellationToken cancellationToken)
		{
			(ApplicationObjectIdWrapper?, ApplicationObjectSyntax) obj = await document.GetDeclaringApplicationObjectAsync(position, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
			ApplicationObjectIdWrapper? item = obj.Item1;
			ApplicationObjectSyntax item2 = obj.Item2;
			Position position2 = Position.Create(position);
			if (item2 != null)
			{
				int? debuggerLineOffsetForNode = item2.GetDebuggerLineOffsetForNode();
				if (debuggerLineOffsetForNode.HasValue)
				{
					int num = position.Line - debuggerLineOffsetForNode.Value;
					position2.Line = item2.Location.GetMappedLineSpan().StartLinePosition.Line + num;
				}
			}
			return (ApplicationObjectId: item, position: position2);
		}

		internal static async Task<(ApplicationObjectIdWrapper? ApplicationObjectId, Position position)> GetDeclaringApplicationObjectAndAdjustLineNumberFromDebugClientPositionsAsync(this Document document, Position position, CancellationToken cancellationToken)
		{
			(ApplicationObjectIdWrapper?, ApplicationObjectSyntax) obj = await document.GetDeclaringApplicationObjectAsync(position, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
			ApplicationObjectIdWrapper? item = obj.Item1;
			ApplicationObjectSyntax item2 = obj.Item2;
			Position position2 = Position.Create(position);
			if (item2 != null)
			{
				int? debuggerLineOffsetForNode = item2.GetDebuggerLineOffsetForNode();
				if (debuggerLineOffsetForNode.HasValue)
				{
					int num = position.Line - item2.Location.GetMappedLineSpan().StartLinePosition.Line;
					position2.Line = debuggerLineOffsetForNode.Value + num;
				}
			}
			return (ApplicationObjectId: item, position: position2);
		}

		private static async Task<(ApplicationObjectIdWrapper? applicationObjectId, ApplicationObjectSyntax? syntax)> GetDeclaringApplicationObjectAsync(this Document document, Position position, CancellationToken cancellationToken)
		{
			IList<ApplicationObjectSyntax> syntaxes = await document.GetDeclaredApplicationObjectSyntaxesAsync(cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
			if (syntaxes.Count == 0)
			{
				return (applicationObjectId: null, syntax: null);
			}
			LinePosition linePosition = new LinePosition(position.Line, position.Character);
			int position2 = await document.GetPositionAsync(linePosition, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
			for (int i = 0; i < syntaxes.Count; i++)
			{
				ApplicationObjectSyntax applicationObjectSyntax = syntaxes[i];
				if (applicationObjectSyntax.Span.Contains(position2))
				{
					ObjectTypeWrapper? objectTypeWrapper = DebugHelper.MapToObjectType(applicationObjectSyntax.Kind);
					if (objectTypeWrapper.HasValue)
					{
						return (applicationObjectId: new ApplicationObjectIdWrapper(objectTypeWrapper.Value, applicationObjectSyntax.ObjectId.GetObjectIdOrDefault()), syntax: applicationObjectSyntax);
					}
				}
			}
			return (applicationObjectId: null, syntax: null);
		}
	}
	internal class RequestRegistry : IDisposable
	{
		private readonly IDictionary<string, IRequestHandler> handlers = new Dictionary<string, IRequestHandler>(StringComparer.OrdinalIgnoreCase);

		private readonly MessageProtocolType protocolType;

		public readonly IResponseQueue ResponseQueue;

		private bool isDisposed;

		private static readonly System.TimeSpan SlowRequestThreshold = System.TimeSpan.FromMilliseconds(300.0);

		internal RequestRegistry(MessageProtocolType protocolType, IResponseQueue ResponseQueue)
		{
			this.protocolType = protocolType;
			this.ResponseQueue = ResponseQueue;
		}

		public void Dispose()
		{
			if (isDisposed)
			{
				return;
			}
			foreach (IRequestHandler value in handlers.Values)
			{
				if (value is IDisposable disposable)
				{
					disposable.Dispose();
				}
			}
			isDisposed = true;
		}

		internal void AddHandler(IRequestHandler handler)
		{
			handlers.Add(handler.EndpointName, handler);
		}

		internal async Task Process(Message message)
		{
			if (message.MessageKind == MessageKind.Response)
			{
				return;
			}
			if (!handlers.TryGetValue(message.Method, out IRequestHandler handler))
			{
				ExternalTelemetryLogger.TrackError("Unhandled message: {0}", message.Method);
				return;
			}
			try
			{
				LocalMachineLogger.LogVerbose("Process:\r\n\r\n {0}", message.Method);
				CancellationToken requestCancellationToken = ResponseQueue.GetRequestCancellationToken(message.Id);
				try
				{
					await handler.HandleAsync(message.Contents, message.Id, requestCancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				}
				finally
				{
					if (handler.ProfilePerformance)
					{
						ExternalTelemetryLogger.TrackEvent(handler.GetCustomTelemetryForRequest(message.Id));
					}
					ResponseQueue.UnregisterCancellationTokenSource(message.Id);
					handler.DisposeCustomTelemetryEventForRequest(message.Id);
				}
			}
			catch (OperationCanceledException)
			{
			}
			catch (Exception e)
			{
				LoggingUtilities.WriteMessageFailedException(message.Method, e);
				SendInternalExceptionInformation(message.Method, message.Id, e);
			}
		}

		private void SendInternalExceptionInformation(string methodId, int requestId, Exception e)
		{
			Response response = ((!ShouldReturnExceptionAsError(e)) ? ResponseFactory.LogNotification(MessageType.Error, LocalMachineLogger.FormatExceptionMessage(methodId, e)) : ResponseFactory.ErrorResponse(new MessageError
			{
				Message = e.Message
			}, methodId, requestId));
			ResponseQueue.Add(response);
		}

		private bool ShouldReturnExceptionAsError(Exception e)
		{
			if (e is JsonSerializationException || e is JsonReaderException)
			{
				return true;
			}
			if (protocolType == MessageProtocolType.LanguageServer)
			{
				return false;
			}
			return true;
		}
	}
