	internal static class FilePathHelper
	{
		internal static string GetFilePath(this string fileNameAsUri)
		{
			if (string.IsNullOrEmpty(fileNameAsUri))
			{
				return string.Empty;
			}
			if (!fileNameAsUri.StartsWith("file://", StringComparison.OrdinalIgnoreCase))
			{
				return fileNameAsUri;
			}
			if (!Uri.TryCreate(fileNameAsUri, UriKind.Absolute, out Uri result))
			{
				return fileNameAsUri;
			}
			string localPath = result.LocalPath;
			if (localPath.Length >= 3 && localPath[0] == '/' && localPath[2] == ':')
			{
				return localPath.Substring(1);
			}
			return localPath.Replace("\\", "/");
		}

		internal static string GetUri(this string filePath)
		{
			if (!Uri.CheckSchemeName(filePath))
			{
				filePath = "file://" + filePath;
			}
			return new Uri(filePath).AbsoluteUri;
		}

