			{
				AppId = appId,
				Id = applicationObjectId,
				Kind = symbolKind,
				Name = (string.IsNullOrEmpty(applicationObjectName) ? string.Empty : PreviewFileUrl.Escape(applicationObjectName)),
				ProjectName = (string.IsNullOrEmpty(projectPath) ? string.Empty : Uri.EscapeDataString(new DirectoryInfo(projectPath).Name))
			});
		}

		internal static string GetPreviewFileUri(PreviewFileUrl previewFileUrl)
