		internal static bool IsAlFile(this string filepath)
		{
			if (filepath.HasAlExtension())
			{
				return File.Exists(filepath);
			}
			return false;
		}

		internal static bool HasAlExtension(this string filepath)
		{
			return filepath.HasExtension(".al");
		}

		internal static bool HasExtension(this string filepath, string extension)
		{
			return string.Equals(Path.GetExtension(filepath), extension, StringComparison.OrdinalIgnoreCase);
		}

		internal static string RemoveInvalidCharactersFromFileName(string path)
		{
			HashSet<char> hashSet = new HashSet<char>();
			hashSet.AddAll(Path.GetInvalidFileNameChars());
			hashSet.AddAll(Path.GetInvalidPathChars());
			StringBuilder stringBuilder = new StringBuilder(path.Length);
			foreach (char c in path)
			{
				if (char.IsLetterOrDigit(c) && !hashSet.Contains(c))
				{
					stringBuilder.Append(c);
				}
			}
			return stringBuilder.ToString();
		}
	}
