	public static class LanguageClientCompilationOptionsExtensions
	{
		public static CompilationOptions WithLanguageClientCompilationOptions(this CompilationOptions options, LanguageClientCompilationOptions vsCodeOptions)
		{
			if (vsCodeOptions.ConcurrentBuild.HasValue)
			{
				options = options.WithConcurrentBuild(vsCodeOptions.ConcurrentBuild.Value);
			}
			if (vsCodeOptions.ConcurrencyLevel.HasValue)
			{
				int num = vsCodeOptions.ConcurrencyLevel.Value;
				if (num == 0)
				{
					num = ConcurrencyLevel.Unbounded.MaxConcurrencyLevel;
				}
				options = options.WithMaxConcurrencyLevel(new ConcurrencyLevel(num));
			}
			if (vsCodeOptions.GenerateReportLayout.HasValue)
			{
				CompilationGenerationOptions compilationGenerateOptions = options.CompilationGenerateOptions;
				options = ((!vsCodeOptions.GenerateReportLayout.Value) ? options.WithGenerationOptions(compilationGenerateOptions & ~CompilationGenerationOptions.ReportLayout) : options.WithGenerationOptions(compilationGenerateOptions | CompilationGenerationOptions.ReportLayout));
			}
			if (vsCodeOptions.CaptureSymbolUsage.HasValue)
			{
				options = options.WithCaptureSymbolUsage(vsCodeOptions.CaptureSymbolUsage.Value);
			}
			if (!string.IsNullOrEmpty(vsCodeOptions.OutFolder))
			{
				options = options.WithOutFolder(vsCodeOptions.OutFolder);
			}
			return options;
		}
	}
	public static class LanguageServerOptions
	{
		public static LogLevel LogLevel { get; private set; }

		public static string LogPath { get; private set; }

		public static EnvironmentInfo EnvironmentInfo { get; private set; }

		public static string ProjectRoot { get; private set; }

		public static BrowserInfo BrowserInfo { get; private set; }

		public static void Init(LogLevel logLevel, string logPath, EnvironmentInfo environmentInfo, string projectRoot, BrowserInfo browserInfo)
		{
			LogLevel = logLevel;
			LogPath = logPath;
			EnvironmentInfo = environmentInfo;
			ProjectRoot = projectRoot;
			BrowserInfo = browserInfo;
		}
	}
	public sealed class DiagnosticService : IDiagnosticService, IProjectClosureCompilation, IDisposable
	{
		private bool usePartialDiagnostics;

		private int documentCount;

		private const long TimeOutBetweenProjectClosureLoadCalls = 200L;

		private readonly NonReentrantLock partialEmitCancellationMutex = new NonReentrantLock(useThisInstanceForSynchronization: true);

		private readonly NonReentrantLock projectClosureCompilationCancellationMutex = new NonReentrantLock(useThisInstanceForSynchronization: true);

		private readonly NonReentrantLock projectsToCompileSetLock = new NonReentrantLock();

		private readonly DiagnosticServiceOptions options;

		private readonly VsCodeWorkspace workspace;

		private readonly AutoResetEvent? diagnosticThreadExecuted;

		private readonly System.Threading.Thread partialDiagnostics;

		private readonly System.Threading.Thread projectClosureDiagnostics;

		private readonly bool allowInMemoryFiles;

		private readonly ManualResetEventSlim stopDiagnostics = new ManualResetEventSlim(initialState: true);

		private AutoResetEvent? bufferChangeFlag;

		private AutoResetEvent? projectClosureCompilationFlag;

		private CancellationTokenSource? cancellationTokenSource;

		private CancellationTokenSource partialEmitCancellationTokenSource;

		private CancellationTokenSource projectClosureCompilationCancellationTokenSource;

		private bool isStopped;

		private int projectHasChanged;

		private int forceStart;

		private readonly IDictionary<string, int> vsCodeDiagnosticState;

		private long lastChangeTick;

		private const int ThreadWaitTime = 500;

		private readonly HashSet<ProjectId> projectsToCompile = new HashSet<ProjectId>();

		private ProjectId currentProjectId = ProjectId.Empty;

		private readonly ConcurrentDictionary<ProjectId, ProjectCompilationStatus> projectCompilationStatus = new ConcurrentDictionary<ProjectId, ProjectCompilationStatus>();

		private readonly Lazy<ConcurrentDictionary<DocumentId, AnalysisDiagnosticCacheEntry?>> moduleAnalyzerDiagnosticsCache = new Lazy<ConcurrentDictionary<DocumentId, AnalysisDiagnosticCacheEntry>>(() => new ConcurrentDictionary<DocumentId, AnalysisDiagnosticCacheEntry>(2, 5));

		private long globalWorkspaceVersion;

		private long projectClosureCompilationVersion;

		private int activeFileChanged;

		private CancellationToken bufferChangesCancellationToken => projectClosureCompilationCancellationTokenSource.Token;

		private CancellationToken projectClosureCompilationCancellationToken => partialEmitCancellationTokenSource.Token;

		internal long GlobalWorkspaceVersion => Interlocked.Read(ref globalWorkspaceVersion);

		internal long ProjectClosureCompilationVersion => Interlocked.Read(ref projectClosureCompilationVersion);

		private IResponseQueue ResponseQueue { get; }

		public event EventHandler<ProjectClosureLoadedEventArgs>? ProjectClosureLoaded;

		internal DiagnosticService(VsCodeWorkspace workspace, ResponseQueue responseQueue, DiagnosticServiceOptions options, bool allowInMemoryFiles = false, AutoResetEvent? diagnosticThreadExecuted = null)
		{
			this.options = options;
			this.workspace = workspace;
			ResponseQueue = responseQueue;
			this.allowInMemoryFiles = allowInMemoryFiles;
			this.diagnosticThreadExecuted = diagnosticThreadExecuted;
			bufferChangeFlag = new AutoResetEvent(initialState: false);
			projectClosureCompilationFlag = new AutoResetEvent(initialState: false);
			vsCodeDiagnosticState = new ConcurrentDictionary<string, int>();
			cancellationTokenSource = CreateNewTokenSource(cancellationTokenSource);
			projectClosureCompilationCancellationTokenSource = CreateNewTokenSource(projectClosureCompilationCancellationTokenSource);
			partialEmitCancellationTokenSource = CreateNewTokenSource(partialEmitCancellationTokenSource);
			this.workspace.WorkspaceChanged += OnWorkspaceChanged;
			if (partialDiagnostics == null)
			{
				partialDiagnostics = new System.Threading.Thread(ListenForBufferChanges)
				{
					Name = "DiagnosticService"
				};
			}
			if (partialDiagnostics.ThreadState != 0)
			{
				partialDiagnostics.Start();
			}
			if (projectClosureDiagnostics == null)
			{
				projectClosureDiagnostics = new System.Threading.Thread(ListenForProjectClosureCompilation)
				{
					Name = "DiagnosticServiceProjectClosure"
				};
			}
			if (projectClosureDiagnostics.ThreadState != 0)
			{
				projectClosureDiagnostics.Start();
			}
		}

		public void Start(bool forceNewCompilation = false)
		{
			ClearPartialAnalysisState();
			if (forceNewCompilation)
			{
				AllowProjectClosureThreadCompilation();
			}
			stopDiagnostics.Set();
		}

		public void Stop()
		{
			ClearPartialAnalysisState();
			if (!isStopped)
			{
				CancelAllPendingDiagnosticRuns();
				stopDiagnostics.Reset();
				isStopped = true;
			}
		}

		public void Dispose()
		{
			Stop();
			workspace.WorkspaceChanged -= OnWorkspaceChanged;
			cancellationTokenSource?.Cancel();
			partialEmitCancellationTokenSource?.Cancel();
			projectClosureCompilationCancellationTokenSource?.Cancel();
			bufferChangeFlag?.Set();
			projectClosureCompilationFlag?.Set();
			partialDiagnostics?.Join(500);
			projectClosureDiagnostics?.Join(500);
			partialEmitCancellationTokenSource?.Dispose();
			partialEmitCancellationTokenSource = null;
			projectClosureCompilationCancellationTokenSource?.Dispose();
			projectClosureCompilationCancellationTokenSource = null;
			cancellationTokenSource?.Dispose();
			cancellationTokenSource = null;
			bufferChangeFlag?.Dispose();
			bufferChangeFlag = null;
			projectClosureCompilationFlag?.Dispose();
			projectClosureCompilationFlag = null;
		}

		public void CancelAllPendingDiagnosticRuns()
		{
			CancelPreviousBufferChangesDiagnosticCallAndRecreate();
			CancelPreviousProjectClosureCompilationAndRecreate();
		}

		public void SetCurrentProjectClosureRoot(ProjectId currentProjectId)
		{
			if (currentProjectId == null)
			{
				return;
			}
			Interlocked.Exchange(ref this.currentProjectId, currentProjectId);
			if (!projectCompilationStatus.TryGetValue(currentProjectId, out ProjectCompilationStatus value) || value != ProjectCompilationStatus.Compiled)
			{
				if (this.currentProjectId != ProjectId.Empty && this.currentProjectId != currentProjectId)
				{
					AddOrUpdateProjectCompilationStatus(this.currentProjectId, ProjectClosureCompilationStatus.Added);
				}
				UpdateProjectsToCompile(currentProjectId);
			}
		}

		public void AddToProjectClosureCompilation(ProjectId dependentProjectId)
		{
			UpdateProjectsToCompile(dependentProjectId);
		}

		public void AllowProjectClosureThreadCompilation()
		{
			Interlocked.Exchange(ref forceStart, 1);
			AllowProjectClosureToCompile();
		}

		public void CancelClosureCompilation(ProjectId id)
		{
			if (projectCompilationStatus.TryGetValue(id, out ProjectCompilationStatus value) && value.CompilationStatus == ProjectClosureCompilationStatus.Compiling)
			{
				CancelPreviousProjectClosureCompilationAndRecreate();
			}
		}

		public ProjectClosureCompilationStatus GetProjectClosureCompilationStatus(ProjectId id)
		{
			if (projectCompilationStatus.TryGetValue(id, out ProjectCompilationStatus value))
			{
				return value.CompilationStatus;
			}
			return ProjectClosureCompilationStatus.Undefined;
		}

		public bool HasProjectLoaded(ProjectId id)
		{
			if (projectCompilationStatus.TryGetValue(id, out ProjectCompilationStatus value))
			{
				return value.HasLoaded;
			}
			return false;
		}

		private void OnWorkspaceChanged(object sender, WorkspaceChangeEventArgs changeEvent)
		{
			Interlocked.Exchange(ref lastChangeTick, DateTime.UtcNow.Ticks);
			switch (changeEvent.Kind)
			{
			case WorkspaceChangeKind.DocumentAdded:
				documentCount++;
				if (documentCount > options.PartialDiagnosticsDocumentThreshold)
				{
					usePartialDiagnostics = true;
				}
				goto case WorkspaceChangeKind.DocumentReloaded;
			case WorkspaceChangeKind.DocumentReloaded:
			case WorkspaceChangeKind.DocumentChanged:
				UpdateProjectsToCompile(changeEvent.ProjectId);
				Interlocked.Increment(ref globalWorkspaceVersion);
				if (CanAllowWorkspaceChangeTriggeredCompilation(changeEvent.ProjectId))
				{
					CancelPreviousBufferChangesDiagnosticCallAndRecreate();
					AllowBufferChangeBasedCompilation();
				}
				break;
			case WorkspaceChangeKind.ActiveDocumentChanged:
				if (CanAllowWorkspaceChangeTriggeredCompilation(changeEvent.ProjectId))
				{
					Interlocked.Exchange(ref activeFileChanged, 1);
					AllowBufferChangeBasedCompilation();
				}
				break;
			case WorkspaceChangeKind.DocumentRemoved:
			{
				documentCount--;
				if (documentCount <= options.PartialDiagnosticsDocumentThreshold)
				{
					usePartialDiagnostics = false;
					ClearPartialAnalysisState();
				}
				Interlocked.Increment(ref globalWorkspaceVersion);
				string uri = changeEvent.OldSolution.GetDocument(changeEvent.DocumentId).FilePath.GetUri();
				ResponseQueue.Add(ResponseFactory.PublishDiagnostics(uri, ImmutableArray<Diagnostic>.Empty));
				if (vsCodeDiagnosticState.ContainsKey(uri))
				{
					vsCodeDiagnosticState.Remove(uri);
				}
				if (moduleAnalyzerDiagnosticsCache.IsValueCreated)
				{
					moduleAnalyzerDiagnosticsCache.Value.TryRemove(changeEvent.DocumentId, out AnalysisDiagnosticCacheEntry _);
				}
				break;
			}
			case WorkspaceChangeKind.ProjectChanged:
				UpdateProjectsToCompile(changeEvent.ProjectId);
				if (CanAllowWorkspaceChangeTriggeredCompilation(changeEvent.ProjectId))
				{
					Interlocked.Exchange(ref projectHasChanged, 1);
					AllowProjectClosureToCompile();
				}
				break;
			case WorkspaceChangeKind.ProjectReloaded:
			case WorkspaceChangeKind.AdditionalDocumentAdded:
			case WorkspaceChangeKind.AdditionalDocumentRemoved:
			case WorkspaceChangeKind.AdditionalDocumentReloaded:
			case WorkspaceChangeKind.AdditionalDocumentChanged:
				break;
			}
		}

		private void UpdateProjectsToCompile(ProjectId? projectId)
		{
			if (projectId != null && projectId != ProjectId.Empty)
			{
				using (projectsToCompileSetLock.DisposableWait())
				{
					projectsToCompile.Add(projectId);
				}
			}
		}

		private async void ListenForBufferChanges()
		{
			CancellationToken token = cancellationTokenSource?.Token ?? CancellationToken.None;
			while (bufferChangeFlag != null && !bufferChangeFlag.WaitOne(500) && !token.IsCancellationRequested)
			{
			}
			if (token.IsCancellationRequested)
			{
				return;
			}
			bool flag = false;
			long localVersion = 0L;
			while (!token.IsCancellationRequested)
			{
				WaitOnStopFlag(token, out var threadCancelled);
				if (threadCancelled)
				{
					break;
				}
				bool flag2 = localVersion < GlobalWorkspaceVersion;
				if (DateTime.UtcNow.Ticks - lastChangeTick > options.DelayAfterLastDocumentChange.Ticks && (flag || flag2 || activeFileChanged == 1))
				{
					long previousLocalVersion = localVersion;
					localVersion = GlobalWorkspaceVersion;
					Interlocked.Exchange(ref activeFileChanged, 0);
					bool flag3 = ProjectClosureCompilationVersion < GlobalWorkspaceVersion;
					if (flag3)
					{
						CancelPreviousProjectClosureCompilationAndRecreate();
					}
					bool changesHappened = flag || flag2;
					if (usePartialDiagnostics)
					{
						if (ShouldEmitDiagnosticsForCurrentDocument(changesHappened, out DocumentId currentDocumentId))
						{
							flag = await EmitCurrentDocumentDiagnostics(currentDocumentId).ConfigureAwait(continueOnCapturedContext: false);
							if (flag)
							{
								localVersion = previousLocalVersion;
							}
						}
					}
					else if (flag3)
					{
						Interlocked.Exchange(ref forceStart, 1);
						projectClosureCompilationFlag?.Set();
					}
				}
				bufferChangeFlag?.WaitOne(500);
			}
		}

		private bool ShouldEmitDiagnosticsForCurrentDocument(bool changesHappened, out DocumentId? currentDocumentId)
		{
			currentDocumentId = workspace.CurrentDocumentId;
			if ((object)currentDocumentId == null)
			{
				return false;
			}
			if (changesHappened)
			{
				return true;
			}
			Project? projectFromDocument = GetProjectFromDocument(currentDocumentId);
			if (projectFromDocument == null)
			{
				return false;
			}
			return projectFromDocument.BackgroundCodeAnalysisScope == BackgroundCodeAnalysisScope.File;
		}

		private void WaitOnStopFlag(CancellationToken token, out bool threadCancelled)
		{
			threadCancelled = false;
			try
			{
				stopDiagnostics.Wait(token);
			}
			catch (Exception ex) when (ex is OperationCanceledException || ex is ObjectDisposedException)
			{
				threadCancelled = true;
			}
		}

		private void CancelPreviousBufferChangesDiagnosticCallAndRecreate()
		{
			using (partialEmitCancellationMutex.DisposableWait())
			{
				partialEmitCancellationTokenSource = CreateNewTokenSource(partialEmitCancellationTokenSource);
			}
		}

		private void CancelPreviousProjectClosureCompilationAndRecreate()
		{
			using (projectClosureCompilationCancellationMutex.DisposableWait())
			{
				projectClosureCompilationCancellationTokenSource = CreateNewTokenSource(projectClosureCompilationCancellationTokenSource);
			}
		}

		private static CancellationTokenSource CreateNewTokenSource(CancellationTokenSource? tokenSource)
		{
			if (tokenSource != null)
			{
				tokenSource.Cancel();
				tokenSource.Dispose();
			}
			return new CancellationTokenSource();
		}

		private async Task<bool> EmitDiagnosticsForProjectsAndActiveDocument(Solution solution, ProjectId currentProjectId, ISet<ProjectId> projectsToCompile, CancellationToken cancellationToken)
		{
			PooledStopwatch stopwatch = ExternalTelemetryLogger.BeginOperation();
			try
			{
				bool forcePartialAnalysis = !AddOrUpdateProjectCompilationStatus(currentProjectId, ProjectClosureCompilationStatus.Compiling).HasLoaded;
				PartialCodeAnalysisOptions partialCodeAnalysisOptions = new PartialCodeAnalysisOptions(usePartialDiagnostics, forcePartialAnalysis, options.PartialDiagnosticsDocumentThreshold);
				ConcurrentDictionary<DocumentId, AnalysisDiagnosticCacheEntry> moduleDiagnosticsCache = (partialCodeAnalysisOptions.UsePartialAnalysis ? moduleAnalyzerDiagnosticsCache.Value : null);
				(PublishDiagnosticsResponse[], bool) tuple = await DiagnosticsProvider.GetDiagnosticsForProjects(solution, projectsToCompile, cancellationToken, allowInMemoryFiles, partialCodeAnalysisOptions, moduleDiagnosticsCache).ConfigureAwait(continueOnCapturedContext: false);
				if (!tuple.Item2 && usePartialDiagnostics)
				{
					tuple = await MergeActiveDocumentDetailedAnalyzerDiagnostics(tuple.Item1, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				}
				if (!tuple.Item2)
				{
					EmitDiagnostics(tuple.Item1, cancellationToken);
					AddOrUpdateProjectCompilationStatus(currentProjectId, ProjectClosureCompilationStatus.Compiled);
					this.ProjectClosureLoaded?.Invoke(this, new ProjectClosureLoadedEventArgs(currentProjectId));
					ResponseQueue?.Add(ResponseFactory.ProgressNotification(new ProgressNotificatonResponse
					{
						Percent = 100,
						Owner = ProgressNotificationOwner.OpenWorkspace
					}));
				}
				else
				{
					AddOrUpdateProjectCompilationStatus(currentProjectId, ProjectClosureCompilationStatus.Canceled);
				}
				return tuple.Item2;
			}
			catch (OperationCanceledException)
			{
				return true;
			}
			finally
			{
				diagnosticThreadExecuted?.Set();
				ExternalTelemetryLogger.EndOperation("ProjectClosureCompilationDiagnostics", stopwatch, options.SlowDiagnosticsThreshold);
			}
		}

		private ProjectCompilationStatus AddOrUpdateProjectCompilationStatus(ProjectId id, ProjectClosureCompilationStatus status)
		{
			ProjectCompilationStatus value;
			ProjectCompilationStatus projectCompilationStatus = ((!this.projectCompilationStatus.TryGetValue(id, out value)) ? ProjectCompilationStatus.Create(status) : value.TransitionTo(status));
			this.projectCompilationStatus[id] = projectCompilationStatus;
			return projectCompilationStatus;
		}

		private async Task<bool> EmitCurrentDocumentDiagnostics(DocumentId documentId)
		{
			try
			{
				CancellationToken cancellationToken = bufferChangesCancellationToken;
				if (cancellationToken.IsCancellationRequested)
				{
					return true;
				}
				(PublishDiagnosticsResponse[], bool) tuple = await GetDocumentDiagnostics(documentId, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				if (!tuple.Item2)
				{
					EmitDiagnostics(tuple.Item1, cancellationToken);
				}
			}
			catch (OperationCanceledException)
			{
				return true;
			}
			finally
			{
				diagnosticThreadExecuted?.Set();
			}
			return false;
		}

		private async Task<(PublishDiagnosticsResponse[] Diagnostics, bool Cancelled)> GetDocumentDiagnostics(DocumentId? documentId, CancellationToken cancellationToken)
		{
			try
			{
				if ((object)documentId == null)
				{
					return (Diagnostics: Array.Empty<PublishDiagnosticsResponse>(), Cancelled: false);
				}
				ProtocolDiagnostic[] precalculatedDiagnostics = null;
				if (moduleAnalyzerDiagnosticsCache.IsValueCreated && moduleAnalyzerDiagnosticsCache.Value.TryGetValue(documentId, out AnalysisDiagnosticCacheEntry value) && value != null)
				{
					precalculatedDiagnostics = value.Diagnostics;
				}
				(PublishDiagnosticsResponse[], bool) result = await DiagnosticsProvider.GetDocumentDiagnostics(workspace.CurrentSolution, documentId, cancellationToken, allowInMemoryFiles, precalculatedDiagnostics).ConfigureAwait(continueOnCapturedContext: false);
				if (result.Item2)
				{
					return (Diagnostics: Array.Empty<PublishDiagnosticsResponse>(), Cancelled: true);
				}
				return result;
			}
			catch (OperationCanceledException)
			{
				return (Diagnostics: Array.Empty<PublishDiagnosticsResponse>(), Cancelled: true);
			}
		}

		private async void ListenForProjectClosureCompilation()
		{
			CancellationToken token = cancellationTokenSource?.Token ?? CancellationToken.None;
			while (projectClosureCompilationFlag != null && !projectClosureCompilationFlag.WaitOne(500) && !token.IsCancellationRequested)
			{
			}
			if (token.IsCancellationRequested)
			{
				return;
			}
			bool flag = false;
			while (!token.IsCancellationRequested)
			{
				WaitOnStopFlag(token, out var threadCancelled);
				if (threadCancelled)
				{
					break;
				}
				bool flag2 = projectClosureCompilationVersion < GlobalWorkspaceVersion;
				bool hasProjectChanged = projectHasChanged == 1;
				bool flag3 = forceStart == 1;
				bool flag4 = DateTime.UtcNow.Ticks - lastChangeTick > options.DelayAfterLastProjectChange.Ticks;
				if ((usePartialDiagnostics && flag4 && flag2) || (flag && flag4) || hasProjectChanged || flag3)
				{
					ProjectId projectId = Interlocked.CompareExchange(ref currentProjectId, ProjectId.Empty, ProjectId.Empty);
					if (projectId == ProjectId.Empty)
					{
						projectId = workspace.CurrentProjectId;
					}
					ImmutableHashSet<ProjectId> immutableHashSet = ImmutableHashSet<ProjectId>.Empty;
					if (projectId != null && projectId != ProjectId.Empty)
					{
						using (projectsToCompileSetLock.DisposableWait())
						{
							projectsToCompile.Add(projectId);
							immutableHashSet = projectsToCompile.ToImmutableHashSet();
							projectsToCompile.Clear();
						}
					}
					CancellationToken cancellationToken = projectClosureCompilationCancellationToken;
					if (!cancellationToken.IsCancellationRequested)
					{
						(long previousClosureVersion, int previousProjectHasChanged, int previousForceStart) previousFlags = SignalCompilationAsDone();
						if ((object)projectId != null && projectId != ProjectId.Empty)
						{
							flag = await EmitDiagnosticsForProjectsAndActiveDocument(workspace.CurrentSolution, projectId, immutableHashSet, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
							if (flag)
							{
								RevertStateOnCancelledCompilation(previousFlags);
							}
						}
						else
						{
							flag = false;
						}
					}
				}
				if (!hasProjectChanged)
				{
					projectClosureCompilationFlag?.WaitOne(500);
				}
			}
		}

		private (long, int, int) SignalCompilationAsDone()
		{
			long item = Interlocked.Exchange(ref projectClosureCompilationVersion, GlobalWorkspaceVersion);
			int item2 = Interlocked.Exchange(ref projectHasChanged, 0);
			int item3 = Interlocked.Exchange(ref forceStart, 0);
			return (item, item2, item3);
		}

		private void RevertStateOnCancelledCompilation((long previousClosureVersion, int previousProjectHasChanged, int previousForceStart) flagsBeforeCompilation)
		{
			Interlocked.Exchange(ref projectClosureCompilationVersion, flagsBeforeCompilation.previousClosureVersion);
			if (flagsBeforeCompilation.previousProjectHasChanged != 0)
			{
				Interlocked.Exchange(ref projectHasChanged, flagsBeforeCompilation.previousProjectHasChanged);
			}
			if (flagsBeforeCompilation.previousForceStart != 0)
			{
				Interlocked.Exchange(ref forceStart, flagsBeforeCompilation.previousForceStart);
			}
		}

		private void AllowProjectClosureToCompile()
		{
			projectClosureCompilationFlag?.Set();
		}

		private bool AllowBufferChangeBasedCompilation()
		{
			return bufferChangeFlag?.Set() ?? false;
		}

		private bool CanAllowWorkspaceChangeTriggeredCompilation(ProjectId id)
		{
			if (projectCompilationStatus.TryGetValue(id, out ProjectCompilationStatus value) && (value == ProjectCompilationStatus.Compiled || value == ProjectCompilationStatus.CompilingAndLoaded) && workspace.AreAllProjectReferencesBound(id))
			{
				return true;
			}
			return false;
		}

		private async Task<(PublishDiagnosticsResponse[] Diagnostics, bool Cancelled)> MergeActiveDocumentDetailedAnalyzerDiagnostics(PublishDiagnosticsResponse[] responses, CancellationToken cancellationToken)
		{
			(bool ActiveDocumentNeedsMerging, DocumentId? Id, string? Uri) activeDocumentDetails = GetActiveDocumentDetails();
			if (!activeDocumentDetails.ActiveDocumentNeedsMerging || (object)activeDocumentDetails.Id == null || activeDocumentDetails.Uri == null)
			{
				return (Diagnostics: responses, Cancelled: false);
			}
			(PublishDiagnosticsResponse[], bool) tuple = await GetDocumentDiagnostics(activeDocumentDetails.Id, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
			if (tuple.Item2)
			{
				return (Diagnostics: responses, Cancelled: true);
			}
			int num = -1;
			for (int i = 0; i < responses.Length; i++)
			{
				if (string.Equals(responses[i].Uri, activeDocumentDetails.Uri, StringComparison.OrdinalIgnoreCase))
				{
					num = i;
				}
			}
			if (num == -1)
			{
				return (Diagnostics: responses, Cancelled: false);
			}
			responses[num] = tuple.Item1[0];
			_ = responses.Length;
			_ = 1;
			return (Diagnostics: responses, Cancelled: false);
		}

		[Conditional("DEBUG")]
		private static void AddDebugErrorDiagnostics(ref PublishDiagnosticsResponse[] responses, PublishDiagnosticsResponse[] currentDocumentDetailedDiagnostics)
		{
			ArrayBuilder<PublishDiagnosticsResponse> instance = ArrayBuilder<PublishDiagnosticsResponse>.GetInstance(responses.Length);
			try
			{
				instance.AddRange(responses);
				for (int i = 1; i < currentDocumentDetailedDiagnostics.Length; i++)
				{
					instance.Add(currentDocumentDetailedDiagnostics[i]);
				}
				responses = instance.ToArray();
			}
			finally
			{
				instance.Free();
			}
		}

		private void EmitDiagnostics(PublishDiagnosticsResponse[] responses, CancellationToken token)
		{
			IEnumerable<PublishDiagnosticsResponse> responses2 = FilterDiagnostics(responses, token);
			EmitAllDiagnostics(responses2);
		}

		private void EmitAllDiagnostics(IEnumerable<PublishDiagnosticsResponse> responses)
		{
			foreach (PublishDiagnosticsResponse response in responses)
			{
				ResponseQueue.Add(ResponseFactory.PublishDiagnostics(response));
			}
		}

		private (bool NeedsDetailedDiagnostics, DocumentId?, string?) GetActiveDocumentDetails()
		{
			DocumentId currentDocumentId = workspace.CurrentDocumentId;
			if ((object)currentDocumentId == null)
			{
				return (NeedsDetailedDiagnostics: false, null, null);
			}
			Project project = workspace.CurrentSolution.GetProject(currentDocumentId.ProjectId);
			if (project == null || project.BackgroundCodeAnalysisScope != 0 || project.AnalyzerReferences.Count == 0)
			{
				return (NeedsDetailedDiagnostics: false, null, null);
			}
			string item = (workspace.CurrentSolution?.GetDocument(currentDocumentId))?.FilePath.GetUri();
			return (NeedsDetailedDiagnostics: true, currentDocumentId, item);
		}

		private Project? GetProjectFromDocument(DocumentId documentId)
		{
			return workspace.CurrentSolution.GetProject(documentId.ProjectId);
		}

		private IEnumerable<PublishDiagnosticsResponse> FilterDiagnostics(PublishDiagnosticsResponse[] responses, CancellationToken token)
		{
			ArrayBuilder<PublishDiagnosticsResponse> arrayBuilder = ((vsCodeDiagnosticState.Keys.Count >= responses.Length) ? ArrayBuilder<PublishDiagnosticsResponse>.GetInstance() : ArrayBuilder<PublishDiagnosticsResponse>.GetInstance(responses.Length));
			try
			{
				foreach (PublishDiagnosticsResponse publishDiagnosticsResponse in responses)
				{
					token.ThrowIfCancellationRequested();
					string uri = publishDiagnosticsResponse.Uri;
					if (uri != null && (!vsCodeDiagnosticState.TryGetValue(uri, out var value) || value != publishDiagnosticsResponse.CombinedDiagnosticsHashCode))
					{
						vsCodeDiagnosticState[uri] = publishDiagnosticsResponse.CombinedDiagnosticsHashCode;
						arrayBuilder.Add(TakeTopNDiagnostics(publishDiagnosticsResponse, options.DiagnosticsPerFile));
					}
				}
				return arrayBuilder.ToArray();
			}
			finally
			{
				arrayBuilder.Free();
			}
		}

		private void ClearPartialAnalysisState()
		{
			if (moduleAnalyzerDiagnosticsCache.IsValueCreated)
			{
				moduleAnalyzerDiagnosticsCache.Value.Clear();
			}
		}

		private static PublishDiagnosticsResponse TakeTopNDiagnostics(PublishDiagnosticsResponse response, int count)
		{
			int num = Math.Min(response.Diagnostics.Length, count);
			ArrayBuilder<ProtocolDiagnostic> instance = ArrayBuilder<ProtocolDiagnostic>.GetInstance(num);
			try
			{
				for (int i = 0; i < num; i++)
				{
					instance.Add(response.Diagnostics[i]);
				}
				return new PublishDiagnosticsResponse
				{
					Uri = response.Uri,
					Diagnostics = instance.ToArray(),
					CombinedDiagnosticsHashCode = response.CombinedDiagnosticsHashCode
				};
			}
			finally
			{
				instance.Free();
			}
		}
	}
