		internal System.TimeSpan SlowDiagnosticsThreshold { get; }

		public DiagnosticServiceOptions(System.TimeSpan? delayAfterLastDocumentChange = null, System.TimeSpan? delayAfterLastProjectChange = null, int? partialDiagnosticsDocumentThreshold = null)
		{
