	internal class ModuleSymbolLookup
	{
		private protected class ReferenceModuleSymbolVisitor : SymbolVisitor
		{
			private PooledList<Symbol>? resultCollection;

			private string? queryString;

			private int queryCollectionLimit;

			public void CollectSymbols(Symbol symbol, PooledList<Symbol> resultCollection, int queryCollectionLimit = 100, string? query = null)
			{
				this.resultCollection = resultCollection;
				queryString = query;
				this.queryCollectionLimit = queryCollectionLimit;
				Visit(symbol);
			}

			public override void DefaultVisit(Symbol symbol)
			{
				if (resultCollection == null || symbol.IsSynthesized)
				{
					return;
				}
				if (string.IsNullOrWhiteSpace(queryString))
				{
					resultCollection.Add(symbol);
				}
				else
				{
					if (resultCollection.Count >= queryCollectionLimit)
					{
						return;
					}
					ApplyQuery(symbol);
				}
				base.DefaultVisit(symbol);
				VisitMembers(symbol);
			}

			private void ApplyQuery(Symbol symbol)
			{
				char[] array = ArrayPool<char>.Shared.Rent(symbol.Name.Length);
				try
				{
					int length = 0;
					string name = symbol.Name;
					foreach (char c in name)
					{
						if (c != ' ')
						{
							array[length++] = c;
						}
					}
					if (new ReadOnlySpan<char>(array, 0, length).Contains(queryString.AsSpan(), StringComparison.OrdinalIgnoreCase))
					{
						resultCollection.Add(symbol);
					}
				}
				finally
				{
					ArrayPool<char>.Shared.Return(array);
				}
			}

			public override void VisitProperty(PropertySymbol node)
			{
			}

			public override void VisitControl(ControlSymbol node)
			{
				if (node.ControlKind != 0)
				{
					base.VisitControl(node);
				}
				else
				{
					VisitMembers(node);
				}
			}

			public override void VisitAction(ActionSymbol node)
			{
				if (node.ActionKind != 0)
				{
					base.VisitAction(node);
				}
				else
				{
					VisitMembers(node);
				}
			}

			private void VisitMembers(Symbol symbol)
			{
				ContainerSymbol containerSymbol = symbol as ContainerSymbol;
				if (!(containerSymbol != null))
				{
					return;
				}
				foreach (Symbol item in containerSymbol.GetMembers().OfType<Symbol>())
				{
					item.Accept(this);
				}
			}
		}

		private protected static BloomFilter ConstructBloomFilter(ReferenceModuleSymbolVisitor visitor, Symbol symbol)
		{
			PooledList<Symbol> instance = PooledList<Symbol>.GetInstance();
			try
			{
				visitor.CollectSymbols(symbol, instance);
				BloomFilter bloomFilter = new BloomFilter(CalculateEstimateSize(instance), 0.01, isCaseSensitive: false);
				foreach (Symbol item in instance)
				{
					string name = item.Name;
					char[] array = ArrayPool<char>.Shared.Rent(name.Length);
					try
					{
						int length = 0;
						string text = name;
						foreach (char c in text)
						{
							if (c != ' ')
							{
								array[length++] = c;
							}
						}
						ReadOnlySpan<char> readOnlySpan = new ReadOnlySpan<char>(array, 0, length);
						bloomFilter.Add(name);
						for (int j = 0; j < Math.Min(readOnlySpan.Length, 3); j++)
						{
							ReadOnlySpan<char> value = readOnlySpan.Slice(0, j + 1);
							bloomFilter.Add(value);
						}
						for (int k = 1; k < readOnlySpan.Length - 3; k++)
						{
							ReadOnlySpan<char> value2 = readOnlySpan.Slice(k, 3);
							bloomFilter.Add(value2);
						}
					}
					finally
					{
						ArrayPool<char>.Shared.Return(array);
					}
				}
				return bloomFilter;
			}
			finally
			{
				instance.Free();
			}
		}

		private protected void GetSymbolsMatchingQuery(string queryString, BloomFilter filter, Symbol symbol, ReferenceModuleSymbolVisitor visitor, PooledList<Symbol> resultingSymbol, int responseLimit)
		{
			ReadOnlySpan<char> value = queryString.AsSpan();
			if (value.Length > 3)
			{
				bool flag = true;
				for (int i = 0; i < value.Length - 3 && flag; i++)
				{
					ReadOnlySpan<char> value2 = value.Slice(i, 3);
					flag &= filter.ProbablyContains(value2);
				}
				if (flag)
				{
					visitor.CollectSymbols(symbol, resultingSymbol, responseLimit, queryString);
				}
			}
			else if (filter.ProbablyContains(value))
			{
				visitor.CollectSymbols(symbol, resultingSymbol, responseLimit, queryString);
			}
		}

		private static int CalculateEstimateSize(PooledList<Symbol> collectionOfSymbols)
		{
			int num = 0;
			foreach (Symbol collectionOfSymbol in collectionOfSymbols)
			{
				num += collectionOfSymbol.Name.Length;
			}
			return num;
		}
	}
	internal sealed class ObjectChangeDocumentManager : IObjectChangeDocumentManager, IDisposable
	{
		private static readonly int TimeToWaitThatChangedDocumentCacheIsUpdated = 500;

		private static readonly int NumberOfIterationsToWaitThatChangedDocumentCacheIsUpdated = 4;

		private readonly VsCodeWorkspace workspace;

		private readonly ConcurrentDictionary<string, RadDocumentState> changedDocumentCache = new ConcurrentDictionary<string, RadDocumentState>(StringComparer.OrdinalIgnoreCase);

		private bool isDisposed;

		private long lastChangeTick;

		private readonly IWorkspaceTaskScheduler taskScheduler;

		private readonly int modifiedChangesUpdateThreshold;

		private readonly ManualResetEventSlim updating = new ManualResetEventSlim(initialState: true);

		public IDictionary<string, RadDocumentState> ChangedDocumentCache => changedDocumentCache;

		public IObjectChangeManager ActiveObjectChangeManager => workspace.GetCurrentProject()?.ObjectChangeManager;

		public ObjectChangeDocumentManager(VsCodeWorkspace workspace, int modifiedChangesUpdateThreshold = 1000)
		{
			this.workspace = workspace;
			IWorkspaceTaskSchedulerFactory service = this.workspace.Services.GetService<IWorkspaceTaskSchedulerFactory>();
			taskScheduler = service.CreateTaskScheduler(TaskScheduler.Default);
			this.workspace.WorkspaceChanged += OnWorkspaceChanged;
			this.modifiedChangesUpdateThreshold = modifiedChangesUpdateThreshold;
		}

		public void Dispose()
		{
			if (!isDisposed)
			{
				updating.Dispose();
				workspace.WorkspaceChanged -= OnWorkspaceChanged;
				isDisposed = true;
			}
		}

		public IObjectChangeManager GetObjectChangeManager(ProjectId id)
		{
			return workspace.CurrentSolution.GetProject(id)?.ObjectChangeManager;
		}

		public void ResetWaitingForDocumentChangesToFinish()
		{
			updating.Set();
		}

		public async Task UpdateDocumentChangeStateAsync(Solution oldSolution, Solution newSolution, DocumentId documentId, WorkspaceChangeKind kind, CancellationToken token)
		{
			Project project = newSolution.GetProject(documentId.ProjectId);
			if (project == null || project.ObjectChangeManager == null)
			{
				return;
			}
			Document document = project.GetDocument(documentId);
			Document document2 = oldSolution.GetDocument(documentId);
			Document document3 = ((document2 == null) ? document : document2);
			if (document3 == null)
			{
				return;
			}
			string path = document3.FilePath;
			if (string.IsNullOrEmpty(path))
			{
				return;
			}
			updating.Reset();
			if (changedDocumentCache.TryGetValue(path, out RadDocumentState value))
			{
				WorkspaceChangeKind workspaceChangeKind = kind;
				if (value.ChangeKind == WorkspaceChangeKind.DocumentAdded)
				{
					if (kind == WorkspaceChangeKind.DocumentRemoved)
					{
						changedDocumentCache.TryRemove(path, out RadDocumentState _);
					}
					return;
				}
				if (value.ChangeKind == WorkspaceChangeKind.DocumentRemoved && kind == WorkspaceChangeKind.DocumentAdded)
				{
					workspaceChangeKind = WorkspaceChangeKind.DocumentChanged;
				}
				if (workspaceChangeKind != value.ChangeKind)
				{
					changedDocumentCache[path] = new RadDocumentState
					{
						ChangeKind = workspaceChangeKind,
						Changes = value.Changes
					};
				}
			}
			else
			{
				ImmutableArray<IObjectTypeSymbol> symbols = await document3.GetDeclaringObjectAsync(token).ConfigureAwait(continueOnCapturedContext: false);
				if (symbols.Length == 0 && kind == WorkspaceChangeKind.DocumentChanged)
				{
					kind = WorkspaceChangeKind.DocumentAdded;
				}
				changedDocumentCache.TryAdd(path, new RadDocumentState
				{
					ChangeKind = kind,
					Changes = FromSymbols(symbols)
				});
			}
		}

		public async Task UpdateObjectChangesAsync(CancellationToken token, ProjectId id = null, bool requireNoDeclarationDiagnostics = true)
		{
			int num = 0;
			while (!updating.Wait(TimeToWaitThatChangedDocumentCacheIsUpdated) && !token.IsCancellationRequested && num < NumberOfIterationsToWaitThatChangedDocumentCacheIsUpdated)
			{
				num++;
			}
			Project project = GetProject(id);
			ImmutableArray<Diagnostic> diagnostics = ImmutableArray<Diagnostic>.Empty;
			if (requireNoDeclarationDiagnostics)
			{
				diagnostics = (await project.GetCompilationAsync(token).ConfigureAwait(continueOnCapturedContext: false)).GetDeclarationDiagnostics(token);
			}
			ImmutableArray<KeyValuePair<string, RadDocumentState>>.Enumerator enumerator = changedDocumentCache.ToImmutableArray().GetEnumerator();
			while (enumerator.MoveNext())
			{
				KeyValuePair<string, RadDocumentState> current = enumerator.Current;
				if (token.IsCancellationRequested)
				{
					break;
				}
				RadDocumentState state = current.Value;
				string key = current.Key;
				if (state.ChangeKind == WorkspaceChangeKind.DocumentRemoved)
				{
					UpdateObjectChangeManager(state.Changes, project.ObjectChangeManager, ObjectChangeState.Removed);
					continue;
				}
				Document document = workspace.GetDocument(key);
				if (document == null)
				{
					LocalMachineLogger.LogError("New document was null on a {0} change kind for document {1}!", state.ChangeKind, key);
				}
				else if (project.ContainsDocument(document.Id) && (!requireNoDeclarationDiagnostics || !diagnostics.HasAnyErrorsInSourceFile(document.FilePath)))
				{
					ImmutableArray<IObjectTypeSymbol> immutableArray = await document.GetDeclaringObjectAsync(token).ConfigureAwait(continueOnCapturedContext: false);
					if (state.ChangeKind == WorkspaceChangeKind.DocumentAdded)
					{
						UpdateObjectChangeManager(immutableArray, project.ObjectChangeManager, ObjectChangeState.Added);
					}
					else
					{
						UpdateObjectChangeManager(state.Changes, immutableArray, project.ObjectChangeManager);
					}
				}
			}
		}

		public void Clear(ProjectId? id = null, bool keepAdded = true)
		{
			Project project = GetProject(id);
			ImmutableArray<KeyValuePair<string, RadDocumentState>>.Enumerator enumerator = changedDocumentCache.ToImmutableArray().GetEnumerator();
			while (enumerator.MoveNext())
			{
				KeyValuePair<string, RadDocumentState> current = enumerator.Current;
				RadDocumentState value = current.Value;
				string path = current.Key;
				if (value.ChangeKind == WorkspaceChangeKind.DocumentRemoved || (value.ChangeKind == WorkspaceChangeKind.DocumentAdded && !keepAdded) || (value.ChangeKind != WorkspaceChangeKind.DocumentAdded && project.Documents.Any((Document d) => d.FilePath.Equals(path, StringComparison.OrdinalIgnoreCase))))
				{
					changedDocumentCache.TryRemove(path, out RadDocumentState _);
				}
			}
		}

		public bool HasProjectRadChanges(ProjectId id)
		{
			Project project = workspace.CurrentSolution.GetProject(id);
			if (project == null)
			{
				return false;
			}
			ImmutableArray<string>.Enumerator enumerator = changedDocumentCache.Keys.ToImmutableArray().GetEnumerator();
			while (enumerator.MoveNext())
			{
				string current = enumerator.Current;
				if (changedDocumentCache[current].ChangeKind == WorkspaceChangeKind.DocumentRemoved)
				{
					return true;
				}
				DocumentId documentId = workspace.GetDocumentId(current);
				if (documentId == null)
				{
					return false;
				}
				if (project.ContainsDocument(documentId))
				{
					return true;
				}
			}
			IObjectChangeManager objectChangeManager = GetObjectChangeManager(id);
			if (objectChangeManager == null)
			{
				return false;
			}
			return objectChangeManager.Changes.Count > 0;
		}

		private Project GetProject(ProjectId id)
		{
			if (!(id != null))
			{
				return workspace.GetCurrentProject();
			}
			return workspace.CurrentSolution.GetProject(id);
		}

		private void OnWorkspaceChanged(object sender, WorkspaceChangeEventArgs changeEvent)
		{
			WorkspaceChangeEventArgs changeEvent2 = changeEvent;
			if (changeEvent2 == null || !changeEvent2.HandleRad || changeEvent2.OldSolution == null || changeEvent2.ProjectId == null || changeEvent2.DocumentId == null || workspace.ProjectClosureCompilation == null || workspace.ProjectClosureCompilation == null)
			{
				return;
			}
			ProjectClosureCompilationStatus projectClosureCompilationStatus = workspace.ProjectClosureCompilation.GetProjectClosureCompilationStatus(changeEvent2.ProjectId);
			if ((projectClosureCompilationStatus != ProjectClosureCompilationStatus.Compiling && projectClosureCompilationStatus != ProjectClosureCompilationStatus.Compiled) || (changeEvent2.Kind != WorkspaceChangeKind.DocumentAdded && changeEvent2.Kind != WorkspaceChangeKind.DocumentChanged && changeEvent2.Kind != WorkspaceChangeKind.DocumentRemoved) || (changeEvent2.Kind == WorkspaceChangeKind.DocumentChanged && DateTime.UtcNow.Ticks - lastChangeTick < modifiedChangesUpdateThreshold))
			{
				return;
			}
			taskScheduler.ScheduleTask(async delegate
			{
				await UpdateDocumentChangeStateAsync(changeEvent2.OldSolution, changeEvent2.NewSolution, changeEvent2.DocumentId, changeEvent2.Kind, CancellationToken.None).ConfigureAwait(continueOnCapturedContext: false);
			}, "RAD.UpdateDocumentChanges", CancellationToken.None).SafeContinueWith(delegate
			{
				ResetWaitingForDocumentChangesToFinish();
				if (changeEvent2.Kind == WorkspaceChangeKind.DocumentChanged)
				{
					Interlocked.Exchange(ref lastChangeTick, DateTime.UtcNow.Ticks);
				}
			}, CancellationToken.None, TaskContinuationOptions.None, TaskScheduler.Default).ConfigureAwait(continueOnCapturedContext: false);
		}

		private static ImmutableArray<ObjectChangeElement> FromSymbols(ImmutableArray<IObjectTypeSymbol> symbols)
		{
			if (symbols.Length == 0)
			{
				return ImmutableArray<ObjectChangeElement>.Empty;
			}
			PooledHashSet<ObjectChangeElement> instance = PooledHashSet<ObjectChangeElement>.GetInstance();
			try
			{
				ImmutableArray<IObjectTypeSymbol>.Enumerator enumerator = symbols.GetEnumerator();
				while (enumerator.MoveNext())
				{
					IObjectTypeSymbol current = enumerator.Current;
					instance.Add(ObjectChangeElement.Create(current));
				}
				return instance.ToImmutableArray();
			}
			finally
			{
				instance.Free();
			}
		}

		private static void UpdateObjectChangeManager(ImmutableArray<IObjectTypeSymbol> symbols, IObjectChangeManager manager, ObjectChangeState kind)
		{
			ImmutableArray<IObjectTypeSymbol>.Enumerator enumerator = symbols.GetEnumerator();
			while (enumerator.MoveNext())
			{
				ObjectChangeElement objectChangeElement = ObjectChangeElement.Create(enumerator.Current);
				manager.Update(objectChangeElement, kind);
			}
		}

		private static void UpdateObjectChangeManager(ImmutableArray<ObjectChangeElement> changes, IObjectChangeManager manager, ObjectChangeState kind)
		{
			ImmutableArray<ObjectChangeElement>.Enumerator enumerator = changes.GetEnumerator();
			while (enumerator.MoveNext())
			{
				ObjectChangeElement current = enumerator.Current;
				manager.Update(current, kind);
			}
		}

		private static void UpdateObjectChangeManager(ImmutableArray<ObjectChangeElement> stored, ImmutableArray<IObjectTypeSymbol> newSymbols, IObjectChangeManager manager)
		{
			if (newSymbols.Length == 0)
			{
				return;
			}
			PooledHashSet<ObjectChangeElement> instance = PooledHashSet<ObjectChangeElement>.GetInstance();
			PooledHashSet<ObjectChangeElement> instance2 = PooledHashSet<ObjectChangeElement>.GetInstance();
			try
			{
				ImmutableArray<IObjectTypeSymbol>.Enumerator enumerator = newSymbols.GetEnumerator();
				while (enumerator.MoveNext())
				{
					ObjectChangeElement item = ObjectChangeElement.Create(enumerator.Current);
					instance.Add(item);
				}
				instance2.AddAll(stored);
				foreach (ObjectChangeElement item2 in instance2)
				{
					if (!instance.Contains(item2))
					{
						manager.Update(item2, ObjectChangeState.Removed);
					}
					else
					{
						manager.Update(item2, ObjectChangeState.Modified);
					}
				}
				foreach (ObjectChangeElement item3 in instance)
				{
					if (!instance2.Contains(item3))
					{
						manager.Update(item3, ObjectChangeState.Added);
					}
				}
			}
			finally
			{
				instance.Free();
				instance2.Free();
			}
		}
	}
	[DebuggerDisplay("Position = {Line}:{Character}")]
	public class Position : IEquatable<Position>
	{
		public static Position InvalidPosition = new Position
		{
			Line = -1,
			Character = -1
		};

		public int Line { get; set; }

		public int Character { get; set; }

		public bool Equals(Position other)
		{
			if (other == null)
			{
				return false;
			}
			if (this == other)
			{
				return true;
			}
			if (Line == other.Line)
			{
				return Character == other.Character;
			}
			return false;
		}

		public override bool Equals(object obj)
		{
			if (obj == null)
			{
				return false;
			}
			if (this == obj)
			{
				return true;
			}
			if (obj.GetType() != GetType())
			{
				return false;
			}
			return Equals((Position)obj);
		}

		public override int GetHashCode()
		{
			return (Line * 397) ^ Character;
		}

		public static implicit operator Position(LinePosition position)
		{
			return Create(position.Line, position.Character);
		}

		public static bool operator <(Position a, Position b)
		{
			if (a.Line <= b.Line)
			{
				return a.Character < b.Character;
			}
			return false;
		}

		public static bool operator >(Position a, Position b)
		{
			if (a.Line >= b.Line)
			{
				return a.Character > b.Character;
			}
			return false;
		}

		public static Position Create(int line, int column, bool isLineOneBased = false)
		{
			if (line < 0)
			{
				return InvalidPosition;
			}
			if (column < 0)
			{
				return InvalidPosition;
			}
			int line2 = line;
			if (isLineOneBased)
			{
				if (line == 0)
				{
					return InvalidPosition;
				}
				line2 = line - 1;
			}
			return new Position
			{
				Line = line2,
				Character = column
			};
		}

		public static Position Create(Position otherPosition)
		{
			return new Position
			{
				Line = otherPosition.Line,
				Character = otherPosition.Character
			};
		}

		public override string ToString()
		{
			return FormattableString.Invariant($"({Line},{Character})");
		}
	}
	internal class PreviewFileUrl
	{
		private const string ALpreviewSchema = "al-preview";

		private const string PreviewHost = "AlLang";

		private const char SlashChar = '/';

		private const char ReplacementSlashChar = '/';

		private static readonly Lazy<PreviewFileUrl> empty = new Lazy<PreviewFileUrl>(() => new PreviewFileUrl
		{
			ProjectName = string.Empty,
			Id = 0,
			Kind = SymbolKind.Undefined,
			Name = string.Empty
		});

		internal static PreviewFileUrl Empty => empty.Value;

		internal Guid? AppId { get; set; }

		internal string? ProjectName { get; set; }

		internal SymbolKind Kind { get; set; }

		internal int Id { get; set; }

		internal string Name { get; set; }

		internal static PreviewFileUrl Create(Uri uri)
		{
			if (uri.Segments == null || uri.Segments.Length < 1)
			{
				return Empty;
			}
			if (!uri.Host.Equals("AlLang", StringComparison.OrdinalIgnoreCase))
			{
				return Empty;
			}
			if (!uri.Scheme.Equals("al-preview", StringComparison.OrdinalIgnoreCase))
			{
				return Empty;
			}
			string[] array = (from s in uri.Segments.Skip(1)
				select Uri.UnescapeDataString(s.EndsWith("/", StringComparison.Ordinal) ? s.Substring(0, s.Length - 1) : s)).ToArray();
			PreviewFileUrl previewFileUrl = new PreviewFileUrl
			{
				ProjectName = string.Empty,
				Kind = SymbolKind.Undefined,
				Id = 0,
				Name = string.Empty
			};
			if (array.Length != 3 && array.Length != 4)
			{
				return previewFileUrl;
			}
			if (array.Length == 4)
			{
				string input = (previewFileUrl.ProjectName = Uri.UnescapeDataString(array[0]));
				if (Guid.TryParse(input, out var result))
				{
					previewFileUrl.AppId = result;
				}
			}
			int num = ((array.Length == 4) ? 1 : 0);
			if (!Enum.TryParse<SymbolKind>(array[num], ignoreCase: true, out var result2))
			{
				return previewFileUrl;
			}
			previewFileUrl.Kind = result2;
			if (++num >= array.Length)
			{
				return previewFileUrl;
			}
			if (int.TryParse(array[num], out var result3))
			{
				previewFileUrl.Id = result3;
			}
			else
			{
				previewFileUrl.Id = 0;
			}
			if (++num >= array.Length)
			{
				return previewFileUrl;
			}
			if (num == array.Length - 1)
			{
				previewFileUrl.Name = Unescape(Path.GetFileNameWithoutExtension(array[num]));
			}
			return previewFileUrl;
		}

		internal static string Escape(string applicationObjectName)
		{
			if (string.IsNullOrEmpty(applicationObjectName))
			{
				return string.Empty;
			}
			return Uri.EscapeDataString(applicationObjectName.Replace('/', '/'));
		}

		internal static string Unescape(string applicationObjectName)
		{
			if (string.IsNullOrEmpty(applicationObjectName))
			{
				return string.Empty;
			}
			return Uri.UnescapeDataString(applicationObjectName).Replace('/', '/');
		}

		public override string ToString()
		{
			string text = (AppId.HasValue ? (AppId.Value.ToString("N") + "/") : (string.IsNullOrEmpty(ProjectName) ? string.Empty : (ProjectName + "/"))) + $"{Kind}/{Id.ToString(CultureInfo.InvariantCulture)}/{Name}{".dal"}";
			return new Uri("al-preview://AlLang/" + text).ToString();
		}
	}
