	public sealed class VsCodeWorkspace : FileBasedWorkspace
	{
		private sealed class ProjectClosureLoadListener : IDisposable
		{
			private readonly NonReentrantLock mutex = new NonReentrantLock(useThisInstanceForSynchronization: true);

			private readonly VsCodeWorkspace workspace;

			private readonly ConcurrentDictionary<ProjectId, HashSet<string>> loadingProjects = new ConcurrentDictionary<ProjectId, HashSet<string>>();

			private const int DelayAfterLastCheck = 500;

			private CancellationTokenSource projectClosureLoadCancellation = new CancellationTokenSource();

			private Task? scheduledTask;

			private bool isDisposed;

			private readonly AutoResetEvent checkForProjectClosure;

			private long lastChangeTick = DateTime.UtcNow.Ticks;

			private ProjectId lastProjectId = ProjectId.Empty;

			internal ProjectClosureLoadListener(VsCodeWorkspace workspace, AutoResetEvent? checkForProjectClosure = null)
			{
				this.workspace = workspace;
				this.checkForProjectClosure = checkForProjectClosure ?? new AutoResetEvent(initialState: false);
			}

			internal void CancelScheduledTask()
			{
				if (scheduledTask != null)
				{
					projectClosureLoadCancellation.Cancel();
					ProjectClosureCompilationStatus projectClosureCompilationStatus = workspace.ProjectClosureCompilation.GetProjectClosureCompilationStatus(lastProjectId);
					if (projectClosureCompilationStatus != ProjectClosureCompilationStatus.Compiled && projectClosureCompilationStatus != 0 && loadingProjects.ContainsKey(lastProjectId))
					{
						loadingProjects.TryRemove(lastProjectId, out HashSet<string> _);
					}
				}
			}

			internal bool ScheduleTask(string[]? activeProjectsClosurePaths)
			{
				ProjectId currentProjectId = workspace.CurrentProjectId;
				if (currentProjectId == null)
				{
					return false;
				}
				CancelScheduledTask();
				scheduledTask?.Wait();
				RecreateCancellationTokenSource();
				bool num = loadingProjects.ContainsKey(currentProjectId);
				bool flag = workspace.ProjectClosureCompilation.GetProjectClosureCompilationStatus(currentProjectId) == ProjectClosureCompilationStatus.Compiled;
				if (num && flag)
				{
					workspace.responseQueue?.Add(ResponseFactory.ProgressNotification(new ProgressNotificatonResponse
					{
						Percent = 100,
						Owner = ProgressNotificationOwner.OpenWorkspace
					}));
					return false;
				}
				SetActiveProjectsClosurePaths(activeProjectsClosurePaths);
				lastProjectId = currentProjectId;
				workspace.ProjectClosureCompilation.SetCurrentProjectClosureRoot(currentProjectId);
				scheduledTask = workspace.ScheduleTask(delegate
				{
					TriggerProjectClosureLoaded(currentProjectId);
				}, "ProjectClosureLoadListener");
				checkForProjectClosure.Set();
				return true;
			}

			internal Task? CheckForClosureLoaded()
			{
				checkForProjectClosure.Set();
				return scheduledTask;
			}

			public void Dispose()
			{
				if (!isDisposed)
				{
					checkForProjectClosure.Dispose();
					projectClosureLoadCancellation.Dispose();
					scheduledTask?.Dispose();
					isDisposed = true;
				}
			}

			private void SetActiveProjectsClosurePaths(string[]? activeProjectsClosurePaths)
			{
				HashSet<string> orAdd = loadingProjects.GetOrAdd(workspace.CurrentProjectId, new HashSet<string>());
				ToHashSet(activeProjectsClosurePaths, orAdd);
			}

			private static void ToHashSet(string[]? activeProjectsClosurePaths, HashSet<string> existingClosures)
			{
				if (activeProjectsClosurePaths != null)
				{
					foreach (string fileNameAsUri in activeProjectsClosurePaths)
					{
						existingClosures.Add(fileNameAsUri.GetFilePath().ToLowerInvariant());
					}
				}
			}

			private void TriggerProjectClosureLoaded(ProjectId id)
			{
				while (!checkForProjectClosure.WaitOne(500))
				{
				}
				if (!loadingProjects.TryGetValue(id, out HashSet<string> value))
				{
					return;
				}
				bool flag = false;
				while (!projectClosureLoadCancellation.IsCancellationRequested)
				{
					if (DateTime.UtcNow.Ticks - lastChangeTick > 500)
					{
						Solution currentSolution = workspace.CurrentSolution;
						Interlocked.Exchange(ref lastChangeTick, DateTime.UtcNow.Ticks);
						ProjectDependencyGraph projectDependencyGraph = currentSolution.GetProjectDependencyGraph();
						if (projectDependencyGraph != null)
						{
							PooledList<ProjectId> instance = PooledList<ProjectId>.GetInstance();
							try
							{
								IImmutableSet<ProjectId> projectsThatThisProjectDirectlyDependsOn = projectDependencyGraph.GetProjectsThatThisProjectDirectlyDependsOn(id);
								bool flag2 = true;
								flag = workspace.AreAllProjectReferencesBound(currentSolution, id);
								foreach (ProjectId item in projectsThatThisProjectDirectlyDependsOn)
								{
									bool flag3 = workspace.AreAllProjectReferencesBound(currentSolution, item);
									if (!flag3)
									{
										flag2 = false;
										flag = false;
										break;
									}
									instance.Add(item);
									if (flag3 && flag)
									{
										Project project = currentSolution.GetProject(item);
										if (project != null && value != null && !value.Contains(project.ProjectFolder.ToLowerInvariant()))
										{
											flag = false;
											break;
										}
									}
								}
								if (flag2 && instance.Count > 0)
								{
									PooledList<string> instance2 = PooledList<string>.GetInstance();
									try
									{
										foreach (ProjectId item2 in instance)
										{
											Project project2 = currentSolution.GetProject(item2);
											if (project2 != null)
											{
												instance2.Add(project2.ProjectFolder.CreateUriFilePath());
												workspace.ProjectClosureCompilation.AddToProjectClosureCompilation(item2);
											}
										}
										workspace.responseQueue?.Add(ResponseFactory.ProjectsLoadedNotification(instance2.ToArray()));
									}
									finally
									{
										instance2.Free();
									}
								}
								if (flag)
								{
									Project project3 = currentSolution.GetProject(id);
									string message = string.Format(CultureInfo.CurrentCulture, ProtocolResources.ResolvingProjectClosure, value?.Count ?? 1, project3.Name);
									workspace.responseQueue?.Add(ResponseFactory.ProgressNotification(new ProgressNotificatonResponse
									{
										Message = message,
										Owner = ProgressNotificationOwner.OpenWorkspace
									}));
									workspace.ProjectClosureCompilation.AllowProjectClosureThreadCompilation();
									workspace.responseQueue?.Add(ResponseFactory.ProjectsLoadedNotification(new string[1] { project3.ProjectFolder.CreateUriFilePath() }));
									MarkClosureLoaded(currentSolution, projectDependencyGraph, project3);
									return;
								}
							}
							finally
							{
								instance.Free();
							}
						}
					}
					checkForProjectClosure.WaitOne(500);
				}
				if (projectClosureLoadCancellation.IsCancellationRequested && !flag)
				{
					Project project4 = workspace.CurrentSolution.GetProject(id);
					string message2 = string.Format(CultureInfo.CurrentCulture, ProtocolResources.CancelResolvingProjectClosure, project4.Name);
					workspace.responseQueue?.Add(ResponseFactory.ProgressNotification(new ProgressNotificatonResponse
					{
						Cancel = true,
						Message = message2,
						Owner = ProgressNotificationOwner.OpenWorkspace
					}));
					workspace.ProjectClosureCompilation.CancelClosureCompilation(id);
				}
			}

			private void MarkClosureLoaded(Solution currentSolution, ProjectDependencyGraph graph, Project currentProject)
			{
				IImmutableSet<ProjectId> projectsThatThisProjectTransitivelyDependsOn = graph.GetProjectsThatThisProjectTransitivelyDependsOn(currentProject.Id);
				PooledList<string> instance = PooledList<string>.GetInstance();
				try
				{
					foreach (ProjectId item in projectsThatThisProjectTransitivelyDependsOn)
					{
						Project project = currentSolution.GetProject(item);
						if (project != null)
						{
							instance.Add(project.ProjectFolder.CreateUriFilePath());
						}
					}
					instance.Add(currentProject.ProjectFolder.CreateUriFilePath());
					workspace.responseQueue?.Add(ResponseFactory.ProjectsLoadedNotification(instance.ToArray()));
				}
				finally
				{
					instance.Free();
				}
			}

			private void RecreateCancellationTokenSource()
			{
				using (mutex.DisposableWait())
				{
					projectClosureLoadCancellation.Dispose();
					projectClosureLoadCancellation = new CancellationTokenSource();
				}
			}
		}

