		internal bool TryAddOrUpdateProject(Settings settings, out IList<Diagnostic> diagnostics, out ProjectManifest? manifest, out bool missingSymbols)
		{
			diagnostics = new List<Diagnostic>();
			manifest = AddOrUpdateProjectFromPath(settings, forceCheckDependencies: false, out List<Diagnostic> projectLoadingDiagnostics, out missingSymbols);
			ICollectionExtensions.AddRange(diagnostics, projectLoadingDiagnostics);
			return manifest != null;
		}

		internal ProjectManifest? AddOrUpdateProjectFromPath(Settings settings, bool forceCheckDependencies, out List<Diagnostic> projectLoadingDiagnostics, out bool missingSymbols)
		{
			missingSymbols = false;
			projectLoadingDiagnostics = new List<Diagnostic>();
			if (settings == null)
			{
				return null;
			}
			int value = settings.SetConcurrencyLevel();
			LanguageClientCompilationOptions vsCodeOptions = new LanguageClientCompilationOptions(settings?.AlResourceConfigurationSettings?.ParallelBuild, value, settings?.AlResourceConfigurationSettings?.GenerateReportLayout, settings?.AlResourceConfigurationSettings?.CaptureSymbolUsage, settings?.GetOutFolder());
			string text = settings.WorkspacePath?.GetFilePath();
			string ruleSetPath = settings.GetRuleSetPath();
			string namespaceTemplate = settings.AlResourceConfigurationSettings?.NamespaceTemplate;
			string[] packageCachePaths = settings.GetPackageCachePaths();
			string dependencyParentProjectPath = settings.DependencyParentWorkspacePath?.GetFilePath();
			string[] assemblyProbingPaths = settings.GetAssemblyProbingPaths();
			BackgroundCodeAnalysisScope backgroundCodeAnalysisScope = settings.BackgroundCodeAnalyzersScope();
			bool enableCodeActions = settings.IsCodeActionsEnabled();
			bool incrementalBuild = settings.IsIncrementalBuild();
			bool enableShowSymbolUsage = settings.IsShowSymbolUsageEnabled();
			bool enableCaptureSymbolUsage = settings.IsCaptureSymbolUsageEnabled();
			bool outputAnalyzerStatistics = settings.IsOutputAnalyzerStatisticsEnabled();
			bool flag = settings.ExternalRulesetsEnabled();
			ImmutableArray<AnalyzerReference> analyzerReferences = settings.GetAnalyzerReferences();
			var (projectManifest, manifestProps) = LoadProjectManifest(text, projectLoadingDiagnostics);
			if (projectManifest == null)
			{
				CompilationOptions compilationOptions = new CompilationOptions(concurrentBuild: true, 4, ReportDiagnostic.Default, reportSuppressedDiagnostics: false, null, CompilationTarget.Extension, allowExtensionAndTargetInSameModule: false, readonlyErrorsAsWarnings: true, CompilerFeatures.None, showMyCode: false, null, CompilationGenerationOptions.None).WithLanguageClientCompilationOptions(vsCodeOptions);
				CompilationOptions options = compilationOptions;
				string ruleSetPath2 = ruleSetPath;
				bool externalRulesetsEnabled = flag;
				string[] probingFolders = assemblyProbingPaths;
				ProjectInfo projectInfo = FileBasedWorkspace.CreateProjectInfo(text, null, packageCachePaths, options, null, null, null, null, analyzerReferences, backgroundCodeAnalysisScope, outputAnalyzerStatistics, probingFolders, ruleSetPath2, externalRulesetsEnabled, enableCodeActions, incrementalBuild, enableShowSymbolUsage, enableCaptureSymbolUsage);
				SetCurrentProjectId(AddProject(projectInfo).Id);
				AddDocumentsFromPathToCurrentProject(text, projectLoadingDiagnostics);
			}
			else
			{
				ExternalTelemetryLogger.Initialize(projectManifest);
				Project project = base.CurrentSolution.FindProject(text);
				ISet<ProjectDefinition> expectedProjectReferences = GetExpectedProjectReferences(settings.ExpectedProjectReferenceDefinitions, manifestProps);
				ISet<SymbolReferenceSpecification> filterList = ToSymbolReferenceSpecification(expectedProjectReferences);
				IEnumerable<SymbolReferenceSpecification> allReferences = projectManifest.GetAllReferences(filterList);
				ProjectDefinition projectDefinition = CreateProjectDefinitionFromManifest(projectManifest);
				if (project != null)
				{
					SetCurrentProjectId(project.Id);
					CompilationOptions options2 = base.CurrentSolution.GetProjectState(project.Id).CompilationOptions.WithManifestOptions(projectManifest.AppManifest).WithGenerationOptions(CompilationGenerationOptions.ReportLayout).WithLanguageClientCompilationOptions(vsCodeOptions);
					options2 = CommonCompiler.TryReadRuleSetAndApplyToOptions(options2, ruleSetPath, projectLoadingDiagnostics, flag);
					options2 = options2.WithMergedWarningSuppressions(projectManifest.AppManifest.SuppressWarnings);
					ParseOptions parseOptions = base.CurrentSolution.GetProjectState(project.Id)?.ParseOptions ?? ParseOptions.Default;
					parseOptions = parseOptions.WithManifestOptions(projectManifest.AppManifest, includeRuntimeVersion: true);
					ChangeKind changeKind = UpdateDependencies(project.Id, allReferences, expectedProjectReferences, packageCachePaths, assemblyProbingPaths, ruleSetPath, namespaceTemplate, flag, options2, parseOptions, dependencyParentProjectPath, projectDefinition, projectManifest.AppManifest.GetInternalsVisibleToModules(), analyzerReferences, backgroundCodeAnalysisScope, outputAnalyzerStatistics, enableCodeActions, incrementalBuild, enableCaptureSymbolUsage);
					if (changeKind.HasFlag(ChangeKind.PackageCachePath) || forceCheckDependencies)
					{
						missingSymbols = RefreshSymbolReferences(project.Id, projectManifest, projectLoadingDiagnostics);
					}
				}
				else
				{
					CompilationOptions options3 = new CompilationOptions().WithManifestOptions(projectManifest.AppManifest).WithGenerationOptions(CompilationGenerationOptions.ReportLayout).WithLanguageClientCompilationOptions(vsCodeOptions);
					options3 = CommonCompiler.TryReadRuleSetAndApplyToOptions(options3, ruleSetPath, projectLoadingDiagnostics, flag);
					options3 = options3.WithMergedWarningSuppressions(projectManifest.AppManifest.SuppressWarnings);
					ParseOptions parseOptions2 = ParseOptions.Default.WithManifestOptions(projectManifest.AppManifest, includeRuntimeVersion: true);
					string appName = projectManifest.AppManifest.AppName;
					CompilationOptions options4 = options3;
					string[] probingFolders = assemblyProbingPaths;
					string ruleSetPath2 = ruleSetPath;
					bool externalRulesetsEnabled = flag;
					ProjectInfo projectInfo2 = FileBasedWorkspace.CreateProjectInfo(text, appName, packageCachePaths, options4, parseOptions2, null, allReferences, projectManifest.AppManifest.GetInternalsVisibleToModules(), analyzerReferences, backgroundCodeAnalysisScope, outputAnalyzerStatistics, probingFolders, ruleSetPath2, externalRulesetsEnabled, enableCodeActions, incrementalBuild, enableShowSymbolUsage: false, enableCaptureSymbolUsage, projectDefinition, expectedProjectReferences);
					project = AddProject(projectInfo2);
					SetCurrentProjectId(project.Id);
					AddDocumentsFromPathToCurrentProject(text, projectLoadingDiagnostics);
					Solution solution = AddCurrentProjectAsAProjectDependency(project.Id, dependencyParentProjectPath, base.CurrentSolution);
					if (solution != base.CurrentSolution)
					{
						TryApplyChangesAndSetCurrentSolution(solution);
					}
					if (responseQueue != null && projectClosureLoadListener != null)
					{
						string message = string.Format(CultureInfo.CurrentCulture, ProtocolResources.LoadingProject, project.Name);
						responseQueue.Add(ResponseFactory.ProgressNotification(new ProgressNotificatonResponse
						{
							Message = message,
							Owner = ProgressNotificationOwner.OpenWorkspace
						}));
					}
					if (forceCheckDependencies || projectManifest.AppManifest.Dependencies == null || !projectManifest.AppManifest.Dependencies.Any())
					{
						missingSymbols = RefreshSymbolReferences(project.Id, projectManifest, projectLoadingDiagnostics);
					}
				}
			}
			projectLoadingDiagnostics = FilterCurrentProjectDiagnostics(projectLoadingDiagnostics);
			return projectManifest;
		}

		internal bool RefreshSymbolReferences(ProjectId projectId, ProjectManifest manifest, bool updateSymbolReference, out IList<Diagnostic> diagnostics)
		{
			if ((object)projectId == null)
			{
				projectId = currentProjectId;
			}
			Project project = base.CurrentSolution.GetProject(projectId);
			DebugAssertHelper.Assert(project != null, "Project with name " + manifest.AppManifest.AppName + " is missing!");
			LocalCacheSymbolReferenceAnalyzer localCacheSymbolReferenceAnalyzer = new LocalCacheSymbolReferenceAnalyzer(project.PackageCachePaths);
			IEnumerable<SymbolReferenceSpecification> allReferences = manifest.GetAllReferences(ToSymbolReferenceSpecification(project.ExpectedProjectReferences));
			IEnumerable<SymbolReferenceSpecification> symbolReferencesThatAreNotProjectReferences = GetSymbolReferencesThatAreNotProjectReferences(projectId, manifest);
			if (updateSymbolReference)
			{
				UpdateSymbolReferences(allReferences, projectId);
			}
			diagnostics = new List<Diagnostic>();
			IEnumerable<SymbolReferenceSpecification> missingReferences;
			return !localCacheSymbolReferenceAnalyzer.FindMissingReferences(symbolReferencesThatAreNotProjectReferences, diagnostics, out missingReferences);
		}

		internal bool RefreshSymbolReferences(ProjectId projectId, IEnumerable<SymbolReferenceSpecification> allReferences, IList<Diagnostic> diagnostics)
		{
			Project project = base.CurrentSolution.GetProject(projectId);
			LocalCacheSymbolReferenceAnalyzer localCacheSymbolReferenceAnalyzer = new LocalCacheSymbolReferenceAnalyzer(project.PackageCachePaths);
			IEnumerable<SymbolReferenceSpecification> declaredReferences = ((project.ProjectReferences == null) ? allReferences : GetSymbolReferencesThatAreNotProjectReferences(project, allReferences));
			IEnumerable<SymbolReferenceSpecification> missingReferences;
			return localCacheSymbolReferenceAnalyzer.FindMissingReferences(declaredReferences, diagnostics, out missingReferences);
		}

		internal bool RefreshSymbolReferences(ProjectId projectId, ProjectManifest manifest, IList<Diagnostic> diagnostics)
		{
			if (manifest == null)
			{
				UpdateSymbolReferences(SpecializedCollections.EmptyList<SymbolReferenceSpecification>());
				return true;
			}
			IList<Diagnostic> diagnostics2;
			bool result = !RefreshSymbolReferences(projectId, manifest, updateSymbolReference: true, out diagnostics2);
			ICollectionExtensions.AddRange(diagnostics, diagnostics2);
			return result;
		}

		internal void UpdateSymbolReferences(IEnumerable<SymbolReferenceSpecification> newReferences, ProjectId projectId = null)
		{
			projectId = projectId ?? currentProjectId;
			Project project = base.CurrentSolution.GetProject(projectId);
			if (project != null && ShouldUpdateDependency(project.SymbolReferences, newReferences))
			{
				Solution solution = base.CurrentSolution.WithProjectSymbolReferences(project.Id, newReferences);
				TryApplyChangesAndSetCurrentSolution(solution);
			}
		}

		internal void UpdateSymbolReferences(SymbolReferenceSpecification specification, IList<Project> projects)
		{
			SymbolReferenceSpecification specification2 = specification;
			Solution solution = base.CurrentSolution;
			foreach (Project project in projects)
			{
				if (!project.SymbolReferences.Any((SymbolReferenceSpecification r) => r.Equals(specification2)))
				{
					return;
				}
				solution = solution.WithReloadSymbolReferences(project.Id, specification2);
			}
			if (base.CurrentSolution != solution)
			{
				TryApplyChangesAndSetCurrentSolution(solution);
			}
		}

		internal bool HasTransitiveClosureLoaded(Solution solution, ProjectId projectId)
		{
			if (!AreAllProjectReferencesBound(solution, projectId))
			{
				return false;
			}
			foreach (ProjectId item in solution.GetProjectDependencyGraph().GetProjectsThatThisProjectTransitivelyDependsOn(projectId))
			{
				if (!AreAllProjectReferencesBound(solution, item))
				{
					return false;
				}
			}
			return true;
		}

		internal bool AreAllProjectReferencesBound(Document document)
		{
			return AreAllProjectReferencesBound(base.CurrentSolution, document.Project.Id);
		}

		internal bool AreAllProjectReferencesBound(Solution solution, Document document)
		{
			return AreAllProjectReferencesBound(solution, document.Project.Id);
		}

		internal bool AreAllProjectReferencesBound(ProjectId projectId)
		{
			return AreAllProjectReferencesBound(base.CurrentSolution, projectId);
		}

		internal bool AreAllProjectReferencesBound(Solution solution, ProjectId projectId)
		{
			Project project = solution.GetProject(projectId);
			if (project == null)
			{
				return false;
			}
			if (project.ProjectReferences == null)
			{
				return project.ExpectedProjectReferences == null;
			}
			if (project.ExpectedProjectReferences == null)
			{
				LocalMachineLogger.LogError(FormattableString.Invariant($"Wrong project request. We have received no project references from the language client for the project with name {project.Name}, yet references are added."));
				return true;
			}
			PooledHashSet<ProjectDefinition> instance = PooledHashSet<ProjectDefinition>.GetInstance();
			try
			{
				foreach (ProjectReference projectReference in project.ProjectReferences)
				{
					Project project2 = solution.GetProject(projectReference.ProjectId);
					if (project2 != null)
					{
						instance.Add(project2.ProjectDefinition);
					}
				}
				if (instance.Count < project.ExpectedProjectReferences.Count)
				{
					return false;
				}
				foreach (ProjectDefinition expectedProjectReference in project.ExpectedProjectReferences)
				{
					if (!instance.Contains(expectedProjectReference))
					{
						return false;
					}
				}
				return true;
			}
			finally
			{
				instance.Free();
			}
		}

