		public void RemoveProject(string projectPath)
		{
			if (string.IsNullOrEmpty(projectPath))
			{
				throw new ArgumentException("Project path is null or empty.", "projectPath");
			}
			Solution solution = base.CurrentSolution;
			Project project = solution.FindProject(projectPath);
			if (project == null)
			{
				return;
			}
			ProjectReference projectReference = new ProjectReference(project);
			ProjectDependencyGraph projectDependencyGraph = solution.GetProjectDependencyGraph();
			if (projectDependencyGraph != null)
			{
				foreach (ProjectId item in projectDependencyGraph.GetProjectsThatThisProjectDirectlyDependsOn(project.Id))
				{
					solution = solution.RemoveProjectReference(item, projectReference);
					SetCurrentSolution(solution);
				}
			}
			if (projectClosureLoadListener != null)
			{
				projectClosureLoadListener.CancelScheduledTask();
			}
			OnProjectRemoved(project.Id);
		}

