			}
			while (true)
			{
				ProjectId projectId3 = Interlocked.CompareExchange(ref currentProjectId, projectId, projectId2);
				if (projectId3 == projectId2)
				{
					break;
				}
				projectId2 = projectId3;
			}
		}

