		internal void AddProjectReferences(string projectPath, IEnumerable<NavAppDependency> dependencies)
		{
			if (dependencies == null)
			{
				return;
			}
			Solution currentSolution = base.CurrentSolution;
			Project project = currentSolution.FindProject(projectPath);
			if (project == null)
			{
				return;
			}
			PooledHashSet<ProjectDefinition> instance = PooledHashSet<ProjectDefinition>.GetInstance();
			try
			{
				instance.AddRange(dependencies.Select((NavAppDependency d) => (ProjectDefinition)d));
				Solution solution = currentSolution;
				foreach (Project project2 in currentSolution.Projects)
				{
					if (instance.Contains(project2.ProjectDefinition))
					{
						ProjectReference projectReference = new ProjectReference(project2);
						solution = currentSolution.AddProjectReference(project.Id, projectReference);
					}
				}
				TryApplyChangesAndSetCurrentSolution(solution);
			}
			finally
			{
				instance.Free();
			}
		}

		internal void SynchronizeProjectDependencies(SynchronizeProjectDependenciesRequest request)
		{
			SynchronizeProjectDependenciesRequest request2 = request;
			Solution solution = base.CurrentSolution;
			Project project = solution.FindProject(request2.Folder.GetFilePath());
			if (project == null || project.ProjectReferences == null)
			{
				return;
			}
			bool flag = project.ProjectReferences.Any();
			if (request2.DependentProjectFolders == null || request2.DependentProjectFolders.Length == 0)
			{
				if (flag)
				{
					solution = solution.RemoveAllProjectReferences(project.Id);
					TryApplyChangesAndSetCurrentSolution(solution);
				}
				return;
			}
			IEnumerable<ProjectReference> enumerable = AddNewReferences();
			IEnumerable<ProjectReference> enumerable2 = RemoveOldReferences();
			if (enumerable2.Any())
			{
				solution = solution.RemoveProjectReferences(project.Id, enumerable2);
			}
			if (enumerable.Any())
			{
				solution = solution.AddProjectReferences(project.Id, enumerable);
			}
			TryApplyChangesAndSetCurrentSolution(solution);
			IEnumerable<ProjectReference> AddNewReferences()
			{
				PooledDictionary<string, ProjectReference> projectReferencePaths = PooledDictionary<string, ProjectReference>.GetInstance();
				try
				{
					projectReferencePaths.AddRange<KeyValuePair<string, ProjectReference>>(project.ProjectReferences.Select((ProjectReference r) => new KeyValuePair<string, ProjectReference>(r.ProjectDirectory.ToLowerInvariant(), r)));
					string[] dependentProjectFolders = request2.DependentProjectFolders;
					foreach (string text in dependentProjectFolders)
					{
						string key = text.ToLowerInvariant();
						if (!projectReferencePaths.TryGetValue(key, out ProjectReference _))
						{
							Project project2 = solution.FindProject(text);
							if (project2 != null)
							{
								yield return new ProjectReference(project2);
							}
						}
					}
				}
				finally
				{
					projectReferencePaths.Free();
				}
			}
			IEnumerable<ProjectReference> RemoveOldReferences()
			{
				PooledHashSet<string> dependentProjectPaths = PooledHashSet<string>.GetInstance();
				try
				{
					dependentProjectPaths.AddRange(request2.DependentProjectFolders.Select((string f) => f.ToLowerInvariant()));
					foreach (ProjectReference projectReference in project.ProjectReferences)
					{
						string item = projectReference.ProjectDirectory.ToLowerInvariant();
						if (!dependentProjectPaths.Contains(item))
						{
							yield return projectReference;
						}
					}
				}
				finally
				{
					dependentProjectPaths.Free();
				}
			}
		}

		internal IEnumerable<SymbolReferenceSpecification> GetSymbolReferencesThatAreNotProjectReferences(ProjectId projectId, ProjectManifest manifest)
		{
			Project project = base.CurrentSolution.GetProject(projectId);
			if (project == null)
			{
				throw new InvalidOperationException("Project with name '" + manifest.AppManifest.AppName + "' could not be found.");
			}
			IEnumerable<SymbolReferenceSpecification> allReferences = manifest.GetAllReferences(ToSymbolReferenceSpecification(project.ExpectedProjectReferences));
			if (project.ProjectReferences != null)
			{
				return GetSymbolReferencesThatAreNotProjectReferences(project, allReferences);
			}
			return allReferences;
		}

		private Solution AddCurrentProjectAsAProjectDependency(ProjectId id, string? dependencyParentProjectPath, Solution oldSolution)
		{
			Solution solution = oldSolution;
			if (string.IsNullOrEmpty(dependencyParentProjectPath))
			{
				return solution;
			}
			Project currentProject = solution.GetProject(id);
			Project project = solution.FindProject(dependencyParentProjectPath);
			if (project == null)
			{
				return solution;
			}
			if (!project.ProjectReferences.Any((ProjectReference r) => r.ProjectId == currentProject.Id))
			{
				ProjectReference projectReference = new ProjectReference(currentProject);
				solution = solution.AddProjectReference(project.Id, projectReference);
			}
			return solution;
		}

		private ChangeKind UpdateDependencies(ProjectId id, IEnumerable<SymbolReferenceSpecification> references, ISet<ProjectDefinition> expectedProjectReferences, string[] packageCachePaths, string[] assemblyProbingPaths, string? ruleSetPath, string? namespaceTemplate, bool externalRulesetsEnabled, CompilationOptions newCompilationOptions, ParseOptions newParseOptions, string? dependencyParentProjectPath, ProjectDefinition projectDefinition, IEnumerable<SymbolReferenceSpecification> internalsVisibleToModules, ImmutableArray<AnalyzerReference> analyzerReferences, BackgroundCodeAnalysisScope isBackgroundCodeAnalyzersEnabled, bool outputAnalyzerStatistics, bool enableCodeActions, bool incrementalBuild, bool enableCaptureSymbolUsage)
		{
			Solution currentSolution = base.CurrentSolution;
			Project? project = currentSolution.GetProject(id);
			ChangeKind changeKind = ChangeKind.Nothing;
			currentSolution = AddCurrentProjectAsAProjectDependency(id, dependencyParentProjectPath, currentSolution);
			if (currentSolution != base.CurrentSolution)
			{
				changeKind |= ChangeKind.SymbolReferences;
			}
			ProjectState projectState = project?.State;
			if (ShouldUpdateDependency(projectState?.AssemblyProbingPaths, assemblyProbingPaths))
			{
				currentSolution = currentSolution.WithAssemblyProbingPaths(currentProjectId, assemblyProbingPaths ?? new string[0]);
				changeKind |= ChangeKind.AssemblyProbingPaths;
			}
			if (ShouldUpdateDependency(projectState?.PackageCachePaths, packageCachePaths))
			{
				currentSolution = currentSolution.WithProjectPackageCachePath(currentProjectId, packageCachePaths ?? new string[0]);
				changeKind |= ChangeKind.PackageCachePath;
			}
			if (ShouldUpdateDependency(projectState?.RuleSetPath, ruleSetPath))
			{
				currentSolution = currentSolution.WithRuleSetPath(currentProjectId, ruleSetPath);
				changeKind |= ChangeKind.RuleSetPath;
			}
			if (ShouldUpdateDependency(projectState?.NamespaceTemplate, namespaceTemplate))
			{
				currentSolution = currentSolution.WithNamespaceTemplate(currentProjectId, namespaceTemplate);
				changeKind |= ChangeKind.NamespaceTemplate;
			}
			if (projectState == null || projectState.ExternalRulesetsEnabled != externalRulesetsEnabled)
			{
				currentSolution = currentSolution.WithExternalRulesetsEnabled(currentProjectId, externalRulesetsEnabled);
				changeKind |= ChangeKind.ExternalRulesetsEnabled;
			}
			if (ShouldUpdateDependency(projectState?.SymbolReferences, references))
			{
				currentSolution = currentSolution.WithProjectSymbolReferences(currentProjectId, references);
				changeKind |= ChangeKind.SymbolReferences;
			}
			if (ShouldUpdateDependency(projectState?.InternalsVisibleToModules, internalsVisibleToModules))
			{
				currentSolution = currentSolution.WithInternalsVisibleToModules(currentProjectId, internalsVisibleToModules);
				changeKind |= ChangeKind.InternalsVisibleToModules;
			}
			if (!newCompilationOptions.Equals(projectState?.CompilationOptions))
			{
				currentSolution = currentSolution.WithProjectCompilationOptions(currentProjectId, newCompilationOptions);
				changeKind |= ChangeKind.CompilationOptions;
			}
			if (!newParseOptions.Equals(projectState?.ParseOptions))
			{
				currentSolution = currentSolution.WithProjectParseOptions(currentProjectId, newParseOptions);
				changeKind |= ChangeKind.ParseOptions;
			}
			if (!projectDefinition.Equals(projectState.ProjectDefinition))
			{
				currentSolution = currentSolution.WithProjectDefinition(currentProjectId, projectDefinition);
				changeKind |= ChangeKind.ProjectDefinition;
				currentSolution = UpdateExpectedProjectReferencesOnProjectsDependingOnThis(currentSolution, currentProjectId, projectState.ProjectDefinition, projectDefinition);
			}
			if (ShouldUpdateDependency(projectState?.AnalyzerReferences, analyzerReferences))
			{
				currentSolution = currentSolution.WithProjectAnalyzerReferences(currentProjectId, analyzerReferences);
				changeKind |= ChangeKind.AnalyzerReferences;
			}
			if (projectState == null || projectState.EnableCodeActions != enableCodeActions)
			{
				currentSolution = currentSolution.WithProjectEnableCodeActions(currentProjectId, enableCodeActions);
				changeKind |= ChangeKind.EnableCodeActions;
			}
			if (projectState == null || projectState.BackgroundCodeAnalysisScope != isBackgroundCodeAnalyzersEnabled)
			{
				currentSolution = currentSolution.WithBackgroundCodeAnalysisScope(currentProjectId, isBackgroundCodeAnalyzersEnabled);
				changeKind |= ChangeKind.BackgroundCodeAnalysisScope;
			}
			if (projectState == null || projectState.OutputAnalyzerStatistics != outputAnalyzerStatistics)
			{
				currentSolution = currentSolution.WithOutputAnalyzerStatistics(currentProjectId, outputAnalyzerStatistics);
				changeKind |= ChangeKind.OutputAnalyzerStatistics;
			}
			if (projectState == null || projectState.IncrementalBuild != incrementalBuild)
			{
				currentSolution = currentSolution.WithProjectIncrementalBuild(currentProjectId, incrementalBuild);
				changeKind |= ChangeKind.IncrementalBuild;
			}
			if (projectState == null || projectState.EnableCaptureSymbolUsage != enableCaptureSymbolUsage)
			{
				currentSolution = currentSolution.WithCaptureSymbolUsage(currentProjectId, enableCaptureSymbolUsage);
				changeKind |= ChangeKind.CaptureSymbolUsage;
			}
			if (projectState == null || !(projectState.ExpectedProjectReferences?.SetEquals(expectedProjectReferences)).GetValueOrDefault())
			{
				currentSolution = currentSolution.WithExpectedProjectReferences(currentProjectId, expectedProjectReferences);
				changeKind |= ChangeKind.ExpectedProjectReferences;
			}
			TryApplyChangesAndSetCurrentSolution(currentSolution);
			if (changeKind > ChangeKind.Nothing)
			{
				changeKind &= ~ChangeKind.Nothing;
			}
			return changeKind;
		}

		private IEnumerable<SymbolReferenceSpecification> GetSymbolReferencesThatAreNotProjectReferences(Project project, IEnumerable<SymbolReferenceSpecification> allReferences)
		{
			foreach (SymbolReferenceSpecification allReference in allReferences)
			{
				ProjectDefinition definition = new ProjectDefinition
				{
					AppId = allReference.AppId,
					Name = allReference.Name,
					Version = allReference.Version,
					Publisher = allReference.Publisher
				};
				Solution solution = base.CurrentSolution;
				if (!project.ProjectReferences.Any((ProjectReference r) => solution.GetProject(r.ProjectId)?.ProjectDefinition == definition))
				{
					yield return allReference;
				}
			}
		}

		internal static bool ShouldUpdateDependency(string? oldValue, string? newValue)
		{
			if (oldValue == null)
			{
				return newValue != null;
			}
			if (newValue == null)
			{
				return true;
			}
			return !string.Equals(newValue, oldValue, StringComparison.OrdinalIgnoreCase);
		}

		internal static bool ShouldUpdateDependency<T>(IEnumerable<T>? oldValue, IEnumerable<T>? newValue)
		{
			if (IsNullOrEmpty(oldValue))
			{
				return !IsNullOrEmpty(newValue);
			}
			if (IsNullOrEmpty(newValue))
			{
				return true;
			}
			return !newValue.SequenceEqual(oldValue);
		}

		internal static bool IsNullOrEmpty<T>(IEnumerable<T>? value)
		{
			return value?.IsEmpty() ?? true;
		}

		internal void TryApplyChangesAndSetCurrentSolution(Solution solution)
		{
			TryApplyChanges(solution);
			SetCurrentSolution(solution);
		}

		internal bool ScheduleProjectLoadListenerTask(string[]? activeProjectsClosure)
		{
			if (CurrentProjectId == null)
			{
				return false;
			}
			if (activeProjectsClosure == null || activeProjectsClosure.Length == 0)
			{
				TriggerProjectClosureCompilation();
				return true;
			}
			if (activeProjectsClosure.Length == 1 && activeProjectsClosure[0].GetFilePath().Equals(CurrentProjectFolder, StringComparison.OrdinalIgnoreCase))
			{
				TriggerProjectClosureCompilation();
				return true;
			}
			if (projectClosureLoadListener == null)
			{
				projectClosureLoadListener = new ProjectClosureLoadListener(this);
			}
			return projectClosureLoadListener?.ScheduleTask(activeProjectsClosure) ?? false;
		}

		internal Task CheckForClosureLoaded(ProjectId? id)
		{
			if (id != CurrentProjectId)
			{
				return Task.CompletedTask;
			}
			using (base.SerializationLock.DisposableWait())
			{
				if (projectClosureLoadListener != null)
				{
					return projectClosureLoadListener.CheckForClosureLoaded();
				}
			}
			return Task.CompletedTask;
		}

		internal void TriggerProjectClosureCompilation()
		{
			ProjectClosureCompilation.SetCurrentProjectClosureRoot(CurrentProjectId);
			ProjectClosureCompilation.AllowProjectClosureThreadCompilation();
		}

		internal static List<Diagnostic> FilterDiagnosticsForProject(List<Diagnostic> diagnostics, Project? project)
		{
			if (project == null || project.CompilationOptions == null)
			{
				return diagnostics;
			}
			using PooledList<Diagnostic> pooledList = PooledList<Diagnostic>.GetInstance();
			foreach (Diagnostic diagnostic2 in diagnostics)
			{
				Diagnostic diagnostic = project.CompilationOptions.FilterDiagnostic(diagnostic2);
				if (diagnostic != null)
				{
					pooledList.Add(diagnostic);
				}
			}
			return pooledList.ToList();
		}

		internal List<Diagnostic> FilterCurrentProjectDiagnostics(List<Diagnostic> diagnostics)
		{
			if (CurrentProjectId == null)
			{
				return diagnostics;
			}
