	public sealed class ProjectCompilationStatus
	{
		public static readonly ProjectCompilationStatus Compiled = new ProjectCompilationStatus(ProjectClosureCompilationStatus.Compiled, hasLoaded: true);

		public static readonly ProjectCompilationStatus Compiling = new ProjectCompilationStatus(ProjectClosureCompilationStatus.Compiling, hasLoaded: false);

		public static readonly ProjectCompilationStatus CompilingAndLoaded = new ProjectCompilationStatus(ProjectClosureCompilationStatus.Compiling, hasLoaded: true);

		public static readonly ProjectCompilationStatus Added = new ProjectCompilationStatus(ProjectClosureCompilationStatus.Added, hasLoaded: false);

		public static readonly ProjectCompilationStatus Undefined = new ProjectCompilationStatus(ProjectClosureCompilationStatus.Undefined, hasLoaded: false);

		public static readonly ProjectCompilationStatus CanceledAndLoaded = new ProjectCompilationStatus(ProjectClosureCompilationStatus.Canceled, hasLoaded: true);

		public static readonly ProjectCompilationStatus Canceled = new ProjectCompilationStatus(ProjectClosureCompilationStatus.Canceled, hasLoaded: false);

		public ProjectClosureCompilationStatus CompilationStatus { get; }

		public bool HasLoaded { get; }

		public static ProjectCompilationStatus Create(ProjectClosureCompilationStatus status)
		{
			return status switch
			{
				ProjectClosureCompilationStatus.Undefined => Undefined, 
				ProjectClosureCompilationStatus.Added => Added, 
				ProjectClosureCompilationStatus.Compiled => Compiled, 
				ProjectClosureCompilationStatus.Canceled => Canceled, 
				ProjectClosureCompilationStatus.Compiling => Compiling, 
				_ => Undefined, 
			};
		}

		private ProjectCompilationStatus(ProjectClosureCompilationStatus compilationStatus, bool hasLoaded)
		{
			CompilationStatus = compilationStatus;
			HasLoaded = hasLoaded;
		}

		public ProjectCompilationStatus TransitionTo(ProjectClosureCompilationStatus previousStatus)
		{
			switch (previousStatus)
			{
			case ProjectClosureCompilationStatus.Undefined:
				return Undefined;
			case ProjectClosureCompilationStatus.Added:
				return Added;
			case ProjectClosureCompilationStatus.Compiled:
				return Compiled;
			case ProjectClosureCompilationStatus.Canceled:
				if (!HasLoaded)
				{
					return Canceled;
				}
				return CanceledAndLoaded;
			case ProjectClosureCompilationStatus.Compiling:
				if (!HasLoaded)
				{
					return Compiling;
				}
				return CompilingAndLoaded;
			default:
				return Undefined;
			}
		}
	}
