			try
			{
				DefaultAnalyzerAssemblyLoader assemblyLoader = new DefaultAnalyzerAssemblyLoader();
				foreach (string item in analyzerPaths)
				{
					try
					{
						if (!File.Exists(item))
						{
							instance.Add(new UnresolvedAnalyzerReference(item, string.Format(CultureInfo.InvariantCulture, CodeAnalysisResources.FileNotFoundException, item)));
						}
						else
						{
							instance.Add(new AnalyzerFileReference(item, assemblyLoader));
						}
					}
					catch (Exception ex) when (ex is IOException || ex is UnauthorizedAccessException)
					{
						instance.Add(new UnresolvedAnalyzerReference(item, ex.Message));
					}
				}
				return instance.ToImmutable();
			}
			finally
			{
				instance.Free();
			}
		}

		private static (string path, bool requireAnalyzerCommon) ReplaceWellKnownAnalyzerVariable(string path)
		{
			string pathToAnalyzerFolder = CompilerPathUtilities.GetPathToAnalyzerFolder();
			string text = path.ToLowerInvariant();
			switch (text)
			{
			case "${codecop}":
				return (path: Path.Combine(pathToAnalyzerFolder, "Microsoft.Dynamics.Nav.CodeCop.dll"), requireAnalyzerCommon: true);
			case "${appsourcecop}":
				return (path: Path.Combine(pathToAnalyzerFolder, "Microsoft.Dynamics.Nav.AppSourceCop.dll"), requireAnalyzerCommon: true);
			case "${pertenantextensioncop}":
				return (path: Path.Combine(pathToAnalyzerFolder, "Microsoft.Dynamics.Nav.PerTenantExtensionCop.dll"), requireAnalyzerCommon: true);
			case "${uicop}":
				return (path: Path.Combine(pathToAnalyzerFolder, "Microsoft.Dynamics.Nav.UICop.dll"), requireAnalyzerCommon: true);
			default:
			{
				if (text.IndexOf("${analyzerfolder}", StringComparison.Ordinal) != 0)
				{
					return (path: path, requireAnalyzerCommon: false);
				}
				string path2 = path.Substring("${analyzerfolder}".Length).TrimStart(PathUtilities.DirectorySeparatorChar);
				return (path: Path.Combine(pathToAnalyzerFolder, path2), requireAnalyzerCommon: false);
			}
			}
		}

