	internal static class SnapshotDebuggerSerializerExtensions
	{
		internal static Microsoft.Dynamics.Nav.AL.Common.SnapshotDebuggerSerializer.StackFrame? GetThisFrame(this MethodContext methodContext)
		{
			if (methodContext.FramesLength == 0)
			{
				return null;
			}
			return methodContext.Frames(0);
		}

		internal static Microsoft.Dynamics.Nav.AL.Common.SnapshotDebuggerSerializer.StackFrame? GetCallerFrame(this MethodContext context, bool strict = false)
		{
			if (context.FramesLength < 1)
			{
				return null;
			}
			if (context.FramesLength == 1)
			{
				if (!strict)
				{
					return context.Frames(0);
				}
				return null;
			}
			return context.Frames(1);
		}

		internal static SnapshotLineDefinition? GetCallerLine(this MethodContext context)
		{
			Microsoft.Dynamics.Nav.AL.Common.SnapshotDebuggerSerializer.StackFrame? callerFrame = context.GetCallerFrame(strict: true);
			if (callerFrame.HasValue)
			{
				return callerFrame.Value.CreateLineDefinitionFromFrame();
			}
			return null;
		}

		internal static SnapshotLineDefinition? GetCalledLine(this MethodContext context)
		{
			Microsoft.Dynamics.Nav.AL.Common.SnapshotDebuggerSerializer.StackFrame? thisFrame = context.GetThisFrame();
			if (thisFrame.HasValue)
			{
				return thisFrame.Value.CreateLineDefinitionFromFrame();
			}
			return null;
		}

		internal static (ApplicationObjectIdWrapper? ApplicationObjectId, string Name) ToApplicationObjectDefinition(this MethodContext methodContext)
		{
			ApplicationObjectIdWrapper? applicationObjectIdWrapper = methodContext.Id.FromBufferedApplicationObjectId();
			if (!applicationObjectIdWrapper.HasValue)
			{
				return (ApplicationObjectId: null, Name: string.Empty);
			}
			Microsoft.Dynamics.Nav.AL.Common.SnapshotDebuggerSerializer.StackFrame? thisFrame = methodContext.GetThisFrame();
			if (!thisFrame.HasValue)
			{
				return (ApplicationObjectId: null, Name: string.Empty);
			}
			return (ApplicationObjectId: new ApplicationObjectIdWrapper(applicationObjectIdWrapper.Value.ObjectType, applicationObjectIdWrapper.Value.ObjectNumber), Name: thisFrame.Value.ObjectName);
		}

		internal static ApplicationObjectIdWrapper? FromBufferedApplicationObjectId(this ApplicationObjectId? id)
		{
			if (!id.HasValue)
			{
				return null;
			}
			return new ApplicationObjectIdWrapper((ObjectTypeWrapper)id.Value.Type, id.Value.Number);
		}

		internal static Microsoft.Dynamics.Nav.DebuggerService.SourceSpan? FromBufferedSourceSpan(this Microsoft.Dynamics.Nav.AL.Common.SnapshotDebuggerSerializer.SourceSpan? span)
		{
			if (!span.HasValue)
			{
				return null;
			}
			return new Microsoft.Dynamics.Nav.DebuggerService.SourceSpan(span.Value.From.FromBufferedSourcePosition(), span.Value.To.FromBufferedSourcePosition());
		}

		internal static Microsoft.Dynamics.Nav.DebuggerService.SourcePosition FromBufferedSourcePosition(this Microsoft.Dynamics.Nav.AL.Common.SnapshotDebuggerSerializer.SourcePosition position)
		{
			return new Microsoft.Dynamics.Nav.DebuggerService.SourcePosition(position.Line, position.Column);
		}

		internal static SnapshotLineDefinition? CreateLineDefinitionFromFrameIndex(this MethodContext context, int frameIndex)
		{
			if (frameIndex >= context.FramesLength)
			{
				return null;
			}
			Microsoft.Dynamics.Nav.AL.Common.SnapshotDebuggerSerializer.StackFrame? stackFrame = context.Frames(frameIndex);
			if (!stackFrame.HasValue)
			{
				return null;
			}
			return stackFrame.Value.CreateLineDefinitionFromFrame();
		}

		internal static SnapshotLineDefinition? CreateLineDefinitionFromFrame(this Microsoft.Dynamics.Nav.AL.Common.SnapshotDebuggerSerializer.StackFrame bufferedFrame)
		{
			ApplicationObjectIdWrapper? applicationObjectIdWrapper = bufferedFrame.Id.FromBufferedApplicationObjectId();
			if (!applicationObjectIdWrapper.HasValue)
			{
				return null;
			}
			Microsoft.Dynamics.Nav.DebuggerService.SourceSpan? sourceSpan = bufferedFrame.StatementSpan.FromBufferedSourceSpan();
			if (!sourceSpan.HasValue)
			{
				return null;
			}
			return new SnapshotLineDefinition
			{
				Id = applicationObjectIdWrapper.Value,
				StatementSpan = sourceSpan.Value
			};
		}
	}
