	internal class SourceModuleSymbolLookup : ModuleSymbolLookup
	{
		private ConcurrentDictionary<DocumentId, Dictionary<Symbol, BloomFilter>> filters = new ConcurrentDictionary<DocumentId, Dictionary<Symbol, BloomFilter>>();

		private SourceModuleSymbolLookup()
		{
		}

		public static async Task<SourceModuleSymbolLookup> CreateFromProject(Project project, CancellationToken cancellationToken)
		{
			SourceModuleSymbolLookup instance = new SourceModuleSymbolLookup();
			foreach (Document document in project.Documents)
			{
				await instance.UpdateForDocumentAsync(document, cancellationToken);
			}
			return instance;
		}

		public void RemoveDocument(DocumentId documentId)
		{
			filters.TryRemove(documentId, out Dictionary<Symbol, BloomFilter> _);
		}

		public async Task UpdateForDocumentAsync(Document? document, CancellationToken cancellationToken)
		{
			if (document == null)
			{
				return;
			}
			DocumentId documentId = document.Id;
			filters.TryRemove(documentId, out Dictionary<Symbol, BloomFilter> _);
			ReferenceModuleSymbolVisitor visitor = new ReferenceModuleSymbolVisitor();
			SyntaxNode root = await document.GetSyntaxRootAsync(cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
			if (root == null)
			{
				return;
			}
			SemanticModel semanticModel = await document.GetSemanticModelAsync(cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
			Dictionary<Symbol, BloomFilter> dictionary = new Dictionary<Symbol, BloomFilter>();
			if (root.Kind == SyntaxKind.CompilationUnit)
			{
				SyntaxList<ObjectSyntax>.Enumerator enumerator = ((CompilationUnitSyntax)root).Objects.GetEnumerator();
				while (enumerator.MoveNext())
				{
					ObjectSyntax current = enumerator.Current;
					Symbol symbol = semanticModel.GetDeclaredSymbolForNode(current, cancellationToken) as Symbol;
					if (symbol != null)
					{
						BloomFilter value2 = ModuleSymbolLookup.ConstructBloomFilter(visitor, symbol);
						dictionary[symbol] = value2;
					}
				}
			}
			filters.TryAdd(documentId, dictionary);
		}

		public void QueryForSymbol(string queryString, string projectFolder, PooledConcurrentSet<WorkspaceSymbol> responseBuilder, int responseLimit = 100, DocumentId? activeDocument = null)
		{
			if (string.IsNullOrWhiteSpace(queryString) || responseBuilder.Count >= responseLimit)
			{
				return;
			}
			int responseLimit2 = responseLimit - responseBuilder.Count;
			ReferenceModuleSymbolVisitor visitor = new ReferenceModuleSymbolVisitor();
			PooledList<Symbol> instance = PooledList<Symbol>.GetInstance();
			try
			{
				if ((object)activeDocument != null && filters.TryGetValue(activeDocument, out Dictionary<Symbol, BloomFilter> value))
				{
					foreach (KeyValuePair<Symbol, BloomFilter> item in value)
					{
						if (item.Key is ObjectTypeSymbol symbol)
						{
							GetSymbolsMatchingQuery(queryString, item.Value, symbol, visitor, instance, responseLimit2);
						}
					}
				}
				foreach (KeyValuePair<DocumentId, Dictionary<Symbol, BloomFilter>> filter in filters)
				{
					DocumentId key = filter.Key;
					if ((object)activeDocument != null && key == activeDocument)
					{
						continue;
					}
					foreach (KeyValuePair<Symbol, BloomFilter> item2 in filter.Value)
					{
						if (item2.Key is ObjectTypeSymbol symbol2)
						{
							GetSymbolsMatchingQuery(queryString, item2.Value, symbol2, visitor, instance, responseLimit2);
						}
					}
				}
				foreach (Symbol item3 in instance)
				{
					responseBuilder.Add(item3.ToWorkspaceSymbol());
				}
			}
			finally
			{
				instance.Free();
			}
		}
	}
	internal static class ZipExtensions
	{
		internal static readonly string VersionInfoFileName = "version";

		private static readonly Lazy<System.Version> DefaultVersion = new Lazy<System.Version>(() => new System.Version());

		internal static T? ReadContentWithRecyclableMemoryc<T>(this ZipArchiveEntry entry, Func<ByteBuffer, T?> getContent) where T : struct
		{
			byte[] array = entry.ReadContentRecyclableMemory();
			if (array == null)
			{
				return null;
			}
			ByteBuffer arg = new ByteBuffer(array);
			return getContent(arg);
		}

		internal static byte[]? ReadContentRecyclableMemory(this ZipArchiveEntry entry)
		{
			if (entry.Length == 0L)
			{
				return null;
			}
			using Stream stream = entry.Open();
			using MemoryStream memoryStream = RecyclableMemoryStreamManagerProxy.Instance.GetStream("DeflatedFlatBuffer", (int)entry.Length);
			stream.CopyTo(memoryStream, (int)entry.Length);
			memoryStream.Position = 0L;
			ArrayBuilder<byte> instance = ArrayBuilder<byte>.GetInstance();
			instance.AddRange(memoryStream.GetBuffer());
			return instance.ToArrayAndFree();
		}

		internal static T? ReadContent<T>(this ZipArchiveEntry entry, Func<ByteBuffer, T?> getContent) where T : struct
		{
			byte[] array = entry.ReadContent();
			if (array == null)
			{
				return null;
			}
			ByteBuffer arg = new ByteBuffer(array);
			return getContent(arg);
		}

		internal static byte[]? ReadContent(this ZipArchiveEntry entry)
		{
			if (entry.Length == 0L)
			{
				return null;
			}
			using Stream stream = entry.Open();
			using MemoryStream memoryStream = new MemoryStream((int)entry.Length);
			stream.CopyTo(memoryStream, (int)entry.Length);
			memoryStream.Position = 0L;
			return memoryStream.GetBuffer();
		}

		internal static async Task<T?> ReadContentAsync<T>(this ZipArchiveEntry entry, Func<ByteBuffer, T?> getContent, CancellationToken token) where T : struct
		{
			byte[] array = await entry.ReadContentAsync(token).ConfigureAwait(continueOnCapturedContext: false);
			if (array == null)
			{
				return null;
			}
			ByteBuffer arg = new ByteBuffer(array);
			return getContent(arg);
		}

		internal static async Task<byte[]?> ReadContentAsync(this ZipArchiveEntry entry, CancellationToken token)
		{
			if (entry.Length == 0L)
			{
				return null;
			}
			using Stream entryStream = entry.Open();
			using MemoryStream memStream = new MemoryStream((int)entry.Length);
			await entryStream.CopyToAsync(memStream, (int)entry.Length, token).ConfigureAwait(continueOnCapturedContext: false);
			memStream.Position = 0L;
			return memStream.GetBuffer();
		}

		internal static async Task<(string? Content, string? Path)> ExtractToTextContentAsync(this ZipArchiveEntry entry, string outputFolder)
		{
			if (entry.Length == 0L)
			{
				return (Content: null, Path: null);
			}
			string path = Path.Combine(outputFolder, entry.Name);
			entry.ExtractToFile(path, overwrite: true);
			string item = null;
			using (StreamReader reader = File.OpenText(path))
			{
				item = await reader.ReadToEndAsync().ConfigureAwait(continueOnCapturedContext: false);
			}
			return (Content: item, Path: path);
		}

		internal static async Task<System.Version> GetVersionFromSnapshotFile(this ZipArchive? archive, CancellationToken token)
		{
			if (archive == null)
			{
				return DefaultVersion.Value;
			}
			ZipArchiveEntry entry = archive.GetEntry(VersionInfoFileName);
			if (entry != null)
			{
				Microsoft.Dynamics.Nav.AL.Common.SnapshotDebuggerSerializer.Version? version = await entry.ReadContentAsync<Microsoft.Dynamics.Nav.AL.Common.SnapshotDebuggerSerializer.Version>((ByteBuffer byteBuffer) => Microsoft.Dynamics.Nav.AL.Common.SnapshotDebuggerSerializer.Version.GetRootAsVersion(byteBuffer), token).ConfigureAwait(continueOnCapturedContext: false);
				if (version.HasValue)
				{
					return new System.Version(version.Value.Major, version.Value.Minor, version.Value.Build, version.Value.Revision);
				}
			}
			return DefaultVersion.Value;
		}
	}
