	public sealed class ActiveDocumentId : IEquatable<ActiveDocumentId>
	{
		public static ActiveDocumentId None = new ActiveDocumentId(null, string.Empty);

		internal DocumentId? DocumentId { get; }

		internal string? FilePath { get; }

		internal ActiveDocumentId(DocumentId? documentId, string? normalizedFilePath)
		{
			DocumentId = documentId;
			FilePath = normalizedFilePath;
		}

		internal ActiveDocumentId(string normalizedFilePath)
		{
			FilePath = normalizedFilePath ?? throw new ArgumentNullException("normalizedFilePath");
		}

		internal static ActiveDocumentId From(Document document)
		{
			if (document == null)
			{
				throw new ArgumentNullException("document");
			}
			return new ActiveDocumentId(document.Id, document.FilePath);
		}

		public bool Equals(ActiveDocumentId other)
		{
			if (this == other)
			{
				return true;
			}
			if (other == null)
			{
				return false;
			}
			if (DocumentId?.Id == other.DocumentId?.Id)
			{
				if ((object)FilePath != other.FilePath)
				{
					return FilePath?.Equals(other.FilePath, StringComparison.Ordinal) ?? false;
				}
				return true;
			}
			return false;
		}

		public override int GetHashCode()
		{
			return (DocumentId, FilePath).GetHashCode();
		}
	}
	internal static class ActiveProjectBuilder
	{
		public static async Task<(bool, ImmutableArray<(ProjectId, string)>)> BuildWorkspaceAsync(CancellationToken cancellationToken, IFileSystem fileSystem, VsCodeWorkspace workspace, string projectDir, IList<string> args, bool buildDependencyPackage, bool isRad, IResponseQueue responseQueue, bool forceBuildOfAllDependencies, CustomTelemetryEvent? telemetryEvent, ITelemetryService? telemetryService, string vsCodeExtensionVersion, IEmitLogger? emitLogger)
		{
			IEmitLogger emitLogger2 = emitLogger;
			IResponseQueue responseQueue2 = responseQueue;
			IList<string> args2 = args;
			VsCodeWorkspace workspace2 = workspace;
			ITelemetryService telemetryService2 = telemetryService;
			string vsCodeExtensionVersion2 = vsCodeExtensionVersion;
			StreamingTextWriter outputWriter = new StreamingTextWriter();
			if (emitLogger2 != null)
			{
				outputWriter.OnLineWritten += delegate(string line)
				{
					emitLogger2.Info(line);
				};
			}
			else
			{
				outputWriter.OnLineWritten += delegate(string line)
				{
					responseQueue2.Add(ResponseFactory.LogNotification(MessageType.Log, line), cancellationToken);
				};
			}
			Solution currentSolution = workspace2.CurrentSolution;
			Project currentProject = currentSolution.FindProject(projectDir);
			if (currentProject == null)
			{
				outputWriter.WriteLine(string.Format(CultureInfo.CurrentCulture, ProtocolResources.CannotBuildProjectWithNonExistingPath, projectDir));
				return (false, ImmutableArray<(ProjectId, string)>.Empty);
			}
			if (!workspace2.HasTransitiveClosureLoaded(currentSolution, currentProject.Id))
			{
				outputWriter.WriteLine(string.Format(CultureInfo.CurrentCulture, ProtocolResources.CannotBuildProjectThatHasNotLoaded, projectDir));
				return (false, ImmutableArray<(ProjectId, string)>.Empty);
			}
			AddGenerateCodeOption(args2);
			PooledList<(ProjectId, string)> projectOutputs = PooledList<(ProjectId, string)>.GetInstance();
			try
			{
				(bool, ImmutableArray<(ProjectId, string)>) tuple = await SolutionBuildHelper.ProcessTransitiveDependenciesInOrderAsync(currentSolution, currentProject.Id, async delegate(Project builtProject, CancellationToken ct)
				{
					IList<string> args3 = CreateArgs(builtProject.ProjectFolder, args2);
					return ((bool Success, string Result))(await Build(workspace2, builtProject, outputWriter, isRad, args3, ct, responseQueue2, telemetryService2, forceBuildOfAllDependencies, null, null, vsCodeExtensionVersion2).ConfigureAwait(continueOnCapturedContext: false));
				}, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				bool item = tuple.Item1;
				ImmutableArray<(ProjectId Id, string Result)> depOutputs = tuple.Item2;
				bool flag = item;
				if (item)
				{
					ImmutableArray<(ProjectId, string)>.Enumerator enumerator = depOutputs.GetEnumerator();
					while (enumerator.MoveNext())
					{
						var (item2, text) = enumerator.Current;
						if (!string.IsNullOrEmpty(text))
						{
							projectOutputs.Add((item2, text));
						}
					}
				}
				if (flag)
				{
					string text2;
					(flag, text2) = await Build(workspace2, currentProject, outputWriter, isRad, args2, cancellationToken, responseQueue2, telemetryService2, forceBuild: true, projectOutputs, telemetryEvent, vsCodeExtensionVersion2).ConfigureAwait(continueOnCapturedContext: false);
					if (buildDependencyPackage && (projectOutputs.Count > 0 || depOutputs.Length > 0))
					{
						new DependencyPackageOutputter(workspace2).CreateDependencyOutputPackage(fileSystem, projectOutputs, currentProject, text2);
					}
					if (flag)
					{
						projectOutputs.Add((currentProject.Id, text2));
					}
				}
				GCSettings.LargeObjectHeapCompactionMode = GCLargeObjectHeapCompactionMode.CompactOnce;
				GC.Collect(2, GCCollectionMode.Forced, blocking: true, compacting: true);
				return (flag, projectOutputs.ToImmutableArray());
			}
			finally
			{
				projectOutputs.Free();
			}
		}

		private static async Task<(bool Success, string OutputPath)> Build(VsCodeWorkspace workspace, Project builtProject, StreamingTextWriter outputWriter, bool isRad, IList<string> args, CancellationToken cancellationToken, IResponseQueue responseQueue, ITelemetryService telemetryService, bool forceBuild = false, IList<(ProjectId, string)> outputFiles = null, CustomTelemetryEvent? telemetryEvent = null, string? requestVsCodeExtensionVersion = null)
		{
			cancellationToken.ThrowIfCancellationRequested();
			string builtProjectFolder = builtProject.ProjectFolder;
			Compilation compilation = await workspace.CurrentSolution.GetCompilationAsync(builtProject.Id, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
			bool hasProjectRadChanges = workspace.ObjectChangeDocumentManager.HasProjectRadChanges(builtProject.Id);
			IObjectChangeManager objectChangeManager = workspace.ObjectChangeDocumentManager.GetObjectChangeManager(builtProject.Id);
			if (hasProjectRadChanges)
			{
				await workspace.ObjectChangeDocumentManager.UpdateObjectChangesAsync(cancellationToken, builtProject.Id).ConfigureAwait(continueOnCapturedContext: false);
			}
			objectChangeManager?.Serialize(builtProjectFolder.RadPath(), compilation.FileSystem);
			LanguageServerCompiler languageServerCompiler = CreateCompiler(compilation, isRad, builtProject, workspace, objectChangeManager, args);
			if (languageServerCompiler.Arguments.ProjectManifest == null)
			{
				languageServerCompiler.ReportErrors(languageServerCompiler.Arguments.Errors, outputWriter, null, compilation.Options);
				return (Success: false, OutputPath: string.Empty);
			}
			if (!string.IsNullOrEmpty(requestVsCodeExtensionVersion) && string.IsNullOrEmpty(languageServerCompiler.Arguments.ProjectManifest.AppManifest.BuildInformation?.By))
			{
				if (languageServerCompiler.Arguments.ProjectManifest.AppManifest.BuildInformation == null)
				{
					languageServerCompiler.Arguments.ProjectManifest.AppManifest.BuildInformation = new BuildInformation();
				}
				languageServerCompiler.Arguments.ProjectManifest.AppManifest.BuildInformation.By = "AL Language Extension," + requestVsCodeExtensionVersion;
			}
			if (builtProject.OutputAnalyzerStatistics)
			{
				languageServerCompiler.Arguments.ReportAnalyzer = true;
			}
			if (!forceBuild && !hasProjectRadChanges)
			{
				return (Success: true, OutputPath: string.Empty);
			}
			if (!builtProject.IncrementalBuild && outputFiles != null && outputFiles.Count > 0)
			{
				InvalidateReferenceCacheAndCopyReferencedProjectBuildOutputToPackageCachePath(workspace, outputFiles, builtProject.Id, responseQueue);
			}
			(int Success, string OutputPath) buildResult = (Success: languageServerCompiler.Run(outputWriter, telemetryService, cancellationToken), OutputPath: languageServerCompiler.OutputPath);
			workspace.ObjectChangeDocumentManager.Clear(builtProject.Id);
			bool hasBuildSucceeeded = buildResult.Success == 0;
			telemetryEvent?.Dimensions.Add("Build Success", hasBuildSucceeeded.ToString());
			if (hasBuildSucceeeded && telemetryEvent != null)
			{
				Compilation compilation2 = await workspace.CurrentSolution.GetCompilationAsync(builtProject.Id, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				telemetryEvent.Dimensions.Add("AppId", compilation2.ModuleInfo.AppId.ToString());
				telemetryEvent.Dimensions.Add("Dependency Count", compilation2.SymbolReferences.Length.ToStringInvariant());
				telemetryEvent.Dimensions.Add("Target", compilation2.Options.Target.ToString());
				telemetryEvent.Dimensions.Add("Suppressed Warnings", compilation2.Options.SpecificDiagnosticOptions.IsEmpty ? "None" : compilation2.Options.SpecificDiagnosticOptions.Select<KeyValuePair<string, ReportDiagnostic>, string>((KeyValuePair<string, ReportDiagnostic> kvp) => FormattableString.Invariant($"{kvp.Key}:{kvp.Value}")).Join(";"));
				telemetryEvent.Metrics.Add("Object Count", compilation2.CompiledModule.GetDeclaredObjectSymbols().Length);
			}
			return (Success: hasBuildSucceeeded, OutputPath: buildResult.OutputPath);
		}

		private static LanguageServerCompiler CreateCompiler(Compilation solutionTrackedCompilation, bool isRad, Project builtProject, VsCodeWorkspace workspace, IObjectChangeManager? objectChangeManager, IList<string> args)
		{
			string projectFolder = builtProject.ProjectFolder;
			bool externalRulesetsEnabled = builtProject.ExternalRulesetsEnabled;
			if (isRad && objectChangeManager != null)
			{
				return new RadLanguageServerCompiler(objectChangeManager, solutionTrackedCompilation, projectFolder, args, builtProject.AnalyzerReferences, builtProject.RuleSetPath, builtProject.CompilationOptions.OutFolder, externalRulesetsEnabled);
			}
			if (builtProject.IncrementalBuild)
			{
				return new IncrementalLanguageServerCompiler(solutionTrackedCompilation, projectFolder, args, builtProject.AnalyzerReferences, builtProject.RuleSetPath, builtProject.CompilationOptions.OutFolder, externalRulesetsEnabled);
			}
			return new LanguageServerCompiler(solutionTrackedCompilation, projectFolder, args, builtProject.AnalyzerReferences, builtProject.RuleSetPath, builtProject.CompilationOptions.OutFolder, externalRulesetsEnabled, null, workspace, builtProject.Id);
		}

		private static void InvalidateReferenceCacheAndCopyReferencedProjectBuildOutputToPackageCachePath(VsCodeWorkspace workspace, IEnumerable<(ProjectId, string)> outputFiles, ProjectId sourceProjectId, IResponseQueue responseQueue)
		{
			PooledList<IModuleSpecification> instance = PooledList<IModuleSpecification>.GetInstance();
			try
			{
				OutputConsoleLogger outputConsoleLogger = new OutputConsoleLogger(responseQueue);
				Solution currentSolution = workspace.CurrentSolution;
				Project project = currentSolution.GetProject(sourceProjectId);
				if (project == null)
				{
					return;
				}
				foreach (var outputFile in outputFiles)
				{
					Project project2 = currentSolution.GetProject(outputFile.Item1);
					instance.Add(project2.ProjectDefinition);
					try
					{
						string fileName = Path.GetFileName(outputFile.Item2);
						string destFileName = Path.Combine(project.PackageCachePaths.First(), fileName);
						File.Copy(outputFile.Item2, destFileName, overwrite: true);
					}
					catch (IOException ex)
					{
						outputConsoleLogger.Exception(ex);
					}
					catch (UnauthorizedAccessException ex2)
					{
						outputConsoleLogger.Exception(ex2);
					}
				}
				PooledList<Diagnostic> instance2 = PooledList<Diagnostic>.GetInstance();
				try
				{
					workspace.RefreshSymbolReferences(sourceProjectId, instance.Select((IModuleSpecification s) => new SymbolReferenceSpecification(s.Publisher, s.Name, s.Version, exact: false, s.AppId, isPropagated: false, s.AlternateIds)).ToList(), instance2);
					responseQueue.AddDiagnosticResponse(instance2, project.FilePath.GetUri(), project.RuleSetPath, CancellationToken.None);
				}
				finally
				{
					instance2.Free();
				}
				workspace.SymbolReferenceLoader.InvalidateModules(instance);
			}
			finally
			{
				instance.Free();
			}
		}

