			list.Add(string.Format(CultureInfo.InvariantCulture, "-project:\"{0}\"", projectFolder));
			string text = args.FirstOrDefault((string arg) => !string.IsNullOrEmpty(arg) && arg.StartsWith("/outfolder:", StringComparison.Ordinal));
			if (!string.IsNullOrEmpty(text))
			{
				list.Add(text);
			}
			AddGenerateCodeOption(list);
			return list;
		}

		private static IList<string> AddGenerateCodeOption(IList<string> args)
		{
			return args;
		}
