	public static class AsyncContext
	{
		public static void Start(Func<Task> asyncMainFunc)
		{
			if (SynchronizationContext.Current != null)
			{
				throw new InvalidOperationException("A SynchronizationContext is already assigned on this thread.");
			}
			ThreadSynchronizationContext threadSyncContext = new ThreadSynchronizationContext();
			SynchronizationContext.SetSynchronizationContext(threadSyncContext);
			Task task = asyncMainFunc();
			Action<Task> continuationAction = delegate
			{
				threadSyncContext.EndLoop();
			};
			task.ContinueWith(continuationAction, TaskScheduler.Default);
			threadSyncContext.RunLoopOnCurrentThread();
			task.GetAwaiter().GetResult();
		}
	}
	public class AsyncContextThread
	{
		private readonly CancellationTokenSource threadCancellationToken = new CancellationTokenSource();

		private Task threadTask;

		private readonly string threadName;

		public AsyncContextThread(string threadName)
		{
			this.threadName = threadName;
		}

		public Task Run(Func<Task> taskReturningFunc)
		{
			Func<Task> taskReturningFunc2 = taskReturningFunc;
			threadTask = Task.Factory.StartNew(delegate
			{
				System.Threading.Thread.CurrentThread.Name = "AsyncContextThread: " + threadName;
				AsyncContext.Start(taskReturningFunc2);
			}, threadCancellationToken.Token, TaskCreationOptions.LongRunning, TaskScheduler.Default);
			return threadTask;
		}

		public void Stop()
		{
			threadCancellationToken.Cancel();
		}
	}
	public class AsyncLock
	{
		private class LockReleaser : IDisposable
		{
			private readonly AsyncLock lockToRelease;

			internal LockReleaser(AsyncLock lockToRelease)
			{
				this.lockToRelease = lockToRelease;
			}

			public void Dispose()
			{
				lockToRelease.lockSemaphore.Release();
			}
		}

		private readonly SemaphoreSlim lockSemaphore = new SemaphoreSlim(1, 1);

		private readonly Task<IDisposable> lockReleaseTask;

		public AsyncLock()
		{
			lockReleaseTask = Task.FromResult((IDisposable)new LockReleaser(this));
		}

		public Task<IDisposable> LockAsync()
		{
			return LockAsync(CancellationToken.None);
		}

		public Task<IDisposable> LockAsync(CancellationToken cancellationToken)
		{
			Task task = lockSemaphore.WaitAsync(cancellationToken);
			if (task.IsCompleted)
			{
				return lockReleaseTask;
			}
			IDisposable result = lockReleaseTask.Result;
			return task.ContinueWith((Task t, object? releaser) => (IDisposable)releaser, result, cancellationToken, TaskContinuationOptions.ExecuteSynchronously, TaskScheduler.Default);
		}
	}
