	internal static class ClassifiedSpanUtility
	{
		internal static List<int> ConvertToSemanticTokenArray(IEnumerable<ClassifiedSpan> results, TextLineCollection lines, ClassificationToSemanticTokensConverter classificationToSemanticTokensConverter)
		{
			List<int> list = new List<int>();
			if (results == null || results.IsEmpty())
			{
				return list;
			}
			int num = 0;
			int num2 = 0;
			SemanticTokenDataEntry semanticTokenDataEntry = default(SemanticTokenDataEntry);
			foreach (IGrouping<TextSpan, ClassifiedSpan> item in from r in results
				group r by r.TextSpan)
			{
				TextSpan key = item.Key;
				LinePositionSpan linePositionSpan = lines.GetLinePositionSpan(key);
				int line = linePositionSpan.Start.Line;
				int character = linePositionSpan.Start.Character;
				if (line != num)
				{
					num2 = 0;
				}
				semanticTokenDataEntry.LineNumber = line - num;
				semanticTokenDataEntry.CharNumber = character - num2;
				semanticTokenDataEntry.Length = key.Length;
				semanticTokenDataEntry.Type = 0;
				semanticTokenDataEntry.Modifiers = 0;
				foreach (ClassifiedSpan item2 in item)
				{
					int typeValue2;
					if (classificationToSemanticTokensConverter.TryGetType(item2.ClassificationType, out var typeValue))
					{
						semanticTokenDataEntry.Type = typeValue;
					}
					else if (classificationToSemanticTokensConverter.TryGetType(item2.ClassificationType, out typeValue2))
					{
						semanticTokenDataEntry.Modifiers |= typeValue2;
					}
					if (item2.Modifier != null && classificationToSemanticTokensConverter.TryGetModifier(item2.Modifier, out var modifierValue))
					{
						semanticTokenDataEntry.Modifiers |= modifierValue;
					}
					if (item2.ClassificationType == "Built In Function Name" && classificationToSemanticTokensConverter.TryGetModifier("defaultLibrary", out var modifierValue2))
					{
						semanticTokenDataEntry.Modifiers |= modifierValue2;
					}
					if (item2.ClassificationType == "event name" && classificationToSemanticTokensConverter.TryGetModifier("static", out var modifierValue3))
					{
						semanticTokenDataEntry.Modifiers |= modifierValue3;
					}
				}
				num2 = character;
				num = line;
				list.Add(semanticTokenDataEntry.LineNumber);
				list.Add(semanticTokenDataEntry.CharNumber);
				list.Add(semanticTokenDataEntry.Length);
				list.Add(semanticTokenDataEntry.Type);
				list.Add(semanticTokenDataEntry.Modifiers);
			}
			return list;
		}
	}
	internal static class CompletionHelper
	{
		private static readonly ISet<string> GlyphEnumNames = Enum.GetNames(typeof(Glyph)).ToSet();

		internal static IList<DebugAdapterCompletionItem> FromCompletions(this IList<Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.Contract.CompletionItem> completions)
		{
			return completions.Select((Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.Contract.CompletionItem c) => new DebugAdapterCompletionItem
			{
				Label = c.Label?.Label,
				Text = c.InsertText,
				Type = MapFromCompletionItemKind(c.Kind),
				Detail = c.Detail,
				SortText = c.SortText
			}).ToList();
			static DebugAdapterCompletionItemType MapFromCompletionItemKind(CompletionItemKind? kind)
			{
				if (!kind.HasValue)
				{
					return DebugAdapterCompletionItemType.CustomColor;
				}
				if (kind.GetValueOrDefault() == CompletionItemKind.Text)
				{
					return DebugAdapterCompletionItemType.Text;
				}
				if (kind > CompletionItemKind.Reference)
				{
					return DebugAdapterCompletionItemType.CustomColor;
				}
				return (DebugAdapterCompletionItemType)kind.Value;
			}
		}

		internal static CompletionItemKind MapToKind(this Glyph glyph)
		{
			switch (glyph)
			{
			case Glyph.Parameter:
			case Glyph.LocalVariable:
			case Glyph.GlobalVariable:
				return CompletionItemKind.Variable;
			case Glyph.Property:
				return CompletionItemKind.Property;
			case Glyph.Method:
			case Glyph.Builtin:
				return CompletionItemKind.Method;
			case Glyph.Trigger:
				return CompletionItemKind.Function;
			case Glyph.Field:
				return CompletionItemKind.Field;
			case Glyph.Class:
			case Glyph.Table:
			case Glyph.Codeunit:
			case Glyph.Report:
			case Glyph.Query:
			case Glyph.XmlPort:
			case Glyph.Page:
				return CompletionItemKind.Class;
			case Glyph.Interface:
				return CompletionItemKind.Interface;
			case Glyph.Enum:
				return CompletionItemKind.Enum;
			case Glyph.EnumValue:
				return CompletionItemKind.EnumMember;
			case Glyph.Constant:
			case Glyph.Keyword:
			case Glyph.Type:
				return CompletionItemKind.Keyword;
			case Glyph.Option:
				return CompletionItemKind.Enum;
			case Glyph.Action:
			case Glyph.Control:
				return CompletionItemKind.Field;
			case Glyph.Snippet:
				return CompletionItemKind.Snippet;
			case Glyph.Namespace:
				return CompletionItemKind.Module;
			default:
				return CompletionItemKind.Reference;
			}
		}

		internal static Glyph GetGlyphForCompletionItem(this Microsoft.Dynamics.Nav.CodeAnalysis.Workspaces.Completion.CompletionItem item)
		{
			string text = item.Tags.FirstOrDefault((string t) => GlyphEnumNames.Contains(t));
			if (text == null || !Enum.TryParse<Glyph>(text, out var result))
			{
				return Glyph.None;
			}
			return result;
		}
	}
	public static class DocumentExtensions
	{
		private static readonly HashSet<SyntaxKind> NoneSymbolizedSyntaxSet = new HashSet<SyntaxKind>
