			SyntaxKind.ReportLabelsSection,
			SyntaxKind.FieldGroupList
		};

		private static readonly HashSet<SymbolKind> ExcludedSymbols = new HashSet<SymbolKind>
		{
			SymbolKind.Property,
			SymbolKind.Permission
		};

		public static async Task<SymbolInformation[]> GetSymbolInformations(this Document document, CancellationToken cancellationToken, bool onlySearchTopLevelObjects, Predicate<ISymbol> predicate = null)
		{
