		public static async Task<IList<ISymbol>?> GetSymbols(this Document document, CancellationToken cancellationToken)
		{
			if (await document.GetSyntaxRootAsync().ConfigureAwait(continueOnCapturedContext: false) == null)
			{
				return null;
			}
			SemanticModel semanticModel = await document.GetSemanticModelAsync(cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
			string uri = document.FilePath.GetUri();
			ArrayBuilder<ISymbol> instance = ArrayBuilder<ISymbol>.GetInstance();
			try
			{
				foreach (SyntaxNode item in semanticModel.Root.DescendantNodes())
				{
					cancellationToken.ThrowIfCancellationRequested();
					if (item.Kind.IsObject() && semanticModel.GetDeclaredSymbol(item, cancellationToken) is ObjectTypeSymbol objectTypeSymbol && !objectTypeSymbol.Kind.IsNestedObject() && objectTypeSymbol.IsInSource && !string.IsNullOrEmpty(objectTypeSymbol.Name))
					{
						ProcessMember(uri, (ISymbol s) => true, objectTypeSymbol, instance, isCodeLens: false, onlySearchTopLevelObjects: true, (Symbol symbol) => symbol, null);
					}
				}
				return instance.ToArray();
			}
			finally
			{
				instance.Free();
			}
		}

		private static async Task<SymbolInformation[]> GetSymbolInformations(Document document, CancellationToken cancellationToken, bool onlySearchTopLevelObjects, bool isCodeLens, Predicate<ISymbol> predicate = null)
		{
			predicate = predicate ?? ((Predicate<ISymbol>)((ISymbol s) => true));
			SemanticModel semanticModel = await document.GetSemanticModelAsync(cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
			string uri = document.FilePath.GetUri();
			ArrayBuilder<SymbolInformation> instance = ArrayBuilder<SymbolInformation>.GetInstance();
			try
			{
				foreach (SyntaxNode item in semanticModel.Root.DescendantNodes())
				{
					cancellationToken.ThrowIfCancellationRequested();
					if (item.Kind.IsObject() && semanticModel.GetDeclaredSymbol(item, cancellationToken) is ObjectTypeSymbol objectTypeSymbol && !objectTypeSymbol.Kind.IsNestedObject() && objectTypeSymbol.IsInSource && !string.IsNullOrEmpty(objectTypeSymbol.Name) && predicate(objectTypeSymbol))
					{
						ProcessMember(uri, predicate, objectTypeSymbol, instance, isCodeLens, onlySearchTopLevelObjects);
					}
				}
				return instance.ToArray();
			}
			finally
			{
