		public static async Task<DocumentSymbol[]> GetDocumentSymbols(this Document document, CancellationToken cancellationToken)
		{
			SemanticModel semanticModel = await document.GetSemanticModelAsync(cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
			ArrayBuilder<DocumentSymbol> instance = ArrayBuilder<DocumentSymbol>.GetInstance();
			try
			{
				foreach (SyntaxNode item in semanticModel.Root.DescendantNodes())
				{
					cancellationToken.ThrowIfCancellationRequested();
					if (item.Kind.IsObject() && semanticModel.GetDeclaredSymbol(item, cancellationToken) is ObjectTypeSymbol objectTypeSymbol && !objectTypeSymbol.Kind.IsNestedObject() && objectTypeSymbol.IsInSource && !string.IsNullOrEmpty(objectTypeSymbol.Name))
					{
						DocumentSymbol documentSymbol = CrateDocumentSymbolFromMember(objectTypeSymbol);
						if (documentSymbol != null)
						{
							instance.Add(documentSymbol);
						}
					}
				}
				return instance.ToArray();
			}
			finally
			{
				instance.Free();
			}
		}

		private static DocumentSymbol? CrateDocumentSymbolFromMember(Symbol symbol)
		{
			if (!ExcludedSymbols.Contains(symbol.Kind) && symbol.IsInSource && !string.IsNullOrEmpty(symbol.Name))
			{
				DocumentSymbol documentSymbol = symbol.ToDocumentSymbol();
				ArrayBuilder<DocumentSymbol> instance = ArrayBuilder<DocumentSymbol>.GetInstance();
				try
				{
					if (symbol is ContainerSymbol containerSymbol)
					{
						PooledHashSet<Symbol> instance2 = PooledHashSet<Symbol>.GetInstance();
						try
						{
							if (containerSymbol.DeclaringSyntaxReference != null)
							{
								ImmutableArray<Symbol> members = containerSymbol.GetMembers();
								foreach (SyntaxNode item in containerSymbol.DeclaringSyntaxReference.GetSyntax().ChildNodes())
								{
									DocumentSymbol documentSymbol2 = CreateSyntaxDocumentSymbol(item, members, instance2);
									if (documentSymbol2 != null && !string.IsNullOrEmpty(documentSymbol2.Name))
									{
										instance.Add(documentSymbol2);
									}
								}
								ImmutableArray<Symbol>.Enumerator enumerator2 = members.GetEnumerator();
								while (enumerator2.MoveNext())
								{
									Symbol current = enumerator2.Current;
									if (current.DeclaringSyntaxReference != null && !instance2.Contains(current))
									{
										DocumentSymbol documentSymbol3 = CrateDocumentSymbolFromMember(current);
										instance2.Add(current);
										if (documentSymbol3 != null)
										{
											instance.Add(documentSymbol3);
										}
									}
								}
							}
						}
						finally
						{
							instance2.Free();
						}
					}
					documentSymbol.Children = instance.ToArray();
					return documentSymbol;
				}
				finally
				{
					instance.Free();
				}
			}
			return null;
		}

		private static DocumentSymbol? CreateSyntaxDocumentSymbol(SyntaxNode grpSyntax, ImmutableArray<Symbol> modelMembers, PooledHashSet<Symbol> usedMembers)
		{
			if (NoneSymbolizedSyntaxSet.Contains(grpSyntax.Kind))
			{
				DocumentSymbol documentSymbol = grpSyntax.ToDocumentSymbol();
				if (documentSymbol != null)
				{
					ArrayBuilder<DocumentSymbol> instance = ArrayBuilder<DocumentSymbol>.GetInstance();
					try
					{
						ImmutableArray<Symbol>.Enumerator enumerator = modelMembers.GetEnumerator();
						while (enumerator.MoveNext())
						{
							Symbol current = enumerator.Current;
							if (current.DeclaringSyntaxReference != null && grpSyntax.Span.OverlapsWith(current.DeclaringSyntaxReference.Span))
							{
								DocumentSymbol documentSymbol2 = CrateDocumentSymbolFromMember(current);
								usedMembers.Add(current);
								if (documentSymbol2 != null)
								{
									instance.Add(documentSymbol2);
								}
							}
						}
						documentSymbol.Children = instance.ToArray();
					}
					finally
					{
						instance.Free();
					}
				}
				return documentSymbol;
			}
			return null;
		}

		private static void ProcessMember(string fileUri, Predicate<ISymbol> predicate, Symbol symbol, ArrayBuilder<SymbolInformation> builder, bool isCodeLens, bool onlySearchTopLevelObjects, int depth = 0)
		{
			string fileUri2 = fileUri;
			ProcessMember(fileUri2, predicate, symbol, builder, isCodeLens, onlySearchTopLevelObjects, (Symbol symbol) => symbol.ToSymbolInformation(fileUri2, isCodeLens), (SyntaxNode syntax) => syntax.ToSymbolInformation(fileUri2), depth);
		}

		private static void ProcessMember<T>(string fileUri, Predicate<ISymbol> predicate, Symbol symbol, ArrayBuilder<T> builder, bool isCodeLens, bool onlySearchTopLevelObjects, Func<Symbol, T> symbolToResult, Func<SyntaxNode, T>? syntaxToResult, int depth = 0)
		{
			if (!ExcludedSymbols.Contains(symbol.Kind) && symbol.IsInSource && !string.IsNullOrEmpty(symbol.Name) && ((onlySearchTopLevelObjects && depth == 0) || (!onlySearchTopLevelObjects && predicate(symbol))))
			{
				builder.Add(symbolToResult(symbol));
			}
			if (!(symbol is ContainerSymbol containerSymbol) || onlySearchTopLevelObjects)
			{
				return;
			}
			ImmutableArray<Symbol>.Enumerator enumerator = containerSymbol.GetMembers().GetEnumerator();
			while (enumerator.MoveNext())
			{
				Symbol current = enumerator.Current;
				ProcessMember(fileUri, predicate, current, builder, isCodeLens, onlySearchTopLevelObjects, symbolToResult, syntaxToResult, depth + 1);
			}
			if (isCodeLens || syntaxToResult == null || containerSymbol.DeclaringSyntaxReference == null)
			{
				return;
			}
			foreach (SyntaxNode item in containerSymbol.DeclaringSyntaxReference.GetSyntax().ChildNodes())
			{
				if (NoneSymbolizedSyntaxSet.Contains(item.Kind))
				{
					builder.Add(syntaxToResult(item));
				}
			}
		}
	}
