	internal class InlayHintBoundVisitor : BoundTreeWalkerWithStackGuard
	{
		public HashSet<BoundCall> Result { get; }

		public InlayHintOptions? Options { get; }

		public InlayHintBoundVisitor(HashSet<BoundCall> result, InlayHintOptions? options)
		{
			Result = result;
			Options = options;
		}

		public override BoundNode VisitCall(BoundCall node)
		{
			if (node.HasAnyErrors)
			{
				return base.VisitCall(node);
			}
			if (IncludeNode(node))
			{
				Result.Add(node);
			}
			return base.VisitCall(node);
		}

		private bool IncludeNode(BoundCall boundCall)
		{
			if (Options == null)
			{
				return false;
			}
			ImmutableArray<BoundExpression> arguments = boundCall.Arguments;
			if (Options.ParameterNamesEnabled && boundCall.EffectiveParameters != null && arguments.Length > 0)
			{
				return true;
			}
			if (Options.ReturnTypesEnabled && boundCall.Method.ReturnType != null && boundCall.Method.ReturnType.NavTypeKind != 0)
			{
				return true;
			}
			return false;
		}
	}
	internal class InlayHintSyntaxVisitor : SyntaxWalker
	{
		public SemanticModel Model { get; }

		public InlayHintBoundVisitor BoundVisitor { get; }

		public TextSpan? Span { get; }

		public InlayHintSyntaxVisitor(SemanticModel model, InlayHintBoundVisitor boundVisitor, TextSpan? span)
		{
			Model = model;
			BoundVisitor = boundVisitor;
			Span = span;
		}

		public override void VisitMethodDeclaration(MethodDeclarationSyntax node)
		{
			VisitOperation(node.Body);
			base.VisitMethodDeclaration(node);
		}

		public override void VisitTriggerDeclaration(TriggerDeclarationSyntax node)
		{
			VisitOperation(node.Body);
			base.VisitTriggerDeclaration(node);
		}

		private void VisitOperation(BlockSyntax? blockSyntax)
		{
			if (blockSyntax != null && Overlaps(blockSyntax.Span) && Model.GetOperation(blockSyntax) is BoundNode node)
			{
				BoundVisitor.Visit(node);
			}
		}

		private bool Overlaps(TextSpan nodeSpan)
		{
			if (!Span.HasValue)
			{
				return true;
			}
			return Span.Value.OverlapsWith(nodeSpan);
		}
	}
