	internal class ReferenceSymbolDefinitionHelper
	{
		public static SymbolInformation[] GetSymbolInformations(IModuleSymbol module, string projectFolder, CancellationToken cancellationToken, Predicate<ISymbol> predicate = null)
		{
			Predicate<ISymbol> predicate2 = predicate;
			string projectFolder2 = projectFolder;
			if (predicate2 == null)
			{
				predicate2 = (ISymbol s) => true;
			}
			PooledConcurrentSet<SymbolInformation> informations = PooledConcurrentSet<SymbolInformation>.GetInstance();
			try
			{
				new ConcurrentQueue<SymbolInformation>();
				Parallel.ForEach(module.GetObjectSymbols(), delegate(IContainerSymbol symbol)
				{
					if (!cancellationToken.IsCancellationRequested)
					{
						ObjectTypeSymbol objectTypeSymbol = (ObjectTypeSymbol)symbol;
						if (!objectTypeSymbol.Kind.IsNestedObject() && !string.IsNullOrEmpty(objectTypeSymbol.Name) && predicate2(objectTypeSymbol))
						{
							string sourceLocation = SymbolExtensions.GetSourceLocation(projectFolder2, objectTypeSymbol);
							if (sourceLocation != null)
							{
								ProcessReferenceMember(sourceLocation, predicate2, objectTypeSymbol, informations);
							}
						}
					}
				});
				if (cancellationToken.IsCancellationRequested)
				{
					return Array.Empty<SymbolInformation>();
				}
				return informations.ToArray();
			}
			finally
			{
				if (informations != null)
				{
					((IDisposable)informations).Dispose();
				}
			}
		}

		private static void ProcessReferenceMember(string fileUri, Predicate<ISymbol> predicate, Symbol symbol, PooledConcurrentSet<SymbolInformation> builder)
