		}

		private static void ProcessReferenceMember<T>(Predicate<ISymbol> predicate, Symbol symbol, PooledConcurrentSet<T> builder, Func<Symbol, T> symbolToResult)
		{
			if (!string.IsNullOrEmpty(symbol.Name) && predicate(symbol))
			{
				builder.Add(symbolToResult(symbol));
			}
		}
	}
