		private static string GetSymbolInformationName(Symbol symbol)
		{
			if (symbol.Kind == SymbolKind.RequestPage)
			{
				return symbol.DeclaringSyntaxNode.GetFirstToken().ValueText;
			}
			return symbol.ToDisplayString(SymbolDisplayFormat.OutLineFormat) ?? symbol.Name;
