		internal static SymbolInformationKind ToSymbolInformationKind(this ISymbol symbol)
		{
			switch (symbol.Kind)
			{
			case SymbolKind.GlobalVariable:
			case SymbolKind.LocalVariable:
			case SymbolKind.Parameter:
				return SymbolInformationKind.Variable;
			case SymbolKind.Property:
				return SymbolInformationKind.Property;
			case SymbolKind.Method:
				return GetMethodKind((IMethodSymbol)symbol);
			case SymbolKind.Field:
				return SymbolInformationKind.Field;
			case SymbolKind.Table:
			case SymbolKind.Codeunit:
			case SymbolKind.Page:
			case SymbolKind.Report:
			case SymbolKind.Query:
			case SymbolKind.XmlPort:
			case SymbolKind.TableExtension:
			case SymbolKind.ReportExtension:
			case SymbolKind.RequestPage:
			case SymbolKind.RequestPageExtension:
				return SymbolInformationKind.Class;
			case SymbolKind.Key:
				return SymbolInformationKind.Key;
			case SymbolKind.Event:
				return SymbolInformationKind.Event;
			case SymbolKind.Control:
				return GetControlKind((IControlSymbol)symbol);
			case SymbolKind.Enum:
			case SymbolKind.EnumExtension:
				return SymbolInformationKind.Enum;
			case SymbolKind.EnumValue:
				return SymbolInformationKind.EnumMember;
			case SymbolKind.Action:
				if (((IActionSymbol)symbol).ActionKind != ActionKind.Action)
				{
					return SymbolInformationKind.Object;
				}
				return SymbolInformationKind.Method;
			case SymbolKind.Interface:
				return SymbolInformationKind.Interface;
			case SymbolKind.Namespace:
				return SymbolInformationKind.Namespace;
			default:
				return SymbolInformationKind.Object;
			}
		}

		private static SymbolInformationKind GetMethodKind(IMethodSymbol symbol)
		{
			switch (symbol.MethodKind)
			{
			case MethodKind.Trigger:
				return SymbolInformationKind.Function;
			case MethodKind.BuiltInOperator:
				return SymbolInformationKind.Operator;
			case MethodKind.EventTrigger:
				return SymbolInformationKind.Event;
			case MethodKind.Method:
				if (!symbol.IsLocal)
				{
					return SymbolInformationKind.Function;
				}
				return SymbolInformationKind.Method;
			default:
				return SymbolInformationKind.Method;
			}
		}

		private static SymbolInformationKind GetControlKind(IControlSymbol symbol)
		{
			switch (symbol.ControlKind)
			{
			case ControlKind.Repeater:
				return SymbolInformationKind.Array;
			case ControlKind.Field:
				return SymbolInformationKind.Field;
			case ControlKind.Fixed:
			case ControlKind.Grid:
			case ControlKind.Part:
			case ControlKind.SystemPart:
			case ControlKind.Label:
			case ControlKind.UserControl:
			case ControlKind.ChartPart:
				return SymbolInformationKind.Package;
			default:
				return SymbolInformationKind.Namespace;
			}
		}

