		internal static string? GetSourceRelativePath(ISymbol symbol)
		{
			string text = null;
			string text2 = null;
			switch (symbol.Location?.Kind)
			{
			case LocationKind.SourceFile:
				text2 = ((Symbol)symbol).DeclaringCompilation?.FileSystem?.GetDirectoryPath();
				text = symbol.Location.SourceTree.FilePath;
				break;
			case LocationKind.ReferenceSourceFile:
				text = WebUtility.UrlDecode(((ReferenceSourceFileLocation)symbol.Location).FileName);
				text2 = Path.GetPathRoot(text);
				break;
			}
			if (text == null)
			{
				return null;
			}
			text = Path.GetDirectoryName(text)?.Substring(text2?.Length ?? 0);
			if (string.IsNullOrEmpty(text))
			{
				return null;
			}
			text = text.TrimStart(PathSeparators);
			int num = text.IndexOfAny(PathSeparators);
			if (num >= 0)
			{
				return text.Substring(0, num);
			}
			return text;
		}

		internal static ApplicationObject ToApplicationObject(ISymbol obj, string projectFolder, bool skipModule = false)
