		internal static T AssignToApplicationObject<T>(T applicationObject, ISymbol obj, string projectFolder, bool skipModule = false, bool skipRelated = false) where T : ApplicationObject
		{
			string name = obj.Name;
			IModuleSymbol containingModule = obj.ContainingModule;
			applicationObject.Name = name;
			applicationObject.Id = ((obj is ISymbolWithId symbolWithId) ? symbolWithId.Id : 0);
			applicationObject.Type = obj.Kind;
			switch (obj.Kind)
			{
			case SymbolKind.Codeunit:
				applicationObject.CodeunitSubtype = ((ICodeunitTypeSymbol)obj).Subtype;
				break;
			case SymbolKind.Table:
				applicationObject.TableType = ((ITableTypeSymbol)obj).TableType;
				break;
			case SymbolKind.Page:
				applicationObject.PageType = ((IPageTypeSymbol)obj).PageType;
				break;
			case SymbolKind.Query:
				applicationObject.QueryType = ((IQueryTypeSymbol)obj).QueryType;
				break;
			}
			if (!skipRelated)
			{
				ITableTypeSymbol relatedTableSymbol = obj.GetRelatedTableSymbol();
				if (relatedTableSymbol != null)
				{
					applicationObject.RelatedTableId = relatedTableSymbol.Id;
					applicationObject.RelatedTableName = relatedTableSymbol.Name;
				}
			}
			if (!skipModule)
			{
				applicationObject.AppId = containingModule?.AppId.ToString();
				applicationObject.AppName = containingModule?.Name;
				applicationObject.AppPublisher = containingModule?.Publisher;
				applicationObject.AppVersion = containingModule?.Version.ToString();
			}
			applicationObject.IsSource = obj.IsSourceSymbol();
			applicationObject.Location = GetSymbolLocation(obj, projectFolder);
			applicationObject.Path = GetSourceRelativePath(obj);
			applicationObject.Namespace = (obj.ContainingNamespace as NamespaceSymbol)?.QualifiedName;
			return applicationObject;
		}

