		internal static IEnumerable<IApplicationObjectTypeSymbol> GetImplementors(this InterfaceTypeSymbol interfaceType, Compilation compilation)
		{
			IEnumerable<ISymbol> enumerable = compilation.GetApplicationObjectTypeSymbolsAcrossModules(SymbolKind.Codeunit);
			string interfaceName = interfaceType.Name;
			foreach (CodeunitTypeSymbol item in enumerable)
			{
				ImmutableArray<InterfaceTypeSymbol>.Enumerator enumerator2 = item.ImplementedInterfaces.GetEnumerator();
				while (enumerator2.MoveNext())
				{
					InterfaceTypeSymbol current = enumerator2.Current;
					if (!current.IsUnresolvedInterface() && SemanticFacts.IsSameName(current.Name, interfaceName))
					{
						yield return item;
						break;
					}
				}
			}
			IEnumerable<ISymbol> enumerable2 = compilation.GetApplicationObjectTypeSymbolsAcrossModules(SymbolKind.Enum);
			foreach (EnumTypeSymbol item2 in enumerable2)
			{
				ImmutableArray<InterfaceTypeSymbol>.Enumerator enumerator2 = item2.ImplementedInterfaces.GetEnumerator();
				while (enumerator2.MoveNext())
				{
					InterfaceTypeSymbol current2 = enumerator2.Current;
					if (!current2.IsUnresolvedInterface() && SemanticFacts.IsSameName(current2.Name, interfaceName))
					{
						yield return item2;
						break;
					}
				}
			}
		}

		internal static bool IsPositionOnTheLocationOfApplicationObjectReference(this ISymbol symbol, Position requestPosition)
		{
			Position startPosition = symbol.Location.GetLineSpan().StartLinePosition;
			Position endPosition = symbol.Location.GetLineSpan().EndLinePosition;
			ITypeSymbol typeSymbol = symbol.GetTypeSymbol();
			bool num = typeSymbol != null && typeSymbol.TypeCategory == TypeCategoryKind.ApplicationObject;
			bool flag = symbol == typeSymbol?.OriginalDefinition;
			if (num && !flag)
			{
				return IsBetween(startPosition, endPosition, requestPosition);
			}
			return false;
		}

		private static bool IsBetween(Position startPosition, Position endPosition, Position position)
		{
			if ((startPosition.Line == position.Line && startPosition.Character <= position.Character) || startPosition.Line < position.Line)
			{
				if (endPosition.Line != position.Line || endPosition.Character < position.Character)
				{
					return endPosition.Line > position.Line;
				}
				return true;
			}
			return false;
		}
	}
	public class SymbolRequestQueryMatcher
	{
		private readonly string[] queryStrings;

		public SymbolRequestQueryMatcher(string query)
		{
			ArrayBuilder<string> instance = ArrayBuilder<string>.GetInstance();
			string[] array = query.Split();
			for (int i = 0; i < array.Length; i++)
			{
				if (!string.IsNullOrEmpty(array[i]))
				{
					instance.Add(array[i].ToLowerInvariant());
				}
			}
			queryStrings = instance.ToArrayAndFree();
		}

		public bool Matches(ISymbol symbol)
		{
			string text = symbol.Kind.ToString();
			string text2 = ((!symbol.Kind.IsRootObjectTypeSymbol()) ? null : symbol.GetContainingApplicationObjectTypeSymbol()?.Id.ToString(CultureInfo.InvariantCulture));
			string[] array = queryStrings;
			foreach (string value in array)
			{
				if (!text.StartsWith(value, StringComparison.OrdinalIgnoreCase) && (text2 == null || !text2.StartsWith(value, StringComparison.OrdinalIgnoreCase)) && !symbol.Name.Contains(value, StringComparison.OrdinalIgnoreCase))
				{
					return false;
				}
			}
			return true;
		}
	}
