	internal static class SyntaxFoldingService
	{
		private class SyntaxFoldingSyntaxWalker : SyntaxWalker, IDisposable
		{
			private readonly ArrayBuilder<FoldingRange> builder;

			private readonly CancellationToken cancellationToken;

			private SyntaxNode firstUsing;

			private SyntaxNode lastUsing;

			public SyntaxFoldingSyntaxWalker(ArrayBuilder<FoldingRange> builder, CancellationToken cancellationToken)
			{
				this.builder = builder;
				this.cancellationToken = cancellationToken;
			}

			public override void DefaultVisit(SyntaxNode node)
			{
				base.DefaultVisit(node);
				if (node.Kind == SyntaxKind.CompilationUnit)
				{
					return;
				}
				cancellationToken.ThrowIfCancellationRequested();
				if (node.Kind == SyntaxKind.UsingDirective)
				{
					if (firstUsing == null)
					{
						firstUsing = node;
					}
					lastUsing = node;
				}
				FoldingRange foldingRange = CreateFoldingRange(node, FoldingRangeKind.Region);
				if (foldingRange != null)
				{
					builder.Add(foldingRange);
				}
			}

			public void Dispose()
			{
				if (firstUsing != null && lastUsing != null && firstUsing != lastUsing)
				{
					builder.Add(CreateFoldingRangeFromTwoTrivia(firstUsing, lastUsing, FoldingRangeKind.Imports));
				}
			}
		}

		public static async Task<FoldingRange[]> GetFoldingRanges(this Document document, CancellationToken cancellationToken)
		{
			SemanticModel semanticModel = await document.GetSemanticModelAsync(cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
			ArrayBuilder<FoldingRange> instance = ArrayBuilder<FoldingRange>.GetInstance();
			try
			{
				using (SyntaxFoldingSyntaxWalker syntaxFoldingSyntaxWalker = new SyntaxFoldingSyntaxWalker(instance, cancellationToken))
				{
					syntaxFoldingSyntaxWalker.Visit(semanticModel.Root);
				}
				Stack<SyntaxTrivia> stack = new Stack<SyntaxTrivia>();
				Stack<SyntaxTrivia> stack2 = new Stack<SyntaxTrivia>();
				List<SyntaxTrivia> list = semanticModel.Root.DescendantTrivia().ToList();
				for (int i = 0; i < list.Count; i++)
				{
					SyntaxTrivia syntaxTrivia = list[i];
					cancellationToken.ThrowIfCancellationRequested();
					if (syntaxTrivia.IsDocumentationCommentTrivia || syntaxTrivia.IsMultiLineComment())
					{
						Range? range = syntaxTrivia.ToRange();
						FoldingRange foldingRange = new FoldingRange
						{
							Kind = FoldingRangeKind.Comment,
							StartLine = (uint)range.Value.Start.Line,
							StartCharacter = (uint)range.Value.End.Character,
							EndLine = (uint)range.Value.End.Line,
							EndCharacter = (uint)range.Value.End.Character
						};
						SyntaxTrivia syntaxTrivia2 = ((i != list.Count - 1) ? list[i + 1] : default(SyntaxTrivia));
						if (syntaxTrivia.IsDocumentationCommentTrivia && syntaxTrivia2 != default(SyntaxTrivia) && foldingRange.EndLine == syntaxTrivia2.ToRange().Value.Start.Line)
						{
							foldingRange.EndLine--;
							foldingRange.EndCharacter = 0u;
						}
						instance.Add(foldingRange);
					}
					if (!syntaxTrivia.IsDirective)
					{
						continue;
					}
					switch (syntaxTrivia.Kind)
					{
					case SyntaxKind.RegionDirectiveTrivia:
						stack2.Push(syntaxTrivia);
						break;
					case SyntaxKind.EndRegionDirectiveTrivia:
						if (stack2.Count > 0)
						{
							instance.Add(CreateFoldingRangeFromTwoTrivia(stack2.Pop(), syntaxTrivia, FoldingRangeKind.Region));
						}
						break;
					case SyntaxKind.IfDirectiveTrivia:
						stack.Push(syntaxTrivia);
						break;
					case SyntaxKind.ElifDirectiveTrivia:
					case SyntaxKind.ElseDirectiveTrivia:
						if (stack.Count > 0)
						{
							SyntaxTrivia startNode = stack.Pop();
							instance.Add(CreateFoldingRangeFromTwoTrivia(startNode, syntaxTrivia, FoldingRangeKind.Region));
							stack.Push(syntaxTrivia);
						}
						break;
					case SyntaxKind.EndIfDirectiveTrivia:
						if (stack.Count > 0)
						{
							instance.Add(CreateFoldingRangeFromTwoTrivia(stack.Pop(), syntaxTrivia, FoldingRangeKind.Region));
						}
						break;
					}
				}
				return instance.OrderBy((FoldingRange r) => r.StartLine).ToArray();
			}
			finally
			{
				instance.Free();
			}
		}

		private static FoldingRange? CreateFoldingRangeFromTwoTrivia(SyntaxTrivia startNode, SyntaxTrivia endNode, FoldingRangeKind kind)
		{
			return CreateFoldingRangeFromTwoRanges(startNode.ToRange(), endNode.ToRange(), kind);
		}

		private static FoldingRange? CreateFoldingRangeFromTwoTrivia(SyntaxNode startNode, SyntaxNode endNode, FoldingRangeKind kind)
		{
			return CreateFoldingRangeFromTwoRanges(startNode.ToRange(), endNode.ToRange(), kind);
		}

		private static FoldingRange? CreateFoldingRangeFromTwoRanges(Range? startRange, Range? endRange, FoldingRangeKind kind)
		{
			if (!startRange.HasValue || !endRange.HasValue)
			{
				return null;
			}
			return new FoldingRange
			{
				Kind = kind,
				StartLine = (uint)startRange.Value.Start.Line,
				StartCharacter = (uint)startRange.Value.Start.Character,
				EndLine = (uint)endRange.Value.End.Line,
				EndCharacter = (uint)endRange.Value.End.Character
			};
		}

		private static FoldingRange CreateFoldingRange(SyntaxNode node, FoldingRangeKind kind)
		{
			Range? range = node.ToRange();
			if (!range.HasValue || range.Value.Start.Line == range.Value.End.Line)
			{
				return null;
			}
			return new FoldingRange
			{
				Kind = kind,
				StartLine = (uint)range.Value.Start.Line,
				StartCharacter = (uint)range.Value.Start.Character,
				EndLine = (uint)range.Value.End.Line,
				EndCharacter = (uint)range.Value.End.Character
			};
		}

		private static FoldingRange? CreateFoldingRange(SyntaxTrivia trivia, FoldingRangeKind kind)
		{
			Range? range = trivia.ToRange();
			if (!range.HasValue || range.Value.Start.Line == range.Value.End.Line)
			{
				return null;
			}
			return new FoldingRange
			{
				Kind = kind,
				StartLine = (uint)range.Value.Start.Line,
				StartCharacter = (uint)range.Value.Start.Character,
				EndLine = (uint)range.Value.End.Line,
				EndCharacter = (uint)range.Value.End.Character
			};
		}
	}
	internal class SyntaxTreeToDiagnosticsMapping : IDisposable
	{
		private readonly PooledDictionary<SyntaxTree, List<Diagnostic>>? mapping;

		private readonly PooledList<Diagnostic>? manifestDiagnostics;

		private readonly PooledList<Diagnostic>? externalFilesDiagnostics;

		public static SyntaxTreeToDiagnosticsMapping Empty = new SyntaxTreeToDiagnosticsMapping(ImmutableArray<Diagnostic>.Empty, string.Empty);

		public bool IsEmpty
		{
			get
			{
				if (mapping == null && manifestDiagnostics == null)
				{
					return externalFilesDiagnostics == null;
				}
				return false;
			}
		}

		public SyntaxTreeToDiagnosticsMapping(ImmutableArray<Diagnostic> diagnostics, string manifestJsonPath)
		{
			if (!diagnostics.IsEmpty)
			{
				(mapping, manifestDiagnostics, externalFilesDiagnostics) = CreateInternalRepresentation(diagnostics, manifestJsonPath);
			}
		}

		public IReadOnlyList<Diagnostic> GetDiagnosticsForSyntaxTree(SyntaxTree syntaxTree)
		{
			if (syntaxTree != null)
			{
				PooledDictionary<SyntaxTree, List<Diagnostic>>? pooledDictionary = mapping;
				if (pooledDictionary != null && pooledDictionary.TryGetValue(syntaxTree, out List<Diagnostic> value))
				{
					return value;
				}
			}
			return Array.Empty<Diagnostic>();
		}

		public IReadOnlyList<Diagnostic> GetManifestDiagnostics()
		{
			IReadOnlyList<Diagnostic> readOnlyList = manifestDiagnostics;
			return readOnlyList ?? Array.Empty<Diagnostic>();
		}

		public IReadOnlyList<Diagnostic> GetExternalFilesDiagnostics()
		{
			IReadOnlyList<Diagnostic> readOnlyList = externalFilesDiagnostics;
			return readOnlyList ?? Array.Empty<Diagnostic>();
		}

		public void Dispose()
		{
			mapping?.Free();
			manifestDiagnostics?.Free();
			externalFilesDiagnostics?.Free();
		}

		private (PooledDictionary<SyntaxTree, List<Diagnostic>>, PooledList<Diagnostic>? manifestDiagnostics, PooledList<Diagnostic>? externalFilesDiagnostics) CreateInternalRepresentation(ImmutableArray<Diagnostic> diagnostics, string appJsonPath)
		{
			PooledDictionary<SyntaxTree, List<Diagnostic>> instance = PooledDictionary<SyntaxTree, List<Diagnostic>>.GetInstance();
			PooledList<Diagnostic> pooledList = null;
			PooledList<Diagnostic> pooledList2 = null;
			try
			{
				ImmutableArray<Diagnostic>.Enumerator enumerator = diagnostics.GetEnumerator();
				while (enumerator.MoveNext())
				{
					Diagnostic current = enumerator.Current;
					SyntaxTree syntaxTree = current.Location?.SourceTree;
					if (syntaxTree != null)
					{
						if (instance.TryGetValue(syntaxTree, out var value))
						{
							value.Add(current);
							continue;
						}
						instance[syntaxTree] = new List<Diagnostic> { current };
					}
					else if (IsManifestDiagnostic(current, appJsonPath))
					{
						if (pooledList == null)
						{
							pooledList = PooledList<Diagnostic>.GetInstance();
						}
						pooledList.Add(current);
					}
					else if (IsDiagnosticInExternalFile(current))
					{
						if (pooledList2 == null)
						{
							pooledList2 = PooledList<Diagnostic>.GetInstance();
						}
						pooledList2.Add(current);
					}
				}
			}
			catch (Exception)
			{
				instance.Free();
				throw;
			}
			return (instance, manifestDiagnostics: pooledList, externalFilesDiagnostics: pooledList2);
		}

		private static bool IsDiagnosticInExternalFile(Diagnostic d)
		{
			if (d.Location != Microsoft.Dynamics.Nav.CodeAnalysis.Text.Location.None)
			{
				return d.Location.Kind == LocationKind.ExternalFile;
			}
			return false;
		}

		private static bool IsManifestDiagnostic(Diagnostic diagnostic, string appjsonPath)
		{
			if (diagnostic.Location == Microsoft.Dynamics.Nav.CodeAnalysis.Text.Location.None)
			{
				return true;
			}
			return string.Equals(new Uri(diagnostic.Location.GetLineSpan().Path).AbsolutePath, appjsonPath, StringComparison.Ordinal);
		}
	}
