	public class ThreadSynchronizationContext : SynchronizationContext
	{
		private readonly BlockingCollection<Tuple<SendOrPostCallback, object>> requestQueue = new BlockingCollection<Tuple<SendOrPostCallback, object>>();

		public override void Post(SendOrPostCallback callback, object state)
		{
			requestQueue.Add(new Tuple<SendOrPostCallback, object>(callback, state));
		}

		public void RunLoopOnCurrentThread()
		{
			Tuple<SendOrPostCallback, object> item;
			while (requestQueue.TryTake(out item, -1))
			{
				item.Item1(item.Item2);
			}
		}

		public void EndLoop()
		{
			requestQueue.CompleteAdding();
		}
	}
	internal class TypeHierarchyHelper
	{
		public static TypeHierarchyItem CreateTypeHierarchyItem(ISymbol? symbol, Project project)
		{
			Symbol symbol2 = symbol as Symbol;
			if (symbol2 == null)
			{
				throw ExceptionUtilities.UnexpectedValue(symbol?.Kind);
			}
			Range range = symbol2.GetSelectionRange() ?? Range.Empty;
			Range valueOrDefault = symbol2.GetSymbolRange().GetValueOrDefault(range);
			return new TypeHierarchyItem
			{
				Kind = symbol2.ToSymbolInformationKind(),
				Name = symbol2.Name,
				Tags = symbol2.GetSymbolTags(),
				Range = valueOrDefault,
				SelectionRange = range,
				Uri = GetSourceLocation(project, symbol2),
				Detail = symbol2.ToDisplayString(SymbolDisplayFormat.OutLineFormat),
				Data = SymbolId.CreateId(symbol2)
			};
		}

		internal static string? GetSourceLocation(Project project, ISymbol symbol)
		{
			switch (symbol.Location?.Kind)
			{
			case LocationKind.SourceFile:
				return symbol.Location.SourceTree.FilePath.GetUri();
			case LocationKind.ReferenceSourceFile:
				return FilePathHelper.GetPreviewFileUri(project.ProjectFolder, (symbol is ISymbolWithId symbolWithId) ? symbolWithId.Id : 0, symbol.Name, symbol.Kind, symbol?.ContainingModule?.AppId ?? null);
			default:
			{
				IApplicationObjectTypeSymbol containingApplicationObjectTypeSymbol = symbol.GetContainingApplicationObjectTypeSymbol();
				if (containingApplicationObjectTypeSymbol != null)
				{
					return FilePathHelper.GetPreviewFileUri(null, containingApplicationObjectTypeSymbol?.Id ?? 0, containingApplicationObjectTypeSymbol.Name, containingApplicationObjectTypeSymbol.Kind, symbol?.ContainingModule?.AppId ?? null);
				}
				return null;
			}
			}
		}
	}
	public static class Validate
	{
		public static void IsNotNull(string parameterName, object valueToCheck)
		{
			if (valueToCheck == null)
			{
				throw new ArgumentNullException(parameterName);
			}
		}

		public static void IsWithinRange(string parameterName, int valueToCheck, int lowerLimit, int upperLimit)
		{
			if (valueToCheck < lowerLimit || valueToCheck > upperLimit)
			{
				throw new ArgumentOutOfRangeException(parameterName, valueToCheck, string.Format(CultureInfo.InvariantCulture, "Value is not between {0} and {1}", lowerLimit, upperLimit));
			}
		}

		public static void IsLessThan(string parameterName, int valueToCheck, int upperLimit)
		{
			if (valueToCheck >= upperLimit)
			{
				throw new ArgumentOutOfRangeException(parameterName, valueToCheck, string.Format(CultureInfo.InvariantCulture, "Value is greater than or equal to {0}", upperLimit));
			}
		}

		public static void IsGreaterThan(string parameterName, int valueToCheck, int lowerLimit)
		{
			if (valueToCheck < lowerLimit)
			{
				throw new ArgumentOutOfRangeException(parameterName, valueToCheck, string.Format(CultureInfo.InvariantCulture, "Value is less than or equal to {0}", lowerLimit));
			}
		}

		public static void IsNotEqual<TValue>(string parameterName, TValue valueToCheck, TValue undesiredValue)
		{
			if (EqualityComparer<TValue>.Default.Equals(valueToCheck, undesiredValue))
			{
				throw new ArgumentException(string.Format(CultureInfo.InvariantCulture, "The given value '{0}' should not equal '{1}'", valueToCheck, undesiredValue), parameterName);
			}
		}

		public static void IsNotNullOrEmptyString(string parameterName, string valueToCheck)
		{
			if (string.IsNullOrWhiteSpace(valueToCheck))
			{
				throw new ArgumentException("Parameter contains a null, empty, or whitespace string.", parameterName);
			}
		}
	}
