	public abstract class CommandHandlerBase<TCommandArgument> : ICommandHandler
	{
		public abstract string Command { get; }

		public VsCodeWorkspace Workspace { get; }

		public IResponseQueue ResponseQueue { get; }

		protected CommandHandlerBase(VsCodeWorkspace workspace, IResponseQueue responseQueue)
		{
			Workspace = workspace;
			ResponseQueue = responseQueue;
		}

		public async Task HandleAsync(JObject[] commandArguments, int requestId, CancellationToken cancellationToken)
		{
			List<TCommandArgument> list = new List<TCommandArgument>();
			if (commandArguments != null)
			{
				for (int i = 0; i < commandArguments.Length; i++)
				{
					TCommandArgument val = commandArguments[i].ToObject<TCommandArgument>();
					if (val != null)
					{
						list.Add(val);
					}
				}
			}
			await HandleAsync(list.ToArray(), requestId, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
		}

		protected abstract Task HandleAsync(TCommandArgument[] commandArguments, int requestId, CancellationToken cancellationToken);
	}
