	public class MessageReader
	{
		private enum ReadState
		{
			Headers,
			Content
		}

		private static readonly string[] NewLineDelimiters = new string[1] { Environment.NewLine };

		private bool needsMoreData = true;

		private byte[] messageBuffer = new byte[8192];

		public const int DefaultBufferSize = 8192;

		public const double BufferResizeTrigger = 0.25;

		private const int CR = 13;

		private const int LF = 10;

		private readonly Stream inputStream;

		private readonly IMessageSerializer messageSerializer;

		private readonly Encoding messageEncoding;

		private ReadState readState;

		private int readOffset;

		private int bufferEndOffset;

		private int expectedContentLength;

		private Dictionary<string, string> messageHeaders;

		public MessageReader(Stream inputStream, IMessageSerializer messageSerializer, Encoding messageEncoding = null)
		{
			Validate.IsNotNull("inputStream", inputStream);
			Validate.IsNotNull("messageSerializer", messageSerializer);
			this.inputStream = inputStream;
			this.messageSerializer = messageSerializer;
			this.messageEncoding = messageEncoding;
			if (messageEncoding == null)
			{
				this.messageEncoding = Encoding.UTF8;
			}
			messageBuffer = new byte[8192];
		}

		public async Task<Message> ReadMessage()
		{
			string messageContent = null;
			while (true)
			{
				bool flag = !needsMoreData;
				if (!flag)
				{
					flag = await ReadNextChunk().ConfigureAwait(continueOnCapturedContext: false);
				}
				if (!flag)
				{
					break;
				}
				needsMoreData = false;
				if (readState == ReadState.Headers && !TryReadMessageHeaders())
				{
					needsMoreData = true;
					continue;
				}
				if (readState != ReadState.Content || TryReadMessageContent(out messageContent))
				{
					break;
				}
				needsMoreData = true;
			}
			JObject messageJson = JObject.Parse(messageContent);
			return messageSerializer.DeserializeMessage(messageJson);
		}

		[Conditional("DEBUG")]
		protected virtual void LogDebug(string message, object param1)
		{
		}

		private async Task<bool> ReadNextChunk()
		{
			if ((double)(messageBuffer.Length - bufferEndOffset) / (double)messageBuffer.Length < 0.25)
			{
				Array.Resize(ref messageBuffer, messageBuffer.Length * 2);
			}
			int num = await inputStream.ReadAsync(messageBuffer, bufferEndOffset, messageBuffer.Length - bufferEndOffset).ConfigureAwait(continueOnCapturedContext: false);
			bufferEndOffset += num;
			if (num == 0)
			{
				throw new EndOfStreamException("MessageReader's input stream ended unexpectedly, terminating.");
			}
			return true;
		}

		private bool TryReadMessageHeaders()
		{
			int i;
			for (i = readOffset; i + 3 < bufferEndOffset && (messageBuffer[i] != 13 || messageBuffer[i + 1] != 10 || messageBuffer[i + 2] != 13 || messageBuffer[i + 3] != 10); i++)
			{
			}
			if (i + 3 >= bufferEndOffset)
			{
				return false;
			}
			messageHeaders = new Dictionary<string, string>();
			string[] array = Encoding.ASCII.GetString(messageBuffer, readOffset, i).Split(NewLineDelimiters, StringSplitOptions.RemoveEmptyEntries);
			foreach (string text in array)
			{
				int num = 58;
				int num2 = text.IndexOf((char)num);
				if (num2 == -1)
				{
					throw new ArgumentException("Message header must separate key and value using :");
				}
				int startIndex = 0;
				int length = num2;
				string key = text.Substring(startIndex, length);
				int startIndex2 = num2 + 1;
				string value = text.Substring(startIndex2).Trim();
				messageHeaders[key] = value;
			}
			string value2 = null;
			if (!messageHeaders.TryGetValue("Content-Length", out value2))
			{
				throw new MessageParseException("", "Fatal error: Content-Length header must be provided.");
			}
			if (!int.TryParse(value2, out expectedContentLength))
			{
				throw new MessageParseException("", "Fatal error: Content-Length value is not an integer.");
			}
			readOffset += i + 4;
			readState = ReadState.Content;
			return true;
		}

		private bool TryReadMessageContent(out string messageContent)
		{
			messageContent = null;
			if (bufferEndOffset - readOffset < expectedContentLength)
			{
				return false;
			}
			messageContent = messageEncoding.GetString(messageBuffer, readOffset, expectedContentLength);
			int count = bufferEndOffset - (expectedContentLength + readOffset);
			Buffer.BlockCopy(messageBuffer, expectedContentLength + readOffset, messageBuffer, 0, count);
			readOffset = 0;
			bufferEndOffset = count;
			readState = ReadState.Headers;
			return true;
		}
	}
	public class MessageWriter
	{
		private readonly AsyncLock writeLock = new AsyncLock();

		private readonly Newtonsoft.Json.JsonSerializer contentSerializer = Newtonsoft.Json.JsonSerializer.Create(Constants.JsonSerializerSettings);

		private readonly Stream outputStream;

		private readonly IMessageSerializer messageSerializer;

		public MessageWriter(Stream outputStream, IMessageSerializer messageSerializer)
		{
			Validate.IsNotNull("outputStream", outputStream);
			Validate.IsNotNull("messageSerializer", messageSerializer);
			this.outputStream = outputStream;
			this.messageSerializer = messageSerializer;
		}

		public async Task WriteMessage(Message messageToWrite)
		{
			Validate.IsNotNull("messageToWrite", messageToWrite);
			JObject value = messageSerializer.SerializeMessage(messageToWrite);
			byte[] messageBytes = Encoding.UTF8.GetBytes(JsonConvert.SerializeObject(value, Constants.JsonSerializerSettings));
			byte[] headerBytes = Encoding.ASCII.GetBytes($"Content-Length: {messageBytes.Length}\r\n\r\n");
			using (await writeLock.LockAsync().ConfigureAwait(continueOnCapturedContext: false))
			{
				await outputStream.WriteAsync(headerBytes, 0, headerBytes.Length).ConfigureAwait(continueOnCapturedContext: false);
				await outputStream.WriteAsync(messageBytes, 0, messageBytes.Length).ConfigureAwait(continueOnCapturedContext: false);
				await outputStream.FlushAsync().ConfigureAwait(continueOnCapturedContext: false);
			}
		}

		[Conditional("DEBUG")]
		protected virtual void LogDebug(string message, object param1)
		{
		}

		public async Task WriteRequest<TParams>(string methodName, TParams requestParams, int requestId)
		{
			await WriteMessage(Message.Request(requestId, methodName, (requestParams != null) ? JToken.FromObject(requestParams, contentSerializer) : null)).ConfigureAwait(continueOnCapturedContext: false);
		}

		public async Task WriteResponse<TResult>(TResult resultContent, string method, int requestId)
		{
			await WriteMessage(Message.Response(requestId, method, (resultContent != null) ? JToken.FromObject(resultContent, contentSerializer) : null)).ConfigureAwait(continueOnCapturedContext: false);
		}

		public async Task WriteResponseError<TResult>(TResult resultContent, string method, int requestId)
		{
			await WriteMessage(Message.ResponseError(requestId, method, (resultContent != null) ? JToken.FromObject(resultContent, contentSerializer) : null)).ConfigureAwait(continueOnCapturedContext: false);
		}

		public async Task WriteEvent<TParams>(string methodName, TParams eventParams)
		{
			await WriteMessage(Message.Event(methodName, (eventParams != null) ? JToken.FromObject(eventParams, contentSerializer) : null)).ConfigureAwait(continueOnCapturedContext: false);
		}
	}
	public class ProtocolEndpoint
	{
		private readonly SynchronizationContext originalSynchronizationContext = SynchronizationContext.Current;

		private bool isStarted;

		private readonly ProtocolEndpointCompletionSource completionSource = new ProtocolEndpointCompletionSource();

		private ChannelBase protocolChannel;

		public async Task Start(ChannelBase channel, MessageProtocolType messageProtocolType, ExtensionOptions extensionOptions)
		{
			if (!isStarted)
			{
				protocolChannel = channel;
				protocolChannel.Start(messageProtocolType, completionSource, extensionOptions);
				protocolChannel.RequestDispatcher.UnhandledException += MessageDispatcher_UnhandledException;
				await OnStart().ConfigureAwait(continueOnCapturedContext: false);
				isStarted = true;
			}
		}

		public void WaitForExit()
		{
			completionSource.WaitForStop();
		}

		public async Task Stop()
		{
			if (isStarted)
			{
				isStarted = false;
				await OnStop().ConfigureAwait(continueOnCapturedContext: false);
				protocolChannel.Stop();
				completionSource.Stop();
			}
		}

		protected virtual Task OnStart()
		{
			return Task.FromResult(result: true);
		}

		protected virtual Task OnStop()
		{
			return Task.FromResult(result: true);
		}

		private void MessageDispatcher_UnhandledException(object sender, Exception e)
		{
			Exception e2 = e;
			if (completionSource != null)
			{
				completionSource.SetException(e2);
			}
			else if (originalSynchronizationContext != null)
			{
				originalSynchronizationContext.Post(delegate
				{
					throw e2;
				}, null);
			}
		}
	}
	public class ProtocolEndpointCompletionSource
	{
		private readonly TaskCompletionSource<bool> completionSource = new TaskCompletionSource<bool>();

		internal void WaitForStop()
		{
			completionSource.Task.Wait();
		}

		internal virtual void Stop()
		{
			completionSource.SetResult(result: true);
		}

		internal virtual void SetException(Exception ex)
		{
			completionSource.SetException(ex);
		}
	}
	public class RequestDispatcher
	{
		private readonly CancellationTokenSource messageLoopCancellationToken = new CancellationTokenSource();

		private readonly RequestRegistry requestRegistry;

		private readonly BlockingCollection<Message> messageQueue = new BlockingCollection<Message>(100);

		private AsyncContextThread messageLoopThread;

		private AsyncContextThread messageProcessingThread;

		public SynchronizationContext SynchronizationContext { get; private set; }

		protected MessageReader MessageReader { get; private set; }

		public event EventHandler<Exception> UnhandledException;

		internal RequestDispatcher(MessageReader messageReader, RequestRegistry requestRegistry)
		{
			MessageReader = messageReader;
			this.requestRegistry = requestRegistry;
		}

		public void Start()
		{
			messageLoopThread = new AsyncContextThread("Request Dispatcher");
			messageLoopThread.Run(() => ListenForMessages(messageLoopCancellationToken.Token)).ContinueWith(OnListenTaskCompleted);
			messageProcessingThread = new AsyncContextThread("Message Processing");
			messageProcessingThread.Run(() => ProcessMessages(messageLoopCancellationToken.Token).ContinueWith(OnListenTaskCompleted));
		}

		public void Stop()
		{
			requestRegistry.Dispose();
			if (messageLoopThread != null || messageProcessingThread != null)
			{
				messageLoopCancellationToken.Cancel();
				messageLoopThread?.Stop();
				messageProcessingThread?.Stop();
			}
		}

		protected void OnUnhandledException(Exception unhandledException)
		{
			this.UnhandledException?.Invoke(this, unhandledException);
		}

		private async Task ListenForMessages(CancellationToken cancellationToken)
		{
			SynchronizationContext = System.Threading.SynchronizationContext.Current;
			while (!cancellationToken.IsCancellationRequested)
			{
				try
				{
					Message newMessage = await MessageReader.ReadMessage().ConfigureAwait(continueOnCapturedContext: false);
					if (!(await PreprocessMessageIfNeeded(newMessage)))
					{
						messageQueue.Add(newMessage, cancellationToken);
					}
				}
				catch (Exception ex) when (((ex is OperationCanceledException || ex is MessageParseException || ex is EndOfStreamException) ? 1 : 0) != 0)
				{
					if (ex is EndOfStreamException)
					{
						LocalMachineLogger.LogWarning("Client connection lost, terminating message listener gracefully");
						break;
					}
					LocalMachineLogger.LogException(ex);
				}
			}
		}

		private async Task ProcessMessages(CancellationToken cancellationToken)
		{
			foreach (Message item in messageQueue.GetConsumingEnumerable(cancellationToken))
			{
				await ProcessMessage(item).ConfigureAwait(continueOnCapturedContext: false);
			}
		}

		private async Task<bool> PreprocessMessageIfNeeded(Message message)
		{
			EnsureRequestIsCancellable(message);
			if (IsMessageWithPreprocessing(message))
			{
				await ProcessMessage(message).ConfigureAwait(continueOnCapturedContext: false);
				return true;
			}
			return false;
		}

		private async Task ProcessMessage(Message message)
		{
			try
			{
				await requestRegistry.Process(message).ConfigureAwait(continueOnCapturedContext: false);
			}
			catch (Exception ex)
			{
				LocalMachineLogger.LogException(ex);
			}
		}

		private void EnsureRequestIsCancellable(Message message)
		{
			requestRegistry.ResponseQueue.RegisterRequestCancellationTokenSource(message.Id);
		}

		private static bool IsMessageWithPreprocessing(Message message)
		{
			string method = message.Method;
			if (!(method == "$/cancelRequest"))
			{
				if (method == "terminate")
				{
					return true;
				}
				return false;
			}
			return true;
		}

		private void OnListenTaskCompleted(Task listenTask)
		{
			if (listenTask.IsFaulted)
			{
				OnUnhandledException(listenTask.Exception);
			}
		}
	}
	public abstract class RequestHandlerBase<TRequestHandler> : IRequestHandler, IDisposable where TRequestHandler : IRequest
	{
		private class DelayedRequestHandler : IDisposable
		{
			private bool isDisposed;

			private readonly Dictionary<ProjectId, IList<(int RequestId, RequestHandlerBase<TRequestHandler>, TRequestHandler Request)>> delayedRequests = new Dictionary<ProjectId, IList<(int, RequestHandlerBase<TRequestHandler>, TRequestHandler)>>();

			private readonly NonReentrantLock mutex = new NonReentrantLock(useThisInstanceForSynchronization: true);

			private bool eventRegistered;

			private readonly SimpleTaskQueue queue;

			internal IProjectClosureCompilation? ProjectClosureCompilation { get; set; }

			public DelayedRequestHandler()
			{
				queue = new SimpleTaskQueue((SynchronizationContext.Current != null) ? TaskScheduler.FromCurrentSynchronizationContext() : TaskScheduler.Default);
			}

			internal virtual void RegisterDelayedRequest(RequestHandlerBase<TRequestHandler> handler, ProjectId projectId, TRequestHandler request, int requestId)
			{
				using (mutex.DisposableWait())
				{
					if (ProjectClosureCompilation != null)
					{
						if (!eventRegistered)
						{
							ProjectClosureCompilation.ProjectClosureLoaded += OnProjectClosureLoaded;
							eventRegistered = true;
						}
						AddRequest(projectId, handler, request, requestId);
					}
				}
			}

			private void OnProjectClosureLoaded(object? sender, ProjectClosureLoadedEventArgs e)
			{
				PooledDictionary<ProjectId, IList<(int, RequestHandlerBase<TRequestHandler>, TRequestHandler)>> instance = PooledDictionary<ProjectId, IList<(int, RequestHandlerBase<TRequestHandler>, TRequestHandler)>>.GetInstance();
				try
				{
					using (mutex.DisposableWait())
					{
						if (delayedRequests.Count == 0)
						{
							return;
						}
						foreach (KeyValuePair<ProjectId, IList<(int, RequestHandlerBase<TRequestHandler>, TRequestHandler)>> delayedRequest in delayedRequests)
						{
							if (e.ProjectLoaded == delayedRequest.Key)
							{
								instance.Add(delayedRequest.Key, delayedRequest.Value);
							}
						}
						foreach (ProjectId key in instance.Keys)
						{
							delayedRequests.Remove(key);
						}
					}
					foreach (KeyValuePair<ProjectId, IList<(int, RequestHandlerBase<TRequestHandler>, TRequestHandler)>> item in instance)
					{
						_ = item.Key;
						foreach (var requestContext in item.Value)
						{
							queue.ScheduleTask(async delegate
							{
								await requestContext.Item2.HandleAsync(requestContext.Item3, requestContext.Item1, CancellationToken.None).ConfigureAwait(continueOnCapturedContext: false);
							});
						}
					}
				}
				finally
				{
					instance.Free();
				}
			}

			private void AddRequest(ProjectId projectId, RequestHandlerBase<TRequestHandler> handler, TRequestHandler request, int requestId)
			{
				if (delayedRequests.TryGetValue(projectId, out IList<(int, RequestHandlerBase<TRequestHandler>, TRequestHandler)> value))
				{
					value?.Add((requestId, handler, request));
					return;
				}
				delayedRequests.Add(projectId, new List<(int, RequestHandlerBase<TRequestHandler>, TRequestHandler)> { (requestId, handler, request) });
			}

			public void Dispose()
			{
				if (isDisposed)
				{
					return;
				}
				using (mutex.DisposableWait())
				{
					if (!isDisposed)
					{
						if (eventRegistered)
						{
							ProjectClosureCompilation.ProjectClosureLoaded -= OnProjectClosureLoaded;
							eventRegistered = false;
						}
						isDisposed = true;
					}
				}
			}
		}

		private readonly Lazy<DelayedRequestHandler> lazyDelayedRequestHandler = new Lazy<DelayedRequestHandler>(() => new DelayedRequestHandler());

		private const string ProcessingMetricName = "Processing (ms)";

		private readonly ConcurrentDictionary<int, CustomTelemetryEvent> customTelemetryEvents = new ConcurrentDictionary<int, CustomTelemetryEvent>();

		public virtual bool ProfilePerformance => false;

		public abstract string EndpointName { get; }

		internal VsCodeWorkspace Workspace { get; }

		public virtual string TelemetryEventName => EndpointName;

		internal IResponseQueue ResponseQueue { get; }

		protected bool Disposed { get; private set; }

		private DelayedRequestHandler DelayedRequestHandlerValue
		{
			get
			{
				lazyDelayedRequestHandler.Value.ProjectClosureCompilation = Workspace.ProjectClosureCompilation;
				return lazyDelayedRequestHandler.Value;
			}
		}

		protected RequestHandlerBase(VsCodeWorkspace workspace, IResponseQueue responseQueue)
		{
			Workspace = workspace;
			ResponseQueue = responseQueue;
		}

		public void Dispose()
		{
			Dispose(disposing: true);
			GC.SuppressFinalize(this);
		}

		public async Task HandleAsync(JToken requestContents, int requestId, CancellationToken cancellationToken)
		{
			TRequestHandler request = default(TRequestHandler);
			if (requestContents != null)
			{
				request = requestContents.ToObject<TRequestHandler>();
			}
			using PooledStopwatch sw = PooledStopwatch.GetInstance();
			sw.Start();
			try
			{
				await HandleAsync(request, requestId, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
			}
			finally
			{
				sw.Stop();
				if (LanguageServerOptions.LogLevel == LogLevel.Verbose)
				{
					string message = $"Processing {EndpointName} took {sw.Elapsed.TotalSeconds} seconds";
					LocalMachineLogger.LogVerbose(message);
					new DebugConsoleLogger(ResponseQueue).Info(message);
				}
				if (ProfilePerformance)
				{
					GetCustomTelemetryForRequest(requestId).Metrics.Add("Processing (ms)", sw.ElapsedMilliseconds);
				}
			}
		}

		protected virtual void Dispose(bool disposing)
		{
			if (!Disposed && lazyDelayedRequestHandler.IsValueCreated)
			{
				DelayedRequestHandlerValue.Dispose();
				Disposed = true;
			}
		}

		internal virtual void RegisterDelayedRequest(ProjectId projectId, TRequestHandler request, int requestId)
		{
			DelayedRequestHandlerValue.RegisterDelayedRequest(this, projectId, request, requestId);
		}

		public abstract Task HandleAsync(TRequestHandler request, int requestId, CancellationToken cancellationToken);

		public CustomTelemetryEvent GetCustomTelemetryForRequest(int requestId)
		{
			return customTelemetryEvents.GetOrAdd(requestId, (int _) => new CustomTelemetryEvent(TelemetryEventName));
		}

		public void DisposeCustomTelemetryEventForRequest(int requestId)
		{
			if (customTelemetryEvents.TryRemove(requestId, out CustomTelemetryEvent value))
			{
				value.Dispose();
			}
		}
	}
	public class Response
	{
		public object Contents { get; set; }

		public MessageError Error { get; set; }

		public MessageKind MessageKind { get; set; }

		public int RequestId { get; set; }

		public string Method { get; set; }
	}
	public class ResponseDispatcher
	{
		private readonly CancellationTokenSource messageLoopCancellationToken = new CancellationTokenSource();

		private AsyncContextThread messageLoopThread;

		public ResponseQueue ResponseQueue { get; private set; }

		public MessageWriter MessageWriter { get; private set; }

		public ResponseDispatcher(MessageWriter messageWriter, ResponseQueue responseQueue)
		{
			MessageWriter = messageWriter;
			ResponseQueue = responseQueue;
		}

		public void Start()
		{
			messageLoopThread = new AsyncContextThread("Response Dispatcher");
			messageLoopThread.Run(() => ListenForResponses(messageLoopCancellationToken.Token));
		}

		private async Task ListenForResponses(CancellationToken cancellationToken)
		{
			while (!cancellationToken.IsCancellationRequested)
			{
				Response response = ResponseQueue.Take();
				if (response == null)
				{
					continue;
				}
				switch (response.MessageKind)
				{
				case MessageKind.Request:
					await MessageWriter.WriteRequest(response.Method, response.Contents, response.RequestId).ConfigureAwait(continueOnCapturedContext: false);
					break;
				case MessageKind.Event:
					await MessageWriter.WriteEvent(response.Method, response.Contents).ConfigureAwait(continueOnCapturedContext: false);
					break;
				case MessageKind.Response:
					if (response.Error != null)
					{
						if (!response.Error.Code.HasValue)
						{
							await MessageWriter.WriteResponseError(response.Error.Message, response.Method, response.RequestId).ConfigureAwait(continueOnCapturedContext: false);
						}
						else
						{
							await MessageWriter.WriteResponseError(response.Error, response.Method, response.RequestId).ConfigureAwait(continueOnCapturedContext: false);
						}
					}
					else
					{
						await MessageWriter.WriteResponse(response.Contents, response.Method, response.RequestId).ConfigureAwait(continueOnCapturedContext: false);
					}
					break;
				default:
					LocalMachineLogger.LogVerbose("Unhandled message: {0}");
					break;
				}
			}
		}

		public void Stop()
		{
			if (messageLoopThread != null)
			{
				messageLoopCancellationToken.Cancel();
				messageLoopThread.Stop();
			}
		}
	}
