	public class ResponseQueue : BlockingCollection<Response>, IResponseQueue, IEnumerable<Response>, IEnumerable, IReadOnlyCollection<Response>
	{
		private readonly ConcurrentDictionary<int, RequestCancellationTokenSource> cancellationTokens = new ConcurrentDictionary<int, RequestCancellationTokenSource>();

		internal ResponseQueue()
			: base((IProducerConsumerCollection<Response>)new ConcurrentQueue<Response>())
		{
		}

		public void RegisterRequestCancellationTokenSource(int requestId)
		{
			cancellationTokens.AddOrUpdate(requestId, (int id) => new RequestCancellationTokenSource(), delegate(int id, RequestCancellationTokenSource cts)
			{
				cts.Dispose();
				return new RequestCancellationTokenSource();
			});
		}

		public CancellationToken GetRequestCancellationToken(int requestId)
		{
			if (requestId <= 0)
			{
				return CancellationToken.None;
			}
			if (cancellationTokens.TryGetValue(requestId, out RequestCancellationTokenSource value))
			{
				return value.Token;
			}
			throw new InvalidOperationException($"No cancellation token found for request ID {requestId}.");
		}

		public void CancelRequest(int requestId)
		{
			if (cancellationTokens.TryGetValue(requestId, out RequestCancellationTokenSource value))
			{
				value.Cancel();
			}
		}

		public void UnregisterCancellationTokenSource(int requestId)
		{
			if (cancellationTokens.TryRemove(requestId, out RequestCancellationTokenSource value))
			{
				value.Dispose();
			}
		}

		void IResponseQueue.Add(Response response)
		{
			Add(response);
		}

		void IResponseQueue.Add(Response response, CancellationToken cancellationToken)
		{
			Add(response, cancellationToken);
		}

		Response IResponseQueue.Take()
		{
			return Take();
		}
	}
	public class RequestCancellationTokenSource : IDisposable
	{
		private readonly object lockObject = new object();

		private CancellationTokenSource? lazyCts;

		private bool isDisposed;

		public CancellationToken Token
		{
			get
			{
				lock (lockObject)
				{
					if (isDisposed)
					{
						throw new ObjectDisposedException("RequestCancellationTokenSource");
					}
					EnsureSourceExists();
					return lazyCts.Token;
				}
			}
		}

		public void Cancel()
		{
			if (isDisposed)
			{
				return;
			}
			lock (lockObject)
			{
				if (!isDisposed)
				{
					EnsureSourceExists();
					lazyCts.Cancel();
				}
			}
		}

		public void Dispose()
		{
			if (isDisposed)
			{
				return;
			}
			lock (lockObject)
			{
				if (!isDisposed)
				{
					if (lazyCts != null)
					{
						lazyCts.Dispose();
					}
					isDisposed = true;
				}
			}
		}

		private void EnsureSourceExists()
		{
			if (lazyCts == null)
			{
				lazyCts = new CancellationTokenSource();
			}
		}
	}
}
