namespace Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.Serializers
{
	public class JsonRpcMessageSerializer : IMessageSerializer
	{
		public JObject SerializeMessage(Message message)
		{
			JObject jObject = new JObject();
			jObject.Add("jsonrpc", JToken.FromObject("2.0"));
			if (message.MessageKind == MessageKind.Request)
			{
				jObject.Add("id", JToken.FromObject(message.Id));
				jObject.Add("method", message.Method);
				jObject.Add("params", message.Contents);
			}
			else if (message.MessageKind == MessageKind.Event)
			{
				jObject.Add("method", message.Method);
				jObject.Add("params", message.Contents);
			}
			else if (message.MessageKind == MessageKind.Response)
			{
				jObject.Add("id", JToken.FromObject(message.Id));
				if (message.Error != null)
				{
					jObject.Add("error", message.Error);
				}
				else
				{
					jObject.Add("result", message.Contents);
				}
			}
			return jObject;
		}

		public Message DeserializeMessage(JObject messageJson)
		{
			JToken value = null;
			if (messageJson.TryGetValue("id", out value))
			{
				int id = int.Parse(value.ToString(), CultureInfo.InvariantCulture);
				if (messageJson.TryGetValue("result", out value))
				{
					return Message.Response(id, null, value);
				}
				if (messageJson.TryGetValue("error", out value))
				{
					return Message.ResponseError(id, null, value);
				}
				JToken value2 = null;
				messageJson.TryGetValue("params", out value2);
				messageJson.TryGetValue("method", out value);
				return Message.Request(id, value.ToString(), value2);
			}
			JToken value3 = value;
			messageJson.TryGetValue("params", out value3);
			messageJson.TryGetValue("method", out value);
			return Message.Event(value.ToString(), value3);
		}
	}
	public class V8MessageSerializer : IMessageSerializer
	{
		public JObject SerializeMessage(Message message)
		{
			JObject jObject = new JObject();
			if (message.MessageKind == MessageKind.Request)
			{
				jObject.Add("type", JToken.FromObject("request"));
				jObject.Add("seq", JToken.FromObject(message.Id));
				jObject.Add("command", message.Method);
				jObject.Add("arguments", message.Contents);
			}
			else if (message.MessageKind == MessageKind.Event)
			{
				jObject.Add("type", JToken.FromObject("event"));
				jObject.Add("event", message.Method);
				jObject.Add("body", message.Contents);
			}
			else if (message.MessageKind == MessageKind.Response)
			{
				jObject.Add("type", JToken.FromObject("response"));
				jObject.Add("request_seq", JToken.FromObject(message.Id));
				jObject.Add("command", message.Method);
				if (message.Error != null)
				{
					jObject.Add("success", JToken.FromObject(false));
					jObject.Add("message", message.Error);
				}
				else
				{
					jObject.Add("success", JToken.FromObject(true));
					jObject.Add("body", message.Contents);
				}
			}
			return jObject;
		}

		public Message DeserializeMessage(JObject messageJson)
		{
			JToken value = null;
			if (messageJson.TryGetValue("type", out value))
			{
				string b = value.ToString();
				if (string.Equals("request", b, StringComparison.OrdinalIgnoreCase))
				{
					return Message.Request(int.Parse(messageJson.GetValue("seq", StringComparison.Ordinal).ToString(), CultureInfo.InvariantCulture), messageJson.GetValue("command", StringComparison.Ordinal).ToString(), messageJson.GetValue("arguments", StringComparison.Ordinal));
				}
				if (!string.Equals("response", b, StringComparison.OrdinalIgnoreCase))
				{
					if (string.Equals("event", b, StringComparison.OrdinalIgnoreCase))
					{
						return Message.Event(messageJson.GetValue("event", StringComparison.Ordinal).ToString(), messageJson.GetValue("body", StringComparison.Ordinal));
					}
					return Message.Unknown();
				}
				if (messageJson.TryGetValue("success", out value))
				{
					int id = int.Parse(messageJson.GetValue("request_seq", StringComparison.Ordinal).ToString(), CultureInfo.InvariantCulture);
					if (value.ToObject<bool>())
					{
						return Message.Response(id, messageJson.GetValue("command", StringComparison.Ordinal).ToString(), messageJson.GetValue("body", StringComparison.Ordinal));
					}
					return Message.ResponseError(id, messageJson.GetValue("command", StringComparison.Ordinal).ToString(), messageJson.GetValue("message", StringComparison.Ordinal));
				}
			}
			return Message.Unknown();
		}
	}
}
