	public class SnapshotDebuggerAttachInitializeRequest : NavServerRequest<ServerConnectionConfiguration>
	{
		private class SnapshotDebuggingExecutionContextJsonConverter : Newtonsoft.Json.JsonConverter
		{
			public override bool CanConvert(Type objectType)
			{
				return objectType.Equals(typeof(SnapshotDebuggingConfigurationExecutionContext));
			}

			public override object ReadJson(JsonReader reader, Type objectType, object existingValue, Newtonsoft.Json.JsonSerializer serializer)
			{
				if (Enum.TryParse<SnapshotDebuggingConfigurationExecutionContext>(reader.Value as string, ignoreCase: true, out var result))
				{
					switch (result)
					{
					case SnapshotDebuggingConfigurationExecutionContext.Debug:
						return SnapshotDebuggingExecutionContext.Debugging;
					case SnapshotDebuggingConfigurationExecutionContext.Profile:
						return SnapshotDebuggingExecutionContext.Profiling;
					case SnapshotDebuggingConfigurationExecutionContext.DebugAndProfile:
						return SnapshotDebuggingExecutionContext.Debugging | SnapshotDebuggingExecutionContext.Profiling;
					}
				}
				throw new UserSetupException(ProtocolResources.WrongSnapshotDebuggingExecutionContext);
			}

			public override void WriteJson(JsonWriter writer, object value, Newtonsoft.Json.JsonSerializer serializer)
			{
				serializer.Serialize(writer, value.ToString());
			}
		}

