	public class Breakpoint : IEquatable<Breakpoint>
	{
		public int Id { get; set; }

		public bool Verified { get; set; }

		public Source Source { get; set; }

		public int Line { get; set; }

		public int Column { get; set; }

		public int EndLine { get; set; }

		public int EndColumn { get; set; }

		public string Message { get; set; }

		internal static Breakpoint CreateFromSource(SourceBreakpoint sourceBreakpoint, Source source, bool verified, long id, string message = "", int lineOffset = 0)
		{
			return new Breakpoint
			{
				Id = (int)id,
				Source = source,
				Line = sourceBreakpoint.Line - lineOffset,
				Column = sourceBreakpoint.Column,
				Verified = verified,
				Message = message,
				EndLine = 0,
				EndColumn = 0
			};
		}

		public bool Equals(Breakpoint other)
		{
			if ((object)this == other)
			{
				return true;
			}
			if (other != null && other.Id == Id && other.Column == Column && other.Line == Line && other.Verified == Verified && other.Source == Source && other.EndColumn == EndLine && other.EndLine == EndLine)
			{
				return string.Equals(other.Message, Message, StringComparison.OrdinalIgnoreCase);
			}
			return false;
		}

		public override bool Equals(object obj)
		{
			return Equals(obj as Breakpoint);
		}

		public static bool operator ==(Breakpoint left, Breakpoint right)
		{
			return object.Equals(left, right);
		}

		public static bool operator !=(Breakpoint left, Breakpoint right)
		{
			return !object.Equals(left, right);
		}

		public override int GetHashCode()
		{
			return Id.GetHashCode();
		}
	}
