	public class DebugAdapterEvaluateRequest : IRequest
	{
		private class DebugAdapterEvaluateContextJsonConverter : Newtonsoft.Json.JsonConverter
		{
			public override bool CanConvert(Type objectType)
			{
				return objectType.Equals(typeof(string));
			}

			public override object? ReadJson(JsonReader reader, Type objectType, object existingValue, Newtonsoft.Json.JsonSerializer serializer)
			{
				if (reader == null || reader.Value == null)
				{
					return null;
				}
				if (!(reader.Value is string value))
				{
					return null;
				}
				if (VariablesContext.Equals(value, StringComparison.OrdinalIgnoreCase))
				{
					return DebugAdapterEvaluateContext.Variables;
				}
				if (DebugConsoleContext.Equals(value, StringComparison.OrdinalIgnoreCase))
				{
					return DebugAdapterEvaluateContext.Console;
				}
				if (WatchContext.Equals(value, StringComparison.OrdinalIgnoreCase))
				{
					return DebugAdapterEvaluateContext.Watch;
				}
				if (HoverContext.Equals(value, StringComparison.OrdinalIgnoreCase))
				{
					return DebugAdapterEvaluateContext.Hover;
				}
				if (ClipboardContext.Equals(value, StringComparison.OrdinalIgnoreCase))
				{
					return DebugAdapterEvaluateContext.Clipboard;
				}
				return null;
			}

			public override void WriteJson(JsonWriter writer, object value, Newtonsoft.Json.JsonSerializer serializer)
			{
				serializer.Serialize(writer, value.ToString());
			}
		}

		[Newtonsoft.Json.JsonIgnore]
		private static readonly string DebugConsoleContext = "repl";

		[Newtonsoft.Json.JsonIgnore]
		private static readonly string WatchContext = "watch";

		[Newtonsoft.Json.JsonIgnore]
		private static readonly string HoverContext = "hover";

		[Newtonsoft.Json.JsonIgnore]
		private static readonly string ClipboardContext = "clipboard";

		[Newtonsoft.Json.JsonIgnore]
		private static readonly string VariablesContext = "variables";

		public string? Expression { get; set; }

		public int FrameId { get; set; }

		[Newtonsoft.Json.JsonConverter(typeof(DebugAdapterEvaluateContextJsonConverter))]
