	[DebuggerDisplay("Message = {Message}, Start = {Range.Start.Line}:{Range.Start.Character}, End = {Range.End.Line}:{Range.End.Character}")]
	public class ProtocolDiagnostic : IEquatable<ProtocolDiagnostic>
	{
		private static readonly Position ZeroPosition = new Position
		{
			Character = 0,
			Line = 0
		};

		private static readonly Range ZeroRange = new Range
		{
			Start = ZeroPosition,
			End = ZeroPosition
		};

		private static readonly int[] UnnecessaryTag = new int[1] { 1 };

		private static readonly int[] DeprecatedTag = new int[1] { 2 };

		public Range Range { get; set; }

		public ProtocolDiagnosticSeverity? Severity { get; set; }

		public string Code { get; set; }

		public string Source { get; set; } = "AL";


		public string Message { get; set; }

		public ProtocolDiagnosticRelatedInformation[]? DiagnosticRelatedInformation { get; set; }

		public CodeDescription? CodeDescription { get; set; }

		public int[]? Tags { get; set; }

		[Newtonsoft.Json.JsonIgnore]
		public Diagnostic? CompilerDiagnostic { get; }

		public ProtocolDiagnostic()
		{
		}

		public ProtocolDiagnostic(Diagnostic diagnostic)
		{
			Range = diagnostic.Location.GetMappedLineSpan().Span;
			Severity = MapSeverity(diagnostic.Severity);
			Message = diagnostic.GetMessage(CultureInfo.CurrentCulture);
			Code = diagnostic.Id;
			CompilerDiagnostic = diagnostic;
			string docLink = diagnostic.GetDocLink();
			if (!string.IsNullOrEmpty(docLink))
			{
				CodeDescription = new CodeDescription
				{
					Url = docLink
				};
			}
			if (diagnostic.Descriptor.IsUnnecessary)
			{
				Tags = UnnecessaryTag;
			}
			if (diagnostic.Descriptor.IsDeprecated)
			{
				Tags = DeprecatedTag;
			}
		}

		public ProtocolDiagnostic(ProtocolDiagnosticSeverity severity, string message)
		{
			Severity = severity;
			Message = message;
			Code = "-1";
			Range = ZeroRange;
		}

		private static ProtocolDiagnosticSeverity MapSeverity(DiagnosticSeverity severity)
		{
			return severity switch
			{
				DiagnosticSeverity.Error => ProtocolDiagnosticSeverity.Error, 
				DiagnosticSeverity.Info => ProtocolDiagnosticSeverity.Information, 
				DiagnosticSeverity.Warning => ProtocolDiagnosticSeverity.Warning, 
				_ => ProtocolDiagnosticSeverity.Hint, 
			};
		}

		public bool Equals(ProtocolDiagnostic other)
		{
			if (other == null)
			{
				return false;
			}
			if (this == other)
			{
				return true;
			}
			if (Range.Equals(other.Range) && Severity == other.Severity && string.Equals(Code, other.Code, StringComparison.Ordinal) && string.Equals(Source, other.Source, StringComparison.Ordinal))
			{
				return string.Equals(Message, other.Message, StringComparison.Ordinal);
			}
			return false;
		}

		public override bool Equals(object obj)
		{
			if (obj == null)
			{
				return false;
			}
			if (this == obj)
			{
				return true;
			}
			if (obj.GetType() != GetType())
			{
				return false;
			}
			return Equals((ProtocolDiagnostic)obj);
		}

		public override int GetHashCode()
		{
			return (((((((Range.GetHashCode() * 397) ^ Severity.GetHashCode()) * 397) ^ ((Code != null) ? StringComparer.Ordinal.GetHashCode(Code) : 0)) * 397) ^ ((Source != null) ? StringComparer.Ordinal.GetHashCode(Source) : 0)) * 397) ^ ((Message != null) ? StringComparer.Ordinal.GetHashCode(Message) : 0);
		}
	}
