	public class WorkspaceEdit
	{
		public Dictionary<string, TextEdit[]> Changes { get; } = new Dictionary<string, TextEdit[]>();


		public void Add(string uri, TextEdit edit)
		{
			if (Changes.TryGetValue(uri, out TextEdit[] value))
			{
				TextEdit[] array = new TextEdit[value.Length + 1];
				Array.Copy(value, array, value.Length);
				array[value.Length] = edit;
				Changes[uri] = array;
			}
			else
			{
				Changes[uri] = new TextEdit[1] { edit };
			}
		}
	}
