namespace Microsoft.Dynamics.Nav.EditorServices.Protocol.LanguageServer
{
	internal class CancelRequestHandler : RequestHandlerBase<CancelRequest>
	{
		public override string EndpointName => "$/cancelRequest";

		internal CancelRequestHandler(VsCodeWorkspace workspace, IResponseQueue responseQueue)
			: base(workspace, responseQueue)
		{
		}

		public override Task HandleAsync(CancelRequest request, int requestId, CancellationToken cancellationToken)
		{
			base.ResponseQueue.CancelRequest(request.Id);
			return Task.CompletedTask;
		}
	}
	public class CodeActionRequestHandler : RequestHandlerBase<ProtocolCodeActionRequest>
	{
		public override string EndpointName => "textDocument/codeAction";

		internal CodeActionRequestHandler(VsCodeWorkspace workspace, ResponseQueue responseQueue)
			: base(workspace, (IResponseQueue)responseQueue)
		{
		}

		public override async Task HandleAsync(ProtocolCodeActionRequest request, int requestId, CancellationToken cancellationToken)
		{
			if (request.TextDocument == null)
			{
				await EmptyResponse(requestId);
				return;
			}
			Document document = base.Workspace.GetDocument(request.TextDocument.FileName);
			if (document == null)
			{
				await EmptyResponse(requestId);
				return;
			}
			if (!base.Workspace.AreAllProjectReferencesBound(document))
			{
				RegisterDelayedRequest(document.Project.Id, request, requestId);
				return;
			}
			TextSpan textSpan = (await document.GetTextAsync()).GetTextSpan(request.Range);
			ImmutableArray<CodeActionProxy> immutableArray = await CodeActionService.GetService(document).GetCodeActionsAsync(document, textSpan, cancellationToken);
			ProtocolCodeAction[] result = ConvertCodeActionsToCommands(document, request.Range, immutableArray);
			base.ResponseQueue.Add(ResponseFactory.CodeAction(result, requestId));
		}

		private ProtocolCodeAction[] ConvertCodeActionsToCommands(Document document, Range range, IEnumerable<CodeActionProxy> codeActions)
		{
			if (codeActions.IsEmpty())
			{
				return Array.Empty<ProtocolCodeAction>();
			}
			ArrayBuilder<ProtocolCodeAction> instance = ArrayBuilder<ProtocolCodeAction>.GetInstance();
			foreach (CodeActionProxy codeAction in codeActions)
			{
				instance.Add(ConvertCodeActionToCommand(document, range, codeAction));
			}
			return instance.ToArrayAndFree();
		}

		private ProtocolCodeAction ConvertCodeActionToCommand(Document document, Range range, CodeActionProxy codeAction)
		{
			RunCodeAction runCodeAction = new RunCodeAction
			{
				FileName = document.FilePath,
				Identifier = codeAction.GetIdentifier(),
				Selection = range,
				WantsTextChanges = true
			};
			UiCommand uiCommand = new UiCommand();
			uiCommand.Title = codeAction.GetTitle();
			uiCommand.Command = "al/runCodeAction";
			uiCommand.Arguments = new object[1] { runCodeAction };
			UiCommand uiCommand2 = uiCommand;
			ProtocolCodeAction protocolCodeAction = new ProtocolCodeAction();
			protocolCodeAction.Title = uiCommand2.Title;
			protocolCodeAction.Command = uiCommand2;
			protocolCodeAction.IsPreferred = codeAction.IsPreferred();
			protocolCodeAction.Kind = codeAction.GetKind().ToString();
			protocolCodeAction.Diagnostics = new ProtocolDiagnostic[0];
			return protocolCodeAction;
		}

		private async Task EmptyResponse(int requestId)
		{
			base.ResponseQueue.Add(ResponseFactory.CodeAction(Array.Empty<ProtocolCodeAction>(), requestId));
			await Task.CompletedTask;
		}
	}
	internal class CodeLensRequestHandler : RequestHandlerBase<CodeLensRequest>
	{
		public TestCodeCoverageManager CodeCoverageManager { get; }

		public override string EndpointName => "textDocument/codeLens";

		internal CodeLensRequestHandler(VsCodeWorkspace workspace, TestCodeCoverageManager codeCoverageManager, IResponseQueue responseQueue)
			: base(workspace, responseQueue)
		{
			CodeCoverageManager = codeCoverageManager;
		}

		public override async Task HandleAsync(CodeLensRequest request, int requestId, CancellationToken cancellationToken)
		{
			Document document = base.Workspace.GetDocument(request.TextDocument.FileName);
			if (document != null)
			{
				if (!base.Workspace.AreAllProjectReferencesBound(document))
				{
					RegisterDelayedRequest(document.Project.Id, request, requestId);
					return;
				}
				CodeLens[] response = new CodeLens[0];
				SymbolInformation[] documentSymbols = await document.GetCodeLensSymbolInformations(cancellationToken, ShowReferenceCodeLens);
				if (documentSymbols != null)
				{
					string version = (await document.GetTextVersionAsync(cancellationToken)).ToString();
					bool flag = CodeCoverageManager != null && CodeCoverageManager.ContainsData();
					ArrayBuilder<CodeLens> instance = ArrayBuilder<CodeLens>.GetInstance();
					SymbolInformation[] array = documentSymbols;
					foreach (SymbolInformation symbolInformation in array)
					{
						instance.Add(new CodeLens
						{
							Range = symbolInformation.Location.Range.GetValueOrDefault(),
							Data = new CodeLensData
							{
								FileName = request.TextDocument.FileName,
								Version = version
							}
						});
						if (flag && ShowTestCoverageCodeLens(symbolInformation.Symbol))
						{
							instance.Add(new CodeLens
							{
								Range = symbolInformation.Location.Range.Value,
								Data = new CodeLensData
								{
									FileName = request.TextDocument.FileName,
									Version = version,
									Type = CodeLensType.CoveredByTest
								}
							});
						}
						if (document.Project.ShowSymbolUsage)
						{
							instance.Add(new CodeLens
							{
								Range = symbolInformation.Location.Range.Value,
								Data = new CodeLensData
								{
									FileName = request.TextDocument.FileName,
									Version = version,
									Type = CodeLensType.ExternalUsage
								}
							});
						}
					}
					response = instance.ToArrayAndFree();
				}
				base.ResponseQueue.Add(ResponseFactory.CodeLens(response, requestId), cancellationToken);
			}
			else
			{
				base.ResponseQueue.Add(ResponseFactory.CodeLens(null, requestId), cancellationToken);
			}
		}

		private bool ShowReferenceCodeLens(ISymbol symbol)
		{
			switch (symbol.Kind)
			{
			case SymbolKind.Method:
			{
				IMethodSymbol methodSymbol = (IMethodSymbol)symbol;
				if (methodSymbol.MethodKind != 0 && methodSymbol.MethodKind != MethodKind.DeclareMethod)
				{
					return methodSymbol.MethodKind == MethodKind.Trigger;
				}
				return true;
			}
			case SymbolKind.Change:
				return false;
			default:
				return true;
			}
		}

		private static bool ShowTestCoverageCodeLens(ISymbol symbol)
		{
			if (symbol.Kind != SymbolKind.Method)
			{
				return false;
			}
			return ((IMethodSymbol)symbol).MethodKind switch
			{
				MethodKind.Method => true, 
				MethodKind.Trigger => true, 
				_ => false, 
			};
		}
	}
	internal class CodeLensResolveRequestHandler : RequestHandlerBase<CodeLensResolveRequest>
	{
		public TestCodeCoverageManager CodeCoverageManager { get; }

		public override string EndpointName => "codeLens/resolve";

		internal CodeLensResolveRequestHandler(VsCodeWorkspace workspace, TestCodeCoverageManager codeCoverageManager, IResponseQueue responseQueue)
			: base(workspace, responseQueue)
		{
			CodeCoverageManager = codeCoverageManager;
		}

		public override async Task HandleAsync(CodeLensResolveRequest request, int requestId, CancellationToken cancellationToken)
		{
			CodeLens response = new CodeLens();
			Document document = base.Workspace.GetDocument(request.Data.FileName);
			if (document == null)
			{
				base.ResponseQueue.Add(ResponseFactory.CodeLensResolve(response, requestId), cancellationToken);
				return;
			}
			if (!base.Workspace.AreAllProjectReferencesBound(document))
			{
				RegisterDelayedRequest(document.Project.Id, request, requestId);
				return;
			}
			if (!string.Equals((await document.GetTextVersionAsync(cancellationToken)).ToString(), request.Data.Version, StringComparison.Ordinal))
			{
				base.ResponseQueue.Add(ResponseFactory.CodeLensResolve(response, requestId), cancellationToken);
				return;
			}
			switch (request.Data.Type)
			{
			case CodeLensType.ExternalUsage:
			{
				int position = (await document.GetTextAsync(cancellationToken)).Lines.GetPosition(new LinePosition(request.Range.Start.Line, request.Range.Start.Character));
				ISymbol symbol = await SymbolFinder.FindSymbolAtPositionAsync(document, position, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				ISymbolUsageInfo symbolUsage = (await document.Project.GetCompilationAsync(cancellationToken).ConfigureAwait(continueOnCapturedContext: false)).GetSymbolUsage(symbol);
				if (symbolUsage != null)
				{
					response = new CodeLens
					{
						Range = request.Range,
						Command = new UiCommand
						{
							Title = $"{symbolUsage.Apps} external"
						}
					};
				}
				break;
			}
			case CodeLensType.CoveredByTest:
				response = await CreateCoveredByCodeLens(request, document, cancellationToken);
				break;
			case CodeLensType.References:
				response = await CreateReferencesCodeLens(request, document, cancellationToken);
				break;
			}
			base.ResponseQueue.Add(ResponseFactory.CodeLensResolve(response, requestId), cancellationToken);
		}

		private async Task<CodeLens> CreateCoveredByCodeLens(CodeLensResolveRequest request, Document document, CancellationToken cancellationToken)
		{
			UiCommand uiCommand = new UiCommand
			{
				Title = "0 covered by"
			};
			int position = (await document.GetTextAsync(cancellationToken)).Lines.GetPosition(new LinePosition(request.Range.Start.Line, request.Range.Start.Character));
			ISymbol symbol = await SymbolFinder.FindSymbolAtPositionAsync(document, position, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
			int num = 0;
			int testsPassed = 0;
			List<TestItem> list = new List<TestItem>();
			if (CodeCoverageManager != null && symbol != null)
			{
				IEnumerable<CodeCoverageForTest> testsCoveringThis = CodeCoverageManager.GetTestsCoveringThis(symbol);
				list = await GetTestItemsFromCoverageData(testsCoveringThis, cancellationToken);
				num = list.Count;
				foreach (TestItem item in list)
				{
					if (item.CodeunitId.HasValue && CodeCoverageManager.TryGetStatus(item.CodeunitId.Value, item.Name, out var status) && status == TestResultStatus.Passed)
					{
						testsPassed++;
					}
				}
			}
			if (num == 0)
			{
				uiCommand.Title = "No tests";
			}
			else if (testsPassed < num)
			{
				uiCommand.Title = string.Format(CultureInfo.InvariantCulture, "?\ufe0f {0} / {1} passing", testsPassed, num);
			}
			else
			{
				uiCommand.Title = string.Format(CultureInfo.InvariantCulture, "? {0} / {1} passing", testsPassed, num);
			}
			if (num > 0 && list != null && list.Count > 0)
			{
				uiCommand.Command = "al.runRelatedTests";
				uiCommand.Arguments = new object[1]
				{
					new
					{
						Tests = list
					}
				};
			}
			return new CodeLens
			{
				Range = request.Range,
				Command = uiCommand
			};
		}

		private async Task<List<TestItem>> GetTestItemsFromCoverageData(IEnumerable<CodeCoverageForTest> testsFromCoverageData, CancellationToken cancellationToken)
		{
			List<TestItem> testItems = new List<TestItem>();
			Project currentProject = base.Workspace.GetCurrentProject();
			if (currentProject == null)
			{
				return testItems;
			}
			Compilation compilation = await currentProject.GetCompilationAsync(cancellationToken);
			foreach (CodeCoverageForTest testsFromCoverageDatum in testsFromCoverageData)
			{
				IMethodSymbol methodFromId = GetMethodFromId(compilation, SymbolKind.Codeunit, testsFromCoverageDatum.ApplicationObjectId, testsFromCoverageDatum.MethodId);
				string text = null;
				if (methodFromId != null)
				{
					text = methodFromId.Name;
				}
				if (text != null)
				{
					TestItem item = new TestItem
					{
						Name = text,
						CodeunitId = testsFromCoverageDatum.ApplicationObjectId
					};
					testItems.Add(item);
				}
			}
			return testItems;
		}

		private static IMethodSymbol? GetMethodFromId(Compilation? compilation, SymbolKind objectKind, int objectId, int methodId)
		{
			return (compilation?.GetApplicationObjectTypeSymbolsByIdAcrossModules(objectKind, objectId).FirstOrDefault())?.GetMembers().FirstOrDefault((ISymbol symbol) => symbol.Kind == SymbolKind.Method && ((IMethodSymbol)symbol).Id == methodId) as IMethodSymbol;
		}

		private static async Task<CodeLens> CreateReferencesCodeLens(CodeLensResolveRequest request, Document document, CancellationToken cancellationToken)
		{
			UiCommand uiCommand = new UiCommand
			{
				Title = ProtocolResources.VoidReferenceDisplayText
			};
			IFindReferencesService findReferences = document.GetLanguageService<IFindReferencesService>();
			int position = (await document.GetTextAsync(cancellationToken)).Lines.GetPosition(new LinePosition(request.Range.Start.Line, request.Range.Start.Character));
			ReferencedSymbol referencedSymbol = findReferences.FindReferencedSymbolsAsync(document, position, cancellationToken).SingleOrDefault();
			if (referencedSymbol != null)
			{
				int num = Math.Max(referencedSymbol.Locations.Count() - 1, 0);
				uiCommand.Title = ((num == 1) ? ProtocolResources.SingleReferenceDisplayText : string.Format(CultureInfo.InvariantCulture, ProtocolResources.MultipleReferencesDisplayText, num));
				if (num > 0)
				{
					uiCommand.Command = "al.peekReferences";
					uiCommand.Arguments = new object[1]
					{
						new PeekReferencesCommandParams
						{
							FilePath = document.FilePath,
							Position = request.Range.Start,
							Multiple = "peek"
						}
					};
				}
			}
			return new CodeLens
			{
				Range = request.Range,
				Command = uiCommand
			};
		}
	}
	public class CompletionRequestHandler : RequestHandlerBase<CompletionRequest>
	{
		private static readonly CompletionItemTag[] DeprecatedTag = new CompletionItemTag[1] { CompletionItemTag.Deprecated };

		public override string EndpointName => "textDocument/completion";

		internal CompletionRequestHandler(VsCodeWorkspace workspace, IResponseQueue responseQueue)
			: base(workspace, responseQueue)
		{
		}

		public override async Task HandleAsync(CompletionRequest request, int requestId, CancellationToken cancellationToken)
		{
			IEnumerable<Document> documents = base.Workspace.GetDocuments(request.TextDocument.FileName);
			HashSet<Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.Contract.CompletionItem> completions = new HashSet<Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.Contract.CompletionItem>();
			foreach (Document document in documents)
			{
				SourceText sourceText = await document.GetTextAsync(cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				int position = sourceText.Lines.GetPosition(new LinePosition(request.Position.Line, request.Position.Character));
				CompletionTrigger trigger = ((request.Context != null) ? new CompletionTrigger(MapCompletionTriggerKind(request.Context.TriggerKind), request.Context.TriggerCharacter?[0] ?? '\0') : CompletionTrigger.Default);
				CompletionService service = CompletionService.GetService(document);
				Microsoft.Dynamics.Nav.CodeAnalysis.Workspaces.Completion.CompletionList completionList;
				try
				{
					completionList = await service.GetCompletionsAsync(document, position, trigger, null, null, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
					if (completionList == null)
					{
						continue;
					}
				}
				catch (Exception)
				{
					base.ResponseQueue.Add(ResponseFactory.Completion(Array.Empty<Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.Contract.CompletionItem>(), requestId), cancellationToken);
					throw;
				}
				LinePositionSpan defaultSpan = sourceText.Lines.GetLinePositionSpan(completionList.DefaultSpan);
				string ns = await document.GetFullyQualifiedNamespaceName(cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				ImmutableDictionary<string, TextSpan> context = await document.GetUsingStatementNamesAndPositionsAsync(cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				TextSpan? anchorPosition = null;
				if (context.Count > 0)
				{
					anchorPosition = context.Values.LastOrDefault();
				}
				else
				{
					NamespaceDeclarationSyntax namespaceDeclarationSyntax = await document.GetNamespaceDeclarationSyntaxAsync(cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
					if (namespaceDeclarationSyntax != null)
					{
						anchorPosition = namespaceDeclarationSyntax.Span;
					}
				}
				int? num = null;
				int? num2 = null;
				if (anchorPosition.HasValue)
				{
					LinePositionSpan? linePositionSpan = sourceText.Lines.GetLinePositionSpan(anchorPosition.Value);
					if (linePositionSpan.HasValue)
					{
						num = linePositionSpan.Value.Start.Line + 1;
						num2 = linePositionSpan.Value.End.Line + 1;
					}
				}
				ImmutableArray<Microsoft.Dynamics.Nav.CodeAnalysis.Workspaces.Completion.CompletionItem>.Enumerator enumerator2 = completionList.Items.GetEnumerator();
				while (enumerator2.MoveNext())
				{
					Microsoft.Dynamics.Nav.CodeAnalysis.Workspaces.Completion.CompletionItem current = enumerator2.Current;
					LinePositionSpan itemsSpan = ((current.Span == default(TextSpan)) ? defaultSpan : sourceText.Lines.GetLinePositionSpan(current.Span));
					InsertFormatKind insertFormatForCompletionItem = GetInsertFormatForCompletionItem(current);
					MarkupContent documentationForCompletionItem = GetDocumentationForCompletionItem(current);
					Glyph glyphForCompletionItem = current.GetGlyphForCompletionItem();
					CompletionItemTag[] tagsFormCompletionItem = GetTagsFormCompletionItem(current);
					Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.Contract.CompletionItem completionItem = new Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.Contract.CompletionItem
					{
						Kind = glyphForCompletionItem.MapToKind(),
						Label = new CompletionItemLabel
						{
							Label = current.DisplayText,
							Description = current.DescriptionValue
						},
						Documentation = documentationForCompletionItem,
						FilterText = current.FilterText,
						InsertTextFormat = insertFormatForCompletionItem,
						InsertText = current.InsertionText,
						Detail = current.DetailText,
						SortText = GenerateSortText(current.SortText, glyphForCompletionItem),
						Range = GetRangeForCompletionItem(itemsSpan),
						Tags = tagsFormCompletionItem
					};
					if (!string.IsNullOrEmpty(current.DescriptionValue) && num.HasValue && num2.HasValue && current.Properties.TryGetValue("Namespace", out string value) && !string.IsNullOrEmpty(value) && !string.Equals(value, ns, StringComparison.OrdinalIgnoreCase) && !context.TryGetValue(value.ToLowerInvariant(), out var _))
					{
						string newText = "using " + value + ";" + Environment.NewLine;
						completionItem.AdditionalTextEdits = new TextEdit[1]
						{
							new TextEdit
							{
								NewText = newText,
								Range = new Range
								{
									Start = new Position
									{
										Line = num.Value,
										Character = 0
									},
									End = new Position
									{
										Line = num2.Value,
										Character = 0
									}
								}
							}
						};
					}
					completions.Add(completionItem);
				}
			}
			Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.Contract.CompletionItem[] result = completions.OrderBy((Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.Contract.CompletionItem c) => c.Label?.Label).ToArray();
			base.ResponseQueue.Add(ResponseFactory.Completion(result, requestId), cancellationToken);
		}

		private static Microsoft.Dynamics.Nav.CodeAnalysis.Workspaces.Completion.CompletionTriggerKind MapCompletionTriggerKind(Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.Contract.CompletionTriggerKind? kind)
		{
			if (!kind.HasValue)
			{
				return Microsoft.Dynamics.Nav.CodeAnalysis.Workspaces.Completion.CompletionTriggerKind.Invoke;
			}
			return kind.Value switch
			{
				Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.Contract.CompletionTriggerKind.Invoke => Microsoft.Dynamics.Nav.CodeAnalysis.Workspaces.Completion.CompletionTriggerKind.Invoke, 
				Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.Contract.CompletionTriggerKind.TriggerCharacter => Microsoft.Dynamics.Nav.CodeAnalysis.Workspaces.Completion.CompletionTriggerKind.Insertion, 
				_ => Microsoft.Dynamics.Nav.CodeAnalysis.Workspaces.Completion.CompletionTriggerKind.Invoke, 
			};
		}

		private static CompletionItemTag[]? GetTagsFormCompletionItem(Microsoft.Dynamics.Nav.CodeAnalysis.Workspaces.Completion.CompletionItem item)
		{
			if (!item.IsDeprecated)
			{
				return null;
			}
			return DeprecatedTag;
		}

		private static Range GetRangeForCompletionItem(LinePositionSpan itemsSpan)
		{
			Range result = default(Range);
			result.Start = new Position
			{
				Line = itemsSpan.Start.Line,
				Character = itemsSpan.Start.Character
			};
			result.End = new Position
			{
				Line = itemsSpan.End.Line,
				Character = itemsSpan.End.Character
			};
			return result;
		}

		private static MarkupContent? GetDocumentationForCompletionItem(Microsoft.Dynamics.Nav.CodeAnalysis.Workspaces.Completion.CompletionItem item)
		{
			if (item.Documentation == null)
			{
				return null;
			}
			string kind = (item.IsMarkdownDocs ? MarkupKind.Markdown : MarkupKind.PlainText);
			return new MarkupContent
			{
				Kind = kind,
				Value = item.Documentation
			};
		}

		private static InsertFormatKind GetInsertFormatForCompletionItem(Microsoft.Dynamics.Nav.CodeAnalysis.Workspaces.Completion.CompletionItem item)
		{
			if (!item.IsSnippet)
			{
				return InsertFormatKind.PlainText;
			}
			return InsertFormatKind.Snippet;
		}

		private static string GenerateSortText(string label, Glyph kind)
		{
			return (kind + 1000).ToString() + label;
		}
	}
