	internal static class DiagnosticsProvider
	{
		private const string TelemetryContext = "DiagnosticsProvider";

		private const string PerFileDiagnosticTelemetryContext = "DiagnosticsProviderPerFile";

		private const string ModuleDiagnosticTelemetryContext = "DiagnosticsProviderModule";

		private const int ParallelCreateDiagnosticsFileThreshold = 100;

		internal static async Task<(PublishDiagnosticsResponse[] Diagnostics, bool Cancelled)> GetDiagnosticsForProjects(Solution solution, ISet<ProjectId> projectIdsToCompile, CancellationToken cancellationToken, bool allowInMemoryFiles = false, PartialCodeAnalysisOptions partialCodeAnalysisOptions = default(PartialCodeAnalysisOptions), ConcurrentDictionary<DocumentId, AnalysisDiagnosticCacheEntry?>? moduleDiagnosticsCache = null)
		{
			IList<Project> projectsToBuild;
			int num;
			(projectsToBuild, num) = GetProjectsToBuild(solution, projectIdsToCompile, cancellationToken);
			if (projectsToBuild.Count == 0)
			{
				return (Diagnostics: SpecializedCollections.EmptyArray<PublishDiagnosticsResponse>(), Cancelled: false);
			}
			bool cancelled = false;
			ArrayBuilder<PublishDiagnosticsResponse> responses = ArrayBuilder<PublishDiagnosticsResponse>.GetInstance(projectsToBuild.Count * num);
			try
			{
				for (int i = 0; i < projectsToBuild.Count; i++)
				{
					cancellationToken.ThrowIfCancellationRequested();
					Project project = projectsToBuild[i];
					Compilation compilation = await project.GetCompilationAsync(cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
					ImmutableArray<Diagnostic> manifestDiagnostics = GetFilteredManifestDiagnosticsForProject(project);
					ImmutableArray<Diagnostic> compilationDiagnostics = ImmutableArray<Diagnostic>.Empty;
					ImmutableArray<Diagnostic> analysisDiagnostics2 = ImmutableArray<Diagnostic>.Empty;
					bool num2 = project.BackgroundCodeAnalysisScope != BackgroundCodeAnalysisScope.None && project.AnalyzerReferences.Count > 0;
					bool usePartialAnalysisStrategy = partialCodeAnalysisOptions.UsePartialAnalysis && project.BackgroundCodeAnalysisScope == BackgroundCodeAnalysisScope.File;
					if (partialCodeAnalysisOptions.PerProjectPartialAnalysisDocumentThreshold > PartialCodeAnalysisOptions.Constants.NoDocumentThreshold)
					{
						usePartialAnalysisStrategy &= project.DocumentIds.Count > partialCodeAnalysisOptions.PerProjectPartialAnalysisDocumentThreshold;
					}
					if (!num2 || usePartialAnalysisStrategy)
					{
						compilationDiagnostics = compilation.GetDiagnostics(cancellationToken);
						cancellationToken.ThrowIfCancellationRequested();
					}
					if (num2)
					{
						if (!usePartialAnalysisStrategy)
						{
							(compilationDiagnostics, analysisDiagnostics2) = await AnalyzersHelper.GetAnalyzerDiagnostics(compilation, project.DiagnosticAnalyzers, AnalyzerOptions.Empty, null, logAnalyzerExceptionAsDiagnostics: true, reportSuppressedDiagnostics: false, TelemetryServiceManager.CurrentTelemetryService, "DiagnosticsProvider", cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
						}
						else
						{
							analysisDiagnostics2 = await AnalyzersHelper.GetPerModuleAnalyzerDiagnostics(compilation, project.DiagnosticAnalyzers, AnalyzerOptions.Empty, null, logAnalyzerExceptionAsDiagnostics: true, reportSuppressedDiagnostics: false, TelemetryServiceManager.CurrentTelemetryService, "DiagnosticsProviderModule", cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
						}
						analysisDiagnostics2 = analysisDiagnostics2.AddRange(AnalyzersHelper.GetAnalyzerLoadingDiagnostics(project.AnalyzerReferences));
					}
					using SyntaxTreeToDiagnosticsMapping analysisDiagnosticsMapping = new SyntaxTreeToDiagnosticsMapping(analysisDiagnostics2, project.FilePath);
					using SyntaxTreeToDiagnosticsMapping compilationDiagnosticsMapping = new SyntaxTreeToDiagnosticsMapping(compilationDiagnostics, project.FilePath);
					foreach (Document document in project.Documents)
					{
						cancellationToken.ThrowIfCancellationRequested();
						document.FilePath.GetUri();
						var (value, cacheEntry) = await CreateDiagnosticResponse(allowInMemoryFiles, document, compilationDiagnosticsMapping, analysisDiagnosticsMapping, compilationDiagnostics.Length + analysisDiagnostics2.Length, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
						responses.AddIfNotNull(value);
						if (moduleDiagnosticsCache != null && usePartialAnalysisStrategy)
						{
							UpdateModuleDiagnosticCacheIfChangedDiagnostics(moduleDiagnosticsCache, document.Id, cacheEntry);
						}
					}
					AddManifestAndExternalDiagnosticsToDiagnosticsResponse(responses, compilationDiagnosticsMapping, analysisDiagnosticsMapping, manifestDiagnostics, project.FilePath, cancellationToken);
				}
			}
			catch (OperationCanceledException)
			{
				cancelled = true;
			}
			catch (Exception e)
			{
				LoggingUtilities.WriteMessageFailedException("DiagnosticProvider", e);
			}
			return (Diagnostics: responses.ToArrayAndFree(), Cancelled: cancelled);
		}

		private static void UpdateModuleDiagnosticCacheIfChangedDiagnostics(ConcurrentDictionary<DocumentId, AnalysisDiagnosticCacheEntry?> cache, DocumentId documentId, AnalysisDiagnosticCacheEntry? cacheEntry)
		{
			if (cache.TryGetValue(documentId, out AnalysisDiagnosticCacheEntry value))
			{
				if (value?.CombinedDiagnosticsHashCode != cacheEntry?.CombinedDiagnosticsHashCode && cacheEntry != null && cacheEntry.Diagnostics.Length == 0)
				{
					cache.TryRemove(documentId, out AnalysisDiagnosticCacheEntry _);
				}
			}
			else if (cacheEntry != null && cacheEntry.Diagnostics.Length != 0)
			{
				cache[documentId] = cacheEntry;
			}
		}

		private static (IList<Project> Projects, int DocumentNumber) GetProjectsToBuild(Solution solution, ISet<ProjectId> projectIdsToCompile, CancellationToken cancellationToken)
		{
			if (projectIdsToCompile.Count < 1)
			{
				return (Projects: SpecializedCollections.EmptyList<Project>(), DocumentNumber: 0);
			}
			PooledList<Project> instance = PooledList<Project>.GetInstance();
			try
			{
				int num = 0;
				ProjectDependencyGraph projectDependencyGraph = solution.GetProjectDependencyGraph();
				if (projectDependencyGraph == null)
				{
					foreach (ProjectId item in projectIdsToCompile)
					{
						cancellationToken.ThrowIfCancellationRequested();
						Project project = solution.GetProject(item);
						if (project != null)
						{
							num += project.DocumentIds.Count;
							instance.Add(project);
						}
					}
				}
				else
				{
					PooledHashSet<ProjectId> instance2 = PooledHashSet<ProjectId>.GetInstance();
					try
					{
						foreach (ProjectId item2 in projectIdsToCompile)
						{
							cancellationToken.ThrowIfCancellationRequested();
							if (!instance2.Add(item2))
							{
								continue;
							}
							foreach (ProjectId item3 in projectDependencyGraph.GetProjectsThatDirectlyDependOnThisProject(item2))
							{
								instance2.Add(item3);
							}
						}
						foreach (ProjectId item4 in projectDependencyGraph.SortDependenciesTopologically(instance2))
						{
							cancellationToken.ThrowIfCancellationRequested();
							Project project2 = solution.GetProject(item4);
							if (project2 != null)
							{
								num += project2.DocumentIds.Count;
								instance.Add(project2);
							}
						}
					}
					finally
					{
						instance2.Free();
					}
				}
				return (Projects: instance.ToList(), DocumentNumber: num);
			}
			finally
			{
				instance.Free();
			}
		}

		internal static void AddManifestAndExternalDiagnosticsToDiagnosticsResponse(ArrayBuilder<PublishDiagnosticsResponse> responses, SyntaxTreeToDiagnosticsMapping compilationDiagnosticsMapping, SyntaxTreeToDiagnosticsMapping analysisDiagnosticsMapping, ImmutableArray<Diagnostic> manifestDiagnostics, string appJsonPath, CancellationToken cancellationToken)
		{
			PublishDiagnosticsResponse value = CreateDiagnosticResponseForManifestDiagnostics(compilationDiagnosticsMapping, analysisDiagnosticsMapping, manifestDiagnostics, appJsonPath, cancellationToken);
			IEnumerable<PublishDiagnosticsResponse> items = CreateDiagnosticResponseForDiagnosticsInExternalFiles(analysisDiagnosticsMapping, cancellationToken);
			responses.AddIfNotNull(value);
			responses.AddRange(items);
		}

		private static IEnumerable<PublishDiagnosticsResponse> CreateDiagnosticResponseForDiagnosticsInExternalFiles(SyntaxTreeToDiagnosticsMapping analysisDiagnosticMapping, CancellationToken cancellationToken)
		{
			PooledDictionary<string, (ArrayBuilder<ProtocolDiagnostic> diagnostics, int combinedHashCode)> diagnosticsPerFile = PooledDictionary<string, (ArrayBuilder<ProtocolDiagnostic>, int)>.GetInstance();
			try
			{
				CollectDiagnosticsFromExternalFiles(analysisDiagnosticMapping, diagnosticsPerFile, cancellationToken);
				foreach (KeyValuePair<string, (ArrayBuilder<ProtocolDiagnostic>, int)> item2 in diagnosticsPerFile)
				{
					cancellationToken.ThrowIfCancellationRequested();
					ProtocolDiagnostic[] diagnostics = item2.Value.Item1.ToArray();
					yield return new PublishDiagnosticsResponse
					{
						Uri = (item2.Key?.GetUri() ?? string.Empty),
						Diagnostics = diagnostics,
						CombinedDiagnosticsHashCode = item2.Value.Item2
					};
				}
			}
			finally
			{
				foreach (var value in diagnosticsPerFile.Values)
				{
					ArrayBuilder<ProtocolDiagnostic> item = value.diagnostics;
					item.Free();
				}
				diagnosticsPerFile.Free();
			}
		}

		private static void CollectDiagnosticsFromExternalFiles(SyntaxTreeToDiagnosticsMapping analysisDiagnosticMapping, PooledDictionary<string, (ArrayBuilder<ProtocolDiagnostic> diagnostics, int combinedHashCode)> diagnosticsPerFile, CancellationToken cancellationToken)
		{
			foreach (Diagnostic externalFilesDiagnostic in analysisDiagnosticMapping.GetExternalFilesDiagnostics())
			{
				cancellationToken.ThrowIfCancellationRequested();
				string key = externalFilesDiagnostic.Location.GetLineSpan().Path.CreateUriFilePath();
				if (!diagnosticsPerFile.TryGetValue(key, out (ArrayBuilder<ProtocolDiagnostic>, int) value))
				{
					value.Item1 = ArrayBuilder<ProtocolDiagnostic>.GetInstance();
					value.Item2 = 0;
				}
				ProtocolDiagnostic item = CreateProtocolDiagnostic(externalFilesDiagnostic, ref value.Item2);
				value.Item1.Add(item);
				diagnosticsPerFile[key] = value;
			}
		}

		internal static async Task<(PublishDiagnosticsResponse[] Diagnostics, bool Cancelled)> GetDocumentDiagnostics(Solution solution, DocumentId documentId, CancellationToken cancellationToken, bool allowInMemoryFiles = false, ProtocolDiagnostic[]? precalculatedDiagnostics = null)
		{
			Document document = solution.GetDocument(documentId);
			if (document == null)
			{
				return (Diagnostics: SpecializedCollections.EmptyArray<PublishDiagnosticsResponse>(), Cancelled: false);
			}
			if (!allowInMemoryFiles && !document.FilePath.IsAlFile())
			{
				return (Diagnostics: SpecializedCollections.EmptyArray<PublishDiagnosticsResponse>(), Cancelled: false);
			}
			bool cancelled = false;
			ArrayBuilder<PublishDiagnosticsResponse> responses = ArrayBuilder<PublishDiagnosticsResponse>.GetInstance(2);
			string responseUri = document.FilePath.GetUri();
			try
			{
				SemanticModel semanticModel = await document.GetSemanticModelAsync(cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				int combinedHashCode = 0;
				_ = ImmutableArray<Diagnostic>.Empty;
				ImmutableArray<Diagnostic> diagnostics;
				if (document.Project.BackgroundCodeAnalysisScope == BackgroundCodeAnalysisScope.File && document.Project.AnalyzerReferences.Count > 0)
				{
					(ImmutableArray<Diagnostic>, ImmutableArray<Diagnostic>) obj = await AnalyzersHelper.GetAnalyzerDiagnosticsForDocument(semanticModel.SyntaxTree, semanticModel.Compilation, document.Project.DiagnosticAnalyzers, TelemetryServiceManager.CurrentTelemetryService, "DiagnosticsProviderPerFile", cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
					ImmutableArray<Diagnostic> item = obj.Item1;
					ImmutableArray<Diagnostic> item2 = obj.Item2;
					diagnostics = item.AddRange(item2).AddRange(AnalyzersHelper.GetAnalyzerLoadingDiagnostics(document.Project.AnalyzerReferences));
				}
				else
				{
					diagnostics = semanticModel.GetDiagnostics(null, cancellationToken);
				}
				ArrayBuilder<ProtocolDiagnostic> instance = ArrayBuilder<ProtocolDiagnostic>.GetInstance(diagnostics.Length + ((precalculatedDiagnostics != null) ? precalculatedDiagnostics.Length : 0));
				try
				{
					AddDocumentDiagnosticsToBuilder(semanticModel.SyntaxTree, diagnostics, ref combinedHashCode, instance, out var _);
					if (precalculatedDiagnostics != null && precalculatedDiagnostics.Length != 0)
					{
						AddAllProtocolDiagnosticsToBuilder(precalculatedDiagnostics, ref combinedHashCode, instance);
					}
					ProtocolDiagnostic[] diagnostics2 = ((instance.Count > 0) ? instance.ToArray() : Array.Empty<ProtocolDiagnostic>());
					responses.Add(new PublishDiagnosticsResponse
					{
						Uri = responseUri,
						Diagnostics = diagnostics2,
						CombinedDiagnosticsHashCode = combinedHashCode
					});
				}
				finally
				{
					instance.Free();
				}
			}
			catch (OperationCanceledException)
			{
				cancelled = true;
			}
			catch (Exception e)
			{
				LoggingUtilities.WriteMessageFailedException("DiagnosticProvider", e);
				cancelled = true;
			}
			return (Diagnostics: responses.ToArrayAndFree(), Cancelled: cancelled);
		}

		private static void AddAllProtocolDiagnosticsToBuilder(IEnumerable<ProtocolDiagnostic> protocolDiagnostics, ref int combinedHashCode, ArrayBuilder<ProtocolDiagnostic> builder)
		{
			foreach (ProtocolDiagnostic protocolDiagnostic in protocolDiagnostics)
			{
				builder.Add(protocolDiagnostic);
				combinedHashCode = Hash.Combine(combinedHashCode, protocolDiagnostic.GetHashCode());
			}
		}

		[Conditional("DEBUG")]
		private static void SendInternalErrorDiagnostic(ArrayBuilder<PublishDiagnosticsResponse> responses, string responseUri, Exception e)
		{
			responses.Add(new PublishDiagnosticsResponse
