				Uri = responseUri,
				Diagnostics = new ProtocolDiagnostic[1]
				{
					new ProtocolDiagnostic(ProtocolDiagnosticSeverity.Error, string.Format(CultureInfo.InvariantCulture, CompilerDiagnosticsResources.ERR_InternalError, e.Message, e.StackTrace))
				}
			});
		}

