		private static async Task<(PublishDiagnosticsResponse? Response, AnalysisDiagnosticCacheEntry? AnalysisDiagnosticsEntry)> CreateDiagnosticResponse(bool allowInMemoryFiles, Document document, SyntaxTreeToDiagnosticsMapping syntaxToCompilationDiagnosticsMapping, SyntaxTreeToDiagnosticsMapping syntaxToAnalysisDiagnosticsMapping, int totalDiagnosticsLength, CancellationToken cancellationToken)
		{
			ProtocolDiagnostic[] analysisDiagnostics = null;
			AnalysisDiagnosticCacheEntry analysisDiagnosticCacheEntry = null;
			if (!allowInMemoryFiles && !document.FilePath.IsAlFile())
			{
				return (Response: null, AnalysisDiagnosticsEntry: null);
			}
			ArrayBuilder<ProtocolDiagnostic> builder = ArrayBuilder<ProtocolDiagnostic>.GetInstance(totalDiagnosticsLength);
			try
			{
				SyntaxTree syntaxTree = await document.GetSyntaxTreeAsync(cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				int combinedHashCode = 0;
				if (!syntaxToAnalysisDiagnosticsMapping.IsEmpty)
				{
					AddDiagnosticsFromSyntaxTreeToBuilder(syntaxToAnalysisDiagnosticsMapping, ref combinedHashCode, builder, syntaxTree);
					analysisDiagnostics = builder.ToArray();
				}
				if (!syntaxToCompilationDiagnosticsMapping.IsEmpty)
				{
					AddDiagnosticsFromSyntaxTreeToBuilder(syntaxToCompilationDiagnosticsMapping, ref combinedHashCode, builder, syntaxTree);
				}
				if (analysisDiagnostics != null)
				{
					analysisDiagnosticCacheEntry = new AnalysisDiagnosticCacheEntry(analysisDiagnostics, combinedHashCode);
				}
				ProtocolDiagnostic[] diagnostics = builder.ToArray();
				return (Response: new PublishDiagnosticsResponse
				{
					Uri = document.FilePath.GetUri(),
					Diagnostics = diagnostics,
					CombinedDiagnosticsHashCode = combinedHashCode
				}, AnalysisDiagnosticsEntry: analysisDiagnosticCacheEntry);
			}
			finally
			{
				builder.Free();
			}
		}

		private static PublishDiagnosticsResponse CreateDiagnosticResponseForManifestDiagnostics(SyntaxTreeToDiagnosticsMapping compilationDiagnosticsMapping, SyntaxTreeToDiagnosticsMapping analysisDiagnosticsMapping, ImmutableArray<Diagnostic> manifestDiagnostics, string appJsonPath, CancellationToken cancellationToken)
		{
			IReadOnlyList<Diagnostic> manifestDiagnostics2 = compilationDiagnosticsMapping.GetManifestDiagnostics();
			IReadOnlyList<Diagnostic> manifestDiagnostics3 = analysisDiagnosticsMapping.GetManifestDiagnostics();
			ArrayBuilder<ProtocolDiagnostic> instance = ArrayBuilder<ProtocolDiagnostic>.GetInstance(manifestDiagnostics2.Count + manifestDiagnostics3.Count + manifestDiagnostics.Length);
			try
			{
				int combinedHashCode = 0;
				AddManifestDiagnosticsToBuilder(manifestDiagnostics2, ref combinedHashCode, instance);
				AddManifestDiagnosticsToBuilder(manifestDiagnostics3, ref combinedHashCode, instance);
				AddAllDiagnosticsToBuilder(manifestDiagnostics, ref combinedHashCode, instance);
				ProtocolDiagnostic[] diagnostics = instance.ToArray();
				return new PublishDiagnosticsResponse
				{
					Uri = (appJsonPath?.GetUri() ?? string.Empty),
					Diagnostics = diagnostics,
					CombinedDiagnosticsHashCode = combinedHashCode
				};
			}
			finally
			{
				instance.Free();
			}
		}

		private static void AddDocumentDiagnosticsToBuilder(SyntaxTree documentSyntaxTree, ImmutableArray<Diagnostic> diagnostics, ref int combinedHashCode, ArrayBuilder<ProtocolDiagnostic> documentDiagnosticBuilder, out bool containsFilesNotInDocument)
		{
			containsFilesNotInDocument = false;
			for (int i = 0; i < diagnostics.Length; i++)
			{
				if (diagnostics[i].Location.SourceTree == documentSyntaxTree)
				{
					documentDiagnosticBuilder.Add(CreateProtocolDiagnostic(diagnostics[i], ref combinedHashCode));
				}
			}
		}

		private static void AddAllDiagnosticsToBuilder(ImmutableArray<Diagnostic> diagnostics, ref int combinedHashCode, ArrayBuilder<ProtocolDiagnostic> builder)
		{
			for (int i = 0; i < diagnostics.Length; i++)
			{
				builder.Add(CreateProtocolDiagnostic(diagnostics[i], ref combinedHashCode));
			}
		}

		private static void AddDiagnosticsFromSyntaxTreeToBuilder(SyntaxTreeToDiagnosticsMapping diagnostics, ref int combinedHashCode, ArrayBuilder<ProtocolDiagnostic> builder, SyntaxTree syntaxTree)
		{
			IReadOnlyList<Diagnostic> diagnosticsForSyntaxTree = diagnostics.GetDiagnosticsForSyntaxTree(syntaxTree);
			if (diagnosticsForSyntaxTree.Count != 0)
			{
				for (int i = 0; i < diagnosticsForSyntaxTree.Count; i++)
				{
					builder.Add(CreateProtocolDiagnostic(diagnosticsForSyntaxTree[i], ref combinedHashCode));
				}
			}
		}

		private static void AddManifestDiagnosticsToBuilder(IReadOnlyList<Diagnostic> diagnostics, ref int combinedHashCode, ArrayBuilder<ProtocolDiagnostic> builder)
		{
			for (int i = 0; i < diagnostics.Count; i++)
			{
				builder.Add(CreateProtocolDiagnostic(diagnostics[i], ref combinedHashCode));
			}
		}

		private static ProtocolDiagnostic CreateProtocolDiagnostic(Diagnostic d, ref int combinedHashCode)
		{
			ProtocolDiagnostic protocolDiagnostic = new ProtocolDiagnostic(d);
			combinedHashCode = Hash.Combine(combinedHashCode, protocolDiagnostic.GetHashCode());
			return protocolDiagnostic;
		}
	}
	public class DidChangeActiveDocumentRequestHandler : RequestHandlerBase<DidChangeActiveDocumentRequest>
	{
		private long sequenceNumber;

		public long CurrentSequenceNumber => sequenceNumber;

		public override string EndpointName => "al/didChangeActiveDocument";

		public DidChangeActiveDocumentRequestHandler(VsCodeWorkspace workspace, IResponseQueue responseQueue)
			: base(workspace, responseQueue)
		{
			sequenceNumber = -1L;
		}

		public override async Task HandleAsync(DidChangeActiveDocumentRequest request, int requestId, CancellationToken cancellationToken)
		{
			HandleRequest(request, requestId, cancellationToken);
			base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId), cancellationToken);
		}

		private void HandleRequest(DidChangeActiveDocumentRequest request, int requestId, CancellationToken cancellationToken)
		{
			if (request.TextDocument == null)
			{
				return;
			}
			long num = sequenceNumber;
			if (request.SequenceNumber >= num)
			{
				UpdateSequenceNumber(request.SequenceNumber, out var shouldHandleRequest);
				if (shouldHandleRequest)
				{
					Document document = base.Workspace.GetDocument(request.TextDocument.FileName);
					ActiveDocumentId currentActiveDocument = ((document == null) ? new ActiveDocumentId(request.TextDocument.FileName) : new ActiveDocumentId(document.Id, document.FilePath));
					base.Workspace.SetCurrentActiveDocument(currentActiveDocument);
				}
			}
		}

		private void UpdateSequenceNumber(long newSequenceNumber, out bool shouldHandleRequest)
		{
			long num;
			for (num = sequenceNumber; num < newSequenceNumber; num = Interlocked.CompareExchange(ref sequenceNumber, newSequenceNumber, num))
			{
			}
			shouldHandleRequest = num == newSequenceNumber;
		}
	}
	internal class DidChangeConfigurationRequestHandler : ProjectRequestHandler<SettingsRequest>
	{
		public override string EndpointName => "workspace/didChangeConfiguration";

		internal DidChangeConfigurationRequestHandler(VsCodeWorkspace workspace, ResponseQueue responseQueue)
			: base(workspace, responseQueue)
		{
		}

		public override Task HandleAsync(SettingsRequest request, int requestId, CancellationToken cancellationToken)
		{
			if (string.IsNullOrEmpty(request.Settings?.WorkspacePath?.GetFilePath()))
			{
				IEnumerable<Project> projects = base.Workspace.CurrentSolution.Projects;
				int num = projects.Count();
				if (num == 0)
				{
					return Task.CompletedTask;
				}
				ConfigurationItem[] array = new ConfigurationItem[num];
				int num2 = 0;
				foreach (Project item in projects)
				{
					string fullName = new DirectoryInfo(item.FilePath).Parent.FullName;
					ConfigurationItem configurationItem = new ConfigurationItem
					{
						ScopeUri = fullName,
						Section = "al"
					};
					array[num2++] = configurationItem;
				}
				ConfigurationParams configurationParams = new ConfigurationParams
				{
					Items = array
				};
				base.ResponseQueue.Add(ResponseFactory.GetConfiguration(configurationParams, requestId));
			}
			else
			{
				TryAddOrUpdateProject(request, cancellationToken, out ProjectManifest _);
			}
			return Task.CompletedTask;
		}
	}
	internal class DidChangeTextDocumentRequestHandler : RequestHandlerBase<DidChangeTextDocumentRequest>
	{
		public override string EndpointName => "textDocument/didChange";

		internal DidChangeTextDocumentRequestHandler(VsCodeWorkspace workspace, ResponseQueue responseQueue)
			: base(workspace, (IResponseQueue)responseQueue)
		{
		}

		public override async Task HandleAsync(DidChangeTextDocumentRequest request, int requestId, CancellationToken cancellationToken)
		{
			Solution currentSolution = base.Workspace.CurrentSolution;
			string fileName = request.TextDocument.FileName;
			if (string.Equals(Path.GetExtension(fileName), ".json", StringComparison.OrdinalIgnoreCase))
			{
				return;
			}
			if ((base.Workspace.CurrentProjectId == null || currentSolution == null) && !base.Workspace.BufferManager.TryApplyChangesToInMemoryFile(request, cancellationToken) && (base.Workspace.CurrentProjectId == null || base.Workspace.CurrentSolution == null))
			{
				LocalMachineLogger.LogError("Missed a didChangeMessage for file {0}.", fileName);
				return;
			}
			DocumentId documentId = base.Workspace.GetDocumentId(fileName);
			if (documentId != null)
			{
				await base.Workspace.BufferManager.UpdateBuffer(request, cancellationToken);
				return;
			}
			foreach (Project project in currentSolution.Projects)
			{
				if (project.IsFileFromProjectFolder(fileName))
				{
					base.Workspace.BufferManager.TryAddTransientDocument(project.Id, fileName, null, handleRad: false, out documentId);
					LocalMachineLogger.LogError("Missed a didChangeMessage for file {0}.", fileName);
					if (documentId == null)
					{
						LocalMachineLogger.LogError("The document {0} could not be added to the workspace.", fileName);
					}
					return;
				}
			}
			LocalMachineLogger.LogError("Missed a didChangeMessage for file {0}.", fileName);
		}
	}
	internal class DidChangeWatchedFilesRequestHandler : RequestHandlerBase<DidChangeWatchedFilesRequest>
	{
		public override string EndpointName => "workspace/didChangeWatchedFiles";

		internal DidChangeWatchedFilesRequestHandler(VsCodeWorkspace workspace, ResponseQueue responseQueue)
			: base(workspace, (IResponseQueue)responseQueue)
		{
		}

		public override Task HandleAsync(DidChangeWatchedFilesRequest request, int requestId, CancellationToken cancellationToken)
		{
			FileEvent[] changes = request.Changes;
			foreach (FileEvent fileEvent in changes)
			{
				try
				{
					if (fileEvent.Type == FileChangeType.Deleted)
					{
						base.Workspace.BufferManager.RemoveTrackedDocumentOrDirectory(fileEvent.Uri, handleRad: true);
					}
					else if (fileEvent.Type == FileChangeType.Created)
					{
						string filePath = fileEvent.Uri.GetFilePath();
						if (filePath.IsAlFile())
						{
							ProjectId projectId = base.Workspace.FindProjectIdForPath(filePath);
							if ((object)projectId != null && !base.Workspace.AddTransientDocument(projectId, filePath))
							{
								LogCouldNotReadFileError(filePath);
							}
						}
						else if (Directory.Exists(filePath))
						{
							ProjectId projectId2 = base.Workspace.FindProjectIdForPath(filePath);
							if ((object)projectId2 != null)
							{
								base.Workspace.AddDocumentsFromPath(projectId2, filePath);
							}
						}
					}
					else if (fileEvent.Type == FileChangeType.Changed)
					{
						string filePath2 = fileEvent.Uri.GetFilePath();
						if (filePath2.HasAlExtension() && !File.Exists(filePath2))
						{
							base.Workspace.BufferManager.RemoveTrackedDocumentOrDirectory(fileEvent.Uri, handleRad: true);
						}
					}
				}
				catch (IOException ex)
				{
					LogException(ex);
				}
			}
			return Task.CompletedTask;
		}

		private void LogCouldNotReadFileError(string path)
		{
			string message = string.Format(CultureInfo.InvariantCulture, ProtocolResources.CouldNotReadFile, path);
			base.ResponseQueue.Add(ResponseFactory.LogNotification(MessageType.Log, message));
		}

		private void LogException(Exception ex)
		{
			string exceptionLogEntry = OutputLoggerUtility.GetExceptionLogEntry(ex);
			base.ResponseQueue.Add(ResponseFactory.LogNotification(MessageType.Log, exceptionLogEntry));
		}
	}
	internal class DidCloseTextDocumentRequestHandler : RequestHandlerBase<DidCloseTextDocumentRequest>
	{
		public override string EndpointName => "textDocument/didClose";

		internal DidCloseTextDocumentRequestHandler(VsCodeWorkspace workspace, ResponseQueue responseQueue)
			: base(workspace, (IResponseQueue)responseQueue)
		{
		}

		public override Task HandleAsync(DidCloseTextDocumentRequest request, int requestId, CancellationToken cancellationToken)
		{
			if (base.Workspace.CurrentProjectId == null)
			{
				return Task.CompletedTask;
			}
			string fileName = request.TextDocument.FileName;
			Project currentProject = base.Workspace.GetCurrentProject();
			if (!IsAlFile(fileName) || currentProject == null || !currentProject.IsFileFromProjectFolder(fileName))
			{
				return Task.CompletedTask;
			}
			if (!Uri.TryCreate(request.TextDocument.Uri, UriKind.Absolute, out Uri result) || result.Scheme != "file")
			{
				return Task.CompletedTask;
			}
			base.Workspace.GetDocumentId(fileName);
			return Task.CompletedTask;
		}

		private static bool IsAlFile(string filePath)
		{
			return string.Equals(".al", Path.GetExtension(filePath), StringComparison.OrdinalIgnoreCase);
		}
	}
	internal class DidOpenTextDocumentRequestHandler : RequestHandlerBase<DidOpenTextDocumentRequest>
	{
		public override string EndpointName => "textDocument/didOpen";

		internal DidOpenTextDocumentRequestHandler(VsCodeWorkspace workspace, ResponseQueue responseQueue)
			: base(workspace, (IResponseQueue)responseQueue)
		{
		}

		public override Task HandleAsync(DidOpenTextDocumentRequest request, int requestId, CancellationToken cancellationToken)
		{
			if (!request.TextDocument.LanguageId.Equals("AL", StringComparison.OrdinalIgnoreCase))
			{
				return Task.CompletedTask;
			}
			if (!RequestFilePathIsAcceptable(request))
			{
				return Task.CompletedTask;
			}
			if (!(base.Workspace.CurrentProjectId == null))
			{
				Project? currentProject = base.Workspace.GetCurrentProject();
				if (currentProject == null || currentProject.IsFileFromProjectFolder(request.TextDocument.FileName))
				{
					string fileName = request.TextDocument.FileName;
					base.Workspace.BufferManager.TryAddTransientDocument(base.Workspace.CurrentProjectId, fileName, request.TextDocument.Text, handleRad: false, out DocumentId _);
					return Task.CompletedTask;
				}
			}
			if (!base.Workspace.BufferManager.AddOrUpdateInMemoryFile(request.TextDocument.FileName, request.TextDocument.Text))
			{
				LocalMachineLogger.LogError("The document {0} could not be added to the workspace because no project was loaded and it could not be saved.", request.TextDocument.FileName);
			}
			return Task.CompletedTask;
		}

		private static bool RequestFilePathIsAcceptable(DidOpenTextDocumentRequest request)
		{
			if (request.TextDocument.LanguageId.Equals("AL", StringComparison.OrdinalIgnoreCase) && Uri.TryCreate(request.TextDocument.Uri, UriKind.Absolute, out Uri result))
			{
				return result.Scheme == "file";
			}
			return false;
		}
	}
	internal class DidSaveTextDocumentRequestHandler : RequestHandlerBase<DidSaveTextDocumentRequest>
	{
		public override string EndpointName => "textDocument/didSave";

		internal DidSaveTextDocumentRequestHandler(VsCodeWorkspace workspace, ResponseQueue responseQueue)
			: base(workspace, (IResponseQueue)responseQueue)
		{
		}

		public override Task HandleAsync(DidSaveTextDocumentRequest request, int requestId, CancellationToken cancellationToken)
		{
			string fileName = Path.GetFileName(request.TextDocument.FileName);
			if (fileName != null)
			{
				if (fileName.Equals("app.json", StringComparison.OrdinalIgnoreCase))
				{
					string directoryName = Path.GetDirectoryName(request.TextDocument.FileName);
					Project projectFromWorkspace = GetProjectFromWorkspace(directoryName);
					ReloadProject(projectFromWorkspace, cancellationToken);
				}
				else
				{
					TryForceRefreshAllProjectsWithAttachedConfigurationFiles(request.TextDocument.FileName, cancellationToken);
				}
			}
			return Task.CompletedTask;
		}

		private void ReloadProject(Project projectToUpdate, CancellationToken cancellationToken)
		{
			if (projectToUpdate == null)
			{
				return;
			}
			Solution currentSolution = base.Workspace.CurrentSolution;
			ProjectId currentProjectId = base.Workspace.CurrentProjectId;
			try
			{
				VsCodeWorkspace workspace = base.Workspace;
				Settings obj = new Settings
				{
					WorkspacePath = projectToUpdate.ProjectFolder
				};
				ALResourceConfigurationSettings obj2 = new ALResourceConfigurationSettings
				{
					AssemblyProbingPaths = projectToUpdate.AssemblyProbingPaths?.ToArray(),
					PackageCachePaths = projectToUpdate.PackageCachePaths.ToArray(),
					BackgroundCodeAnalysis = projectToUpdate.BackgroundCodeAnalysisScope.IntoString(),
					RuleSetPath = projectToUpdate.RuleSetPath
				};
				IReadOnlyList<AnalyzerReference> analyzerReferences = projectToUpdate.AnalyzerReferences;
				obj2.EnableCodeAnalysis = analyzerReferences != null && analyzerReferences.Count > 0;
				obj2.IncrementalBuild = projectToUpdate.IncrementalBuild;
				obj2.CaptureSymbolUsage = projectToUpdate.CaptureSymbolUsage;
				obj2.EnableCodeActions = projectToUpdate.EnableCodeActions;
				CompilationOptions compilationOptions = projectToUpdate.CompilationOptions;
				obj2.GenerateReportLayout = (object)compilationOptions == null || (compilationOptions.CompilationGenerateOptions & CompilationGenerationOptions.ReportLayout) != 0;
				obj2.MaxDegreeOfParallelism = projectToUpdate.CompilationOptions?.MaxConcurrencyLevel.MaxConcurrencyLevel ?? ConcurrencyLevel.Unbounded.MaxConcurrencyLevel;
				obj2.ParallelBuild = projectToUpdate.CompilationOptions?.ConcurrentBuild;
				obj2.CodeAnalyzers = projectToUpdate.AnalyzerReferences?.Select((AnalyzerReference r) => r.FullPath).ToArray() ?? SpecializedCollections.EmptyArray<string>();
				obj2.OutFolder = projectToUpdate.CompilationOptions?.OutFolder;
				obj2.NamespaceTemplate = projectToUpdate.NamespaceTemplate;
				obj.AlResourceConfigurationSettings = obj2;
				obj.DependencyParentWorkspacePath = string.Empty;
				List<Diagnostic> projectLoadingDiagnostics;
				bool missingSymbols;
				ProjectManifest? projectManifest = workspace.AddOrUpdateProjectFromPath(obj, forceCheckDependencies: true, out projectLoadingDiagnostics, out missingSymbols);
				string uri = projectToUpdate.FilePath.GetUri();
				string ruleSetPath = (RulesetUtilities.IsRemotePath(projectToUpdate.RuleSetPath) ? projectToUpdate.FilePath.GetUri() : (projectToUpdate.RuleSetPath?.GetUri() ?? string.Empty));
				if (projectManifest == null)
				{
					base.ResponseQueue.AddDiagnosticResponse(projectLoadingDiagnostics, uri, ruleSetPath, cancellationToken);
				}
				if (missingSymbols)
				{
					base.ResponseQueue.Add(ResponseFactory.CreateSymbolsMissingEvent(), cancellationToken);
				}
				Solution currentSolution2 = base.Workspace.CurrentSolution;
				if (currentSolution != currentSolution2)
				{
					base.Workspace.ForceProjectClosureDiagnosticsEmit(projectToUpdate.Id);
				}
			}
			finally
			{
				if (currentProjectId != null)
				{
					base.Workspace.SetCurrentProjectId(currentProjectId);
				}
			}
		}

		private void TryForceRefreshAllProjectsWithAttachedConfigurationFiles(string fileName, CancellationToken cancellationToken)
		{
			bool flag = fileName.EndsWith("AppSourceCop.json", StringComparison.OrdinalIgnoreCase);
			bool flag2 = !flag && fileName.EndsWith(".ruleset.json", StringComparison.OrdinalIgnoreCase);
			if (!flag && !flag2)
			{
				return;
			}
			Solution currentSolution = base.Workspace.CurrentSolution;
			if (currentSolution == null)
			{
				return;
			}
			foreach (Project project in currentSolution.Projects)
			{
				bool flag3 = false;
				if (flag2 && !string.IsNullOrEmpty(project.RuleSetPath))
				{
					if (project.RuleSetPath.CreateUriFilePath().Equals(fileName, StringComparison.OrdinalIgnoreCase))
					{
						flag3 = true;
					}
				}
				else if (flag && project.AnalyzerReferences != null && project.AnalyzerReferences.Any((AnalyzerReference r) => "Microsoft.Dynamics.Nav.AppSourceCop.dll".Equals(Path.GetFileName(r.FullPath), StringComparison.OrdinalIgnoreCase)))
				{
					flag3 = true;
				}
				if (flag3)
				{
					ReloadProject(project, cancellationToken);
					base.Workspace.ForceProjectClosureDiagnosticsEmit(project.Id);
				}
			}
		}

		private Project GetProjectFromWorkspace(string folderPath)
		{
			if (string.IsNullOrEmpty(folderPath))
			{
				return null;
			}
			return base.Workspace.CurrentSolution.FindProject(folderPath);
		}
