	public class ExplorerService : IDisposable
	{
		private System.Timers.Timer refreshTimer;

		private VsCodeWorkspace Workspace { get; }

		private ResponseQueue ResponseQueue { get; }

		public ExplorerService(VsCodeWorkspace workspace, ResponseQueue responseQueue)
		{
			Workspace = workspace;
			ResponseQueue = responseQueue;
			refreshTimer = new System.Timers.Timer(System.TimeSpan.FromSeconds(1.0).TotalMilliseconds)
			{
				AutoReset = false
			};
			refreshTimer.Elapsed += OnRefreshTimerElapsed;
			Workspace.WorkspaceChanged += OnWorkspaceChanged;
		}

		public void Dispose()
		{
			Workspace.WorkspaceChanged -= OnWorkspaceChanged;
		}

		private void OnWorkspaceChanged(object sender, WorkspaceChangeEventArgs changeEvent)
		{
			if (changeEvent.Kind != WorkspaceChangeKind.ActiveDocumentChanged)
			{
				refreshTimer.Start();
			}
		}

		private void OnRefreshTimerElapsed(object source, ElapsedEventArgs e)
		{
			SendFreshObjectsEvent();
		}

		private void SendFreshObjectsEvent()
		{
			ResponseQueue.Add(ResponseFactory.RefreshExplorer());
		}
	}
