				{
					WorkspacePath = projectPath.GetFilePath()
				}, forceCheckDependencies: false, out projectLoadingDiagnostics, out missingSymbols);
				AddResponse(projectPath, null, projectManifest == null, missingSymbols, projectLoadingDiagnostics, cancellationToken);
				if (projectManifest != null && base.Workspace.GetCurrentProject().DocumentIds.Count != 0 && projectManifest.AppManifest.Dependencies != null)
