	public class HoverRequestHandler : RequestHandlerBase<HoverRequest>
	{
		public override string EndpointName => "textDocument/hover";

		internal HoverRequestHandler(VsCodeWorkspace workspace, ResponseQueue responseQueue)
			: base(workspace, (IResponseQueue)responseQueue)
		{
		}

		public override async Task HandleAsync(HoverRequest request, int requestId, CancellationToken cancellationToken)
		{
			Hover response = null;
			Document document = base.Workspace.GetDocument(request.TextDocument.FileName);
			if (document != null && base.Workspace.AreAllProjectReferencesBound(document))
			{
				LinePosition linePosition = new LinePosition(request.Position.Line, request.Position.Character);
				if (await document.IsPositionNotOnTokenTrivia(linePosition, cancellationToken))
				{
					ISymbol symbol = await document.GetSymbolAtPositionAsync(linePosition, cancellationToken);
					if (symbol != null)
					{
						MarkupContent markupContent = CreateContent(symbol, await document.GetSemanticModelAsync(cancellationToken), cancellationToken);
						if (!string.IsNullOrEmpty(markupContent.Value))
						{
							response = new Hover
							{
								Range = null,
								Contents = markupContent
							};
						}
					}
					if (response == null)
					{
						PropertySymbol propertySymbol = await document.GetPropertySymbolFromValueAtPositionAsync(linePosition, cancellationToken);
						if (propertySymbol != null)
						{
							MarkupContent markupContent2 = CreateContent(propertySymbol);
							if (!string.IsNullOrEmpty(markupContent2.Value))
							{
								response = new Hover
								{
									Range = null,
									Contents = markupContent2
								};
							}
						}
					}
				}
				if (response == null)
				{
					SyntaxNode syntaxNode = await document.GetKeywordNodeAtPositionAsync(linePosition, cancellationToken);
					if (syntaxNode != null)
					{
						string documentation = syntaxNode.GetDocumentation();
						if (!string.IsNullOrEmpty(documentation))
						{
							MarkupContent markupContent3 = CreateContent(documentation);
							if (!string.IsNullOrEmpty(markupContent3.Value))
							{
								response = new Hover
								{
									Range = null,
									Contents = markupContent3
								};
							}
						}
					}
				}
			}
			base.ResponseQueue.Add(ResponseFactory.Hover(response ?? new Hover(), requestId));
		}

		private static MarkupContent CreateContent(ISymbol symbol, SemanticModel semanticModel, CancellationToken cancellationToken)
		{
			string signature = symbol.ToDisplayString(GetDisplayTextFormatter(symbol), semanticModel);
			string documentationComment = symbol.GetDocumentationComment(cancellationToken);
			return CreateContent(MarkdownHelper.CreateSignature(signature, documentationComment));
		}

		private static SymbolDisplayFormat GetDisplayTextFormatter(ISymbol symbol)
		{
			if (symbol.Kind != SymbolKind.Method)
			{
				return SymbolDisplayFormat.HoverFormat;
			}
			return SymbolDisplayFormat.SimpleHoverFormat;
		}

		private static MarkupContent CreateContent(string docs)
		{
			return new MarkupContent
			{
				Kind = MarkupKind.Markdown,
				Value = docs
			};
		}

		private static MarkupContent CreateContent(PropertySymbol propertySymbol)
		{
			string propertyValueDocumentationFromSymbol = GetPropertyValueDocumentationFromSymbol(propertySymbol);
			return new MarkupContent
			{
				Kind = MarkupKind.Markdown,
				Value = propertyValueDocumentationFromSymbol
			};
		}

		private static string GetPropertyValueDocumentationFromSymbol(PropertySymbol propertySymbol)
		{
			if (propertySymbol.Value as OptionSymbol != null)
			{
				string valueText = propertySymbol.ValueText;
				string enumValuePropertyDetailText = propertySymbol.GetEnumValuePropertyDetailText(valueText);
				string enumValuePropertyDocumentation = propertySymbol.GetEnumValuePropertyDocumentation(valueText);
				return MarkdownHelper.CreateSignature(enumValuePropertyDetailText, enumValuePropertyDocumentation);
			}
			if (propertySymbol.Value is bool booleanValue)
			{
				return MarkdownHelper.CreateSignature(propertySymbol.GetBooleanValuePropertyDetailText(booleanValue), string.Empty);
			}
			if (propertySymbol.PropertyKind == PropertyKind.Image)
			{
				string valueText2 = propertySymbol.ValueText;
				string imageFromResources = GetImageFromResources(valueText2);
				string text = MarkdownHelper.CreateBase64Image(valueText2, imageFromResources);
				if (!string.IsNullOrEmpty(text))
				{
					return MarkdownHelper.CreateSignature(FormattableString.Invariant($"{valueText2} {propertySymbol.Name}"), text);
				}
			}
			return string.Empty;
		}

		private static string GetImageFromResources(string imageName)
		{
			return GetImageFromResource(imageName, ImageResources.GetActionCueGroupImageResources()) ?? GetImageFromResource(imageName, ImageResources.GetActionImageResources()) ?? GetImageFromResource(imageName, ImageResources.GetFieldCueGroupImageResources()) ?? GetImageFromResource(imageName, ImageResources.GetRoleCenterActionGroupImageResources()) ?? string.Empty;
		}

		private static string? GetImageFromResource(string imageName, IDictionary<string, string> dict)
		{
			if (dict.Keys.Contains(imageName))
			{
				return Uri.UnescapeDataString(dict[imageName]);
			}
			return null;
		}
	}
	public class ImplementationRequestHandler : RequestHandlerBase<ImplementationRequest>
	{
		private readonly ReferenceSymbolDefinitionManager referenceSymbolDefinitionManager;

		public override string EndpointName => "textDocument/implementation";

		public ImplementationRequestHandler(VsCodeWorkspace workspace, IResponseQueue responseQueue)
			: base(workspace, responseQueue)
		{
			referenceSymbolDefinitionManager = new ReferenceSymbolDefinitionManager(workspace);
			referenceSymbolDefinitionManager.AddLogger(new DebugConsoleLogger(base.ResponseQueue));
		}

		public override async Task HandleAsync(ImplementationRequest request, int requestId, CancellationToken cancellationToken)
		{
			List<Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.Contract.Location> response = new List<Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.Contract.Location>();
			Project currentProject = base.Workspace.GetCurrentProject();
			if (currentProject == null || !base.Workspace.AreAllProjectReferencesBound(currentProject.Id))
			{
				base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId), cancellationToken);
				return;
			}
			Document document = base.Workspace.GetDocument(request.TextDocument.FileName);
			if (base.Workspace.AreAllProjectReferencesBound(document))
			{
				SemanticModel semanticModel = await document.GetSemanticModelAsync(cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				LinePosition symbolPosition = new LinePosition(request.Position.Line, request.Position.Character);
				ISymbol symbol = await document.GetSymbolAtPositionAsync(symbolPosition, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				if (symbol != null)
				{
					if (symbol.Kind == SymbolKind.Interface)
					{
						InterfaceTypeSymbol interfaceType = (InterfaceTypeSymbol)symbol;
						foreach (IApplicationObjectTypeSymbol implementor in interfaceType.GetImplementors(semanticModel.Compilation))
						{
							Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.Contract.Location symbolLocation = Microsoft.Dynamics.Nav.EditorServices.Protocol.Utility.SymbolExtensions.GetSymbolLocation(implementor, currentProject.ProjectFolder);
							if (symbolLocation != null)
							{
								response.Add(symbolLocation);
							}
							else
							{
								response.Add(await referenceSymbolDefinitionManager.TryGetDefinitionFromReference(implementor, null, cancellationToken).ConfigureAwait(continueOnCapturedContext: false));
							}
						}
					}
					else if (symbol.Kind == SymbolKind.Method)
					{
						MethodSymbol searchMethod = (MethodSymbol)symbol;
						ISymbol containingSymbol = symbol.ContainingSymbol;
						if (containingSymbol != null)
						{
							if (containingSymbol.Kind == SymbolKind.Interface)
							{
								List<CodeunitTypeSymbol> list = (from s in ((InterfaceTypeSymbol)containingSymbol).GetImplementors(semanticModel.Compilation)
									where s.Kind == SymbolKind.Codeunit
									select s).OfType<CodeunitTypeSymbol>().ToList();
								foreach (CodeunitTypeSymbol item in list)
								{
									ImmutableArray<Symbol>.Enumerator enumerator3 = item.GetMembers(symbol.Name).GetEnumerator();
									while (enumerator3.MoveNext())
									{
										Symbol current3 = enumerator3.Current;
										if (current3.Kind != SymbolKind.Method)
										{
											continue;
										}
										MethodSymbol methodSymbol = (MethodSymbol)current3;
										if (methodSymbol.HasSameSignature(searchMethod))
										{
											Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.Contract.Location symbolLocation2 = Microsoft.Dynamics.Nav.EditorServices.Protocol.Utility.SymbolExtensions.GetSymbolLocation(methodSymbol, currentProject.ProjectFolder);
											if (symbolLocation2 != null)
											{
												response.Add(symbolLocation2);
											}
											else
											{
												response.Add(await referenceSymbolDefinitionManager.TryGetDefinitionFromReference(methodSymbol, null, cancellationToken).ConfigureAwait(continueOnCapturedContext: false));
											}
										}
									}
								}
							}
							else if (containingSymbol.Kind == SymbolKind.Codeunit)
							{
								CodeunitTypeSymbol obj = (CodeunitTypeSymbol)containingSymbol;
								List<InterfaceTypeSymbol> list2 = new List<InterfaceTypeSymbol>();
								ImmutableArray<InterfaceTypeSymbol>.Enumerator enumerator4 = obj.ImplementedInterfaces.GetEnumerator();
								while (enumerator4.MoveNext())
								{
									InterfaceTypeSymbol current4 = enumerator4.Current;
									if (current4.IsUnresolvedInterface())
									{
										continue;
									}
									ImmutableArray<Symbol>.Enumerator enumerator5 = current4.GetMembers(searchMethod.Name).GetEnumerator();
									while (enumerator5.MoveNext())
									{
										Symbol current5 = enumerator5.Current;
										if (current5.Kind == SymbolKind.Method)
										{
											MethodSymbol methodSymbol2 = (MethodSymbol)current5;
											if (searchMethod.HasSameSignature(methodSymbol2))
											{
												list2.Add(current4);
											}
										}
									}
								}
								IEnumerable<IGrouping<int, CodeunitTypeSymbol>> enumerable = from i in list2.Select((InterfaceTypeSymbol i) => i.GetImplementors(semanticModel.Compilation).OfType<CodeunitTypeSymbol>()).SelectMany((IEnumerable<CodeunitTypeSymbol> i) => i)
									group i by i.Id;
								foreach (IGrouping<int, CodeunitTypeSymbol> item2 in enumerable)
								{
									CodeunitTypeSymbol codeunitTypeSymbol = item2.First();
									ImmutableArray<Symbol>.Enumerator enumerator3 = codeunitTypeSymbol.GetMembers(searchMethod.Name).GetEnumerator();
									while (enumerator3.MoveNext())
									{
										Symbol current6 = enumerator3.Current;
										if (current6.Kind != SymbolKind.Method)
										{
											continue;
										}
										MethodSymbol methodSymbol3 = (MethodSymbol)current6;
										if (!searchMethod.HasSameSignature(methodSymbol3))
										{
											continue;
										}
										Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.Contract.Location symbolLocation3 = Microsoft.Dynamics.Nav.EditorServices.Protocol.Utility.SymbolExtensions.GetSymbolLocation(methodSymbol3, currentProject.ProjectFolder);
										if (symbolLocation3 != null)
										{
											response.Add(symbolLocation3);
											continue;
										}
										Definition definition = await referenceSymbolDefinitionManager.TryGetDefinitionFromReference(methodSymbol3, null, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
										if (definition != null)
										{
											response.Add(definition);
										}
									}
								}
							}
							else
							{
								response.Add(await GetDefinitionResponseForSymbol(requestId, symbol, request.Position, null, cancellationToken).ConfigureAwait(continueOnCapturedContext: false));
							}
						}
					}
					else
					{
						response.Add(await GetDefinitionResponseForSymbol(requestId, symbol, request.Position, null, cancellationToken).ConfigureAwait(continueOnCapturedContext: false));
					}
				}
			}
			base.ResponseQueue.Add(ResponseFactory.Implementation(requestId, response), cancellationToken);
		}

		private async Task<Definition?> GetDefinitionResponseForSymbol(int requestId, ISymbol symbol, Position? requestPosition, LaunchConfiguration launchConfiguration, CancellationToken cancellationToken)
		{
			Definition definition = new Definition();
			if (symbol.Location == null || !symbol.Location.IsInSource)
			{
				definition = await referenceSymbolDefinitionManager.TryGetDefinitionFromReference(symbol, launchConfiguration, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				if (definition == null)
				{
					return null;
				}
			}
			else
			{
				if (requestPosition != null && symbol.IsPositionOnTheLocationOfApplicationObjectReference(requestPosition))
				{
					return await GetDefinitionResponseForSymbol(requestId, symbol.GetTypeSymbol()?.OriginalDefinition, requestPosition, launchConfiguration, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				}
				if (!TryGetDefinitionFromSource(symbol.Location, ref definition))
				{
					return null;
				}
			}
			return definition;
		}

		private bool TryGetDefinitionFromSource(Microsoft.Dynamics.Nav.CodeAnalysis.Text.Location location, ref Definition definition)
		{
			Document document = base.Workspace.CurrentSolution.GetDocument(location.SourceTree);
			if (document == null)
			{
				return false;
			}
			FileLinePositionSpan mappedLineSpan = location.GetMappedLineSpan();
			definition = new Definition
			{
				Uri = document.FilePath.GetUri(),
				Range = new Range
				{
					Start = new Position
					{
						Line = mappedLineSpan.StartLinePosition.Line,
						Character = mappedLineSpan.StartLinePosition.Character
					},
					End = new Position
					{
						Line = mappedLineSpan.EndLinePosition.Line,
						Character = mappedLineSpan.EndLinePosition.Character
					}
				}
			};
			return true;
		}
	}
