	public class InlayHintRequestHandler : RequestHandlerBase<InlayHintRequest>
	{
		public InlayHintOptions InlayHintOptions { get; }

		public override string EndpointName => "textDocument/inlayHint";

		public InlayHintRequestHandler(VsCodeWorkspace workspace, IResponseQueue responseQueue, InlayHintOptions inlayHintOptions)
			: base(workspace, responseQueue)
		{
			InlayHintOptions = inlayHintOptions;
		}

		public override async Task HandleAsync(InlayHintRequest request, int requestId, CancellationToken cancellationToken)
		{
			Document document = base.Workspace.GetDocument(request.TextDocument.FileName);
			if (document == null || !base.Workspace.AreAllProjectReferencesBound(document))
			{
				base.ResponseQueue.Add(ResponseFactory.InlayHint(requestId, null), cancellationToken);
				return;
			}
			List<InlayHint> data = await GetInlayHints(document, request.Range, cancellationToken);
			base.ResponseQueue.Add(ResponseFactory.InlayHint(requestId, data), cancellationToken);
		}

		private async Task<List<InlayHint>?> GetInlayHints(Document document, Range? range, CancellationToken cancellationToken)
		{
			SourceText sourceText = await document.GetTextAsync(cancellationToken);
			TextSpan? textSpan = GetTextSpan(sourceText, range);
			SemanticModel semanticModel = await document.GetSemanticModelAsync(cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
			SyntaxNode node = await document.GetSyntaxRootAsync(cancellationToken);
			HashSet<BoundCall> hashSet = new HashSet<BoundCall>();
			InlayHintBoundVisitor boundVisitor = new InlayHintBoundVisitor(hashSet, InlayHintOptions);
			new InlayHintSyntaxVisitor(semanticModel, boundVisitor, textSpan).Visit(node);
			List<InlayHint> list = null;
			if (hashSet.Count > 0)
			{
				list = new List<InlayHint>(hashSet.Count);
				foreach (BoundCall item3 in hashSet)
				{
					if (textSpan.HasValue && !item3.Syntax.Span.OverlapsWith(textSpan.Value))
					{
						continue;
					}
					if (InlayHintOptions.ParameterNamesEnabled)
					{
						ImmutableArray<BoundExpression> arguments = item3.Arguments;
						ImmutableArray<ParameterSymbol> parameters = item3.EffectiveParameters.Parameters;
						for (int i = 0; i < arguments.Length; i++)
						{
							BoundExpression boundExpression = arguments[i];
							ParameterSymbol parameterSymbol = parameters[i];
							InlayHint item = new InlayHint
							{
								Kind = InlayHintKind.Parameter,
								Label = parameterSymbol.Name + ":",
								Position = sourceText.Lines.GetLinePosition(boundExpression.Syntax.Span.Start),
								PaddingRight = true,
								Tooltip = CreateContent(parameterSymbol, semanticModel)
							};
							list.Add(item);
						}
					}
					TypeSymbol returnType = item3.Method.ReturnType;
					if (InlayHintOptions.ReturnTypesEnabled && returnType != null && returnType.NavTypeKind != 0)
					{
						InlayHint item2 = new InlayHint
						{
							Kind = InlayHintKind.Type,
							Label = ":" + returnType.ToDisplayString(SymbolDisplayFormat.ShortFormat),
							Position = sourceText.Lines.GetLinePosition(item3.Syntax.Span.End),
							PaddingLeft = true,
							Tooltip = CreateContent(returnType, semanticModel)
						};
						list.Add(item2);
					}
				}
			}
			return list;
		}

		private static MarkupContent CreateContent(ISymbol symbol, SemanticModel semanticModel, CancellationToken cancellationToken = default(CancellationToken))
		{
			string signature = symbol.ToDisplayString(SymbolDisplayFormat.HoverFormat, semanticModel);
			string documentationComment = symbol.GetDocumentationComment(cancellationToken);
			string value = MarkdownHelper.CreateSignature(signature, documentationComment);
			return new MarkupContent
			{
				Kind = MarkupKind.Markdown,
				Value = value
			};
		}

		private static TextSpan? GetTextSpan(SourceText? sourceText, Range? range)
		{
			if (sourceText == null || !range.HasValue || range.Value.Start == null || range.Value.End == null)
			{
				return null;
			}
			int position = sourceText.Lines.GetPosition(new LinePosition(range.Value.Start.Line, range.Value.Start.Character));
			int position2 = sourceText.Lines.GetPosition(new LinePosition(range.Value.End.Line, range.Value.End.Character));
			return new TextSpan(position, position2 - position);
		}
	}
