	internal class LanguageServerCompiler : NavCompiler
	{
		private readonly Lazy<ImmutableArray<DiagnosticAnalyzer>> analyzerReferences;

		private readonly ISymbolReferenceLoader referenceLoader;

		private readonly IDotNetResolverFactory dotNetResolverFactory;

		private readonly VsCodeWorkspace? workspace;

		private readonly ProjectId? builtProjectId;

		protected override bool IncrementialBuild => false;

		protected Compilation PreviousCompilation { get; }

		private static IEnumerable<string> BuildArguments(IEnumerable<string> args, string rulesetPath, string? outFolder, bool externalRulesetsEnabled, bool printFullPaths)
		{
			if (!string.IsNullOrEmpty(rulesetPath))
			{
				args = args.Concat(string.Format(CultureInfo.InvariantCulture, "-ruleset:\"{0}\"", rulesetPath));
			}
			if (!string.IsNullOrEmpty(outFolder))
			{
				args = args.Concat(string.Format(CultureInfo.InvariantCulture, "-outfolder:{0}", outFolder));
			}
			if (externalRulesetsEnabled)
			{
				args = args.Concat("-enableexternalrulesets");
			}
			if (printFullPaths)
			{
				args = args.Concat("-fullpaths");
			}
			return args;
		}

		internal LanguageServerCompiler(Compilation previousCompilation, string projectDirectory, IEnumerable<string> args, IEnumerable<AnalyzerReference> analyzerReferences, string ruleSetPath, string? outFolder, bool externalRulesetsEnabled, IFileSystem fileSystem = null, VsCodeWorkspace workspace = null, ProjectId projectId = null)
		{
			IEnumerable<AnalyzerReference> analyzerReferences2 = analyzerReferences;
			base..ctor(CommandLineParser.Default, Path.Combine(Microsoft.Dynamics.Nav.CodeAnalysis.Utilities.AppContextUtility.GetBaseDirectory(), "alc.rsp"), BuildArguments(args, ruleSetPath, outFolder, externalRulesetsEnabled, printFullPaths: true), Microsoft.Dynamics.Nav.CodeAnalysis.Utilities.AppContextUtility.GetBaseDirectory(), projectDirectory, string.Empty, string.Empty, null, fileSystem);
			PreviousCompilation = previousCompilation;
			referenceLoader = previousCompilation.ReferenceLoader;
			this.analyzerReferences = new Lazy<ImmutableArray<DiagnosticAnalyzer>>(() => analyzerReferences2.SelectMany((AnalyzerReference x) => x.GetAnalyzers()).ToImmutableArray());
			dotNetResolverFactory = previousCompilation.DotNetResolverFactory;
			this.workspace = workspace;
			builtProjectId = projectId;
		}

		protected override PackageModuleOutputterBase CreatePackageModuleOutputter(NavAppPackageWriter packageWriter, Compilation compilation)
		{
			return base.CreatePackageModuleOutputter(packageWriter, compilation);
		}

		protected override Compilation AddSymbolReferences(Compilation compilation, ProjectManifest manifest, List<DiagnosticInfo> diagnostics)
		{
			compilation = compilation.AddReferences(manifest.GetAllReferences()).WithReferenceLoader(referenceLoader);
			if (workspace != null && builtProjectId != null)
			{
				Solution currentSolution = workspace.CurrentSolution;
				Project project = currentSolution.GetProject(builtProjectId);
				if (project != null && project.ProjectReferences.Any())
				{
					compilation = compilation.WithReferenceManager(new ProjectReferencesReferenceManager(currentSolution, builtProjectId, compilation.ReferenceManager?.DelegatingResolver));
				}
			}
			return compilation;
		}

		protected override ImmutableArray<DiagnosticAnalyzer> ResolveAnalyzersFromArguments(IList<DiagnosticInfo> diagnostics, CommonMessageProvider messageProvider)
		{
			return analyzerReferences.Value;
		}

		protected override IDotNetResolverFactory GetDotNetResolverFactory()
		{
			return dotNetResolverFactory ?? base.GetDotNetResolverFactory();
		}
	}
	internal class LanguageServerInitializeRequestHandler : ProjectRequestHandler<LanguageServerInitializeRequest>
	{
		public ExtensionOptions ExtensionOptions { get; }

		public override string EndpointName => "initialize";

		internal LanguageServerInitializeRequestHandler(VsCodeWorkspace workspace, ResponseQueue responseQueue, ExtensionOptions extensionOptions)
			: base(workspace, responseQueue)
		{
			ExtensionOptions = extensionOptions;
		}

		public override Task HandleAsync(LanguageServerInitializeRequest request, int requestId, CancellationToken cancellationToken)
		{
			try
			{
				ClearServerInfoCache();
				if (request.Capabilities?.TextDocument?.SemanticTokens?.TokenTypes != null)
				{
					request.Capabilities.TextDocument.SemanticTokens.TokenTypes.AddRange(SemanticTokenTypeNames.AllCustomScopes);
					base.Workspace.ClassificationConverter = ClassificationToSemanticTokensConverter.Create(request.Capabilities.TextDocument.SemanticTokens);
				}
				LanguageServerInitializeResult result = CreateLanguageServerInitializeResult(request);
				base.ResponseQueue.Add(ResponseFactory.LanguageServerInitialize(result, requestId), cancellationToken);
			}
			catch (Exception ex)
			{
				LoggingUtilities.WriteMessageFailedException(requestId.ToString(CultureInfo.InvariantCulture), ex);
				base.ResponseQueue.Add(new Response
				{
					Error = new MessageError<LanguageServerInitializeError>
					{
						Code = MessageErrorCode.InternalError,
						Message = ex.Message,
						Data = new LanguageServerInitializeError
						{
							Retry = true
						}
					},
					MessageKind = MessageKind.Response,
					Method = "initialize",
					RequestId = requestId
				}, cancellationToken);
			}
			return Task.CompletedTask;
		}

		private void ClearServerInfoCache()
		{
			UserProtectedFileStorage.CreateServerInfoCache(new OutputConsoleLogger(base.ResponseQueue)).Clear();
		}

		private LanguageServerInitializeResult CreateLanguageServerInitializeResult(LanguageServerInitializeRequest request)
		{
			LanguageServerInitializeResult languageServerInitializeResult = new LanguageServerInitializeResult();
			languageServerInitializeResult.Capabilities = new Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.Contract.ServerCapabilities
			{
				TextDocumentSync = TextDocumentSyncKind.Incremental,
				DefinitionProvider = false,
				ReferencesProvider = true,
				DocumentHighlightProvider = true,
				DocumentSymbolProvider = true,
				WorkspaceSymbolProvider = new WorkspaceSymbolOptions
				{
					ResolveProvider = (ExtensionOptions.ExtendGoToSymbolInWorkspace?.Enabled ?? false)
				},
				CodeActionProvider = true,
				HoverProvider = true,
				RenameProvider = true,
				CompletionProvider = new Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.Contract.CompletionOptions
				{
					ResolveProvider = false,
					TriggerCharacters = new string[5] { ".", ":", "\"", "/", "<" }
				},
				SignatureHelpProvider = new SignatureHelpOptions
				{
					TriggerCharacters = new string[1] { "(" }
				},
				CodeLensProvider = new CodeLensOptions
				{
					ResolveProvider = true
				},
				DocumentFormattingProvider = true,
				DocumentRangeFormattingProvider = true,
				Workspace = new WorkspaceFolderCapabilities
				{
					Supported = true,
					ChangeNotifications = true
				},
				ExecuteCommandProvider = new ExecuteCommandOptions
				{
					Commands = new string[1] { "al/runCodeAction" }
				},
				SemanticTokensProvider = new SemanticTokensOptions
				{
					Range = true,
					Full = true,
					Legend = new SemanticTokensLegend(request.Capabilities.TextDocument?.SemanticTokens)
				},
				FoldingRangeProvider = ExtensionOptions.FoldingEnabled,
				ImplementationProvider = true,
				TypeHierarchyProvider = true,
				InlayHintProvider = (ExtensionOptions.InlayHintOptions?.ShouldProvideInlayHints() ?? false)
			};
			return languageServerInitializeResult;
		}
	}
