	internal class PrepareTypeHierarchyRequestHandler : RequestHandlerBase<TypeHierarchyPrepareRequest>
	{
		public override string EndpointName => "textDocument/prepareTypeHierarchy";

		public PrepareTypeHierarchyRequestHandler(VsCodeWorkspace workspace, IResponseQueue responseQueue)
			: base(workspace, responseQueue)
		{
		}

		public override async Task HandleAsync(TypeHierarchyPrepareRequest request, int requestId, CancellationToken cancellationToken)
		{
			Document document = base.Workspace.GetDocument(request.TextDocument.FileName);
			if (document == null)
			{
				base.ResponseQueue.Add(ResponseFactory.TypeHierarchy(requestId, null), cancellationToken);
				return;
			}
			if (!base.Workspace.AreAllProjectReferencesBound(document))
			{
				RegisterDelayedRequest(document.Project.Id, request, requestId);
				return;
			}
			int position = (await document.GetTextAsync(cancellationToken)).Lines.GetPosition(new LinePosition(request.Position.Line, request.Position.Character));
			Symbol symbol = (await SymbolFinder.FindSymbolAtPositionAsync(document, position, cancellationToken)) as Symbol;
			if (symbol == null)
			{
				base.ResponseQueue.Add(ResponseFactory.TypeHierarchy(requestId, null), cancellationToken);
				return;
			}
			List<TypeHierarchyItem> data = new List<TypeHierarchyItem> { TypeHierarchyHelper.CreateTypeHierarchyItem(symbol, document.Project) };
			base.ResponseQueue.Add(ResponseFactory.TypeHierarchy(requestId, data), cancellationToken);
		}
	}
	public abstract class ProjectRequestHandler<TRequestHandler> : RequestHandlerBase<TRequestHandler> where TRequestHandler : IRequest
	{
		internal ProjectRequestHandler(VsCodeWorkspace workspace, ResponseQueue responseQueue)
			: base(workspace, (IResponseQueue)responseQueue)
		{
		}

		internal bool TryAddOrUpdateProject(SettingsRequest request, CancellationToken cancellationToken, out ProjectManifest? manifest)
		{
			manifest = null;
			if (request == null || request.Settings == null)
			{
				return false;
			}
			ProjectId projectId = null;
			try
			{
				if (!request.Settings.SetActiveWorkspace)
				{
					projectId = base.Workspace.CurrentProjectId;
				}
				IList<Diagnostic> diagnostics;
				bool missingSymbols;
				bool num = base.Workspace.TryAddOrUpdateProject(request.Settings, out diagnostics, out manifest, out missingSymbols);
				AddResponse(request.Settings.WorkspacePath, request.Settings.GetRuleSetPath(), manifest == null, missingSymbols, diagnostics, cancellationToken);
				if (num)
				{
					if (request.Settings.SetActiveWorkspace)
					{
						base.Workspace.ScheduleProjectLoadListenerTask(request.Settings.ActiveWorkspaceClosure);
					}
					else
					{
						base.Workspace.CheckForClosureLoaded(projectId);
					}
				}
				return num;
			}
			catch (InvalidOperationException ex)
			{
				base.ResponseQueue.AddDiagnosticResponse(new List<Diagnostic> { Diagnostic.Create(MessageProvider.Instance, 1077, ex.Message) }, request.Settings?.WorkspacePath, request.Settings?.GetRuleSetPath(), cancellationToken);
				return false;
			}
			finally
			{
				if (projectId != null)
				{
					base.Workspace.SetCurrentProjectId(projectId);
				}
			}
		}

		protected void AddResponse(string? projectPath, string? ruleSetPath, bool missingManifest, bool missingSymbol, IList<Diagnostic> diagnostics, CancellationToken cancellationToken)
		{
			if (!string.IsNullOrEmpty(projectPath))
			{
				string uriOfManifestFile = GetUriOfManifestFile(projectPath);
				string ruleSetPath2 = (RulesetUtilities.IsRemotePath(ruleSetPath) ? uriOfManifestFile : ruleSetPath?.GetUri()) ?? string.Empty;
				base.ResponseQueue.AddDiagnosticResponse(diagnostics, uriOfManifestFile, ruleSetPath2, cancellationToken);
			}
			if (missingManifest && base.Workspace.GetCurrentProject().DocumentIds.Count != 0)
			{
				base.ResponseQueue.Add(ResponseFactory.CreateManifestMissingEvent(), cancellationToken);
			}
			else if (missingSymbol)
			{
				base.ResponseQueue.Add(ResponseFactory.CreateSymbolsMissingEvent(), cancellationToken);
			}
		}

		protected static string? GetUriOfManifestFile(string? projectPath)
		{
			if (!string.IsNullOrEmpty(projectPath))
			{
				return projectPath.GetUri() + "/app.json";
			}
			return null;
		}
	}
	internal class RadLanguageServerCompiler : LanguageServerCompiler
	{
		private readonly IObjectChangeManager applicationObjectChangeManager;

		private readonly Predicate<ISymbol> radCompilationFilter;

		internal RadLanguageServerCompiler(IObjectChangeManager applicationObjectChangeManager, Compilation previousCompilation, string projectDirectory, IEnumerable<string> args, IEnumerable<AnalyzerReference> analyzerReferences, string ruleSetPath, string? outFolder, bool externalRulesetsEnabled, IFileSystem fileSystem = null)
			: base(previousCompilation, projectDirectory, args, analyzerReferences, ruleSetPath, outFolder, externalRulesetsEnabled, fileSystem)
		{
			this.applicationObjectChangeManager = applicationObjectChangeManager;
			radCompilationFilter = ShouldMethodCompileApplicationObject;
		}

		public override Compilation GetOrCreateCompilation(CompilerTextWriter consoleOutput, CompilationOptions compilationOptions, ErrorLogger errorLogger)
		{
			return base.PreviousCompilation;
		}

		protected internal override (NavAppPackageWriter Writer, Stream PackageStream) CreateNavAppPackageWriterAndStream(string outputFilePath, CompilerTextWriter consoleOutput)
		{
			if (!base.FileSystem.Exists(outputFilePath))
			{
				if (consoleOutput != null)
				{
					DiagnosticInfo diagnosticInfo = new DiagnosticInfo(base.MessageProvider, 1050, outputFilePath);
					consoleOutput.WriteDiagnostic(diagnosticInfo.Severity, diagnosticInfo.ToString(Culture));
				}
				return (Writer: null, PackageStream: null);
			}
			NavAppManifest navAppManifest = null;
			using (Stream stream = OpenFile(outputFilePath, consoleOutput, FileMode.Open, FileAccess.Read, FileShare.Read))
			{
				if (stream == null)
				{
					return (Writer: null, PackageStream: null);
				}
				NavAppPackageReader navAppPackageReader = null;
				try
				{
					navAppPackageReader = NavAppPackageReader.Create(stream, leaveOpen: false, outputFilePath);
					navAppManifest = navAppPackageReader.ReadNavAppManifest();
				}
				catch (InvalidOperationException e)
				{
					LoggingUtilities.WriteMessageFailedException(string.Format(CultureInfo.InvariantCulture, "Rad building failed. We require an existing app, but the one provided in '{0}' did not have a manifest.", outputFilePath), e);
				}
				finally
				{
					navAppPackageReader?.Dispose();
				}
			}
			if (navAppManifest == null)
			{
				if (consoleOutput != null)
				{
					DiagnosticInfo diagnosticInfo2 = new DiagnosticInfo(base.MessageProvider, 565, outputFilePath);
					consoleOutput.WriteDiagnostic(diagnosticInfo2.Severity, diagnosticInfo2.ToString(Culture));
				}
				return (Writer: null, PackageStream: null);
			}
			if (!navAppManifest.AppName.Equals(ProjectManifest.AppManifest.AppName, StringComparison.OrdinalIgnoreCase) || navAppManifest.AppVersion != ProjectManifest.AppManifest.AppVersion || !navAppManifest.AppPublisher.Equals(ProjectManifest.AppManifest.AppPublisher, StringComparison.OrdinalIgnoreCase))
			{
				if (consoleOutput != null)
				{
					DiagnosticInfo diagnosticInfo3 = new DiagnosticInfo(base.MessageProvider, 1051, Path.GetFileName(outputFilePath));
					consoleOutput.WriteDiagnostic(diagnosticInfo3.Severity, diagnosticInfo3.ToString(Culture));
				}
				return (Writer: null, PackageStream: null);
			}
			return base.CreateNavAppPackageWriterAndStream(outputFilePath, consoleOutput);
		}

		protected override PackageModuleOutputterBase CreatePackageModuleOutputter(NavAppPackageWriter packageWriter, Compilation compilation)
		{
			EmitOptions options = base.CreateEmitOptions(compilation.Options);
			return new RadPackageModuleOutputter(applicationObjectChangeManager, ProjectManifest.AppManifest, compilation, options, base.BaseDirectory, packageWriter);
		}

		protected override int RunCoreImpl(CompilerTextWriter consoleOutput, ErrorLogger errorLogger, Compilation compilation, AnalyzerDriver analyzerDriver, IEnumerable<Diagnostic> analyzerExceptionDiagnostics, IEnumerable<AdditionalTextFile> additionalTextFiles, CancellationToken cancellationToken)
		{
			if (base.PreviousCompilation == null)
			{
				return base.RunCoreImpl(consoleOutput, errorLogger, compilation, analyzerDriver, analyzerExceptionDiagnostics, additionalTextFiles, cancellationToken);
			}
			cancellationToken.ThrowIfCancellationRequested();
			ImmutableArray<Diagnostic> immutableArray = base.PreviousCompilation.GetDeclarationDiagnostics(cancellationToken);
			if (!immutableArray.HasAnyErrors())
			{
				immutableArray = ValidateObjectChangesAgainstSymbols();
			}
			if (ReportErrors(immutableArray, consoleOutput, errorLogger, compilation.Options))
			{
				return 1;
			}
			if (ReportErrors(analyzerExceptionDiagnostics, consoleOutput, errorLogger, compilation.Options))
			{
				return 1;
			}
			cancellationToken.ThrowIfCancellationRequested();
			return PackageTheModule(compilation, consoleOutput, cancellationToken, errorLogger, analyzerDriver, null, radCompilationFilter);
		}

		private ImmutableArray<Diagnostic> ValidateObjectChangesAgainstSymbols()
		{
			DiagnosticBag instance = DiagnosticBag.GetInstance();
			foreach (ObjectChangeContext change in applicationObjectChangeManager.Changes)
			{
				Symbol symbol = base.PreviousCompilation.CompiledModule.GetSymbol(change.ObjectChangeElement);
				ErrorCode errorCode = ErrorCode.None;
				switch (change.State)
				{
				case ObjectChangeState.Modified:
				case ObjectChangeState.Added:
					if (symbol == null)
					{
						errorCode = ErrorCode.ERR_ObjectChangeNotFoundInCompilation;
					}
					break;
				case ObjectChangeState.Removed:
					if (symbol != null)
					{
						errorCode = ErrorCode.ERR_DeletedObjectChangeFoundInCompilation;
					}
					break;
				}
				if (errorCode != 0)
				{
					instance.Add(errorCode, Microsoft.Dynamics.Nav.CodeAnalysis.Text.Location.None, change.ObjectChangeElement.Kind, change.ObjectChangeElement.Name, (!change.ObjectChangeElement.Id.HasValue) ? string.Empty : change.ObjectChangeElement.Id.Value.ToString(CultureInfo.InvariantCulture));
				}
			}
			return instance.ToReadOnlyAndFree();
		}

		private bool ShouldMethodCompileApplicationObject(ISymbol symbol)
		{
			if (symbol == null)
			{
				return false;
			}
			if (!symbol.Kind.IsRootObjectTypeSymbol())
			{
				return true;
			}
			IObjectTypeSymbol symbol2 = (IObjectTypeSymbol)symbol;
			return applicationObjectChangeManager.ContainsSymbol(symbol2);
		}
	}
	public enum ReferenceSourceKind
	{
		Undefined,
		Source,
		Metadata,
		CALSource
	}
	public class ReferencesRequestHandler : RequestHandlerBase<ReferencesRequest>
	{
		public override string EndpointName => "textDocument/references";

		internal ReferencesRequestHandler(VsCodeWorkspace workspace, ResponseQueue responseQueue)
			: base(workspace, (IResponseQueue)responseQueue)
		{
		}

		public override async Task HandleAsync(ReferencesRequest request, int requestId, CancellationToken cancellationToken)
		{
			Document document = base.Workspace.GetDocument(request.TextDocument.FileName);
			ArrayBuilder<Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.Contract.Location> builder = ArrayBuilder<Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.Contract.Location>.GetInstance();
			if (document != null)
			{
				if (!base.Workspace.AreAllProjectReferencesBound(document))
				{
					RegisterDelayedRequest(document.Project.Id, request, requestId);
					return;
				}
				IFindReferencesService findReferences = document.GetLanguageService<IFindReferencesService>();
				int position = (await document.GetTextAsync(cancellationToken).ConfigureAwait(continueOnCapturedContext: false)).Lines.GetPosition(new LinePosition(request.Position.Line, request.Position.Character));
				foreach (ReferencedSymbol item in findReferences.FindReferencedSymbolsAsync(document, position, cancellationToken))
				{
					foreach (ReferenceLocation location in item.Locations)
					{
						builder.Add(new Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.Contract.Location
						{
							Uri = location.Document.FilePath.GetUri(),
							Range = location.Location
						});
					}
				}
			}
			base.ResponseQueue.Add(ResponseFactory.References(builder.ToArrayAndFree(), requestId), cancellationToken);
		}
	}
	internal class ReferenceSymbolDefinitionManager
	{
		private class ReferenceSymbolContentProvider : IReferenceSymbolContentProvider
		{
			private readonly VsCodeWorkspace workspace;

			private readonly ConcurrentDictionary<IObjectTypeSymbol, (string? Content, ReferenceSourceKind Kind)> sourceContent = new ConcurrentDictionary<IObjectTypeSymbol, (string, ReferenceSourceKind)>();

			public IEmitLogger? Logger { get; set; }

			public ReferenceSymbolContentProvider(VsCodeWorkspace workspace)
			{
				this.workspace = workspace;
				Logger = new VoidLogger();
			}

			public (string Content, ReferenceSourceKind Kind) GetContent(IObjectTypeSymbol symbol)
			{
				sourceContent.TryGetValue(symbol, out (string, ReferenceSourceKind) value);
				return value;
			}

			public void ClearContent()
			{
				sourceContent.Clear();
			}

			public string? CreateMetadataContent(IObjectTypeSymbol symbol)
			{
				if (sourceContent.TryGetValue(symbol, out (string, ReferenceSourceKind) value2) && value2.Item2 == ReferenceSourceKind.Metadata)
				{
					return value2.Item1;
				}
				string text = ReferenceSymbolToSyntax.ConvertToCompilationUnitSyntax(symbol, null, ConvertOptions.NoMethodsOrTriggers)?.NormalizeWhiteSpace().ToString();
				sourceContent.AddOrUpdate(symbol, (text, ReferenceSourceKind.Metadata), (IObjectTypeSymbol key, (string? Content, ReferenceSourceKind Kind) value) => value);
				return text;
			}

			public async Task<(string? Content, ReferenceSourceKind Kind)> CreateSourceContent(IObjectTypeSymbol symbol, LaunchConfiguration? configuration)
			{
				if (configuration == null)
				{
					return (Content: CreateSourceContentFromApplicationFile(symbol), Kind: ReferenceSourceKind.Source);
				}
				return await CreateSourceContentByDownloadingSource(symbol, configuration).ConfigureAwait(continueOnCapturedContext: false);
			}

			private async Task<(string? Content, ReferenceSourceKind Kind)> CreateSourceContentByDownloadingSource(IObjectTypeSymbol symbol, LaunchConfiguration config)
			{
				DebugAssertHelper.Assert(Logger != null);
				if (config == null || symbol == null)
				{
					return (Content: null, Kind: ReferenceSourceKind.Undefined);
				}
				ConnectionOptions connectionOptions = config.CreateConnectionOptions();
				try
				{
					ServerInfo serverInfo = await ServerRegistry.DevInstance.GetServerInfo(connectionOptions, Logger).ConfigureAwait(continueOnCapturedContext: false);
					if (serverInfo == null || !serverInfo.Supports(DevApiFeature.GetSourceCode))
					{
						return (Content: null, Kind: ReferenceSourceKind.Undefined);
					}
					ObjectTypeWrapper? objectTypeWrapper = DebugHelper.MapToObjectType(symbol.Kind);
					if (!objectTypeWrapper.HasValue)
					{
						return (Content: null, Kind: ReferenceSourceKind.Undefined);
					}
					string value2 = await new SourceContentApiClient(connectionOptions, Logger).GetSource((int)objectTypeWrapper.Value, symbol.GetIdOrDefault());
					if (string.IsNullOrEmpty(value2))
					{
						return (Content: null, Kind: ReferenceSourceKind.Undefined);
					}
					SourceContent sourceContent = JsonConvert.DeserializeObject<SourceContent>(value2);
					if (sourceContent != null)
					{
						this.sourceContent.AddOrUpdate(symbol, (sourceContent.Content, sourceContent.IsALContent ? ReferenceSourceKind.Source : ReferenceSourceKind.CALSource), (IObjectTypeSymbol key, (string? Content, ReferenceSourceKind Kind) value) => value);
						return (Content: sourceContent.Content, Kind: sourceContent.IsALContent ? ReferenceSourceKind.Source : ReferenceSourceKind.CALSource);
					}
					return (Content: null, Kind: ReferenceSourceKind.Undefined);
				}
				catch (HttpRequestException)
				{
					return (Content: null, Kind: ReferenceSourceKind.Undefined);
				}
			}

			private string CreateSourceContentFromApplicationFile(IObjectTypeSymbol symbol)
			{
				DebugAssertHelper.Assert(Logger != null);
				if (symbol == null)
				{
					return null;
				}
				if (symbol.Location == null || symbol.Location.Kind != LocationKind.ReferenceSourceFile)
				{
					return null;
				}
				if (sourceContent.TryGetValue(symbol, out (string, ReferenceSourceKind) value2) && value2.Item2 == ReferenceSourceKind.Source)
				{
					return value2.Item1;
				}
				Project currentProject = workspace.GetCurrentProject();
				if (currentProject == null || currentProject.PackageCachePaths.Count == 0)
				{
					return null;
				}
				PooledList<Diagnostic> instance = PooledList<Diagnostic>.GetInstance();
				try
				{
					ReferenceSourceFileLocation referenceSourceFileLocation = (ReferenceSourceFileLocation)symbol.Location;
					NavAppManifest matchingManifest;
					string text = new LocalCacheSymbolReferenceAnalyzer(currentProject.PackageCachePaths).FindMatchingPackageFile(referenceSourceFileLocation.SymbolReferenceSpecification, instance, out matchingManifest);
					if (matchingManifest == null || string.IsNullOrEmpty(text))
					{
						return null;
					}
					try
					{
						using (FileStream stream = File.OpenRead(text))
						{
							using NavAppPackageReader navAppPackageReader = NavAppPackageReader.Create(stream, leaveOpen: false, text);
							string fileName = (navAppPackageReader.IsRuntimePackage ? RuntimePackageModuleOutputter.CreateRuntimeSourceCodeFileName(symbol, ".al") : referenceSourceFileLocation.FileName);
							string text2 = navAppPackageReader.ReadAlSourceContent(fileName);
							if (text2 != null)
							{
								sourceContent.AddOrUpdate(symbol, (text2, ReferenceSourceKind.Source), (IObjectTypeSymbol key, (string? Content, ReferenceSourceKind Kind) value) => value);
								return text2;
							}
						}
						return null;
					}
					catch (Exception ex)
					{
						Logger.Error("An exception happened while reading the manifest from the package '{0}'. {1}", text, ex.Message);
						return null;
					}
				}
				finally
				{
					instance.Free();
				}
			}
		}

		private class ReferenceSymbolResolver : IReferenceManager, Microsoft.Dynamics.Nav.CodeAnalysis.IReferenceResolver
		{
			private readonly IReferenceManager proxyManager;

			public IReferenceManager DelegatingResolver => proxyManager.DelegatingResolver;

			public ReferenceManagerKind Kind => proxyManager.Kind;

			public ReferenceSymbolResolver(IReferenceManager proxyManager)
			{
				this.proxyManager = proxyManager;
			}

			public ImmutableArray<Diagnostic> GetDiagnostics(CancellationToken cancellationToken)
			{
				return proxyManager.GetDiagnostics(cancellationToken);
			}

			public ImmutableArray<IModuleSymbol> GetLoadedModules()
			{
				return proxyManager.GetLoadedModules();
			}

			public ImmutableArray<ISymbolWithId> GetObjectSymbolsByIdAcrossModules(IModuleSymbol referencingModule, SymbolKind kind, int id)
			{
				ImmutableArray<ISymbolWithId> objectSymbolsByIdAcrossModules = proxyManager.GetObjectSymbolsByIdAcrossModules(referencingModule, kind, id);
				ISymbolWithId symbolWithId = HandleSpecialCase(objectSymbolsByIdAcrossModules);
				if (symbolWithId != null)
				{
					return new ISymbolWithId[1] { symbolWithId }.ToImmutableArray();
				}
				return objectSymbolsByIdAcrossModules;
			}

			public IEnumerable<ISymbol> GetObjectSymbolsByKindAcrossModules(IModuleSymbol referencingModule, SymbolKind kind)
			{
				return proxyManager.GetObjectSymbolsByKindAcrossModules(referencingModule, kind);
			}

			public ImmutableArray<ISymbol> GetObjectSymbolsByNameAcrossModules(IModuleSymbol referencingModule, SymbolKind kind, string name)
			{
				ImmutableArray<ISymbol> objectSymbolsByNameAcrossModules = proxyManager.GetObjectSymbolsByNameAcrossModules(referencingModule, kind, name);
				ISymbol symbol = HandleSpecialCase(objectSymbolsByNameAcrossModules);
				if (symbol != null)
				{
					return new ISymbol[1] { symbol }.ToImmutableArray();
				}
				return objectSymbolsByNameAcrossModules;
			}

			public ISymbol? GetObjectSymbolByName(IModuleSymbol referencingModule, Guid moduleId, SymbolKind kind, string name)
			{
				return proxyManager.GetObjectSymbolByName(referencingModule, moduleId, kind, name);
			}

			private static T HandleSpecialCase<T>(ImmutableArray<T> symbols) where T : ISymbol
			{
				if (symbols.Length == 2)
				{
					ImmutableArray<T>.Enumerator enumerator = symbols.GetEnumerator();
					while (enumerator.MoveNext())
					{
						T current = enumerator.Current;
						if (current.Location != null && current.Location.IsInSource)
						{
							return current;
						}
					}
				}
				return default(T);
			}
		}

		private const string LineStartAttributeName = "LineStart";

		private readonly VsCodeWorkspace workspace;

		private Compilation compilation;

		private readonly IReferenceSymbolContentProvider contentProvider;

		private readonly object mutex = new object();

		private ProjectId compilationProjectId;

		private bool compilationContextSet;

		internal ReferenceSymbolDefinitionManager(VsCodeWorkspace workspace)
		{
			this.workspace = workspace;
			compilation = Compilation.Create("GotoDefinition");
			contentProvider = new ReferenceSymbolContentProvider(this.workspace);
		}

		internal void AddLogger(IEmitLogger logger)
		{
			contentProvider.Logger = logger;
		}

		internal void ClearContent()
		{
			contentProvider.ClearContent();
		}

		internal async Task<(string Content, ReferenceSourceKind Kind)> GetContentAsync(Uri previewUri, LaunchConfiguration configuration, CancellationToken token, bool relyOnCachedValue = false)
		{
			await EnsureCompilationContextIsSet(token).ConfigureAwait(continueOnCapturedContext: false);
			IObjectTypeSymbol objectTypeSymbol = await GetDeclaringSymbolAsync(previewUri, token).ConfigureAwait(continueOnCapturedContext: false);
			if (objectTypeSymbol == null)
			{
				return (Content: null, Kind: ReferenceSourceKind.Undefined);
			}
			(string, ReferenceSourceKind) content = contentProvider.GetContent(objectTypeSymbol);
			if (content.Item2 != 0)
			{
				return content;
			}
			if (relyOnCachedValue)
			{
				return (Content: null, Kind: ReferenceSourceKind.Undefined);
			}
			return await CreateContent(objectTypeSymbol, configuration).ConfigureAwait(continueOnCapturedContext: false);
		}

		internal async Task<Definition> GetDefinitionForSymbolAtPositionAsync(Uri previewUri, Position requestPosition, LaunchConfiguration configuration, CancellationToken cancellationToken)
		{
			await EnsureCompilationContextIsSet(cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
			(string, ReferenceSourceKind) tuple = await GetContentAsync(previewUri, configuration, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
			if (tuple.Item2 != ReferenceSourceKind.Source)
			{
				return null;
			}
			return await FindDefinitionAtPositionAsync(tuple.Item1, requestPosition, configuration, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
		}

		internal async Task<Definition?> TryGetDefinitionFromReference(ISymbol symbol, LaunchConfiguration? configuration, CancellationToken cancellationToken)
		{
			await EnsureCompilationContextIsSet(cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
			ObjectTypeSymbol appSymbol = GetDeclaringReferenceApplicationSymbol(symbol);
			if (appSymbol == null)
			{
				return null;
			}
			(string, ReferenceSourceKind) tuple = await CreateContent(appSymbol, configuration).ConfigureAwait(continueOnCapturedContext: false);
			Range value = FindRangeInContent(symbol, tuple.Item2, tuple.Item1);
			Project currentProject = workspace.GetCurrentProject();
			return new Definition
			{
				Uri = FilePathHelper.GetPreviewFileUri((currentProject == null) ? string.Empty : currentProject.ProjectFolder, appSymbol.GetIdOrDefault(), appSymbol.Name, appSymbol.Kind, appSymbol.DeclaringCompilation?.ModuleInfo?.AppId ?? null),
				Range = value
			};
		}

		private async Task<IObjectTypeSymbol?> GetDeclaringSymbolAsync(Uri previewUri, CancellationToken token)
		{
			Project currentProject = workspace.GetCurrentProject();
			if (currentProject == null)
			{
				return null;
			}
			PreviewFileUrl parsedUrl = previewUri.ParsePreviewFileUrl();
			Compilation projectCompilation = await currentProject.GetCompilationAsync(token).ConfigureAwait(continueOnCapturedContext: false);
			IObjectTypeSymbol objectTypeSymbol = null;
			if (parsedUrl.Id > 0)
			{
				ImmutableArray<IApplicationObjectTypeSymbol> array = projectCompilation.GetApplicationObjectTypeSymbolsByIdAcrossModules(parsedUrl.Kind, parsedUrl.Id);
				if (array.Length > 1)
				{
					array = array.WhereAsArray((IApplicationObjectTypeSymbol x) => !x.IsObsoleteMoved);
				}
				objectTypeSymbol = ((array.Length == 1) ? (array[0] as IObjectTypeSymbol) : null);
			}
			else if (parsedUrl.AppId.HasValue)
			{
				Guid appId = projectCompilation.CompiledModule.AppId;
				Guid? appId2 = parsedUrl.AppId;
				if (appId != appId2)
				{
					return projectCompilation.ReferenceManager.GetObjectSymbolByName(projectCompilation.CompiledModule, parsedUrl.AppId.Value, parsedUrl.Kind, parsedUrl.Name) as IObjectTypeSymbol;
				}
				objectTypeSymbol = projectCompilation.CompiledModule.SymbolMap?.GetSymbolByName(parsedUrl.Kind, parsedUrl.Name) as IObjectTypeSymbol;
			}
			if (objectTypeSymbol == null && !string.IsNullOrEmpty(parsedUrl.ProjectName))
			{
				Solution currentSolution = workspace.CurrentSolution;
				if (currentSolution != null)
				{
					Project project = currentSolution.Projects.FirstOrDefault((Project n) => n.Name.Equals(parsedUrl.ProjectName, StringComparison.OrdinalIgnoreCase));
					if (project != null)
					{
						objectTypeSymbol = (await project.GetCompilationAsync(token).ConfigureAwait(continueOnCapturedContext: false)).CompiledModule.SymbolMap.GetSymbolByName(parsedUrl.Kind, parsedUrl.Name) as IObjectTypeSymbol;
					}
				}
			}
			if (objectTypeSymbol == null)
			{
				ImmutableArray<IObjectTypeSymbol> array2 = projectCompilation.GetObjectTypeSymbolsByNameAcrossModulesAndNamespaces(parsedUrl.Kind, parsedUrl.Name);
				if (array2.Length > 1)
				{
					array2 = array2.WhereAsArray((IObjectTypeSymbol x) => !x.IsObsoleteMoved);
				}
				return (array2.Length == 1) ? array2[0] : null;
			}
			return objectTypeSymbol;
		}

		private async Task EnsureCompilationContextIsSet(CancellationToken token)
		{
			if (compilationContextSet && compilationProjectId == workspace.CurrentProjectId)
			{
				return;
			}
			Project project = workspace.CurrentSolution?.GetProject(workspace.CurrentProjectId);
			Compilation compilation = await project.GetCompilationAsync(token).ConfigureAwait(continueOnCapturedContext: false);
			ReferenceSymbolResolver referenceManager = new ReferenceSymbolResolver(compilation.ReferenceManager);
			lock (mutex)
			{
				this.compilation = this.compilation.WithReferenceManager(referenceManager).WithReferenceLoader(compilation.ReferenceLoader);
				if (project.SymbolReferences != null)
				{
					this.compilation = this.compilation.WithReferences(project.SymbolReferences);
				}
				compilationProjectId = workspace.CurrentProjectId;
				compilationContextSet = true;
			}
		}

		private ObjectTypeSymbol? GetDeclaringReferenceApplicationSymbol(ISymbol symbol)
		{
			ObjectTypeSymbol containingSymbolOfType = symbol.GetContainingSymbolOfType<ObjectTypeSymbol>();
			if (!(containingSymbolOfType == null) && (!containingSymbolOfType.IsSourceSymbol() || containingSymbolOfType.DeclaringCompilation == compilation))
			{
				return containingSymbolOfType;
			}
			return null;
		}

		private async Task<(string Content, ReferenceSourceKind Kind)> CreateContent(IObjectTypeSymbol appSymbol, LaunchConfiguration? configuration)
		{
			(string, ReferenceSourceKind) result = await contentProvider.CreateSourceContent(appSymbol, configuration).ConfigureAwait(continueOnCapturedContext: false);
			if (!string.IsNullOrEmpty(result.Item1))
			{
				return result;
			}
			string? text = contentProvider.CreateMetadataContent(appSymbol);
			ReferenceSourceKind item = ((!string.IsNullOrEmpty(text)) ? ReferenceSourceKind.Metadata : ReferenceSourceKind.Undefined);
			return (Content: text, Kind: item);
		}

		private async Task<Definition?> FindDefinitionAtPositionAsync(string content, Position position, LaunchConfiguration configuration, CancellationToken cancellationToken, int lineOffset = 0)
		{
			LinePosition linePosition = new LinePosition(position.Line, position.Character);
			(SyntaxNode? Node, SyntaxTree? Tree) context = await content.GetNodeAtPositionAsync(linePosition, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
			if (context.Node == null)
			{
				return null;
			}
			try
			{
				compilation = compilation.AddSyntaxTrees(context.Tree);
				SemanticModel semanticModel = compilation.GetSemanticModel(context.Tree);
				if (semanticModel == null)
				{
					return null;
				}
				Microsoft.Dynamics.Nav.CodeAnalysis.SymbolInfo symbolInfo = semanticModel.GetSymbolInfo(context.Node, cancellationToken);
				ISymbol symbol = symbolInfo.Symbol ?? symbolInfo.CandidateSymbols.FirstOrDefault();
				if (symbol == null)
				{
					return null;
				}
				ObjectTypeSymbol appSymbol = GetDeclaringReferenceApplicationSymbol(symbol);
				if (appSymbol == null)
				{
					return null;
				}
				_ = Range.Empty;
				Range value;
				if (symbol.Location != null && symbol.Location.IsInSource)
				{
					FileLinePositionSpan mappedLineSpan = symbol.Location.GetMappedLineSpan();
					Range range = default(Range);
					range.Start = new Position
					{
						Line = mappedLineSpan.StartLinePosition.Line + lineOffset,
						Character = mappedLineSpan.StartLinePosition.Character
					};
					range.End = new Position
					{
						Line = mappedLineSpan.EndLinePosition.Line + lineOffset,
						Character = mappedLineSpan.EndLinePosition.Character
					};
					value = range;
				}
				else
				{
					(string, ReferenceSourceKind) tuple = await CreateContent(appSymbol, configuration).ConfigureAwait(continueOnCapturedContext: false);
					if (string.IsNullOrEmpty(tuple.Item1))
					{
						return null;
					}
					value = FindRangeInContent(symbol, tuple.Item2, tuple.Item1);
				}
				Project currentProject = workspace.GetCurrentProject();
				return new Definition
				{
					Uri = FilePathHelper.GetPreviewFileUri((currentProject == null) ? string.Empty : currentProject.ProjectFolder, appSymbol.GetIdOrDefault(), appSymbol.Name, appSymbol.Kind, appSymbol.ContainingModule?.AppId),
					Range = value
				};
			}
			finally
			{
				compilation = compilation.RemoveSyntaxTrees(context.Tree);
			}
		}

		private Range FindRangeInContent(ISymbol symbol, ReferenceSourceKind kind, string content)
		{
			Range result = Range.Empty;
			if (kind != ReferenceSourceKind.CALSource)
			{
				result = FindSymbolRangeInContent(symbol, content);
			}
			return result;
		}

		private Range FindSymbolRangeInContent(ISymbol symbol, string content, int lineOffset = 0)
		{
			if (string.IsNullOrEmpty(content))
			{
				return Range.Empty;
			}
			SyntaxTree syntaxTree = SyntaxFactory.ParseSyntaxTree(SourceText.From(content));
			if (syntaxTree == null)
			{
				return Range.Empty;
			}
			try
			{
				compilation = compilation.AddSyntaxTrees(syntaxTree);
				SemanticModel semanticModel = compilation.GetSemanticModel(syntaxTree);
				if (semanticModel == null)
				{
					return Range.Empty;
				}
				foreach (ObjectSyntax item in syntaxTree.GetRoot().DescendantNodes().OfType<ObjectSyntax>())
				{
					foreach (SyntaxNode item2 in item.DescendantNodesAndSelf())
					{
						ISymbol declaredSymbol = semanticModel.GetDeclaredSymbol(item2);
						if (declaredSymbol == null || !SemanticFacts.IsSameName(declaredSymbol.Name, symbol.Name) || declaredSymbol.Kind != symbol.Kind || !(declaredSymbol.Location != null))
						{
							continue;
						}
						if (symbol.Kind == SymbolKind.Method && declaredSymbol.Kind == SymbolKind.Method)
						{
							MethodSymbol obj = (MethodSymbol)symbol;
							MethodSymbol methodSymbol = (MethodSymbol)declaredSymbol;
							if (!obj.HasMatchingSignature(methodSymbol))
							{
								continue;
							}
						}
						FileLinePositionSpan mappedLineSpan = declaredSymbol.Location.GetMappedLineSpan();
						Range result = default(Range);
						result.Start = new Position
						{
							Line = mappedLineSpan.StartLinePosition.Line + lineOffset,
							Character = mappedLineSpan.StartLinePosition.Character
						};
						result.End = new Position
						{
							Line = mappedLineSpan.EndLinePosition.Line + lineOffset,
							Character = mappedLineSpan.EndLinePosition.Character
						};
						return result;
					}
				}
			}
			finally
			{
				compilation = compilation.RemoveSyntaxTrees(syntaxTree);
			}
			return Range.Empty;
		}
	}
	public class RenameRequestHandler : RequestHandlerBase<RenameRequest>
	{
		public override string EndpointName => "textDocument/rename";

		internal RenameRequestHandler(VsCodeWorkspace workspace, ResponseQueue responseQueue)
			: base(workspace, (IResponseQueue)responseQueue)
		{
		}

		public override async Task HandleAsync(RenameRequest request, int requestId, CancellationToken cancellationToken)
		{
			if (base.Workspace.CurrentProjectId == null)
			{
				LocalMachineLogger.LogError("Missed a didChangeMessage for file {0}.");
				return;
			}
			WorkspaceEdit response = new WorkspaceEdit();
			Document document = base.Workspace.GetDocument(request.TextDocument.FileName);
			if (document != null && base.Workspace.AreAllProjectReferencesBound(document))
			{
				IFindReferencesService findReferences = document.GetLanguageService<IFindReferencesService>();
				int position = (await document.GetTextAsync(cancellationToken)).Lines.GetPosition(new LinePosition(request.Position.Line, request.Position.Character));
				if (!IsRenamingAllowed(await CompletionProvider.CreateMemberContextAsync(document, position, cancellationToken), position))
				{
					base.ResponseQueue.Add(ResponseFactory.Rename(response, requestId), cancellationToken);
					return;
				}
				foreach (ReferencedSymbol item in findReferences.FindReferencedSymbolsAsync(document, position, cancellationToken))
				{
					foreach (ReferenceLocation location in item.Locations)
					{
						response.Add(location.Document.FilePath.GetUri(), new TextEdit
						{
							Range = location.Location,
							NewText = request.NewName.QuoteIdentifierIfNeeded()
						});
					}
				}
			}
			base.ResponseQueue.Add(ResponseFactory.Rename(response, requestId), cancellationToken);
		}

		private static bool IsRenamingAllowed(AbstractSyntaxContext syntaxContext, int position)
		{
			if (syntaxContext.LeftToken.Kind == SyntaxKind.IdentifierToken)
			{
				return true;
			}
			SyntaxToken nextToken = syntaxContext.LeftToken.GetNextToken();
			if (nextToken.IsKind(SyntaxKind.IdentifierToken) && nextToken.SpanStart == position)
			{
				return true;
			}
			return false;
		}
	}
	public class RunCodeActionCommandHandler : CommandHandlerBase<RunCodeAction>
	{
		public override string Command => "al/runCodeAction";

		internal RunCodeActionCommandHandler(VsCodeWorkspace workspace, ResponseQueue responseQueue)
			: base(workspace, (IResponseQueue)responseQueue)
		{
		}

		protected override async Task HandleAsync(RunCodeAction[] commandArguments, int requestId, CancellationToken cancellationToken)
		{
			RunCodeAction runCodeAction = commandArguments.FirstOrDefault();
			if (runCodeAction?.FileName == null)
			{
				base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId));
				return;
			}
			Document document = base.Workspace.GetDocument(runCodeAction.FileName);
			if (document == null)
			{
				base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId));
				return;
			}
			if (!base.Workspace.AreAllProjectReferencesBound(document))
			{
				base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId));
				return;
			}
			TextSpan textSpan = (await document.GetTextAsync()).GetTextSpan(runCodeAction.Selection);
			CodeActionProxy codeActionProxy = (await CodeActionService.GetService(document).GetCodeActionsAsync(document, textSpan, cancellationToken)).FirstOrDefault((CodeActionProxy a) => a.GetIdentifier().Equals(runCodeAction.Identifier, StringComparison.InvariantCultureIgnoreCase));
			if (codeActionProxy == null)
			{
				base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId));
				return;
			}
			WorkspaceEdit workspaceEdit = new WorkspaceEdit();
			Solution solution = base.Workspace.CurrentSolution;
			string directory = Path.GetDirectoryName(runCodeAction.FileName);
			ImmutableArray<CodeActionOperation> immutableArray = await codeActionProxy.GetOperationsAsync(CancellationToken.None);
			string text = WorkspacesResources.TermInstance;
			if (codeActionProxy.CodeAction is CodeAction.CodeActionWithFixAll codeActionWithFixAll)
			{
				text = codeActionWithFixAll.GetFixAllState().Scope.ToDisplayString();
			}
			string message = FormattableString.Invariant($"Executing code action '{codeActionProxy.GetIdentifier()}' with type '{codeActionProxy.GetKind()}' and scope '{text}' which will change '{immutableArray.Length}' spans.");
			ExternalTelemetryLogger.TelemetryService.TrackInfo(message);
			IDiagnosticService diagnosticService = (IDiagnosticService)base.Workspace.ProjectClosureCompilation;
			try
			{
				diagnosticService.Stop();
				ImmutableArray<CodeActionOperation>.Enumerator enumerator = immutableArray.GetEnumerator();
				while (enumerator.MoveNext())
				{
					if (enumerator.Current is ApplyChangesOperation applyChangesOperation)
					{
						await ProcessOperationAsync(applyChangesOperation.ChangedSolution, solution, directory, workspaceEdit);
						solution = base.Workspace.CurrentSolution;
					}
				}
			}
			finally
			{
				diagnosticService.Start(forceNewCompilation: true);
			}
			ApplyWorkspaceEditParams applyWorkspaceEditParams = new ApplyWorkspaceEditParams
			{
				Label = runCodeAction.Identifier,
				Edit = workspaceEdit
			};
			base.ResponseQueue.Add(ResponseFactory.ApplyEdit(applyWorkspaceEditParams, requestId));
		}

		private async Task ProcessOperationAsync(Solution newSolution, Solution oldSolution, string directory, WorkspaceEdit workspaceEdit)
		{
			WorkspaceEdit workspaceEdit2 = workspaceEdit;
			foreach (ProjectChanges projectChange in newSolution.GetChanges(oldSolution).GetProjectChanges())
			{
				foreach (DocumentId addedDocument in projectChange.GetAddedDocuments())
				{
					Document newDocument2 = newSolution.GetDocument(addedDocument);
					SourceText sourceText = await newDocument2.GetTextAsync();
					Uri uri = new Uri((newDocument2.FilePath == null || !Path.IsPathRooted(newDocument2.FilePath)) ? Path.Combine(directory, newDocument2.Name) : newDocument2.FilePath);
					workspaceEdit2.Add(uri.AbsoluteUri, new TextEdit
					{
						NewText = sourceText.ToString()
					});
				}
				foreach (DocumentId changedDocument in projectChange.GetChangedDocuments())
				{
					Document newDocument2 = newSolution.GetDocument(changedDocument);
					Document oldDocument = oldSolution.GetDocument(changedDocument);
					SourceText oldText = await oldDocument.GetTextAsync();
					IEnumerable<TextChange> textChanges = await newDocument2.GetTextChangesAsync(oldDocument);
					Uri fileUri = new Uri(newDocument2.FilePath);
					GetTextEdits(oldText, textChanges, delegate(TextEdit te)
					{
						workspaceEdit2.Add(fileUri.AbsoluteUri, te);
					});
				}
			}
		}

		private void GetTextEdits(SourceText oldText, IEnumerable<TextChange> textChanges, Action<TextEdit> action)
		{
			foreach (TextChange textChange in textChanges)
			{
				TextSpan span = textChange.Span;
				_ = textChange.NewText;
				_ = string.Empty;
				_ = string.Empty;
				LinePositionSpan linePositionSpan = oldText.Lines.GetLinePositionSpan(span);
				action(new TextEdit
				{
					NewText = textChange.NewText,
					Range = new Range
					{
						Start = new Position
						{
							Line = linePositionSpan.Start.Line,
							Character = linePositionSpan.Start.Character
						},
						End = new Position
						{
							Line = linePositionSpan.End.Line,
							Character = linePositionSpan.End.Character
						}
					}
				});
			}
		}
	}
