	public class SignatureHelpRequestHandler : RequestHandlerBase<SignatureHelpRequest>
	{
		public override string EndpointName => "textDocument/signatureHelp";

		internal SignatureHelpRequestHandler(VsCodeWorkspace workspace, ResponseQueue responseQueue)
			: base(workspace, (IResponseQueue)responseQueue)
		{
		}

		public override async Task HandleAsync(SignatureHelpRequest request, int requestId, CancellationToken cancellationToken)
		{
			Document document = base.Workspace.GetDocument(request.TextDocument.FileName);
			if (document == null)
			{
				base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId));
				return;
			}
			if (!base.Workspace.AreAllProjectReferencesBound(document))
			{
				base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId));
				return;
			}
			int position = (await document.GetTextAsync(cancellationToken)).Lines.GetPosition(new LinePosition(request.Position.Line, request.Position.Character));
			SignatureHelp signatureHelp = null;
			ISignatureHelpService signatureHelpService = document.GetLanguageService<ISignatureHelpService>();
			SignatureHelpRequest.SignatureHelpContext context = request.Context;
			if (context != null && context.IsReTrigger && context.ActiveSignatureHelp != null && context.ActiveSignatureHelp.ActiveSignature != SignatureHelpService.DefaultSelectedSignature)
			{
				int? num = await signatureHelpService.GetActiveParameterAsync(document, position, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				if (num.HasValue)
				{
					context.ActiveSignatureHelp.ActiveParameter = num.Value;
					base.ResponseQueue.Add(ResponseFactory.SignatureHelp(context.ActiveSignatureHelp, requestId));
					return;
				}
			}
			SignatureHelpResult<SymbolSignature> signatureHelpResult = await signatureHelpService.ProvideSymbolicHelpAsync(document, position, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
			if (signatureHelpResult != null)
			{
				signatureHelp = CreateSignatureHelp(signatureHelpResult, cancellationToken);
			}
			else
			{
				SignatureHelpResult<SyntaxSignature> signatureHelpResult2 = await signatureHelpService.ProvideSyntacticHelpAsync(document, position, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				if (signatureHelpResult2 != null)
				{
					signatureHelp = CreateSignatureHelp(signatureHelpResult2);
				}
			}
			if (signatureHelp == null)
			{
				base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId));
			}
			else
			{
				base.ResponseQueue.Add(ResponseFactory.SignatureHelp(signatureHelp, requestId));
			}
		}

		private static SignatureHelp CreateSignatureHelp(SignatureHelpResult<SymbolSignature> help, CancellationToken cancellationToken)
		{
			return new SignatureHelp
			{
				Signatures = help.Signatures.Select((SymbolSignature signature) => new SignatureInformation
				{
					Label = signature.Label.ToDisplayString(SymbolDisplayFormat.SignatureFormat),
					Documentation = CreateContent(signature.Label.GetDocumentationComment(cancellationToken)),
					Parameters = signature.Parameters.Select((ISymbol parameter) => new ParameterInformation
					{
						Label = parameter.ToDisplayString(SymbolDisplayFormat.NameOnlyFormat),
						Documentation = CreateContent(parameter.GetDocumentationComment(cancellationToken))
					}).ToArray()
				}).ToArray(),
				ActiveParameter = help.ActiveParameter,
				ActiveSignature = help.ActiveSignature
			};
		}

		private static SignatureHelp CreateSignatureHelp(SignatureHelpResult<SyntaxSignature> help)
		{
			return new SignatureHelp
			{
				Signatures = help.Signatures.Select((SyntaxSignature signature) => new SignatureInformation
				{
					Label = FormatLabel(signature),
					Documentation = CreateContent(signature.Definition.GetDocumentation()),
					Parameters = signature.Parameters.Select((SyntaxNodeSlotDefinition parameter) => new ParameterInformation
					{
						Label = parameter.Name,
						Documentation = CreateContent(signature.Definition.GetParameterDocumentation(parameter.Name))
					}).ToArray()
				}).ToArray(),
				ActiveParameter = help.ActiveParameter,
				ActiveSignature = help.ActiveSignature
			};
		}

		private static string FormatLabel(SyntaxSignature signature)
		{
			StringBuilder stringBuilder = new StringBuilder(signature.KeywordKind.GetText());
			stringBuilder.Append(SyntaxKind.OpenParenToken.GetText());
			for (int i = 0; i < signature.Parameters.Count; i++)
			{
				SyntaxNodeSlotDefinition syntaxNodeSlotDefinition = signature.Parameters[i];
				if (i > 0)
				{
					stringBuilder.Append(signature.Separators[i - 1].GetText());
					stringBuilder.Append(" ");
				}
				stringBuilder.Append(syntaxNodeSlotDefinition.Name);
			}
			stringBuilder.Append(SyntaxKind.CloseParenToken.GetText());
			return stringBuilder.ToString();
		}

		private static MarkupContent CreateContent(string documentation)
		{
			return new MarkupContent
			{
				Kind = MarkupKind.Markdown,
				Value = (documentation ?? ProtocolResources.NoDocumentationAvailable)
			};
		}
	}
	internal class TypeHierarchySubTypesRequestHandler : RequestHandlerBase<TypeHierarchySubTypesRequest>
	{
		public override string EndpointName => "typeHierarchy/subtypes";

		public TypeHierarchySubTypesRequestHandler(VsCodeWorkspace workspace, IResponseQueue responseQueue)
			: base(workspace, responseQueue)
		{
		}

		public override async Task HandleAsync(TypeHierarchySubTypesRequest request, int requestId, CancellationToken cancellationToken)
		{
			Project currentProject = base.Workspace.GetCurrentProject();
			ValueTask<Compilation>? valueTask = currentProject?.GetCompilationAsync(cancellationToken);
			if (currentProject == null || !valueTask.HasValue)
			{
				base.ResponseQueue.Add(ResponseFactory.TypeHierarchySubTypes(requestId, null), cancellationToken);
				return;
			}
			Compilation compilation = await valueTask.Value;
			List<TypeHierarchyItem> subType = GetSubType(SymbolId.GetFirstSymbolForId(request.Item.Data, compilation) as Symbol, currentProject, compilation.CompiledModule);
			base.ResponseQueue.Add(ResponseFactory.TypeHierarchySubTypes(requestId, subType), cancellationToken);
		}

		private static List<TypeHierarchyItem>? GetSubType(Symbol? symbol, Project project, ModuleSymbol currentCompilationCompiledModule)
		{
			if (symbol == null)
			{
				return null;
			}
			if (currentCompilationCompiledModule == null)
			{
				return null;
			}
			if (symbol is IApplicationObjectTypeSymbol applicationObjectSymbol && symbol.Kind.IsExtensibleObject())
			{
				return GetExtensionObjects(project, currentCompilationCompiledModule, applicationObjectSymbol);
			}
			if (symbol.Kind == SymbolKind.Interface)
			{
				return GetImplementingObjects(project, currentCompilationCompiledModule, (InterfaceTypeSymbol)symbol);
			}
			return null;
		}

		private static List<TypeHierarchyItem>? GetExtensionObjects(Project project, ModuleSymbol module, IApplicationObjectTypeSymbol applicationObjectSymbol)
		{
			ImmutableArray<IApplicationObjectExtensionTypeSymbol> applicationObjectExtensionTypeSymbolsAcrossModules = module.GetApplicationObjectExtensionTypeSymbolsAcrossModules(applicationObjectSymbol);
			if (applicationObjectExtensionTypeSymbolsAcrossModules.Length == 0)
			{
				return null;
			}
			int num = applicationObjectExtensionTypeSymbolsAcrossModules.Length;
			if (applicationObjectSymbol.Kind == SymbolKind.Enum)
			{
				num += ((EnumTypeSymbol)applicationObjectSymbol).ImplementedInterfaces.Length;
			}
			ArrayBuilder<TypeHierarchyItem> instance = ArrayBuilder<TypeHierarchyItem>.GetInstance(num);
			try
			{
				ImmutableArray<IApplicationObjectExtensionTypeSymbol>.Enumerator enumerator = module.GetApplicationObjectExtensionTypeSymbolsAcrossModules(applicationObjectSymbol).GetEnumerator();
				while (enumerator.MoveNext())
				{
					TypeHierarchyItem item = TypeHierarchyHelper.CreateTypeHierarchyItem(enumerator.Current, project);
					instance.Add(item);
				}
				if (applicationObjectSymbol.Kind == SymbolKind.Enum)
				{
					ImmutableArray<InterfaceTypeSymbol>.Enumerator enumerator2 = ((EnumTypeSymbol)applicationObjectSymbol).ImplementedInterfaces.GetEnumerator();
					while (enumerator2.MoveNext())
					{
						InterfaceTypeSymbol current = enumerator2.Current;
						if (!current.IsUnresolvedInterface())
						{
							TypeHierarchyItem item2 = TypeHierarchyHelper.CreateTypeHierarchyItem(current, project);
							instance.Add(item2);
						}
					}
				}
				return instance.ToList();
			}
			finally
			{
				instance.Free();
			}
		}

		private static List<TypeHierarchyItem>? GetImplementingObjects(Project project, ModuleSymbol module, InterfaceTypeSymbol interfaceSymbol)
		{
			IEnumerable<IApplicationObjectTypeSymbol> implementors = interfaceSymbol.GetImplementors(module.DeclaringCompilation);
			ArrayBuilder<TypeHierarchyItem> instance = ArrayBuilder<TypeHierarchyItem>.GetInstance();
			try
			{
				foreach (IApplicationObjectTypeSymbol item2 in implementors)
				{
					TypeHierarchyItem item = TypeHierarchyHelper.CreateTypeHierarchyItem(item2, project);
					instance.Add(item);
				}
				return instance.ToList();
			}
			finally
			{
				instance.Free();
			}
		}
	}
	internal class TypeHierarchySuperTypesRequestHandler : RequestHandlerBase<TypeHierarchySuperTypesRequest>
	{
		public override string EndpointName => "typeHierarchy/supertypes";

		public TypeHierarchySuperTypesRequestHandler(VsCodeWorkspace workspace, IResponseQueue responseQueue)
			: base(workspace, responseQueue)
		{
		}

		public override async Task HandleAsync(TypeHierarchySuperTypesRequest request, int requestId, CancellationToken cancellationToken)
		{
			Project currentProject = base.Workspace.GetCurrentProject();
			ValueTask<Compilation>? valueTask = currentProject?.GetCompilationAsync(cancellationToken);
			if (currentProject == null || !valueTask.HasValue)
			{
				base.ResponseQueue.Add(ResponseFactory.TypeHierarchySuperTypes(requestId, null), cancellationToken);
				return;
			}
			Compilation compilation = await valueTask.Value;
			List<TypeHierarchyItem> superType = GetSuperType(SymbolId.GetFirstSymbolForId(request.Item.Data, compilation) as Symbol, currentProject);
			if (superType == null)
			{
				base.ResponseQueue.Add(ResponseFactory.TypeHierarchySuperTypes(requestId, null), cancellationToken);
			}
			else
			{
				base.ResponseQueue.Add(ResponseFactory.TypeHierarchySuperTypes(requestId, superType), cancellationToken);
			}
		}

		private static List<TypeHierarchyItem>? GetSuperType(Symbol? symbol, Project currentProject)
		{
			if (symbol == null)
			{
				return null;
			}
			if (symbol.Kind.IsExtensionOrCustomizationObject())
			{
				TypeHierarchyItem item = TypeHierarchyHelper.CreateTypeHierarchyItem(symbol.GetBaseApplicationObjectSymbol(), currentProject);
				return new List<TypeHierarchyItem> { item };
			}
			if (symbol.Kind == SymbolKind.Codeunit)
			{
				return ConvertInterfaces(((CodeunitTypeSymbol)symbol).ImplementedInterfaces, currentProject);
			}
			if (symbol.Kind == SymbolKind.Enum)
			{
				return ConvertInterfaces(((EnumTypeSymbol)symbol).ImplementedInterfaces, currentProject);
			}
			return null;
		}

		private static List<TypeHierarchyItem>? ConvertInterfaces(ImmutableArray<InterfaceTypeSymbol> interfaces, Project project)
		{
			if (interfaces.Length == 0)
			{
				return null;
			}
			ArrayBuilder<TypeHierarchyItem> instance = ArrayBuilder<TypeHierarchyItem>.GetInstance(interfaces.Length);
			try
			{
				ImmutableArray<InterfaceTypeSymbol>.Enumerator enumerator = interfaces.GetEnumerator();
				while (enumerator.MoveNext())
				{
					InterfaceTypeSymbol current = enumerator.Current;
					if (!current.IsUnresolvedInterface())
					{
						TypeHierarchyItem item = TypeHierarchyHelper.CreateTypeHierarchyItem(current, project);
						instance.Add(item);
					}
				}
				return instance.ToList();
			}
			finally
			{
				instance.Free();
			}
		}
	}
	public class WorkspaceSymbolRequestHandler : RequestHandlerBase<WorkspaceSymbolRequest>
	{
		private readonly ExtensionOptions extensionOptions;

		private readonly ConcurrentDictionary<IModuleSymbol, ReferenceModuleSymbolLookup> referenceSymbolLookup = new ConcurrentDictionary<IModuleSymbol, ReferenceModuleSymbolLookup>();

		private readonly ConcurrentDictionary<ProjectId, SourceModuleSymbolLookup> sourceModuleSymbolLookup = new ConcurrentDictionary<ProjectId, SourceModuleSymbolLookup>();

		private ConcurrentDictionary<ProjectId, ConcurrentSet<DocumentId>> dirtyProjects = new ConcurrentDictionary<ProjectId, ConcurrentSet<DocumentId>>();

		public override string EndpointName => "workspace/symbol";

		internal WorkspaceSymbolRequestHandler(VsCodeWorkspace workspace, ResponseQueue responseQueue, ExtensionOptions extensionOptions)
			: base(workspace, (IResponseQueue)responseQueue)
		{
			this.extensionOptions = extensionOptions;
			SetupWorkspaceListeners();
		}

		private void SetupWorkspaceListeners()
		{
			base.Workspace.WorkspaceChanged += WorkspaceOnWorkspaceChanged;
		}

		private void WorkspaceOnWorkspaceChanged(object? sender, WorkspaceChangeEventArgs e)
		{
			DocumentId documentId = e.DocumentId;
			switch (e.Kind)
			{
			case WorkspaceChangeKind.DocumentAdded:
			case WorkspaceChangeKind.DocumentReloaded:
			case WorkspaceChangeKind.DocumentChanged:
				if (documentId != null)
				{
					if (!dirtyProjects.TryGetValue(documentId.ProjectId, out ConcurrentSet<DocumentId> _))
					{
						dirtyProjects.TryAdd(documentId.ProjectId, new ConcurrentSet<DocumentId>());
					}
					if (dirtyProjects.TryGetValue(documentId.ProjectId, out ConcurrentSet<DocumentId> value3))
					{
						value3.Add(documentId);
					}
				}
				break;
			case WorkspaceChangeKind.DocumentRemoved:
			{
				if (documentId != null && sourceModuleSymbolLookup.TryGetValue(documentId.ProjectId, out SourceModuleSymbolLookup value))
				{
					value.RemoveDocument(documentId);
				}
				break;
			}
			}
		}

		public override async Task HandleAsync(WorkspaceSymbolRequest request, int requestId, CancellationToken cancellationToken)
		{
			ExternalTelemetryLogger.TelemetryService?.TrackInfo($"ExtendedGoToSymbol. Enabled:{extensionOptions?.ExtendGoToSymbolInWorkspace?.Enabled}. IncludeSymbolFiles:{extensionOptions?.ExtendGoToSymbolInWorkspace?.IncludeSymbolFiles}. ResultLimit:{extensionOptions?.ExtendGoToSymbolInWorkspace?.ResultLimit}.");
			ExtensionOptions obj = extensionOptions;
			if (obj != null && (obj.ExtendGoToSymbolInWorkspace?.Enabled).GetValueOrDefault())
			{
				ExternalTelemetryLogger.TelemetryService?.TrackMetric("ExtendGoToSymbolInWorkspaceQueryLength", request.Query?.Length ?? 0);
				PooledStopwatch stopwatch = ExternalTelemetryLogger.BeginOperation();
				try
				{
					await HandleWithExtendedSearchAsync(request, requestId, cancellationToken);
					return;
				}
				finally
				{
					ExternalTelemetryLogger.EndOperation("ExtendGoToSymbolInWorkspaceDuration", stopwatch, System.TimeSpan.MinValue);
				}
			}
			ExternalTelemetryLogger.TelemetryService?.TrackMetric("TopLevelGoToSymbolInWorkspaceQueryLength", request.Query?.Length ?? 0);
			PooledConcurrentSet<SymbolInformation> builder = PooledConcurrentSet<SymbolInformation>.GetInstance();
			try
			{
				if (!string.IsNullOrEmpty(request.Query) && base.Workspace.CurrentSolution != null)
				{
					SymbolRequestQueryMatcher symbolRequestQueryMatcher = new SymbolRequestQueryMatcher(request.Query);
					HashSet<Guid> visitedApps = new HashSet<Guid>();
					foreach (Project project in base.Workspace.CurrentSolution.Projects)
					{
						if (cancellationToken.IsCancellationRequested)
						{
							base.ResponseQueue.Add(ResponseFactory.WorkspaceSymbol(Array.Empty<SymbolInformation>(), requestId));
							return;
						}
						if (project == null)
						{
							continue;
						}
						await Parallel.ForEachAsync(project.Documents, cancellationToken, async delegate(Document document, CancellationToken token)
						{
							try
							{
								SymbolInformation[] array3 = await document.GetSymbolInformations(token, onlySearchTopLevelObjects: true, (ISymbol s) => symbolRequestQueryMatcher.Matches(s));
								if (array3 != null)
								{
									SymbolInformation[] array4 = array3;
									foreach (SymbolInformation value2 in array4)
									{
										builder.Add(value2);
									}
								}
							}
							catch (OperationCanceledException)
							{
							}
						});
						Compilation compilation = await project.GetCompilationAsync(cancellationToken);
						if (compilation == null)
						{
							continue;
						}
						visitedApps.Add(compilation.CompiledModule.AppId);
						ImmutableArray<IModuleSymbol>.Enumerator enumerator2 = compilation.CompiledModule.ReferenceModules.GetEnumerator();
						while (enumerator2.MoveNext())
						{
							IModuleSymbol current = enumerator2.Current;
							if (visitedApps.Contains(current.AppId))
							{
								continue;
							}
							SymbolInformation[] symbolInformations = ReferenceSymbolDefinitionHelper.GetSymbolInformations(current, project.ProjectFolder, cancellationToken, (ISymbol s) => symbolRequestQueryMatcher.Matches(s));
							if (symbolInformations != null)
							{
								SymbolInformation[] array = symbolInformations;
								foreach (SymbolInformation value in array)
								{
									builder.Add(value);
								}
							}
						}
					}
				}
				SymbolInformation[] array2 = builder.ToArray();
				Array.Sort(array2, (SymbolInformation x, SymbolInformation y) => StringComparer.OrdinalIgnoreCase.Compare(x.Name, y.Name));
				base.ResponseQueue.Add(ResponseFactory.WorkspaceSymbol(array2, requestId));
			}
			finally
			{
				if (builder != null)
				{
					((IDisposable)builder).Dispose();
				}
			}
		}

		public async Task HandleWithExtendedSearchAsync(WorkspaceSymbolRequest request, int requestId, CancellationToken cancellationToken)
		{
			using PooledConcurrentSet<WorkspaceSymbol> builder = PooledConcurrentSet<WorkspaceSymbol>.GetInstance();
			if (!string.IsNullOrEmpty(request.Query) && base.Workspace.CurrentSolution != null)
			{
				int responseLimit = extensionOptions.ExtendGoToSymbolInWorkspace?.ResultLimit ?? 100;
				HashSet<Guid> visitedApps = new HashSet<Guid>();
				foreach (Project project in base.Workspace.CurrentSolution.Projects)
				{
					if (cancellationToken.IsCancellationRequested)
					{
						base.ResponseQueue.Add(ResponseFactory.WorkspaceSymbol(Array.Empty<SymbolInformation>(), requestId));
						return;
					}
					if (project == null)
					{
						continue;
					}
					if (!sourceModuleSymbolLookup.TryGetValue(project.Id, out SourceModuleSymbolLookup sourceSymbolIndex))
					{
						sourceSymbolIndex = await SourceModuleSymbolLookup.CreateFromProject(project, cancellationToken);
						sourceModuleSymbolLookup[project.Id] = sourceSymbolIndex;
					}
					if (sourceSymbolIndex != null)
					{
						await UpdateIndexForDirtyDocumentsAsync(project, sourceSymbolIndex, cancellationToken);
						sourceSymbolIndex.QueryForSymbol(request.Query, project.ProjectFolder, builder, responseLimit, base.Workspace.CurrentDocumentId);
					}
					Compilation compilation = await project.GetCompilationAsync(cancellationToken);
					if (compilation == null)
					{
						continue;
					}
					visitedApps.Add(compilation.CompiledModule.AppId);
					if (extensionOptions.ExtendGoToSymbolInWorkspace?.IncludeSymbolFiles ?? false)
					{
						ImmutableArray<IModuleSymbol>.Enumerator enumerator2 = compilation.CompiledModule.ReferenceModules.GetEnumerator();
						while (enumerator2.MoveNext())
						{
							IModuleSymbol current = enumerator2.Current;
							if (visitedApps.Contains(current.AppId))
							{
								continue;
							}
							if (!referenceSymbolLookup.TryGetValue(current, out ReferenceModuleSymbolLookup value))
							{
								PooledStopwatch stopwatch = ExternalTelemetryLogger.BeginOperation();
								try
								{
									value = ReferenceModuleSymbolLookup.CreateFromReferenceModule(current);
								}
								finally
								{
									ExternalTelemetryLogger.EndOperation("BuildIndexForReferenceModuleSymbolLookupDuration", stopwatch, System.TimeSpan.MinValue);
								}
								referenceSymbolLookup[current] = value;
							}
							value?.GetSymbolsMatchingQuery(request.Query, project.ProjectFolder, builder, responseLimit);
						}
					}
					sourceSymbolIndex = null;
				}
			}
			WorkspaceSymbol[] array = builder.ToArray();
			Array.Sort(array, SymbolComparer);
			base.ResponseQueue.Add(ResponseFactory.WorkspaceSymbol(array, requestId), cancellationToken);
		}

		private static int SymbolComparer(WorkspaceSymbol x, WorkspaceSymbol y)
		{
			return StringComparer.OrdinalIgnoreCase.Compare(x.Name, y.Name);
		}

		private async Task UpdateIndexForDirtyDocumentsAsync(Project project, SourceModuleSymbolLookup sourceSymbolIndex, CancellationToken cancellationToken)
		{
			if (!dirtyProjects.TryGetValue(project.Id, out ConcurrentSet<DocumentId> dirtyDocumentSet) || dirtyDocumentSet.Count == 0)
			{
				return;
			}
			foreach (DocumentId item in dirtyDocumentSet.ToList())
			{
				if (dirtyDocumentSet.Remove(item))
				{
					await sourceSymbolIndex.UpdateForDocumentAsync(project.GetDocument(item), cancellationToken);
				}
			}
		}
	}
	internal class WorkspaceSymbolResolveRequestHandler : RequestHandlerBase<WorkspaceSymbolResolveRequest>
	{
		private readonly ReferenceSymbolDefinitionManager referenceSymbolDefinitionManager;

		public override string EndpointName => "workspaceSymbol/resolve";

		public WorkspaceSymbolResolveRequestHandler(VsCodeWorkspace workspace, ReferenceSymbolDefinitionManager referenceSymbolDefinitionManager, IResponseQueue responseQueue)
			: base(workspace, responseQueue)
		{
			this.referenceSymbolDefinitionManager = referenceSymbolDefinitionManager;
		}

		public override async Task HandleAsync(WorkspaceSymbolResolveRequest request, int requestId, CancellationToken cancellationToken)
		{
			PooledStopwatch stopwatch = ExternalTelemetryLogger.BeginOperation();
			try
			{
				ISymbol bestSymbolFound = null;
				WorkspaceSymbol responseSymbol = null;
				foreach (Project project in base.Workspace.CurrentSolution.Projects)
				{
					if (cancellationToken.IsCancellationRequested)
					{
						base.ResponseQueue.Add(ResponseFactory.WorkspaceSymbolResolve(CreateFallbackWorkspaceSymbol(request), requestId), cancellationToken);
						return;
					}
					if (project == null || request.Data == null)
					{
						continue;
					}
					Compilation compilation = await project.GetCompilationAsync(cancellationToken);
					if (compilation == null)
					{
						continue;
					}
					ISymbol firstSymbolForId = SymbolId.GetFirstSymbolForId(request.Data.SymbolId, compilation);
					if (firstSymbolForId != null)
					{
						if (bestSymbolFound == null)
						{
							bestSymbolFound = firstSymbolForId;
						}
						else if (!bestSymbolFound.IsSourceSymbol() && firstSymbolForId.IsSourceSymbol())
						{
							bestSymbolFound = firstSymbolForId;
							break;
						}
					}
				}
				Symbol symbol = bestSymbolFound as Symbol;
				if ((object)symbol != null)
				{
					if (bestSymbolFound.IsSynthesized && bestSymbolFound.Kind == SymbolKind.GlobalVariable)
					{
						symbol = ((SynthesizedGlobalVariableSymbol)bestSymbolFound).Type.OriginalDefinition;
					}
					LaunchConfiguration configuration = null;
					Definition definition = new Definition();
					if (symbol.Location == null || !symbol.Location.IsInSource)
					{
						definition = await referenceSymbolDefinitionManager.TryGetDefinitionFromReference(bestSymbolFound, configuration, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
						if (definition == null)
						{
							base.ResponseQueue.Add(ResponseFactory.WorkspaceSymbolResolve(CreateFallbackWorkspaceSymbol(request), requestId), cancellationToken);
							return;
						}
					}
					else if (!TryGetDefinitionFromSource(symbol.Location, ref definition))
					{
						base.ResponseQueue.Add(ResponseFactory.WorkspaceSymbolResolve(CreateFallbackWorkspaceSymbol(request), requestId), cancellationToken);
						return;
					}
					if (definition != null && definition.Uri != null && definition.Range.HasValue)
					{
						responseSymbol = symbol.ToWorkspaceSymbol(definition.Uri, definition.Range.Value);
					}
				}
				if (responseSymbol == null)
				{
					responseSymbol = CreateFallbackWorkspaceSymbol(request);
				}
				base.ResponseQueue.Add(ResponseFactory.WorkspaceSymbolResolve(responseSymbol, requestId), cancellationToken);
			}
			catch
			{
				base.ResponseQueue.Add(ResponseFactory.WorkspaceSymbolResolve(CreateFallbackWorkspaceSymbol(request), requestId), cancellationToken);
			}
			finally
			{
				ExternalTelemetryLogger.EndOperation("WorkspaceSymbolResolveDuration", stopwatch, System.TimeSpan.MinValue);
			}
		}

		private WorkspaceSymbol CreateFallbackWorkspaceSymbol(WorkspaceSymbolResolveRequest request)
		{
			return new WorkspaceSymbol
			{
				Name = request.Name,
				ContainerName = request.ContainerName,
				Kind = request.Kind,
				Tags = request.Tags,
				Data = request.Data,
				Location = new Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.Contract.Location
				{
					Uri = request.Location?.Uri,
					Range = new Range
					{
						Start = new Position
						{
							Line = 0,
							Character = 0
						},
						End = new Position
						{
							Line = 0,
							Character = 0
						}
					}
				}
			};
		}

		private bool TryGetDefinitionFromSource(Microsoft.Dynamics.Nav.CodeAnalysis.Text.Location location, ref Definition definition)
		{
			if (location.SourceTree == null)
			{
				return false;
			}
			Document document = base.Workspace.CurrentSolution.GetDocument(location.SourceTree);
			if (document == null)
			{
				return false;
			}
			FileLinePositionSpan mappedLineSpan = location.GetMappedLineSpan();
			definition = new Definition
			{
				Uri = document.FilePath.GetUri(),
				Range = new Range
				{
					Start = new Position
					{
						Line = mappedLineSpan.StartLinePosition.Line,
						Character = mappedLineSpan.StartLinePosition.Character
					},
					End = new Position
					{
						Line = mappedLineSpan.EndLinePosition.Line,
						Character = mappedLineSpan.EndLinePosition.Character
					}
				}
			};
			return true;
		}
	}
}
namespace Microsoft.Dynamics.Nav.EditorServices.Protocol.LanguageServer.Extensions
{
	internal class DebugAdapterEvaluateExpressionProviderHandler : DebugAdapterRequestHandlerBase<DebugAdapterEvaluateExpressionRequest>
	{
		public override string EndpointName => "al/provideDebuggerEvaluateExpression";

		internal DebugAdapterEvaluateExpressionProviderHandler(IProxyBasedDebuggerService service, VsCodeWorkspace workspace, ResponseQueue responseQueue)
			: base(service, workspace, responseQueue)
		{
		}

		public override async Task HandleAsync(DebugAdapterEvaluateExpressionRequest request, int requestId, CancellationToken cancellationToken)
		{
			if (request == null || request.Uri == null)
			{
				base.Logger.Error(FormattableString.Invariant(FormattableStringFactory.Create("The request {0} has invalid input request.", "al/provideDebuggerEvaluateExpression")));
				base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId), cancellationToken);
				return;
			}
			string filePath = request.Uri.CreateUriFilePath();
			Document document = base.Workspace.GetDocument(filePath);
			if (document == null)
			{
				base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId), cancellationToken);
				return;
			}
			SourceText sourceText = await document.GetTextAsync(cancellationToken);
			LinePosition linePosition = new LinePosition(request.Position.Line, request.Position.Character);
			if (!(await document.IsPositionNotOnTokenTrivia(linePosition, cancellationToken)))
			{
				base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId), cancellationToken);
				return;
			}
			SyntaxTree syntaxTree = await document.GetSyntaxTreeAsync(cancellationToken);
			if (syntaxTree == null)
			{
				base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId), cancellationToken);
				return;
			}
			int position = sourceText.Lines.GetPosition(linePosition);
			if (syntaxTree.IsInNonUserCode(position, cancellationToken))
			{
				base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId), cancellationToken);
				return;
			}
			SyntaxNode standaloneNode = SyntaxFactory.GetStandaloneNode(Microsoft.Dynamics.Nav.CodeAnalysis.Syntax.SyntaxTreeExtensions.FindTokenOnLeftOfPosition(syntaxTree, position, cancellationToken).Parent);
			if (standaloneNode.IsKind(SyntaxKind.IdentifierName, SyntaxKind.MemberAccessExpression, SyntaxKind.OptionAccessExpression) && (standaloneNode.Kind != SyntaxKind.MemberAccessExpression || !standaloneNode.ParentIsKind(SyntaxKind.InvocationExpression)))
			{
				CreateResponse(requestId, sourceText, standaloneNode.Position, standaloneNode.EndPosition, cancellationToken, standaloneNode.ToString());
			}
			else
			{
				base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId), cancellationToken);
			}
		}

		private void CreateResponse(int requestId, SourceText sourceText, int startPosition, int endposition, CancellationToken cancellationToken, string epression = null)
		{
			LinePosition linePosition = sourceText.Lines.GetLinePosition(startPosition);
			LinePosition linePosition2 = sourceText.Lines.GetLinePosition(Math.Max(endposition - 1, 0));
			Range range = default(Range);
			range.Start = new Position
			{
				Line = linePosition.Line,
				Character = linePosition.Character
			};
			range.End = new Position
			{
				Line = linePosition2.Line,
				Character = linePosition2.Character
			};
			Range range2 = range;
			base.ResponseQueue.Add(ResponseFactory.DebugAdapterEvaluateExpressionResponse(requestId, range2, epression?.ToString()), cancellationToken);
		}
	}
