	internal class AlDefinitionRequestHandler : NavServerRequestHandler<AlDefinitionRequest, LaunchConfiguration>
	{
		private readonly ReferenceSymbolDefinitionManager referenceSymbolDefinitionManager;

		public override string EndpointName => "al/gotodefinition";

		internal AlDefinitionRequestHandler(VsCodeWorkspace workspace, ReferenceSymbolDefinitionManager referenceSymbolDefinitionManager, ResponseQueue responseQueue)
			: base(workspace, responseQueue)
		{
			this.referenceSymbolDefinitionManager = referenceSymbolDefinitionManager;
		}

		protected override async Task ProcessRequestAsync(AlDefinitionRequest request, int requestId, CancellationToken cancellationToken)
		{
			ISymbol symbol = null;
			Response response;
			if (request.SymbolId != null)
			{
				Compilation compilation = await base.Workspace.CurrentSolution.GetCompilationAsync(base.Workspace.CurrentProjectId, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				symbol = SymbolId.GetFirstSymbolForId(request.SymbolId, compilation);
			}
			else
			{
				string text = request?.TextDocumentPositionParams?.TextDocument?.FileName;
				if (string.IsNullOrEmpty(text))
				{
					base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId), cancellationToken);
					return;
				}
				Document document = base.Workspace.GetDocument(text);
				if (document == null)
				{
					Uri previewUri = new Uri(text);
					Definition definition = await referenceSymbolDefinitionManager.GetDefinitionForSymbolAtPositionAsync(previewUri, request.TextDocumentPositionParams.Position, request.Configuration, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
					if (definition != null)
					{
						response = ResponseFactory.Definition(definition, requestId);
						base.ResponseQueue.Add(response, cancellationToken);
						return;
					}
				}
				else if (base.Workspace.AreAllProjectReferencesBound(document))
				{
					symbol = await document.GetSymbolAtPositionAsync(new LinePosition(request.TextDocumentPositionParams.Position.Line, request.TextDocumentPositionParams.Position.Character), cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				}
			}
			if (symbol == null)
			{
				base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId), cancellationToken);
				return;
			}
			if (symbol.IsSynthesized & (symbol.Kind == SymbolKind.GlobalVariable))
			{
				symbol = ((SynthesizedGlobalVariableSymbol)symbol).Type.OriginalDefinition;
			}
			response = await GetResponseForSymbol(requestId, symbol, request.TextDocumentPositionParams?.Position, request.Configuration, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
			base.ResponseQueue.Add(response, cancellationToken);
		}

		private async Task<Response> GetResponseForSymbol(int requestId, ISymbol symbol, Position? requestPosition, LaunchConfiguration launchConfiguration, CancellationToken cancellationToken)
		{
			Definition definition = new Definition();
			if (symbol.Location == null || !symbol.Location.IsInSource)
			{
				definition = await referenceSymbolDefinitionManager.TryGetDefinitionFromReference(symbol, launchConfiguration, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				if (definition == null)
				{
					return ResponseFactory.EmptyResponse(requestId);
				}
			}
			else
			{
				if (requestPosition != null && symbol.IsPositionOnTheLocationOfApplicationObjectReference(requestPosition))
				{
					return await GetResponseForSymbol(requestId, symbol.GetTypeSymbol()?.OriginalDefinition, requestPosition, launchConfiguration, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				}
				if (!TryGetDefinitionFromSource(symbol.Location, ref definition))
				{
					return ResponseFactory.EmptyResponse(requestId);
				}
			}
			return ResponseFactory.Definition(definition, requestId);
		}

		private bool TryGetDefinitionFromSource(Microsoft.Dynamics.Nav.CodeAnalysis.Text.Location location, ref Definition definition)
		{
			Document document = base.Workspace.CurrentSolution.GetDocument(location.SourceTree);
			if (document == null)
			{
				return false;
			}
			FileLinePositionSpan mappedLineSpan = location.GetMappedLineSpan();
			definition = new Definition
			{
				Uri = document.FilePath.GetUri(),
				Range = new Range
				{
					Start = new Position
					{
						Line = mappedLineSpan.StartLinePosition.Line,
						Character = mappedLineSpan.StartLinePosition.Character
					},
					End = new Position
					{
						Line = mappedLineSpan.EndLinePosition.Line,
						Character = mappedLineSpan.EndLinePosition.Character
					}
				}
			};
			return true;
		}
	}
	internal static class BuildAndPublishHelper
	{
		public static async Task<bool> BuildAndPublishProjectsAsync(VsCodeWorkspace workspace, IEmitLogger logger, Func<PublishOptions, CancellationToken, Task<PublishResult>> publishCallback, IFileSystem fileSystem, ICollection<ProjectId> projectIds, string projectDir, IList<string> args, PublishOptions publishOptions, bool forceBuildOfAllDependencies, string vsCodeExtensionVersion, CustomTelemetryEvent? telemetryEvent, IResponseQueue responseQueue, CancellationToken cancellationToken, bool addProjectArgument = false)
		{
			if (projectIds == null || projectIds.Count == 0)
			{
				logger.Error(ProtocolResources.FullDependencyPublishWorkspaceNotLoaded);
				return false;
			}
			if (projectIds.Count > 1)
			{
				telemetryEvent = null;
			}
			Solution currentSolution = workspace.CurrentSolution;
			foreach (ProjectId projectId in projectIds)
			{
				if (!workspace.AreAllProjectReferencesBound(projectId))
				{
					Project project2 = currentSolution.GetProject(projectId);
					logger.Error(string.Format(CultureInfo.InvariantCulture, ProtocolResources.FullDependencyPublishProjectNotBuilt, project2?.Name ?? projectId.ToString()));
					return false;
				}
			}
			PooledDictionary<ProjectId, string> outputFileLookup = PooledDictionary<ProjectId, string>.GetInstance();
			PooledHashSet<ProjectId> allBuiltProjects = PooledHashSet<ProjectId>.GetInstance();
			try
			{
				foreach (ProjectId projectId2 in projectIds)
				{
					cancellationToken.ThrowIfCancellationRequested();
					Project project = currentSolution.GetProject(projectId2);
					if (project == null)
					{
						logger.Error(string.Format(CultureInfo.InvariantCulture, ProtocolResources.FullDependencyPublishProjectNotBuilt, projectId2.ToString()));
						return false;
					}
					string text = (string.IsNullOrEmpty(projectDir) ? project.ProjectFolder : projectDir);
					if (string.IsNullOrEmpty(text))
					{
						logger.Error(string.Format(CultureInfo.InvariantCulture, ProtocolResources.FullDependencyPublishProjectNotBuilt, project.Name));
						return false;
					}
					IList<string> list = args;
					if (addProjectArgument)
					{
						list = new List<string>();
						bool flag = false;
						if (args != null)
						{
							foreach (string arg in args)
							{
								list.Add(arg);
								if (arg.StartsWith("-project:", StringComparison.OrdinalIgnoreCase))
								{
									flag = true;
								}
							}
						}
						if (!flag)
						{
							list.Add(string.Format(CultureInfo.InvariantCulture, "-project:\"{0}\"", text));
						}
					}
					(bool, ImmutableArray<(ProjectId, string)>) tuple = await ActiveProjectBuilder.BuildWorkspaceAsync(cancellationToken, fileSystem, workspace, text, list, buildDependencyPackage: true, isRad: false, responseQueue, forceBuildOfAllDependencies, telemetryEvent, TelemetryServiceManager.CurrentTelemetryService, vsCodeExtensionVersion, logger).ConfigureAwait(continueOnCapturedContext: false);
					if (!tuple.Item1)
					{
						logger.Error(string.Format(CultureInfo.InvariantCulture, ProtocolResources.FullDependencyPublishPublishingFailed, project.Name));
						return false;
					}
					ImmutableArray<(ProjectId, string)>.Enumerator enumerator4 = tuple.Item2.GetEnumerator();
					while (enumerator4.MoveNext())
					{
						(ProjectId, string) current4 = enumerator4.Current;
						if (!outputFileLookup.ContainsKey(current4.Item1))
						{
							outputFileLookup.Add(current4.Item1, current4.Item2);
							allBuiltProjects.Add(current4.Item1);
						}
					}
				}
				List<ProjectId> sortedProjects = (forceBuildOfAllDependencies ? GetSortedProjectsForFullDependencyPublish(currentSolution, workspace.CurrentProjectId) : GetSortedProjectsForSelectivePublish(currentSolution, allBuiltProjects));
				return await PublishProjectsAsync(workspace, logger, publishCallback, fileSystem, sortedProjects, outputFileLookup, publishOptions, currentSolution, telemetryEvent, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
			}
			finally
			{
				outputFileLookup.Free();
				allBuiltProjects.Free();
			}
		}

		private static List<ProjectId> GetSortedProjectsForFullDependencyPublish(Solution currentSolution, ProjectId currentProjectId)
		{
			List<ProjectId> list = new List<ProjectId>();
			foreach (ProjectId item in currentSolution.GetProjectDependencyGraph().GetProjectsThatThisProjectTransitivelyDependsOnTopologicallySorted(currentProjectId))
			{
				list.Add(item);
			}
			list.Add(currentProjectId);
			return list;
		}

		private static List<ProjectId> GetSortedProjectsForSelectivePublish(Solution currentSolution, PooledHashSet<ProjectId> builtProjects)
		{
			List<ProjectId> list = new List<ProjectId>();
			ProjectDependencyGraph projectDependencyGraph = currentSolution.GetProjectDependencyGraph();
			foreach (ProjectId builtProject in builtProjects)
			{
				if (list.Contains(builtProject))
				{
					continue;
				}
				foreach (ProjectId item in projectDependencyGraph.GetProjectsThatThisProjectTransitivelyDependsOnTopologicallySorted(builtProject))
				{
					if (builtProjects.Contains(item) && !list.Contains(item))
					{
						list.Add(item);
					}
				}
				list.Add(builtProject);
			}
			return list;
		}

		public static async Task<bool> PublishProjectsAsync(VsCodeWorkspace workspace, IEmitLogger logger, Func<PublishOptions, CancellationToken, Task<PublishResult>> publishCallback, IFileSystem fileSystem, List<ProjectId> sortedProjects, PooledDictionary<ProjectId, string> outputFileLookup, PublishOptions publishOptions, Solution currentSolution, CustomTelemetryEvent? telemetryEvent, CancellationToken cancellationToken)
		{
			logger.Info(string.Format(CultureInfo.InvariantCulture, ProtocolResources.FullDependencyPublishPreparingToPublish, sortedProjects.Count));
			telemetryEvent?.Metrics.Add("PublishCount", sortedProjects.Count);
			for (int j = 0; j < sortedProjects.Count; j++)
			{
				ProjectId projectId = sortedProjects[j];
				Project project2 = currentSolution.GetProject(projectId);
				if (project2 == null)
				{
					logger.Error(string.Format(CultureInfo.InvariantCulture, ProtocolResources.FullDependencyPublishProjectNotBuilt, projectId.ToString()));
					return false;
				}
				if (!outputFileLookup.ContainsKey(projectId))
				{
					logger.Error(string.Format(CultureInfo.InvariantCulture, ProtocolResources.FullDependencyPublishProjectNotBuilt, project2.Name));
					return false;
				}
				logger.Info(FormattableString.Invariant($"{j + 1}. {project2.Name}"));
			}
			for (int i = 0; i < sortedProjects.Count; i++)
			{
				cancellationToken.ThrowIfCancellationRequested();
				ProjectId projectId2 = sortedProjects[i];
				Project project = currentSolution.GetProject(projectId2);
				logger.Info(string.Format(CultureInfo.InvariantCulture, ProtocolResources.FullDependencyPublishPublishing, i + 1, sortedProjects.Count, project.Name));
				string path = outputFileLookup[projectId2];
				publishOptions.Directory = Path.GetDirectoryName(path);
				publishOptions.PackageFileName = Path.GetFileName(path);
				publishOptions.DependencyPublishingOption = DependencyPublishingOption.Ignore;
				PublishResult publishResult;
				try
				{
					publishResult = await publishCallback(publishOptions, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				}
				catch (Exception ex)
				{
					logger.Error(string.Format(CultureInfo.InvariantCulture, ProtocolResources.FullDependencyPublishPublishingFailed, project.Name));
					logger.Error(ex.ToString());
					return false;
				}
				if (!publishResult.Success)
				{
					logger.Error(string.Format(CultureInfo.InvariantCulture, ProtocolResources.FullDependencyPublishPublishingFailed, project.Name));
					logger.Error(FormattableString.Invariant($"Failed to publish: {project.Name}"));
					return false;
				}
				EmptyRadContext(workspace, fileSystem, project);
				logger.Info(string.Format(CultureInfo.InvariantCulture, ProtocolResources.FullDependencyPublishPublishDone, i + 1, sortedProjects.Count, project.Name));
			}
			return true;
		}

		private static void EmptyRadContext(VsCodeWorkspace workspace, IFileSystem fileSystem, Project project)
		{
			IObjectChangeManager objectChangeManager = workspace.ObjectChangeDocumentManager.GetObjectChangeManager(project.Id);
			if (objectChangeManager != null)
			{
				string text = project.ProjectFolder.RadPath();
				if (!string.IsNullOrEmpty(text))
				{
					fileSystem.EmptyRadFile(objectChangeManager, text);
				}
			}
		}
	}
