	internal class DebuggerConsoleCompletionRequestHandler : ProjectRequestHandler<DebuggerConsoleCompletionRequest>
	{
		private readonly ReferenceSymbolDefinitionManager referenceSymbolDefinitionManager;

		private readonly IDiagnosticService diagnosticService;

		public override string EndpointName => "al/debuggerConsoleCompletionRequest";

		internal DebuggerConsoleCompletionRequestHandler(IDiagnosticService diagnosticService, VsCodeWorkspace workspace, ReferenceSymbolDefinitionManager referenceSymbolDefinitionManager, ResponseQueue responseQueue)
			: base(workspace, responseQueue)
		{
			this.referenceSymbolDefinitionManager = referenceSymbolDefinitionManager;
			this.diagnosticService = diagnosticService;
		}

		public override async Task HandleAsync(DebuggerConsoleCompletionRequest request, int requestId, CancellationToken cancellationToken)
		{
			HashSet<Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.Contract.CompletionItem> completions = new HashSet<Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.Contract.CompletionItem>();
			if (request.Text == null)
			{
				base.ResponseQueue.Add(ResponseFactory.DebuggerConsoleCompletionResponse(requestId, completions));
				return;
			}
			Project currentProject = base.Workspace.GetCurrentProject();
			if (currentProject == null)
			{
				base.ResponseQueue.Add(ResponseFactory.DebuggerConsoleCompletionResponse(requestId, completions));
				return;
			}
			Compilation obj = await currentProject.GetCompilationAsync(cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
			SymbolKind kind = DebugHelper.MapToSymbolKind((ObjectTypeWrapper)request.ObjectType);
			ApplicationObjectTypeSymbol applicationObjectTypeSymbol = obj.GetApplicationObjectTypeSymbolsByIdAcrossModules(kind, request.ObjectId).FirstOrDefault() as ApplicationObjectTypeSymbol;
			if (applicationObjectTypeSymbol == null)
			{
				base.ResponseQueue.Add(ResponseFactory.DebuggerConsoleCompletionResponse(requestId, completions));
				return;
			}
			Solution oldSolution = base.Workspace.CurrentSolution;
			Document document = null;
			Microsoft.Dynamics.Nav.CodeAnalysis.Text.Location location = null;
			try
			{
				diagnosticService?.Stop();
				location = applicationObjectTypeSymbol.GetLocation();
				if (!(location != null))
				{
					return;
				}
				if (location.IsInSource)
				{
					document = base.Workspace.GetDocument(location.SourceTree.FilePath);
				}
				else
				{
					string previewUrl = FilePathHelper.GetPreviewFileUri(currentProject.ProjectFolder, request.ObjectId, applicationObjectTypeSymbol.Name, kind);
					Uri previewUri = new Uri(previewUrl);
					string item2 = (await referenceSymbolDefinitionManager.GetContentAsync(previewUri, null, cancellationToken).ConfigureAwait(continueOnCapturedContext: false)).Item1;
					if (!string.IsNullOrEmpty(item2))
					{
						document = currentProject.AddDocument($"{kind}_{request.ObjectId}", item2, null, previewUrl);
					}
				}
				if (document == null)
				{
					return;
				}
				SourceText sourceText = await document.GetTextAsync(cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				if (sourceText == null)
				{
					return;
				}
				int line = location.GetLineSpan().StartLinePosition.Line;
				int line2 = ((ushort)request.Line).ConvertClientLineToDebuggerLine() + line;
				LinePosition position = new LinePosition(line2, 0);
				int methodStartPosition = sourceText.Lines.GetPosition(position);
				SyntaxTree syntaxTree = await document.GetSyntaxTreeAsync(cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				SyntaxNode root = await syntaxTree.GetRootAsync(cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				SyntaxToken syntaxToken = Microsoft.Dynamics.Nav.CodeAnalysis.Syntax.SyntaxTreeExtensions.FindTokenOnLeftOfPosition(syntaxTree, methodStartPosition, cancellationToken);
				BlockSyntax blockSyntax = ((syntaxToken.Parent.Kind == SyntaxKind.Block) ? (syntaxToken.Parent as BlockSyntax) : syntaxToken.Parent.GetAncestor<BlockSyntax>());
				if (blockSyntax == null)
				{
					return;
				}
				StatementSyntax node = SyntaxFactory.ParseStatement(request.Text);
				node = node.WithLeadingTrivia(SyntaxFactory.Space);
				if (string.IsNullOrWhiteSpace(request.Text))
				{
					node = node.WithLeadingTrivia(SyntaxFactory.Space);
				}
				int num = ((blockSyntax.Statements.Count == 0) ? blockSyntax.BeginKeywordToken.EndPosition : blockSyntax.Statements[blockSyntax.Statements.Count - 1].EndPosition);
				BlockSyntax newNode = blockSyntax.AddStatements(node);
				SyntaxNode root2 = root.ReplaceNode(blockSyntax, newNode);
				Document newDocument = document.WithSyntaxRoot(root2);
				int caretPosition = ((!string.IsNullOrWhiteSpace(request.Text)) ? (num + node.FullWidth) : (num + node.FullWidth - 1));
				Microsoft.Dynamics.Nav.CodeAnalysis.Workspaces.Completion.CompletionList completionList = await CompletionService.GetService(newDocument).GetCompletionsAsync(newDocument, caretPosition, CompletionTrigger.CreateDebuggerConsoleCompletion(), null, null, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				if (completionList == null)
				{
					return;
				}
				ImmutableArray<Microsoft.Dynamics.Nav.CodeAnalysis.Workspaces.Completion.CompletionItem>.Enumerator enumerator = completionList.Items.GetEnumerator();
				while (enumerator.MoveNext())
				{
					Microsoft.Dynamics.Nav.CodeAnalysis.Workspaces.Completion.CompletionItem item = enumerator.Current;
					Glyph glyph = item.GetGlyphForCompletionItem();
					if (await ShouldIncludeItem(item, newDocument, glyph, cancellationToken).ConfigureAwait(continueOnCapturedContext: false))
					{
						completions.Add(new Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.Contract.CompletionItem
						{
							Kind = glyph.MapToKind(),
							Label = new CompletionItemLabel
							{
								Label = item.DisplayText,
								Description = item.DescriptionValue
							},
							FilterText = item.FilterText,
							InsertText = item.InsertionText,
							Detail = item.DetailText,
							SortText = glyph.ToString() + item.SortText
						});
					}
				}
			}
			catch (Exception e)
			{
				LoggingUtilities.WriteMessageFailedException("DebuggerConsoleCompletionRequestHandler", e);
			}
			finally
			{
				Solution currentSolution = base.Workspace.CurrentSolution;
				if (location != null && !location.IsInSource && document != null && currentSolution.ContainsDocument(document.Id))
				{
					currentSolution.RemoveDocument(document.Id);
				}
				diagnosticService?.Start();
				base.Workspace.SetCurrentSolution(oldSolution);
				base.ResponseQueue.Add(ResponseFactory.DebuggerConsoleCompletionResponse(requestId, completions));
			}
		}

		private static async Task<bool> ShouldIncludeItem(Microsoft.Dynamics.Nav.CodeAnalysis.Workspaces.Completion.CompletionItem item, Document document, Glyph glyph, CancellationToken cancellationToken)
		{
			ImmutableArray<ISymbol> immutableArray = await SymbolCompletionItem.GetSymbolsAsync(item, document, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
			if (immutableArray.Length > 0)
			{
				return immutableArray[0].Kind.CanParticipateInDebuggerConsoleRecommendation();
			}
			switch (glyph)
			{
			default:
				return false;
			case Glyph.Parameter:
			case Glyph.LocalVariable:
			case Glyph.GlobalVariable:
			case Glyph.Field:
			case Glyph.Class:
			case Glyph.Table:
			case Glyph.Codeunit:
			case Glyph.Report:
			case Glyph.Query:
			case Glyph.XmlPort:
			case Glyph.Page:
			case Glyph.Reference:
			case Glyph.Option:
			case Glyph.Enum:
			case Glyph.EnumValue:
			case Glyph.Interface:
			case Glyph.Namespace:
				return true;
			}
		}
	}
	internal class GetApiPagesRequestHandler : RequestHandlerBase<GetApiPagesRequest>
	{
		public override string EndpointName => "al/getApiPages";

		internal GetApiPagesRequestHandler(VsCodeWorkspace workspace, ResponseQueue responseQueue)
			: base(workspace, (IResponseQueue)responseQueue)
		{
		}

		public override async Task HandleAsync(GetApiPagesRequest request, int requestId, CancellationToken cancellationToken)
		{
			Project defaultProject = base.Workspace.GetCurrentProject();
			if (defaultProject == null || !base.Workspace.AreAllProjectReferencesBound(defaultProject.Id))
			{
				base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId));
				return;
			}
			Compilation compilation = await base.Workspace.CurrentSolution.GetCompilationAsync(defaultProject.Id, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
			if (compilation == null)
			{
				base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId));
				return;
			}
			ApiObject[] apiObjects = GetApiObjects(compilation, defaultProject.ProjectFolder);
			base.ResponseQueue.Add(ResponseFactory.CreateGetApplicationObjectsResponse(requestId, apiObjects), cancellationToken);
		}

		public static ApiObject[] GetApiObjects(Compilation compilation, string defaultProjectFolder)
		{
			using PooledList<ApiObject> pooledList = PooledList<ApiObject>.GetInstance();
			IEnumerable<PageTypeSymbol> pageObjects = compilation.GetObjectSymbolsByKindAcrossModules(SymbolKind.Page, accessibleOnly: true).Cast<PageTypeSymbol>();
			IEnumerable<QueryTypeSymbol> queryObjects = compilation.GetObjectSymbolsByKindAcrossModules(SymbolKind.Query, accessibleOnly: true).Cast<QueryTypeSymbol>();
			AddPages(defaultProjectFolder, pageObjects, pooledList);
			AddQueries(defaultProjectFolder, queryObjects, pooledList);
			return pooledList.ToArray();
		}

		private static void AddPages(string defaultProjectFolder, IEnumerable<PageTypeSymbol> pageObjects, PooledList<ApiObject> apis)
		{
			foreach (PageTypeSymbol pageObject in pageObjects)
			{
				if (pageObject.PageType == PageTypeKind.API)
				{
					AddSymbol(defaultProjectFolder, apis, pageObject);
				}
			}
		}

		private static void AddQueries(string defaultProjectFolder, IEnumerable<QueryTypeSymbol> queryObjects, PooledList<ApiObject> apis)
		{
			foreach (QueryTypeSymbol queryObject in queryObjects)
			{
				if (queryObject.QueryType == QueryTypeKind.API)
				{
					AddSymbol(defaultProjectFolder, apis, queryObject);
				}
			}
		}

		private static void AddSymbol(string defaultProjectFolder, PooledList<ApiObject> apis, Symbol symbolObject)
		{
			string name = symbolObject.Name.QuoteIdentifierIfNeeded();
			IModuleSymbol containingModule = symbolObject.ContainingModule;
			Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.Contract.Location location = null;
			string sourceLocation = Microsoft.Dynamics.Nav.EditorServices.Protocol.Utility.SymbolExtensions.GetSourceLocation(defaultProjectFolder, symbolObject);
			if (sourceLocation != null)
			{
				location = Microsoft.Dynamics.Nav.EditorServices.Protocol.Utility.SymbolExtensions.GetSymbolLocation(sourceLocation, symbolObject);
			}
			apis.Add(new ApiObject
			{
				Name = name,
				Id = ((symbolObject is ISymbolWithId symbolWithId) ? symbolWithId.Id : 0),
				Type = symbolObject.Kind,
				Namespace = symbolObject.ContainingNamespace?.ToDisplayString(),
				EntityName = symbolObject.GetPropertySymbol(PropertyKind.EntityName)?.ValueText,
				ApiGroup = symbolObject.GetPropertySymbol(PropertyKind.APIGroup)?.ValueText,
				ApiPublisher = symbolObject.GetPropertySymbol(PropertyKind.APIPublisher)?.ValueText,
				AppId = containingModule?.AppId.ToString(),
				AppName = containingModule?.Name,
				AppPublisher = containingModule?.Publisher,
				AppVersion = containingModule?.Version.ToString(),
				Location = location
			});
		}
	}
	internal class GetApplicationObjectRequestHandler : RequestHandlerBase<GetApplicationObjectRequest>
	{
		private readonly ReferenceSymbolDefinitionManager referenceSymbolDefinitionManager;

		public override string EndpointName => "al/getApplicationObject";

		internal GetApplicationObjectRequestHandler(VsCodeWorkspace workspace, ReferenceSymbolDefinitionManager referenceSymbolDefinitionManager, ResponseQueue responseQueue)
			: base(workspace, (IResponseQueue)responseQueue)
		{
			this.referenceSymbolDefinitionManager = referenceSymbolDefinitionManager;
		}

		public override async Task HandleAsync(GetApplicationObjectRequest request, int requestId, CancellationToken cancellationToken)
		{
			GetApplicationObjectRequest request2 = request;
			Project defaultProject = base.Workspace.GetCurrentProject();
			if (defaultProject == null || !base.Workspace.AreAllProjectReferencesBound(defaultProject.Id))
			{
				base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId));
				return;
			}
			Compilation compilation = await base.Workspace.CurrentSolution.GetCompilationAsync(defaultProject.Id, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
			if (compilation == null)
			{
				base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId));
				return;
			}
			ImmutableArray<IApplicationObjectTypeSymbol> immutableArray = ((request2.Id != 0) ? compilation.GetApplicationObjectTypeSymbolsByIdAcrossModules(request2.Type, request2.Id) : compilation.GetApplicationObjectTypeSymbolsByNameAcrossModulesAndNamespaces(request2.Type, request2.Name));
			if (immutableArray.IsDefaultOrEmpty)
			{
				base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId));
				return;
			}
			IApplicationObjectTypeSymbol applicationObjectTypeSymbol = immutableArray.FirstOrDefault((IApplicationObjectTypeSymbol ao) => request2.AppId == null || ao.ContainingModule.AppId.ToString() == request2.AppId);
			if (applicationObjectTypeSymbol == null)
			{
				base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId));
			}
			else if (request2.FieldName != null)
			{
				Symbol firstField = ((TableTypeSymbol)applicationObjectTypeSymbol).GetFirstField(request2.FieldName, compilation);
				if (firstField == null)
				{
					base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId));
					return;
				}
				ApplicationObjectMember appObjMember = await Microsoft.Dynamics.Nav.EditorServices.Protocol.Utility.SymbolExtensions.AssignToApplicationObjectMemberAsync(firstField, referenceSymbolDefinitionManager, cancellationToken);
				base.ResponseQueue.Add(ResponseFactory.CreateGetApplicationObjectMemberResponse(requestId, appObjMember), cancellationToken);
			}
			else
			{
				ApplicationObjectDetails applicationObjectDetails = Microsoft.Dynamics.Nav.EditorServices.Protocol.Utility.SymbolExtensions.AssignToApplicationObject(new ApplicationObjectDetails(), applicationObjectTypeSymbol, defaultProject.ProjectFolder);
				applicationObjectDetails.DocComment = applicationObjectTypeSymbol.GetDocumentationComment(cancellationToken);
				applicationObjectDetails.Details = SerializableSymbolModelConverter.SerializeObjectTypeSymbol(applicationObjectTypeSymbol, compilation.RuntimeVersion);
				base.ResponseQueue.Add(ResponseFactory.CreateGetApplicationObjectResponse(requestId, applicationObjectDetails), cancellationToken);
			}
		}
	}
	internal class GetApplicationObjectsRequestHandler : RequestHandlerBase<GetApplicationObjectsRequest>
	{
		public override string EndpointName => "al/getApplicationObjects";

		internal GetApplicationObjectsRequestHandler(VsCodeWorkspace workspace, ResponseQueue responseQueue)
			: base(workspace, (IResponseQueue)responseQueue)
		{
		}

		public override async Task HandleAsync(GetApplicationObjectsRequest request, int requestId, CancellationToken cancellationToken)
		{
			object result = null;
			if (request.TextDocument?.FileName != null)
			{
				Document document = base.Workspace.GetDocument(request.TextDocument.FileName);
				if (document != null)
				{
					IList<ISymbol> list = await document.GetSymbols(cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
					if (list != null && list.Count > 0)
					{
						IModuleSymbol containingModule = list[0].ContainingModule;
						result = new object[1]
						{
							new
							{
								AppId = containingModule?.AppId.ToString(),
								AppName = containingModule?.Name,
								AppPublisher = containingModule?.Publisher,
								AppVersion = containingModule?.Version.ToString(),
								Objects = list.Select((ISymbol symbol) => Microsoft.Dynamics.Nav.EditorServices.Protocol.Utility.SymbolExtensions.ToApplicationObject(symbol, document.Project.ProjectFolder, skipModule: true))?.ToArray()
							}
						};
					}
				}
				base.ResponseQueue.Add(ResponseFactory.CreateGetApplicationObjectsResponse(requestId, result), cancellationToken);
				return;
			}
			Project defaultProject = base.Workspace.GetCurrentProject();
			if (defaultProject == null || !base.Workspace.AreAllProjectReferencesBound(defaultProject.Id))
			{
				base.ResponseQueue.Add(ResponseFactory.CreateGetApplicationObjectsResponse(requestId, result), cancellationToken);
				return;
			}
			Compilation compilation = await base.Workspace.CurrentSolution.GetCompilationAsync(defaultProject.Id, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
			if (compilation == null)
			{
				base.ResponseQueue.Add(ResponseFactory.CreateGetApplicationObjectsResponse(requestId, result), cancellationToken);
				return;
			}
			IEnumerable<ISymbol> source;
			if (!request.ObjectTypeFilter.HasValue)
			{
				IEnumerable<ISymbol> enumerable = SymbolKindExtensions.AllRootObjectSymbolKinds.Where(IncludedSymbolKinds).AsParallel().WithCancellation(cancellationToken)
					.SelectMany((SymbolKind kind) => compilation.GetObjectSymbolsByKindAcrossModules(kind));
				source = enumerable;
			}
			else
			{
				source = compilation.GetObjectSymbolsByKindAcrossModules(request.ObjectTypeFilter.Value);
			}
			var appObjs = (from obj in source
				group obj by obj.ContainingModule.AppId).Select(delegate(IGrouping<Guid, ISymbol> group)
			{
				IModuleSymbol containingModule2 = group.First().ContainingModule;
				return new
				{
					AppId = containingModule2?.AppId.ToString(),
					AppName = containingModule2?.Name,
					AppPublisher = containingModule2?.Publisher,
					AppVersion = containingModule2?.Version.ToString(),
					Objects = group.Select(delegate(ISymbol obj)
					{
						string sourceLocation = GetSourceLocation(defaultProject, obj);
						if (sourceLocation != null)
						{
							GetSymbolLocation(sourceLocation, obj);
						}
						return Microsoft.Dynamics.Nav.EditorServices.Protocol.Utility.SymbolExtensions.ToApplicationObject(obj, defaultProject.ProjectFolder, skipModule: true);
					})
				};
			}).ToArray();
			base.ResponseQueue.Add(ResponseFactory.CreateGetApplicationObjectsResponse(requestId, appObjs), cancellationToken);
		}

		internal static bool IncludedSymbolKinds(SymbolKind kind)
		{
			if ((uint)(kind - 113) <= 1u)
			{
				return false;
			}
			return kind.IsObjectTypeSymbol();
		}

		internal string? GetSourceLocation(Project project, ISymbol symbol)
		{
			return Microsoft.Dynamics.Nav.EditorServices.Protocol.Utility.SymbolExtensions.GetSourceLocation(project.ProjectFolder, symbol);
		}

		internal static Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.Contract.Location GetSymbolLocation(string fileName, ISymbol symbol)
		{
			if (symbol.Location == null)
			{
				return new Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.Contract.Location();
			}
			FileLinePositionSpan lineSpan = symbol.Location.GetLineSpan();
			return new Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.Contract.Location
			{
				Uri = fileName,
				Range = new Range
				{
					Start = new Position
					{
						Line = lineSpan.StartLinePosition.Line,
						Character = lineSpan.StartLinePosition.Character
					},
					End = new Position
					{
						Line = lineSpan.EndLinePosition.Line,
						Character = lineSpan.EndLinePosition.Character
					}
				}
			};
		}
	}
	internal class GetExtensibleEnumsRequestHandler : RequestHandlerBase<GetExtensibleEnumsRequest>
	{
		public override string EndpointName => "al/getExtensibleEnums";

		internal GetExtensibleEnumsRequestHandler(VsCodeWorkspace workspace, ResponseQueue responseQueue)
			: base(workspace, (IResponseQueue)responseQueue)
		{
		}

		public override async Task HandleAsync(GetExtensibleEnumsRequest request, int requestId, CancellationToken cancellationToken)
		{
			Project defaultProject = base.Workspace.GetCurrentProject();
			if (defaultProject == null || !base.Workspace.AreAllProjectReferencesBound(defaultProject.Id))
			{
				base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId));
				return;
			}
			Compilation compilation = await base.Workspace.CurrentSolution.GetCompilationAsync(defaultProject.Id, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
			if (compilation == null)
			{
				base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId));
				return;
			}
			ExtensibleEnumObject[] extensibleEnumObjects = GetExtensibleEnumObjects(compilation, defaultProject.ProjectFolder);
			base.ResponseQueue.Add(ResponseFactory.CreateGetApplicationObjectsResponse(requestId, extensibleEnumObjects), cancellationToken);
		}

		public static ExtensibleEnumObject[] GetExtensibleEnumObjects(Compilation compilation, string defaultProjectFolder)
		{
			PooledList<ExtensibleEnumObject> instance = PooledList<ExtensibleEnumObject>.GetInstance();
			IEnumerable<EnumTypeSymbol> enumerable = compilation.GetObjectSymbolsByKindAcrossModules(SymbolKind.Enum, accessibleOnly: true).Cast<EnumTypeSymbol>();
			try
			{
				foreach (EnumTypeSymbol item in enumerable)
				{
					if (item.IsExtensible && item.ImplementedInterfaces.Any())
					{
						string name = item.Name.QuoteIdentifierIfNeeded();
						IModuleSymbol containingModule = item.ContainingModule;
						Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.Contract.Location location = null;
						string sourceLocation = Microsoft.Dynamics.Nav.EditorServices.Protocol.Utility.SymbolExtensions.GetSourceLocation(defaultProjectFolder, item);
						if (sourceLocation != null)
						{
							location = Microsoft.Dynamics.Nav.EditorServices.Protocol.Utility.SymbolExtensions.GetSymbolLocation(sourceLocation, item);
						}
						instance.Add(new ExtensibleEnumObject
						{
							Name = name,
							Id = (((ISymbolWithId)item)?.Id ?? 0),
							Type = item.Kind,
							Namespace = item.ContainingNamespace?.ToDisplayString(),
							AppId = containingModule?.AppId.ToString(),
							AppName = containingModule?.Name,
							AppPublisher = containingModule?.Publisher,
							AppVersion = containingModule?.Version.ToString(),
							Location = location
						});
					}
				}
				return instance.ToArray();
			}
			finally
			{
				instance.Free();
			}
		}
	}
	internal class SetSymbolMembersRequestHandler : SymbolRequestHandler<SetSymbolMemberRequest>
	{
		public override string EndpointName => "al/setSymbolMembers";

		internal SetSymbolMembersRequestHandler(VsCodeWorkspace workspace, ResponseQueue responseQueue)
			: base(workspace, responseQueue)
		{
		}

		public override async Task HandleAsync(SetSymbolMemberRequest request, int requestId, CancellationToken cancellationToken)
		{
			if (request.TextDocument?.FileName == null)
			{
				base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId));
				return;
			}
			Document document = base.Workspace.GetDocument(request.TextDocument.FileName);
			if (document == null)
			{
				base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId));
				return;
			}
			SyntaxNode symbolSyntax = await SymbolRequestHandler<SetSymbolMemberRequest>.GetSymbolSyntax(request, document, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
			if (symbolSyntax == null)
			{
				base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId));
				return;
			}
			WorkspaceEdit edit = new WorkspaceEdit();
			SourceText sourceText = await document.GetTextAsync().ConfigureAwait(continueOnCapturedContext: false);
			if (request.NewName != null)
			{
				SetMemberName(request.NewName, request.TextDocument.Uri, symbolSyntax, edit, sourceText);
			}
			if (request.NewId.HasValue)
			{
				SetMemberId(request.NewId.Value, request.TextDocument.Uri, symbolSyntax, edit, sourceText);
			}
			if (request.NewType != null)
			{
				SetMemberType(request.NewType, request.TextDocument.Uri, symbolSyntax, edit, sourceText);
			}
			base.ResponseQueue.Add(ResponseFactory.SetObjectInfo(requestId, edit));
		}

		private static void SetMemberId(int id, string uri, SyntaxNode? symbolSyntax, WorkspaceEdit edit, SourceText sourceText)
		{
			SyntaxNodeOrToken? syntaxNodeOrToken = symbolSyntax.GetIdNodeOrToken();
			if (syntaxNodeOrToken.HasValue)
			{
				edit.Add(uri, new TextEdit
				{
					NewText = id.ToStringInvariant(),
					Range = sourceText.Lines.GetLinePositionSpan(syntaxNodeOrToken.Value.Span)
				});
			}
		}

		private static void SetMemberName(string name, string uri, SyntaxNode? symbolSyntax, WorkspaceEdit edit, SourceText sourceText)
		{
			IdentifierNameSyntax identifierNameSyntax = symbolSyntax.GetIdentifierNameSyntax();
			if (identifierNameSyntax != null)
			{
				edit.Add(uri, new TextEdit
				{
					NewText = name.QuoteIdentifierIfNeeded(),
					Range = sourceText.Lines.GetLinePositionSpan(identifierNameSyntax.Identifier.Span)
				});
			}
		}

		private static void SetMemberType(string type, string uri, SyntaxNode symbolSyntax, WorkspaceEdit edit, SourceText sourceText)
		{
			if (symbolSyntax.Kind != SyntaxKind.Field)
			{
				throw ExceptionUtilities.UnexpectedValue(symbolSyntax.Kind);
			}
			DataTypeSyntax type2 = ((FieldSyntax)symbolSyntax).Type;
			if (type2 != null)
			{
				edit.Add(uri, new TextEdit
				{
					NewText = type,
					Range = sourceText.Lines.GetLinePositionSpan(type2.Span)
				});
			}
		}
	}
	internal class SetSymbolPropertyRequestHandler : SymbolRequestHandler<SetSymbolPropertyRequest>
	{
		public override string EndpointName => "al/setSymbolProperty";

		internal SetSymbolPropertyRequestHandler(VsCodeWorkspace workspace, ResponseQueue responseQueue)
			: base(workspace, responseQueue)
		{
		}

		public override async Task HandleAsync(SetSymbolPropertyRequest request, int requestId, CancellationToken cancellationToken)
		{
			if (request.TextDocument?.FileName == null)
			{
				return;
			}
			Document document = base.Workspace.GetDocument(request.TextDocument.FileName);
			if (document == null)
			{
				return;
			}
			SyntaxNode symbolSyntax = await SymbolRequestHandler<SetSymbolPropertyRequest>.GetSymbolSyntax(request, document, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
			if (symbolSyntax == null || !symbolSyntax.GetPropertyTypeInfos().TryGetValue(request.PropertyName.ToUpperInvariant(), out PropertyTypeInfo propertyInfo))
			{
				return;
			}
			SourceText sourceText = await document.GetTextAsync().ConfigureAwait(continueOnCapturedContext: false);
			PropertySyntax property = symbolSyntax.GetProperty(request.PropertyName);
			string text = FormatValue(propertyInfo, request.Value);
			if (property != null)
			{
				WorkspaceEdit workspaceEdit = new WorkspaceEdit();
				workspaceEdit.Add(request.TextDocument.Uri, new TextEdit
				{
					NewText = text,
					Range = sourceText.Lines.GetLinePositionSpan(property.Value.FullSpan)
				});
				base.ResponseQueue.Add(ResponseFactory.SetSymbolProperty(requestId, workspaceEdit));
				return;
			}
			string text2 = request.PropertyName + " = " + text + ";\n";
			SyntaxList<PropertySyntaxOrEmpty> propertyList = symbolSyntax.GetPropertyList();
			Range range2;
			if (propertyList.Count == 0)
			{
				text2 = new string(' ', sourceText.Lines.GetLinePosition(symbolSyntax.GetFirstToken().SpanStart).Character + 4) + text2;
				SyntaxToken syntaxToken = symbolSyntax.DescendantTokens().FirstOrDefault((SyntaxToken t) => t.Kind == SyntaxKind.OpenBraceToken);
				if (syntaxToken.Kind != SyntaxKind.OpenBraceToken)
				{
					return;
				}
				LinePosition linePosition = sourceText.Lines.GetLinePosition(syntaxToken.EndPosition);
				Range range = default(Range);
				range.Start = linePosition;
				range.End = linePosition;
				range2 = range;
			}
			else
			{
				PropertySyntaxOrEmpty propertySyntaxOrEmpty = propertyList.Last();
				int count = 0;
				if (propertySyntaxOrEmpty.Kind == SyntaxKind.Property)
				{
					PropertyNameSyntax name = ((PropertySyntax)propertySyntaxOrEmpty).Name;
					count = sourceText.Lines.GetLinePosition(name.GetFirstToken().SpanStart).Character;
				}
				text2 = new string(' ', count) + text2;
				LinePosition linePosition2 = sourceText.Lines.GetLinePosition(propertySyntaxOrEmpty.GetLastToken().EndPosition);
				Range range = default(Range);
				range.Start = linePosition2;
				range.End = linePosition2;
				range2 = range;
			}
			WorkspaceEdit workspaceEdit2 = new WorkspaceEdit();
			workspaceEdit2.Add(request.TextDocument.Uri, new TextEdit
			{
				NewText = text2,
				Range = range2
			});
			base.ResponseQueue.Add(ResponseFactory.SetSymbolProperty(requestId, workspaceEdit2));
		}

		private static string FormatValue(PropertyTypeInfo propertyInfo, string value)
		{
			if (propertyInfo.ParserName == "StringLiteral")
			{
				return value.QuoteLiteral();
			}
			return value;
		}
	}
	internal abstract class SymbolRequestHandler<T> : RequestHandlerBase<T> where T : SymbolRequest
	{
		internal SymbolRequestHandler(VsCodeWorkspace workspace, ResponseQueue responseQueue)
			: base(workspace, (IResponseQueue)responseQueue)
		{
		}

		protected static async Task<SyntaxNode?> GetSymbolSyntax(T request, Document document, CancellationToken cancellationToken)
		{
			T request2 = request;
			if (!document.TryGetSyntaxTree(out SyntaxTree syntaxTree))
			{
				return null;
			}
			SyntaxKind rootSyntaxKind = request2.RootKind.ToSyntaxKind();
			SyntaxNode syntaxNode = (from ObjectSyntax node in from node in (await syntaxTree.GetRootAsync(cancellationToken)).DescendantNodes((SyntaxNode node) => !node.Kind.IsObject())
					where node.Kind == rootSyntaxKind
					select node
				where SemanticFacts.IsSameName(node.Name.Unquoted(), request2.RootName)
				select node).FirstOrDefault();
			if (syntaxNode == null)
			{
				return null;
			}
			if (request2.RootKind != request2.SymbolKind)
			{
				syntaxNode = (from node in syntaxNode.DescendantNodes()
					where request2.SymbolKind.IsValidSyntaxKind(node.Kind)
					where SemanticFacts.IsSameName(node.GetIdentifierNameSyntax().Unquoted(), request2.SymbolName)
					select node).FirstOrDefault();
			}
			return syntaxNode;
		}
	}
