	internal class DownloadSourceRequestHandler : NavServerRequestHandler<DownloadSourceRequest, ServerConnectionConfiguration>
	{
		public override string EndpointName => "al/downloadSource";

		public DownloadSourceRequestHandler(VsCodeWorkspace workspace, ResponseQueue responseQueue)
			: base(workspace, responseQueue)
		{
		}

		protected override async Task ProcessRequestAsync(DownloadSourceRequest request, int requestId, CancellationToken cancellationToken)
		{
			Project defaultProject = base.Workspace.GetCurrentProject();
			if (await ContainsErrors().ConfigureAwait(continueOnCapturedContext: false))
			{
				base.Logger.Error(ProtocolResources.ProjectContainsErrors);
				base.ResponseQueue.Add(ResponseFactory.CreateDownloadSourceResponse(requestId, new WorkspaceEdit(), Array.Empty<NewTextDocument>(), success: false));
				return;
			}
			bool success = false;
			WorkspaceEdit result = new WorkspaceEdit();
			PooledList<NewTextDocument> newFiles = PooledList<NewTextDocument>.GetInstance();
			try
			{
				ProjectManifest projectManifest = ProjectLoader.LoadFromFile(defaultProject.FilePath);
				if (projectManifest != null)
				{
					NavDevServerPackageDownloader navDevServerPackageDownloader = new NavDevServerPackageDownloader(request.Configuration.CreateConnectionOptions(), base.Logger);
					SymbolReferenceSpecification package = new SymbolReferenceSpecification(projectManifest.AppManifest.AppPublisher, projectManifest.AppManifest.AppName, projectManifest.AppManifest.AppVersion, exact: false, projectManifest.AppManifest.AppId, isPropagated: false, projectManifest.AppManifest.AppAlternateIds);
					using (Stream packageStream = await navDevServerPackageDownloader.DownloadPackage(package))
					{
						using NavAppPackageReader reader = NavAppPackageReader.Create(packageStream);
						await SourceFilesManipulation(reader, defaultProject, result, newFiles);
					}
					success = true;
				}
				else
				{
					base.Logger.Error(DeploymentResources.FileInvalidOrDoesNotExistError, defaultProject.FilePath);
				}
				base.ResponseQueue.Add(ResponseFactory.CreateDownloadSourceResponse(requestId, result, newFiles.ToArray(), success), cancellationToken);
			}
			finally
			{
				newFiles.Free();
			}
		}

		private async Task<bool> ContainsErrors()
		{
			if (base.Workspace.CurrentSolution == null)
			{
				return false;
			}
			IEnumerable<PublishDiagnosticsResponse> item = (await DiagnosticsProvider.GetDiagnosticsForProjects(base.Workspace.CurrentSolution, new HashSet<ProjectId> { base.Workspace.CurrentProjectId }, CancellationToken.None).ConfigureAwait(continueOnCapturedContext: false)).Item1;
			foreach (PublishDiagnosticsResponse item2 in item)
			{
				if (item2.Diagnostics.Any((ProtocolDiagnostic d) => d.Severity.HasValue && ProtocolDiagnosticSeverity.Error.Equals(d.Severity.Value)))
				{
					return true;
				}
			}
			return false;
		}

		private static async Task SourceFilesManipulation(NavAppPackageReader packageReader, Project defaultProject, WorkspaceEdit workspaceEdits, PooledList<NewTextDocument> newFiles)
		{
			foreach (string item in packageReader.ReadSourceContents())
			{
				SyntaxTree syntaxTree = SyntaxFactory.ParseSyntaxTree(SourceText.From(item), "", defaultProject.ParseOptions);
				foreach (ObjectSyntax packageApplicationObject in syntaxTree.GetRoot().DescendantNodes().OfType<ObjectSyntax>())
				{
					if (!packageApplicationObject.Kind.IsRootObject())
					{
						continue;
					}
					bool foundObject = false;
					foreach (Document document in defaultProject.Documents)
					{
						IEnumerable<ObjectSyntax> enumerable = (await document.GetSyntaxRootAsync()).DescendantNodes().OfType<ObjectSyntax>();
						foreach (ObjectSyntax currentObject in enumerable)
						{
							if (IsSameObject(currentObject, packageApplicationObject))
							{
								foundObject = true;
								if (!currentObject.IsEquivalentTo(packageApplicationObject))
								{
									SourceText sourceText = await document.GetTextAsync();
									TextEdit edit = new TextEdit
									{
										NewText = packageApplicationObject.ToFullString(),
										Range = sourceText.Lines.GetLinePositionSpan(currentObject.FullSpan)
									};
									workspaceEdits.Add(document.FilePath.GetUri(), edit);
									break;
								}
							}
						}
						if (foundObject)
						{
							break;
						}
					}
					if (!foundObject)
					{
						string fileName = FilePathHelper.RemoveInvalidCharactersFromFileName(packageApplicationObject.Name.Unquoted()) + ".al";
						newFiles.Add(new NewTextDocument
						{
							FileName = fileName,
							Content = packageApplicationObject.ToFullString()
						});
					}
				}
			}
		}

		private static bool IsSameObject(ObjectSyntax downloadedObject, ObjectSyntax currentObject)
		{
			if (!currentObject.Kind.IsRootObject())
			{
				return false;
			}
			if (downloadedObject.Kind != currentObject.Kind)
			{
				return false;
			}
			if (currentObject.Kind == SyntaxKind.DotNetPackage)
			{
				return true;
			}
			return SemanticFacts.IsSameName(currentObject.Name.Identifier.ValueText, downloadedObject.Name.Identifier.ValueText);
		}
	}
	internal class DownloadSymbolsFromGlobalSourcesRequestHandler : NavServerRequestHandler<DownloadSymbolsFromGlobalSourcesRequest, LaunchConfiguration>
	{
		private readonly ReferenceSymbolDefinitionManager referenceSymbolDefinitionManager;

		public override string EndpointName => "al/downloadSymbolsFromGlobalSources";

		public override bool ProfilePerformance => true;

		internal DownloadSymbolsFromGlobalSourcesRequestHandler(VsCodeWorkspace workspace, ReferenceSymbolDefinitionManager referenceSymbolDefinitionManager, ResponseQueue responseQueue)
			: base(workspace, responseQueue)
		{
			this.referenceSymbolDefinitionManager = referenceSymbolDefinitionManager;
		}

		protected override async Task ProcessRequestAsync(DownloadSymbolsFromGlobalSourcesRequest request, int requestId, CancellationToken cancellationToken)
		{
			if (request == null)
			{
				base.Logger.Error(ProtocolResources.InvalidRequest);
				base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId));
				return;
			}
			Project currentProject = base.Workspace.GetCurrentProject();
			if (currentProject == null)
			{
				base.Logger.Error(ProtocolResources.CannotDownloadSymbolsForProjectThatHasNotLoaded);
				base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId));
				return;
			}
			IEnumerable<string> packageCachePaths = currentProject.PackageCachePaths;
			base.Logger.Info(ProtocolResources.UsingPackageCachePath, string.Join(", ", packageCachePaths));
			ProjectManifest projectManifest = ProjectLoader.LoadFromFile(currentProject.FilePath);
			if (projectManifest == null)
			{
				base.Logger.Error(string.Format(CultureInfo.CurrentCulture, "Project file {0} is invalid or does not exist", currentProject.FilePath));
				base.ResponseQueue.Add(ResponseFactory.CreateDownloadSymbolsFromGlobalSourcesResponse(requestId, success: false), cancellationToken);
				return;
			}
			IList<SymbolReferenceSpecification> symbolReferences = base.Workspace.GetSymbolReferencesThatAreNotProjectReferences(currentProject.Id, projectManifest).ToList();
			if (projectManifest.AppManifest.DependencyReferences != null)
			{
				List<SymbolReferenceSpecification> list = projectManifest.AppManifest.DependencyReferences.ToList();
				base.Logger.Info("Checking {0} dependencies from manifest:", list.Count);
				foreach (SymbolReferenceSpecification dep in list)
				{
					base.Logger.Info("  Checking dependency: {0} {1} (AppId: {2})", dep.Name, dep.Publisher, dep.AppId);
					SymbolReferenceSpecification symbolReferenceSpecification = symbolReferences.FirstOrDefault((SymbolReferenceSpecification sr) => sr.AppId.ToString() == dep.AppId.ToString());
					if (symbolReferenceSpecification == null)
					{
						base.Logger.Info("    -> Adding missing dependency: {0}", dep.Name);
						symbolReferences.Add(dep);
					}
					else
					{
						base.Logger.Info("    -> Dependency already exists: {0}", symbolReferenceSpecification.Name);
					}
				}
			}
			base.Logger.Info("Final reference list contains {0} symbol references:", symbolReferences.Count);
			foreach (SymbolReferenceSpecification item in symbolReferences)
			{
				base.Logger.Info("  - {0} {1} (Publisher: {2}, AppId: {3})", item.Name, item.Version, item.Publisher, item.AppId);
			}
			base.Logger.Info("Manifest contains:");
			if (projectManifest.AppManifest.AppReference != null)
			{
				base.Logger.Info("  AppReference: {0} {1}", projectManifest.AppManifest.AppReference.Name, projectManifest.AppManifest.AppReference.Publisher);
			}
			if (projectManifest.AppManifest.PlatformReference != null)
			{
				base.Logger.Info("  PlatformReference: {0} {1}", projectManifest.AppManifest.PlatformReference.Name, projectManifest.AppManifest.PlatformReference.Publisher);
			}
			if (projectManifest.AppManifest.DependencyReferences != null)
			{
				List<SymbolReferenceSpecification> list2 = projectManifest.AppManifest.DependencyReferences.ToList();
				base.Logger.Info("  DependencyReferences ({0} items):", list2.Count);
				foreach (SymbolReferenceSpecification item2 in list2)
				{
					base.Logger.Info("    -> {0} {1} (AppId: {2})", item2.Name, item2.Publisher, item2.AppId);
				}
			}
			else
			{
				base.Logger.Info("  DependencyReferences: None");
			}
			int count = symbolReferences.Count;
			GetCustomTelemetryForRequest(requestId).Metrics.Add("Number of packages", count);
			GetCustomTelemetryForRequest(requestId).Dimensions.Add("Download method", "NuGet");
			ImmutableArray<SymbolReferenceSpecification> referencesToDownload = symbolReferences.ToImmutableArray();
			IDiagnosticService diagnosticService = (IDiagnosticService)base.Workspace.ProjectClosureCompilation;
			diagnosticService?.Stop();
			try
			{
				ImmutableArray<SymbolReferenceSpecification> immutableArray = await DownloadFiles(request, Path.Combine(base.Workspace.CurrentProjectFolder, packageCachePaths.First()), referencesToDownload).ConfigureAwait(continueOnCapturedContext: false);
				bool flag = immutableArray.Length >= referencesToDownload.Length;
				base.Workspace.SymbolReferenceLoader.InvalidateDependencies(immutableArray);
				base.Workspace.UpdateSymbolReferences(symbolReferences);
				referenceSymbolDefinitionManager.ClearContent();
				if (flag && immutableArray.Length > 0)
				{
					base.Logger.Info($"Successfully downloaded symbols from global sources: {immutableArray.Length} packages are available");
				}
				else if (immutableArray.Length > 0)
				{
					base.Logger.Info($"{immutableArray.Length} packages are available (requested {referencesToDownload.Length})");
				}
				else
				{
					base.Logger.Info("No packages are available");
				}
				base.ResponseQueue.Add(ResponseFactory.CreateDownloadSymbolsFromGlobalSourcesResponse(requestId, flag), cancellationToken);
			}
			catch (Exception ex)
			{
				base.Logger.Error("Error occurred while downloading packages from NuGet feeds: {0}", ex.Message);
				base.ResponseQueue.Add(ResponseFactory.CreateDownloadSymbolsFromGlobalSourcesResponse(requestId, success: false), cancellationToken);
			}
			finally
			{
				diagnosticService?.Start(forceNewCompilation: true);
			}
		}

		private async Task<ImmutableArray<SymbolReferenceSpecification>> DownloadFiles(DownloadSymbolsFromGlobalSourcesRequest request, string cacheDirectory, ImmutableArray<SymbolReferenceSpecification> referencesToDownload)
		{
			base.Logger.Info($"Downloading {referencesToDownload.Length} packages from NuGet feeds to {cacheDirectory}");
			string text = request.SymbolsCountryRegion ?? "w1";
			base.Logger.Info("Using symbols country/region: " + text);
			IReadOnlyList<string> nugetFeeds = request.NugetFeeds;
			bool useOnlyCustomFeeds = request.UseOnlyCustomFeeds;
			if (nugetFeeds != null && nugetFeeds.Count > 0)
			{
				base.Logger.Info($"Using {nugetFeeds.Count} custom NuGet feed(s)");
				foreach (string item in nugetFeeds)
				{
					base.Logger.Info("  - " + item);
				}
				if (useOnlyCustomFeeds)
				{
					base.Logger.Info("Only searching custom feeds (built-in Microsoft feeds will not be used)");
				}
			}
			return await new NuGetPackageDownloader(base.Logger, text, nugetFeeds, useOnlyCustomFeeds).DownloadPackages(referencesToDownload, cacheDirectory);
		}

		private IEnumerable<SymbolReferenceSpecification> FindReferencesToDownload(DownloadSymbolsFromGlobalSourcesRequest request, Project project, IEnumerable<SymbolReferenceSpecification> allReferences)
		{
			if (request.Force)
			{
				Solution currentSolution = base.Workspace.CurrentSolution;
				currentSolution = currentSolution.RemoveSymbolReferences(project.Id, project.SymbolReferences);
				base.Workspace.TryApplyChanges(currentSolution);
				return allReferences;
			}
			new LocalCacheSymbolReferenceAnalyzer(project.PackageCachePaths).FindMissingReferences(allReferences, out IEnumerable<SymbolReferenceSpecification> missingReferences);
			return missingReferences.ToImmutableArray();
		}
	}
	internal class DownloadSymbolsRequestHandler : NavServerRequestHandler<DownloadSymbolsRequest, LaunchConfiguration>
	{
		private readonly ReferenceSymbolDefinitionManager referenceSymbolDefinitionManager;

		public override string EndpointName => "al/downloadSymbols";

		public override bool ProfilePerformance => true;

		internal DownloadSymbolsRequestHandler(VsCodeWorkspace workspace, ReferenceSymbolDefinitionManager referenceSymbolDefinitionManager, ResponseQueue responseQueue)
			: base(workspace, responseQueue)
		{
			this.referenceSymbolDefinitionManager = referenceSymbolDefinitionManager;
		}

		protected override async Task ProcessRequestAsync(DownloadSymbolsRequest request, int requestId, CancellationToken cancellationToken)
		{
			if (request == null || request.Configuration == null || request.Configuration.CreateConnectionOptions() == null)
			{
				base.Logger.Error(ProtocolResources.InvalidRequest);
				base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId));
				return;
			}
			Project defaultProject = base.Workspace.GetCurrentProject();
			if (defaultProject == null)
			{
				base.Logger.Error(ProtocolResources.CannotDownloadSymbolsForProjectThatHasNotLoaded);
				base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId));
				return;
			}
			IEnumerable<string> cacheDirectories = defaultProject.PackageCachePaths;
			base.Logger.Info(ProtocolResources.UsingPackageCachePath, string.Join(", ", cacheDirectories));
			ProjectManifest manifest = ProjectLoader.LoadFromFile(defaultProject.FilePath);
			if (manifest == null)
			{
				base.Logger.Error(string.Format(DeploymentResources.FileInvalidOrDoesNotExistError, defaultProject.FilePath));
				base.ResponseQueue.Add(ResponseFactory.CreateDownloadSymbolsResponse(requestId, success: false), cancellationToken);
				return;
			}
			if (request.IsForSnapshotEndpoint)
			{
				ConnectionOptions options = request.Configuration.CreateConnectionOptions();
				ServerInfo serverInfo = await ServerRegistry.SnapshotInstance.GetServerInfo(options, base.Logger).ConfigureAwait(continueOnCapturedContext: false);
				if (serverInfo == null || !serverInfo.Supports(SnapshotApiFeature.DownloadSymbols))
				{
					string message = string.Format(CultureInfo.CurrentCulture, ProtocolResources.DownloadingSymbolsForSnapshotContextNotSupported, request.Configuration.Name);
					base.Logger.Error(message);
					base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId));
					return;
				}
			}
			IList<SymbolReferenceSpecification> symbolReferences = base.Workspace.GetSymbolReferencesThatAreNotProjectReferences(defaultProject.Id, manifest).ToList();
			int referencesToDownloadCount = symbolReferences.Count;
			GetCustomTelemetryForRequest(requestId).Metrics.Add("Number of packages", referencesToDownloadCount);
			GetCustomTelemetryForRequest(requestId).Dimensions.Add("Is for snapshot endpoint", request.IsForSnapshotEndpoint.ToString());
			ImmutableArray<SymbolReferenceSpecification> referencesToDownload = symbolReferences.ToImmutableArray();
			bool flag = false;
			if (!request.IsForSnapshotEndpoint)
			{
				referencesToDownload = FindReferencesToDownload(request, defaultProject, symbolReferences).ToImmutableArray();
				referencesToDownloadCount = referencesToDownload.Length;
				flag = referencesToDownloadCount == 0;
			}
			IDiagnosticService diagnosticService = (IDiagnosticService)base.Workspace.ProjectClosureCompilation;
			diagnosticService?.Stop();
			try
			{
				if (!flag)
				{
					ImmutableArray<SymbolReferenceSpecification> immutableArray = await DownloadFiles(request, Path.Combine(base.Workspace.CurrentProjectFolder, cacheDirectories.First()), referencesToDownload).ConfigureAwait(continueOnCapturedContext: false);
					flag = immutableArray.Length == referencesToDownloadCount;
					base.Workspace.SymbolReferenceLoader.InvalidateDependencies(immutableArray);
					base.Workspace.UpdateSymbolReferences(symbolReferences);
					referenceSymbolDefinitionManager.ClearContent();
					base.Logger.Info(flag ? ProtocolResources.SymbolsDownloaded : ProtocolResources.SymbolsNotDownloaded);
				}
				else
				{
					base.Logger.Info(ProtocolResources.AllSymbolsInCache);
				}
			}
			finally
			{
				diagnosticService?.Start(forceNewCompilation: true);
			}
			base.ResponseQueue.Add(ResponseFactory.CreateDownloadSymbolsResponse(requestId, flag), cancellationToken);
		}

		private async Task<ImmutableArray<SymbolReferenceSpecification>> DownloadFiles(DownloadSymbolsRequest request, string cacheDirectory, ImmutableArray<SymbolReferenceSpecification> referencesToDownload)
		{
			ConnectionOptions options = request.Configuration.CreateConnectionOptions();
			IPackageDownloader packageDownloader = ((!request.IsForSnapshotEndpoint) ? ((IPackageDownloader)new NavDevServerPackageDownloader(options, base.Logger)) : ((IPackageDownloader)new NavProductionServerPackageDownloader(options, base.Logger)));
			return await packageDownloader.DownloadPackages(referencesToDownload, cacheDirectory);
		}

		private IEnumerable<SymbolReferenceSpecification> FindReferencesToDownload(DownloadSymbolsRequest request, Project project, IEnumerable<SymbolReferenceSpecification> allReferences)
		{
			if (request.Force)
			{
				Solution currentSolution = base.Workspace.CurrentSolution;
				currentSolution = currentSolution.RemoveSymbolReferences(project.Id, project.SymbolReferences);
				base.Workspace.TryApplyChanges(currentSolution);
				return allReferences;
			}
			new LocalCacheSymbolReferenceAnalyzer(project.PackageCachePaths).FindMissingReferences(allReferences, out IEnumerable<SymbolReferenceSpecification> missingReferences);
			return missingReferences.ToImmutableArray();
		}
	}
