	internal class GenerateCpuProfileOutputRequestHandler : RequestHandlerBase<GenerateCpuProfileOutputRequest>
	{
		private const string OutputExtension = ".alcpuprofile";

		public override string EndpointName => "al/generatecpuprofile";

		internal IFileSystem? FileSystem { get; set; }

		internal GenerateCpuProfileOutputRequestHandler(VsCodeWorkspace workspace, ResponseQueue responseQueue)
			: base(workspace, (IResponseQueue)responseQueue)
		{
		}

		public override async Task HandleAsync(GenerateCpuProfileOutputRequest request, int requestId, CancellationToken cancellationToken)
		{
			IEmitLogger logger = new OutputConsoleLogger(base.ResponseQueue);
			string profileOutputPath = string.Empty;
			if (!TryExtractIfOnlySamplingProfileFile(request.Url, logger, out profileOutputPath))
			{
				profileOutputPath = await GenerateCpuProfileOutput(request, requestId, logger, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
			}
			base.ResponseQueue.Add(ResponseFactory.GenerateProfileOutputResponse(requestId, profileOutputPath), cancellationToken);
		}

		private bool TryExtractIfOnlySamplingProfileFile(string snapshotFilePath, IEmitLogger logger, out string profileOutputPath)
		{
			profileOutputPath = string.Empty;
			if (!File.Exists(snapshotFilePath))
			{
				logger.Error(string.Format(CultureInfo.CurrentCulture, ProtocolResources.ProfileGenerationFailedWrongsnapshotFileParameter, snapshotFilePath));
				return false;
			}
			using (ZipArchive zipArchive = CpuProfileGenerator.OpenZipArchive(snapshotFilePath, logger))
			{
				if (zipArchive == null)
				{
					return false;
				}
				if (zipArchive.Entries.Count != 1)
				{
					return false;
				}
				if (Path.GetExtension(zipArchive.Entries[0].Name).Equals(".alcpuprofile", StringComparison.OrdinalIgnoreCase))
				{
					try
					{
						string directoryName = Path.GetDirectoryName(snapshotFilePath);
						profileOutputPath = Path.Combine(directoryName, zipArchive.Entries[0].Name);
						zipArchive.Entries[0].ExtractToFile(profileOutputPath, overwrite: true);
						profileOutputPath = profileOutputPath.GetUri();
						return true;
					}
					finally
					{
						base.ResponseQueue.Add(ResponseFactory.ProgressNotification(new ProgressNotificatonResponse
						{
							Owner = ProgressNotificationOwner.Profiler,
							Percent = 100
						}), CancellationToken.None);
					}
				}
			}
			return false;
		}

		private async Task<string> GenerateCpuProfileOutput(GenerateCpuProfileOutputRequest request, int requestId, IEmitLogger logger, CancellationToken cancellationToken)
		{
			long startTime = Stopwatch.GetTimestamp();
			logger.Info(ProtocolResources.GeneratingProfile);
			CpuProfileGenerator generator = new CpuProfileGenerator(logger, base.Workspace, base.ResponseQueue, cancellationToken);
			string outputFileName = string.Empty;
			try
			{
				if (!(await generator.Initialize(request.Url)))
				{
					return outputFileName;
				}
				CpuProfile cpuProfile = await generator.GenerateProfile().ConfigureAwait(continueOnCapturedContext: false);
				if (cpuProfile == null)
				{
					return outputFileName;
				}
				outputFileName = Path.GetFileNameWithoutExtension(request.Url);
				string directoryName = Path.GetDirectoryName(request.Url);
				outputFileName = Path.Combine(directoryName, outputFileName + ".alcpuprofile");
				IFileSystem? obj = FileSystem ?? Microsoft.Dynamics.Nav.CodeAnalysis.FileSystem.Instance;
				UTF8Encoding encoding = new UTF8Encoding(encoderShouldEmitUTF8Identifier: false, throwOnInvalidBytes: false);
				using (Stream stream = obj.CreateFile(outputFileName))
				{
					using StreamWriter textWriter = new StreamWriter(stream, encoding, 1024, leaveOpen: true);
					Newtonsoft.Json.JsonSerializer jsonSerializer = Newtonsoft.Json.JsonSerializer.Create(SymbolReferenceJsonWriter.StandardSerializerSettings);
					jsonSerializer.ContractResolver = new CamelCasePropertyNamesContractResolver();
					jsonSerializer.Serialize(textWriter, cpuProfile);
				}
				long num = (Stopwatch.GetTimestamp() - startTime) / 10000000;
				CustomTelemetryEvent customTelemetryForRequest = GetCustomTelemetryForRequest(requestId);
				customTelemetryForRequest.Metrics.Add("ProfileGenerationTime", num);
				ExternalTelemetryLogger.TrackEvent(customTelemetryForRequest);
				logger.Info(ProtocolResources.ProfileGenerationSucceeded, outputFileName);
			}
			finally
			{
				generator.SendProgressNotificationResponse(100);
			}
			return outputFileName.GetUri();
		}
	}
	public class GeneratePermissionSetsAsALObjectRequestHandler : RequestHandlerBase<GeneratePermissionSetRequest>
	{
		public override string EndpointName => "al/generatePermissionSetInALObject";

		public GeneratePermissionSetsAsALObjectRequestHandler(VsCodeWorkspace workspace, IResponseQueue responseQueue)
			: base(workspace, responseQueue)
		{
		}

		public override async Task HandleAsync(GeneratePermissionSetRequest request, int requestId, CancellationToken cancellationToken)
		{
			try
			{
				await GenerateALObject(request, requestId, cancellationToken);
			}
			catch (Exception ex) when (ex is IOException || ex is UnauthorizedAccessException)
			{
				Response response = ResponseFactory.CreatePermissionSetInALObjectResponse(requestId, new WorkspaceEdit(), Array.Empty<NewTextDocument>(), success: false);
				base.ResponseQueue.Add(response, cancellationToken);
			}
		}

		private async Task GenerateALObject(GeneratePermissionSetRequest request, int requestId, CancellationToken cancellationToken)
		{
			if (!base.Workspace.AreAllProjectReferencesBound(base.Workspace.CurrentProjectId))
			{
				return;
			}
			Compilation compilation = await base.Workspace.CurrentSolution.GetCompilationAsync(base.Workspace.CurrentProjectId, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
			string text = (string.IsNullOrEmpty(request.PermissionSetName) ? "GeneratedPermissions" : request.PermissionSetName);
			string namespaceName = request.NamespaceName;
			OutputConsoleLogger outputConsoleLogger = new OutputConsoleLogger(base.ResponseQueue);
			try
			{
				CompilationUnitSyntax original;
				CompilationUnitSyntax newSyntax3;
				(original, newSyntax3) = PermissionSetGenerator.GenerateAlObject(compilation, text, namespaceName);
				if (newSyntax3 == null)
				{
					Response response = ResponseFactory.CreatePermissionSetInALObjectResponse(requestId, new WorkspaceEdit(), Array.Empty<NewTextDocument>(), success: false);
					base.ResponseQueue.Add(response, cancellationToken);
					return;
				}
				newSyntax3 = newSyntax3.NormalizeWhiteSpace("    ");
				newSyntax3 = EnsureWhitespace(newSyntax3);
				if (original != null)
				{
					Project currentProject = base.Workspace.GetCurrentProject();
					Document document = currentProject.GetDocument(original.SyntaxTree);
					WorkspaceEdit edits = new WorkspaceEdit();
					SourceText sourceText = await document.GetTextAsync(cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
					TextEdit edit = new TextEdit
					{
						NewText = newSyntax3.ToFullString(),
						Range = sourceText.Lines.GetLinePositionSpan(original.FullSpan)
					};
					edits.Add(document.FilePath.GetUri(), edit);
					Response response2 = ResponseFactory.CreatePermissionSetInALObjectResponse(requestId, edits, Array.Empty<NewTextDocument>(), success: true);
					base.ResponseQueue.Add(response2, cancellationToken);
				}
				else
				{
					string fileName = FilePathHelper.RemoveInvalidCharactersFromFileName(text) + ".permissionset.al";
					NewTextDocument[] newFiles = new NewTextDocument[1]
					{
						new NewTextDocument
						{
							FileName = fileName,
							Content = newSyntax3.ToFullString()
						}
					};
					Response response3 = ResponseFactory.CreatePermissionSetInALObjectResponse(requestId, new WorkspaceEdit(), newFiles, success: true);
					base.ResponseQueue.Add(response3, cancellationToken);
				}
			}
			catch (InvalidPermissionSetGenerationParameters invalidPermissionSetGenerationParameters)
			{
				outputConsoleLogger.Error(invalidPermissionSetGenerationParameters.Message);
				LocalMachineLogger.LogError(invalidPermissionSetGenerationParameters.Message);
				Response response4 = ResponseFactory.CreatePermissionSetInALObjectResponse(requestId, new WorkspaceEdit(), Array.Empty<NewTextDocument>(), success: false);
				base.ResponseQueue.Add(response4, cancellationToken);
			}
		}

		private static CompilationUnitSyntax EnsureWhitespace(CompilationUnitSyntax syntax)
		{
			NamespaceDeclarationSyntax namespaceDeclaration = syntax.NamespaceDeclaration;
			if (namespaceDeclaration == null)
			{
				return syntax;
			}
			syntax = syntax.WithNamespaceDeclaration(namespaceDeclaration.WithTrailingTrivia(SyntaxFactory.CarriageReturnLinefeed, SyntaxFactory.CarriageReturnLinefeed));
			if (syntax.Objects.Count == 0)
			{
				return syntax;
			}
			if (!(syntax.Objects[0] is PermissionSetSyntax))
			{
				return syntax;
			}
			SyntaxList<UsingDirectiveSyntax> usings = syntax.Usings;
			if (syntax.Usings.Count == 0)
			{
				return syntax;
			}
			UsingDirectiveSyntax usingDirectiveSyntax = usings.Last();
			usings = usings.Replace(usingDirectiveSyntax, usingDirectiveSyntax.WithTrailingTrivia(SyntaxFactory.CarriageReturnLinefeed, SyntaxFactory.CarriageReturnLinefeed));
			return syntax.WithUsings(usings);
		}
	}
