	internal class GetEventPublishersRequestHandler : RequestHandlerBase<GetEventPublishersRequest>
	{
		private static readonly ImmutableArray<SymbolKind> SymbolsWithEvents = new SymbolKind[9]
		{
			SymbolKind.Codeunit,
			SymbolKind.Page,
			SymbolKind.PageExtension,
			SymbolKind.Query,
			SymbolKind.Report,
			SymbolKind.ReportExtension,
			SymbolKind.Table,
			SymbolKind.TableExtension,
			SymbolKind.XmlPort
		}.ToImmutableArray();

		public override string EndpointName => "al/getEventPublishersRequest";

		internal GetEventPublishersRequestHandler(VsCodeWorkspace workspace, ResponseQueue responseQueue)
			: base(workspace, (IResponseQueue)responseQueue)
		{
		}

		public override async Task HandleAsync(GetEventPublishersRequest request, int requestId, CancellationToken cancellationToken)
		{
			Project defaultProject = base.Workspace.GetCurrentProject();
			if (defaultProject == null || !base.Workspace.AreAllProjectReferencesBound(defaultProject.Id))
			{
				base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId));
				return;
			}
			Compilation compilation = await base.Workspace.CurrentSolution.GetCompilationAsync(defaultProject.Id, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
			if (compilation == null)
			{
				base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId));
				return;
			}
			ParallelQuery<MethodSymbol> source = SymbolsWithEvents.AsParallel().WithCancellation(cancellationToken).SelectMany((SymbolKind kind) => compilation.GetApplicationObjectTypeSymbolsAcrossModules(kind, accessibleOnly: true))
				.SelectMany((IApplicationObjectTypeSymbol s) => s.QueryAllEvents(compilation))
				.Distinct();
			if (request.Format == EventPublisherFormat.Signature)
			{
				bool useIdentifiers = VersionChecker.IsSupported(compilation.CompiledModule, Feature.IdentifiersInEventSubscribers);
				EventSignature[] events = source.OrderBy<MethodSymbol, string>((MethodSymbol e) => e.Name, StringComparer.CurrentCultureIgnoreCase).Select(delegate(MethodSymbol e)
				{
					IApplicationObjectTypeSymbol applicationObjectOrTarget2 = GetApplicationObjectOrTarget(e.GetContainingApplicationObjectTypeSymbol());
					if (applicationObjectOrTarget2 == null)
					{
						return (EventSignature)null;
					}
					string text = applicationObjectOrTarget2.Name.QuoteIdentifierIfNeeded();
					string text2 = CreateMethodSignature(e, applicationObjectOrTarget2, text, asSubscriber: true);
					return new EventSignature
					{
						Label = e.Name.QuoteIdentifierIfNeeded(),
						Description = $"{applicationObjectOrTarget2.Kind} {text}",
						Signature = $"[EventSubscriber(ObjectType::{applicationObjectOrTarget2.Kind}, {applicationObjectOrTarget2.Kind.ToEnumObjectTypeString()}::{text}, {(useIdentifiers ? e.Name.QuoteIdentifierIfNeeded() : e.Name.QuoteLiteral())}, '', false, false)]\nlocal procedure {text2}\nbegin\nend;\n"
					};
				}).WhereNotNull()
					.ToArray();
				base.ResponseQueue.Add(ResponseFactory.CreateGetEventPublishersResponse(requestId, events), cancellationToken);
				return;
			}
			EventPublisher[] events2 = source.OrderBy<MethodSymbol, string>((MethodSymbol e) => e.Name, StringComparer.CurrentCultureIgnoreCase).Select(delegate(MethodSymbol e)
			{
				IApplicationObjectTypeSymbol applicationObjectOrTarget = GetApplicationObjectOrTarget(e.GetContainingApplicationObjectTypeSymbol());
				if (applicationObjectOrTarget == null)
				{
					return (EventPublisher)null;
				}
				string appObjName = applicationObjectOrTarget.Name.QuoteIdentifierIfNeeded();
				string signature = CreateMethodSignature(e, applicationObjectOrTarget, appObjName, asSubscriber: false);
				string subscriberSignature = CreateMethodSignature(e, applicationObjectOrTarget, appObjName, asSubscriber: true);
				return new EventPublisher
				{
					Name = e.Name.QuoteIdentifierIfNeeded(),
					Location = Microsoft.Dynamics.Nav.EditorServices.Protocol.Utility.SymbolExtensions.GetSymbolLocation(e, defaultProject.ProjectFolder),
					Signature = signature,
					SubscriberSignature = subscriberSignature,
					Path = Microsoft.Dynamics.Nav.EditorServices.Protocol.Utility.SymbolExtensions.GetSourceRelativePath(applicationObjectOrTarget),
					Host = Microsoft.Dynamics.Nav.EditorServices.Protocol.Utility.SymbolExtensions.ToApplicationObject(applicationObjectOrTarget, defaultProject.ProjectFolder),
					SymbolId = SymbolId.CreateId(e)
				};
			}).WhereNotNull()
				.ToArray();
			base.ResponseQueue.Add(ResponseFactory.CreateGetEventPublishersResponse(requestId, events2), cancellationToken);
		}

		private static IApplicationObjectTypeSymbol? GetApplicationObjectOrTarget(IApplicationObjectTypeSymbol? symbol)
		{
			IApplicationObjectTypeSymbol applicationObjectTypeSymbol = symbol;
			if (applicationObjectTypeSymbol == null)
			{
				return null;
			}
			if (applicationObjectTypeSymbol.Kind.IsExtensionObject())
			{
				applicationObjectTypeSymbol = ((IApplicationObjectExtensionTypeSymbol)applicationObjectTypeSymbol).Target;
			}
			return applicationObjectTypeSymbol;
		}

		private static string CreateMethodSignature(MethodSymbol methodSymbol, IApplicationObjectTypeSymbol appObj, string appObjName, bool asSubscriber)
		{
			string text = (asSubscriber ? (appObj.Name + "_" + methodSymbol.Name) : methodSymbol.Name).QuoteIdentifierIfNeeded();
			string text2 = text + methodSymbol.ToDisplayString(SymbolDisplayFormat.EventSnippetFormat);
			AttributeSymbol attributeSymbol = methodSymbol?.GetEventPublisherAttribute();
			if ((object)attributeSymbol != null && attributeSymbol.Arguments.Length > 0 && attributeSymbol.Arguments[0].ValueAsBoolean.Value)
			{
				int num = text.Length + 1;
				bool flag = text2[num] != ')';
				text2 = text2.Insert(num, "var Sender: " + appObj.Kind.ToVarDeclarationObjectTypeString() + " " + appObjName + (flag ? "; " : string.Empty));
			}
			return text2;
		}
	}
