	public class LoadManifestRequestHandler : RequestHandlerBase<LoadManifestRequest>
	{
		public override string EndpointName => "al/loadManifest";

		internal LoadManifestRequestHandler(VsCodeWorkspace workspace, ResponseQueue responseQueue)
			: base(workspace, (IResponseQueue)responseQueue)
		{
		}

		public override async Task HandleAsync(LoadManifestRequest request, int requestId, CancellationToken cancellationToken)
		{
			try
			{
				List<Diagnostic> diagnostics = new List<Diagnostic>();
				ProjectManifestProps projectManifestProps = ProjectManifestProps.LoadFromFile(request.ProjectFolder, diagnostics);
				if (projectManifestProps == null && !string.IsNullOrEmpty(request.Manifest))
				{
					base.ResponseQueue.Add(ResponseFactory.LoadManifestResponse(requestId, success: true, request.Manifest), cancellationToken);
					return;
				}
				ProjectManifest projectManifest = (string.IsNullOrEmpty(request.Manifest) ? ProjectManifest.ReadFromFile(Path.Combine(request.ProjectFolder, "app.json"), projectManifestProps, diagnostics) : ProjectManifest.ReadFromString(Path.Combine(request.ProjectFolder, "app.json"), request.Manifest, projectManifestProps, diagnostics));
				bool success = projectManifest != null;
				base.ResponseQueue.Add(ResponseFactory.LoadManifestResponse(requestId, success, projectManifest?.AppManifest.ToJsonString() ?? string.Empty), cancellationToken);
			}
			catch
			{
				base.ResponseQueue.Add(ResponseFactory.LoadManifestResponse(requestId, success: false, string.Empty), cancellationToken);
			}
		}
	}
