		public McpListToolsRequestHandler(VsCodeWorkspace workspace, ResponseQueue responseQueue, IMcpSessionManager sessionManager)
			: base(workspace, responseQueue, sessionManager)
		{
		}

		protected override async Task ProcessRequestAsync(McpListToolsRequest request, int requestId, CancellationToken cancellationToken)
		{
			if (request == null)
			{
				AddInvalidRequestError("Request payload is null.", requestId, cancellationToken);
				return;
			}
			if (string.IsNullOrEmpty(request.SessionId))
			{
				AddInvalidParamsError("sessionId is required.", requestId, cancellationToken);
				return;
			}
			if (!TryGetServerNameForSession(request.SessionId, out string serverName))
			{
				AddMethodNotFoundError("Session not found: " + request.SessionId, requestId, cancellationToken);
				return;
			}
			base.Logger.Info($"Started MCP session '{request.SessionId}' for server '{serverName}'.");
			McpClient mcpClient = null;
			try
			{
				mcpClient = await GetOrCreateMcpClient(serverName, request.Configuration, requestId, cancellationToken);
				if (mcpClient == null)
				{
					AddInvalidRequestError("No MCP client found that can execute a start session request.", requestId, cancellationToken);
					return;
				}
				IList<McpClientTool> obj = await mcpClient.ListToolsAsync(null, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				List<McpTool> list = new List<McpTool>(obj.Count);
				foreach (Tool item in obj.Select((McpClientTool t) => t.ProtocolTool))
				{
					list.Add(new McpTool
					{
						Name = item.Name,
						Description = item.Description,
						InputSchema = item.InputSchema
					});
				}
				McpListToolsResult result = new McpListToolsResult
				{
					Tools = list,
					NextCursor = null
				};
				base.ResponseQueue.Add(ResponseFactory.McpResponse(result, EndpointName, requestId), cancellationToken);
			}
			finally
			{
				if (mcpClient != null)
				{
					await mcpClient.DisposeAsync().ConfigureAwait(continueOnCapturedContext: false);
				}
			}
		}
