	internal abstract class McpRequestHandlerBase<TRequest, TLaunchConfiguration> : NavServerRequestHandler<TRequest, TLaunchConfiguration> where TRequest : NavServerRequest<TLaunchConfiguration> where TLaunchConfiguration : ServerConnectionConfiguration
	{
		private static readonly JsonSerializerSettings JsonSerializerSettings = new JsonSerializerSettings
		{
			Formatting = Formatting.None,
			NullValueHandling = NullValueHandling.Ignore,
			DefaultValueHandling = DefaultValueHandling.Ignore,
			StringEscapeHandling = StringEscapeHandling.Default,
			ContractResolver = new CamelCasePropertyNamesContractResolver()
		};

		internal const string TroubleshootingMcpOptionHeaderName = "mcp-troubleshooting-options";

		internal const string TroubleshootingMcpServerValue = "troubleshooting";

		private readonly ConcurrentDictionary<(string serverName, int sessionId, string? hostId), IMcpClientProvider> clientProviders = new ConcurrentDictionary<(string, int, string), IMcpClientProvider>();

		internal IMcpSessionManager SessionManager { get; private set; }

		protected McpRequestHandlerBase(VsCodeWorkspace workspace, ResponseQueue responseQueue, IMcpSessionManager sessionManager)
			: base(workspace, responseQueue)
		{
			SessionManager = sessionManager ?? throw new ArgumentNullException("sessionManager");
		}

		protected bool TryGetServerNameForSession(string sessionId, out string serverName)
		{
			return SessionManager.TryGetServerName(sessionId, out serverName);
		}

		protected async Task<McpClient?> GetOrCreateMcpClient(string mcpProxyServerName, InitializeDebugAdapterRequest? options, int requestId, CancellationToken token)
		{
			ConnectionOptions connectionOptions = options?.CreateConnectionOptions();
			if (connectionOptions == null)
			{
				base.Logger.Error(ProtocolResources.McpClientConnectionFailed);
				base.ResponseQueue.Add(ResponseFactory.ErrorResponse(MessageErrorCode.InvalidRequest, ProtocolResources.McpClientConnectionFailed, EndpointName, requestId), token);
				return null;
			}
			connectionOptions.Port = (options?.McpServerPort).GetValueOrDefault(7047);
			int valueOrDefault = (options?.SessionId).GetValueOrDefault(-1);
			string text = options?.HostId;
			(string, int, string) key2 = (mcpProxyServerName, valueOrDefault, text);
			if (!clientProviders.TryGetValue(key2, out IMcpClientProvider clientProvider) || clientProvider?.Options != connectionOptions)
			{
				if (!mcpProxyServerName.Equals("Business Central Troubleshooting MCP Server", StringComparison.OrdinalIgnoreCase))
				{
					return null;
				}
				string item = StringSerializerHelper.SerializePayload(new TroubleshootingMcpOptions
				{
					VersionNumber = "1.0",
					SessionId = valueOrDefault,
					HostId = text
				}, JsonSerializerSettings);
				(string, string)[] additionalHeaderValues = new(string, string)[1] { ("mcp-troubleshooting-options", item) };
				clientProvider = new McpClientProvider(connectionOptions, base.Logger, TroubleshootingMcpContext.Debugging, additionalHeaderValues);
				clientProviders.AddOrUpdate(key2, clientProvider, ((string serverName, int sessionId, string? hostId) key, IMcpClientProvider existingProvider) => clientProvider);
			}
			return await clientProvider.GetMcpClient(token).ConfigureAwait(continueOnCapturedContext: false);
		}

		protected void AddInvalidRequestError(string message, int requestId, CancellationToken ct)
		{
			base.Logger.Error(message);
			base.ResponseQueue.Add(ResponseFactory.ErrorResponse(MessageErrorCode.InvalidRequest, message, EndpointName, requestId), ct);
		}

		protected void AddInvalidParamsError(string message, int requestId, CancellationToken ct)
		{
			base.Logger.Error(message);
			base.ResponseQueue.Add(ResponseFactory.ErrorResponse(MessageErrorCode.InvalidParams, message, EndpointName, requestId), ct);
		}

		protected void AddMethodNotFoundError(string message, int requestId, CancellationToken ct)
		{
			base.Logger.Error(message);
			base.ResponseQueue.Add(ResponseFactory.ErrorResponse(MessageErrorCode.MethodNotFound, message, EndpointName, requestId), ct);
		}

		protected void AddInternalError(string message, int requestId, CancellationToken ct)
		{
			base.Logger.Error(message);
			base.ResponseQueue.Add(ResponseFactory.ErrorResponse(MessageErrorCode.InternalError, message, EndpointName, requestId), ct);
		}
	}
