	internal abstract class NavServerRequestHandler<T, U> : RequestHandlerBase<T> where T : NavServerRequest<U> where U : ServerConnectionConfiguration
	{
		protected IEmitLogger Logger { get; private set; }

		protected NavServerRequestHandler(VsCodeWorkspace workspace, ResponseQueue responseQueue)
			: base(workspace, (IResponseQueue)responseQueue)
		{
			Logger = new OutputConsoleLogger(base.ResponseQueue);
		}

		public override async Task HandleAsync(T request, int requestId, CancellationToken cancellationToken)
		{
			try
			{
				await ProcessRequestAsync(request, requestId, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
			}
			catch (TaskCanceledException)
			{
				base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId), cancellationToken);
			}
			catch (HttpRequestException)
			{
				base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId), cancellationToken);
			}
			catch (UserNotAuthenticatedException)
			{
				SendAuthErrorResponse(requestId, cancellationToken);
				Logger.Info(ProtocolResources.AuthenticationNeeded);
			}
			catch (UserNotAuthorizedException)
			{
				if (request.Configuration != null)
				{
					OnPremiseHttpClientFactory.Instance.Value.ClearCredentials(request.Configuration.CreateConnectionOptions(), Logger);
				}
				SendAuthErrorResponse(requestId, cancellationToken);
				Logger.Info(ProtocolResources.AuthorizationNeeded);
			}
			catch (IncompatibleExtensionException ex5)
			{
				Logger.Info(ex5.Message);
				base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId), cancellationToken);
			}
			catch (UserSetupException ex6)
			{
				Logger.Info(ex6.Message);
				base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId), cancellationToken);
			}
		}

		private void SendAuthErrorResponse(int requestId, CancellationToken cancellationToken)
		{
			base.ResponseQueue.Add(ResponseFactory.ErrorResponse(new MessageError<HttpStatusCode>
			{
				Code = MessageErrorCode.InvalidRequest,
				Data = HttpStatusCode.Unauthorized
			}, EndpointName, requestId), cancellationToken);
		}

		protected abstract Task ProcessRequestAsync(T request, int requestId, CancellationToken cancellationToken);

		protected ISnapshotDebuggerClient CreateSnapshotDebuggerClientIfOptionsDiffer(ISnapshotDebuggerClient? existingClient, ConnectionOptions options)
		{
			if (existingClient == null || existingClient.Options != options)
			{
				return new SnapshotDebuggerClient(options, Logger);
			}
			return existingClient;
		}
	}
	internal class OpenEventRecorderRequestHandler : NavServerRequestHandler<OpenEventRecorderRequest, LaunchConfiguration>
	{
		private const int EventRecorderPageId = 9845;

