	internal class OpenPageDesignerRequestHandler : NavServerRequestHandler<LaunchObjectRequest, LaunchConfiguration>
	{
		private readonly IClientStartup clientStartup;

		public override string EndpointName => "al/openPageDesigner";

		internal OpenPageDesignerRequestHandler(VsCodeWorkspace workspace, ResponseQueue responseQueue, IClientStartup clientStartup)
			: base(workspace, responseQueue)
		{
			this.clientStartup = clientStartup;
		}

		protected override async Task ProcessRequestAsync(LaunchObjectRequest request, int requestId, CancellationToken cancellationToken)
		{
			string text = Path.Combine(base.Workspace.CurrentProjectFolder, "app.json");
			List<Diagnostic> diagnostics = new List<Diagnostic>();
			ProjectManifestProps manifestProps = ProjectManifestProps.LoadFromFile(base.Workspace.CurrentProjectFolder, diagnostics);
			ProjectManifest manifest = ProjectManifest.ReadFromFile(text, manifestProps, diagnostics);
			if (manifest != null)
			{
				base.Logger.Info(string.Format(DeploymentResources.OpenDesignerMessage, manifest.AppManifest.AppName, manifest.AppManifest.AppPublisher, manifest.AppManifest.AppVersion, manifest.AppManifest.AppId));
				if (manifest.AppManifest.ResourceExposurePolicy?.AllowDownloadingSource ?? manifest.AppManifest.ShowMyCode)
				{
					base.Logger.Info(string.Format(DeploymentResources.OpenDesigneAllowDownloadingSourceFalse));
				}
				request.Configuration.PackageFileName = manifest.AppManifest.DefaultPackageName() + ".app";
				request.Configuration.Directory = request.OutputFolder ?? base.Workspace.CurrentProjectFolder;
				ServerInfo serverInfo = await ServerRegistry.DevInstance.GetServerInfo(request.Configuration.CreateConnectionOptions(), base.Logger).ConfigureAwait(continueOnCapturedContext: false);
				PublishResult publishResult = await new Publisher(base.Logger).Publish(request.Configuration, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				if (publishResult.Success)
				{
					Uri webEndpointUri = serverInfo?.GetWebEndpointUrl();
					clientStartup.OpenStartupObject(webEndpointUri, request.Configuration.CreateConnectionOptions(), base.Logger, request.Configuration.StartupObjectId, request.Configuration.StartupObjectType, request.Configuration.StartupCompany, manifest.AppManifest.AppId, null, request.BrowserInfo);
				}
				base.ResponseQueue.Add(ResponseFactory.CreateOpenPageDesignerResponse(requestId, publishResult.Success), cancellationToken);
			}
			else
			{
				base.Logger.Error(string.Format(DeploymentResources.FileInvalidOrDoesNotExistError, text));
				base.ResponseQueue.Add(ResponseFactory.CreateOpenPageDesignerResponse(requestId, success: false), cancellationToken);
			}
		}
	}
