	internal class RefreshSymbolReferencesRequestHandler : RequestHandlerBase<RefreshSymbolReferencesRequest>
	{
		public override string EndpointName => "al/refreshsymbolreferencesrequest";

		internal RefreshSymbolReferencesRequestHandler(VsCodeWorkspace workspace, ResponseQueue responseQueue)
			: base(workspace, (IResponseQueue)responseQueue)
		{
		}

		public override Task HandleAsync(RefreshSymbolReferencesRequest request, int requestId, CancellationToken cancellationToken)
		{
			if (request.Folders == null || request.Folders.Length == 0)
			{
				return Task.CompletedTask;
			}
			SymbolReferenceSpecification specification = null;
			try
			{
				using FileStream stream = File.OpenRead(request.AppPath);
				using NavAppPackageReader navAppPackageReader = NavAppPackageReader.Create(stream, leaveOpen: false, request.AppPath);
				NavAppManifest navAppManifest = navAppPackageReader.ReadNavAppManifest();
				specification = new SymbolReferenceSpecification(navAppManifest.AppPublisher, navAppManifest.AppName, navAppManifest.AppVersion, exact: false, navAppManifest.AppId, isPropagated: false, navAppManifest.AppAlternateIds);
			}
			catch (IOException ex)
			{
				base.ResponseQueue.Add(ResponseFactory.ErrorResponse(new MessageError
				{
					Message = string.Format(CultureInfo.CurrentCulture, ProtocolResources.FailedOpeningAppToResolveSymbolReferences, request.AppPath, ex.Message)
				}, EndpointName, requestId), cancellationToken);
				return Task.CompletedTask;
			}
			catch (Exception e)
			{
				LoggingUtilities.WriteMessageFailedException(requestId.ToString(CultureInfo.InvariantCulture), e);
				throw;
			}
			IList<Project> list = new List<Project>(request.Folders.Length);
			Solution currentSolution = base.Workspace.CurrentSolution;
			string[] folders = request.Folders;
			foreach (string path in folders)
			{
				Project project = currentSolution.FindProject(path);
				if (project != null)
				{
					list.Add(project);
				}
			}
			base.Workspace.UpdateSymbolReferences(specification, list);
			base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId));
			return Task.CompletedTask;
		}
	}
	internal class ReloadRadFileRequestHandler : RequestHandlerBase<ReloadRadFileRequest>
	{
		public override string EndpointName => "al/reloadRadFile";

		internal IFileSystem FileSystem { get; set; }

		internal ReloadRadFileRequestHandler(VsCodeWorkspace workspace, ResponseQueue responseQueue)
			: base(workspace, (IResponseQueue)responseQueue)
		{
		}

		public override Task HandleAsync(ReloadRadFileRequest request, int requestId, CancellationToken cancellationToken)
		{
			ReloadCurrentAndAllProjectReferencesRadFile();
			base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId));
			return Task.CompletedTask;
		}

		private void ReloadCurrentAndAllProjectReferencesRadFile()
		{
			Solution currentSolution = base.Workspace.CurrentSolution;
			ProjectId projectId = base.Workspace?.CurrentProjectId;
			base.Workspace?.ObjectChangeDocumentManager.Clear(projectId, keepAdded: false);
			IFileSystem fileSystem = FileSystem ?? Microsoft.Dynamics.Nav.CodeAnalysis.FileSystem.Instance;
			string currentRadPath = base.Workspace.CurrentRadPath;
			if (fileSystem.Exists(currentRadPath))
			{
				base.Workspace.ObjectChangeDocumentManager.ActiveObjectChangeManager.Load(currentRadPath, fileSystem);
			}
			ProjectDependencyGraph projectDependencyGraph = currentSolution.GetProjectDependencyGraph();
			if (projectDependencyGraph == null)
			{
				return;
			}
			foreach (ProjectId item in projectDependencyGraph.GetProjectsThatThisProjectDirectlyDependsOn(projectId))
			{
				IObjectChangeManager objectChangeManager = base.Workspace.ObjectChangeDocumentManager.GetObjectChangeManager(item);
				Project project = currentSolution.GetProject(item);
				if (project != null)
				{
					base.Workspace.ObjectChangeDocumentManager.Clear(project.Id, keepAdded: false);
					string path = project.ProjectFolder.RadPath();
					if (fileSystem.Exists(path))
					{
						objectChangeManager.Load(path, fileSystem);
					}
				}
			}
		}
	}
