	internal class SnapshotDebuggerAttachInitializeRequestHandler : NavServerRequestHandler<SnapshotDebuggerAttachInitializeRequest, ServerConnectionConfiguration>
	{
		public override bool ProfilePerformance => true;

		public override string EndpointName => "al/initializeSnapshotDebuggerAttach";

		protected internal ISnapshotDebuggerClient? SnapshotDebuggerClient { get; set; }

		internal SnapshotDebuggerAttachInitializeRequestHandler(VsCodeWorkspace workspace, ResponseQueue responseQueue)
			: base(workspace, responseQueue)
		{
		}

		protected override async Task ProcessRequestAsync(SnapshotDebuggerAttachInitializeRequest request, int requestId, CancellationToken cancellationToken)
		{
			if (request == null || request.Configuration == null)
			{
				base.Logger.Error(ProtocolResources.SnapshotDebuggerInitializationFailedWrongInputParameter);
				base.ResponseQueue.Add(ResponseFactory.SnapshotDebuggerAttachInitialized(null, null, SnapshotDebuggerAttachKindWrapper.Undefined, requestId));
				return;
			}
			LogTelemetry(request, requestId);
			ConnectionOptions connectionOptions = request.Configuration.CreateConnectionOptions();
			if (connectionOptions == null)
			{
				base.Logger.Error(ProtocolResources.SnapshotDebuggerInitializationFailedWrongInputParameter);
				base.ResponseQueue.Add(ResponseFactory.SnapshotDebuggerAttachInitialized(null, null, SnapshotDebuggerAttachKindWrapper.Undefined, requestId));
				return;
			}
			ConnectionOptions connectionOptions2 = connectionOptions;
			int? port = connectionOptions2.Port;
			port.GetValueOrDefault();
			if (!port.HasValue)
			{
				int value = 7083;
				connectionOptions2.Port = value;
			}
			ServerInfo serverInfo = await ServerRegistry.SnapshotInstance.GetServerInfo(connectionOptions, base.Logger).ConfigureAwait(continueOnCapturedContext: false);
			if (request.ProfileKind.HasValue && request.ProfileKind.Value == ProfileKind.Sampling)
			{
				bool flag = serverInfo != null && !serverInfo.Supports(SnapshotApiFeature.SampleProfiling);
				if (flag || request.ExecutionContext.HasFlag(SnapshotDebuggingExecutionContext.Debugging))
				{
					string message = (flag ? string.Format(CultureInfo.CurrentCulture, ProtocolResources.SamplingProfilingNotSupported, request.Configuration.Name) : string.Format(CultureInfo.CurrentCulture, ProtocolResources.SamplingProfilingNotSupportedIfExecutionContextIsNotProfiling, request.Configuration.Name));
					base.Logger.Error(message);
					base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId));
					return;
				}
			}
			SnapshotDebuggerClient = CreateSnapshotDebuggerClientIfOptionsDiffer(SnapshotDebuggerClient, serverInfo?.ConnectionOptions ?? connectionOptions);
			IList<SourceBreakpointLocationWrapper> list = ((request.SnapPointLocations != null) ? (await CreateSourceBreakpointLocationAsync(request.SnapPointLocations, cancellationToken).ConfigureAwait(continueOnCapturedContext: false)) : SpecializedCollections.EmptyList<SourceBreakpointLocationWrapper>());
			IList<SourceBreakpointLocationWrapper> source = list;
			string debuggingContext = Guid.NewGuid().ToString();
			bool success = false;
			string affinityCookie = null;
			SnapshotDebuggerAttachKindWrapper attachKind = SnapshotDebuggerAttachKindWrapper.Undefined;
			try
			{
				(success, affinityCookie, attachKind) = await SnapshotDebuggerClient.InitalizeAttachAsync(new SnapshotDebuggerAttachPayloadWrapper
				{
					ClientType = request.ClientType.MapClientType(),
					SnapshotVerbosity = MapSnapshotVerbosity(request.SnapshotVerbosity),
					ExecutionContext = MapExecutionContext(request.ExecutionContext),
					SessionId = request.SessionId,
					UserId = request.UserId,
					SourceBreakpointLocations = source.ToArray(),
					DebuggingContext = debuggingContext,
					Kind = MapProfileKind(request.ProfileKind),
					SamplingInterval = MapSamplingInterval(request.SamplingInterval)
				}).ConfigureAwait(continueOnCapturedContext: false);
			}
			finally
			{
				Response response = ResponseFactory.SnapshotDebuggerAttachInitialized(success ? debuggingContext : string.Empty, affinityCookie ?? string.Empty, attachKind, requestId);
				if (success)
				{
					LogDebuggingContext(debuggingContext, requestId);
				}
				base.ResponseQueue.Add(response, cancellationToken);
			}
		}

		private async Task<IList<SourceBreakpointLocationWrapper>> CreateSourceBreakpointLocationAsync(IList<SnapPointLocation> snapPointLocations, CancellationToken cancellationToken)
		{
			if (snapPointLocations == null)
			{
				return SpecializedCollections.EmptyList<SourceBreakpointLocationWrapper>();
			}
			PooledDictionary<ApplicationObjectIdWrapper, IList<LineWrapper>> sourceBreakPoints = PooledDictionary<ApplicationObjectIdWrapper, IList<LineWrapper>>.GetInstance();
			try
			{
				foreach (SnapPointLocation snapPointLocation in snapPointLocations)
				{
					if (string.IsNullOrEmpty(snapPointLocation.Path) || snapPointLocation.LineContexts == null)
					{
						continue;
					}
					ApplicationObjectIdWrapper? wrapper = null;
					Document document = base.Workspace.GetDocument(snapPointLocation.Path.CreateUriFilePath());
					bool documentHasSingleApplicationObject = false;
					if (document == null)
					{
						PreviewFileUrl previewFileUrl = new Uri(snapPointLocation.Path).ParsePreviewFileUrl();
						if (previewFileUrl.Id == 0)
						{
							continue;
						}
						ObjectTypeWrapper? objectTypeWrapper = DebugHelper.MapToObjectType(previewFileUrl.Kind);
						if (objectTypeWrapper.HasValue)
						{
							wrapper = new ApplicationObjectIdWrapper(objectTypeWrapper.Value, previewFileUrl.Id);
						}
					}
					else
					{
						IList<ApplicationObjectSyntax> list = await document.GetDeclaredApplicationObjectSyntaxesAsync(cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
						if (list != null && list.Count == 1)
						{
							documentHasSingleApplicationObject = true;
							ObjectTypeWrapper? objectTypeWrapper2 = DebugHelper.MapToObjectType(list[0].Kind);
							if (objectTypeWrapper2.HasValue)
							{
								wrapper = new ApplicationObjectIdWrapper(objectTypeWrapper2.Value, list[0].ObjectId.GetObjectIdOrDefault());
							}
						}
					}
					Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.LanguageServerContract.Extensions.LineContext[] lineContexts = snapPointLocation.LineContexts;
					foreach (Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.LanguageServerContract.Extensions.LineContext line in lineContexts)
					{
						Position position = Position.Create(line.LineNumber, 0, DebugAdapterInitializeRequestHandler.Settings != null && DebugAdapterInitializeRequestHandler.Settings.LinesStartAt1);
						if (position == Position.InvalidPosition)
						{
							continue;
						}
						if (document != null && !documentHasSingleApplicationObject)
						{
							(ApplicationObjectIdWrapper?, Position) tuple = await document.GetDeclaringApplicationObjectAndAdjustLineNumberFromDebugClientPositionsAsync(position, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
							if (!tuple.Item1.HasValue)
							{
								continue;
							}
							wrapper = tuple.Item1;
							position.Line = tuple.Item2.Line;
						}
						LineWrapper item = new LineWrapper
						{
							Position = new Microsoft.Dynamics.Nav.DebuggerService.SourcePosition((ushort)position.Line, 0),
							Condition = line.Condition
						};
						if (sourceBreakPoints.ContainsKey(wrapper.Value))
						{
							sourceBreakPoints[wrapper.Value].Add(item);
							continue;
						}
						sourceBreakPoints.Add(wrapper.Value, new List<LineWrapper> { item });
					}
				}
				return sourceBreakPoints.Select<KeyValuePair<ApplicationObjectIdWrapper, IList<LineWrapper>>, SourceBreakpointLocationWrapper>((KeyValuePair<ApplicationObjectIdWrapper, IList<LineWrapper>> s) => new SourceBreakpointLocationWrapper
				{
					Id = s.Key,
					Lines = s.Value.ToArray()
				}).ToList();
			}
			finally
			{
				sourceBreakPoints.Free();
			}
		}

		private static SnapshotDebuggingExecutionContextWrapper MapExecutionContext(SnapshotDebuggingExecutionContext executionContext)
		{
			SnapshotDebuggingExecutionContextWrapper snapshotDebuggingExecutionContextWrapper = SnapshotDebuggingExecutionContextWrapper.Debugging;
			if (executionContext == SnapshotDebuggingExecutionContext.Profiling)
			{
				return SnapshotDebuggingExecutionContextWrapper.Profiling;
			}
			if ((executionContext & SnapshotDebuggingExecutionContext.Profiling) != 0)
			{
				snapshotDebuggingExecutionContextWrapper |= SnapshotDebuggingExecutionContextWrapper.Profiling;
			}
			return snapshotDebuggingExecutionContextWrapper;
		}

		private static ProfileKindWrapper? MapProfileKind(ProfileKind? kind)
		{
			if (!kind.HasValue)
			{
				return null;
			}
			if (kind.Value == ProfileKind.Sampling)
			{
				return ProfileKindWrapper.Sampling;
			}
			return ProfileKindWrapper.Instrumentation;
		}

		private static ProfilerSamplingIntervalWrapper? MapSamplingInterval(ProfilingSamplingInterval? interval)
		{
			if (!interval.HasValue)
			{
				return null;
			}
			return (ProfilerSamplingIntervalWrapper)interval.Value;
		}

		private static SnapshotVerbosityWrapper MapSnapshotVerbosity(SnapshotVerbosity snapshotVerbosity)
		{
			if (snapshotVerbosity == SnapshotVerbosity.Full)
			{
				return SnapshotVerbosityWrapper.Full;
			}
			return SnapshotVerbosityWrapper.SnapPoint;
		}

		private void LogDebuggingContext(string debuggingContext, int requestId)
		{
			GetCustomTelemetryForRequest(requestId).Dimensions.Add("Debugging context", debuggingContext);
		}

		private void LogTelemetry(SnapshotDebuggerAttachInitializeRequest request, int requestId)
		{
			GetCustomTelemetryForRequest(requestId).Dimensions.Add("User ID Specified", (!string.IsNullOrEmpty(request.UserId)).ToString());
			GetCustomTelemetryForRequest(requestId).Dimensions.Add("Session ID", request.SessionId.ToString());
			GetCustomTelemetryForRequest(requestId).Dimensions.Add("Client Type", request.ClientType.ToString());
			GetCustomTelemetryForRequest(requestId).Dimensions.Add("Number of SnapPoints", request.SnapPointLocations?.Length.ToString() ?? "0");
			if (request.ProfileKind.HasValue && request.ProfileKind.Value != 0)
			{
				GetCustomTelemetryForRequest(requestId).Dimensions.Add("ProfileKind", request.ProfileKind.Value.ToString());
				if (request.ProfileKind.GetValueOrDefault() == ProfileKind.Sampling && request.SamplingInterval.HasValue)
				{
					GetCustomTelemetryForRequest(requestId).Dimensions.Add("SamplingInterval", request.SamplingInterval.Value.ToString());
				}
			}
		}
	}
