	internal static class SourceTextExtension
	{
		internal static TextSpan GetTextSpan(this SourceText sourceText, Range range)
		{
			int position = sourceText.Lines.GetPosition(new LinePosition(range.Start.Line, range.Start.Character));
			int position2 = sourceText.Lines.GetPosition(new LinePosition(range.End.Line, range.End.Character));
			return TextSpan.FromBounds(position, position2);
		}
	}
	internal class StreamingTextWriter : CompilerTextWriter
	{
		public event Action<string> OnLineWritten;

		public override void WriteLine()
		{
			RaiseOnLineWritten(string.Empty);
		}

		public override void WriteLine(string text)
		{
			RaiseOnLineWritten(text);
		}

		public override void WriteLine(string text, params object[] args)
		{
			RaiseOnLineWritten(string.Format(CultureInfo.InvariantCulture, text, args));
		}

		protected void RaiseOnLineWritten(string message)
		{
			this.OnLineWritten?.Invoke(message);
		}
	}
