	internal class RunTestRequestHandler : NavServerRequestHandler<RunTestRequest, LaunchConfiguration>
	{
		private readonly ITestRunnerService testRunnerService;

		private readonly ServerRegistry serverRegistry;

		public override string EndpointName => "al/runTests";

		public override bool ProfilePerformance => true;

		private Func<PublishOptions, CancellationToken, Task<PublishResult>> PublishCallback { get; set; }

		public RunTestRequestHandler(ITestRunnerService testRunnerService, VsCodeWorkspace workspace, ResponseQueue responseQueue, ServerRegistry? serverRegistry = null, Func<PublishOptions, CancellationToken, Task<PublishResult>>? publishCallback = null)
			: base(workspace, responseQueue)
		{
			this.testRunnerService = testRunnerService;
			this.serverRegistry = serverRegistry ?? ServerRegistry.DevInstance;
			if (publishCallback == null)
			{
				PublishCallback = (PublishOptions options, CancellationToken cancellationToken) => new Publisher(this.testRunnerService.Logger).Publish(options, cancellationToken);
			}
			else
			{
				PublishCallback = publishCallback;
			}
		}

		protected override async Task ProcessRequestAsync(RunTestRequest request, int requestId, CancellationToken cancellationToken)
		{
			if (request?.Configuration == null)
			{
				base.ResponseQueue.Add(ResponseFactory.TestExecutionRunFinished(), cancellationToken);
				return;
			}
			ConnectionOptions connectionOptions = request.Configuration.CreateConnectionOptions();
			ServerInfo serverInfo = await serverRegistry.GetServerInfo(connectionOptions, base.Logger).ConfigureAwait(continueOnCapturedContext: false);
			if (serverInfo == null || !serverInfo.Supports(DevApiFeature.TestRunning))
			{
				testRunnerService.SendMessage(ProtocolResources.TestRunningNotSupported);
				base.ResponseQueue.Add(ResponseFactory.TestExecutionRunFinished(), cancellationToken);
				return;
			}
			if (!request.SkipPublish)
			{
				testRunnerService.SendMessage("Preparing to build and publish projects...\r\n");
				if (!(await BuildAndPublishProjectsAsync(request, requestId, cancellationToken).ConfigureAwait(continueOnCapturedContext: false)))
				{
					testRunnerService.SendMessage("Build/publish failed. Tests will not run.\r\n");
					base.ResponseQueue.Add(ResponseFactory.TestExecutionRunFinished(), cancellationToken);
					return;
				}
				testRunnerService.SendMessage("Build and publish completed successfully.\r\n\r\n");
			}
			TestPlan testPlan = RunTestHelpers.BuildTestPlan(request.Tests);
			await testRunnerService.SetupAndRunTests(connectionOptions, request.Configuration.StartupCompany ?? string.Empty, testPlan, string.Empty, request.CoverageMode, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
			base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId), cancellationToken);
		}

		private async Task<bool> BuildAndPublishProjectsAsync(RunTestRequest request, int requestId, CancellationToken cancellationToken)
		{
			IFileSystem instance = FileSystem.Instance;
			Solution currentSolution = base.Workspace.CurrentSolution;
			PooledHashSet<ProjectId> affectedProjectIds = PooledHashSet<ProjectId>.GetInstance();
			PooledHashSet<int> processedCodeunitIds = PooledHashSet<int>.GetInstance();
			try
			{
				TestItem[] tests = request.Tests;
				foreach (TestItem testItem in tests)
				{
					if (testItem.Scope != TestItemScope.Method)
					{
						continue;
					}
					if (!testItem.CodeunitId.HasValue)
					{
						testRunnerService.SendMessage(string.Format(CultureInfo.InvariantCulture, "Warning: Skipping test '{0}' - missing CodeunitId. The test may be from an unloaded project.\r\n", testItem.Name));
						continue;
					}
					int value = testItem.CodeunitId.Value;
					if (!processedCodeunitIds.Contains(value) && testItem.Location?.Source != null)
					{
						string filePath = testItem.Location.Source.GetFilePath();
						Document document = base.Workspace.GetDocument(filePath);
						if (!(document?.Id.ProjectId != null))
						{
							testRunnerService.SendMessage(string.Format(CultureInfo.InvariantCulture, "Error: Could not find project for test '{0}' in file '{1}'.\r\n", testItem.Name, filePath));
							return false;
						}
						affectedProjectIds.Add(document.Id.ProjectId);
						processedCodeunitIds.Add(value);
					}
				}
				if (affectedProjectIds.Count == 0)
				{
					testRunnerService.SendMessage("Error: No valid projects found for the selected tests.\r\n");
					return false;
				}
				GetCustomTelemetryForRequest(requestId).Metrics.Add("AffectedProjectCount", affectedProjectIds.Count);
				testRunnerService.SendMessage(string.Format(CultureInfo.InvariantCulture, "Found {0} project(s) to build and publish.\r\n", affectedProjectIds.Count));
				foreach (ProjectId item in affectedProjectIds)
				{
					if (!base.Workspace.AreAllProjectReferencesBound(item))
					{
						Project project = currentSolution.GetProject(item);
						testRunnerService.SendMessage(string.Format(CultureInfo.InvariantCulture, "Error: Project '{0}' references are not loaded. Cannot build.\r\n", project?.Name ?? item.ToString()));
						return false;
					}
				}
				IList<string> args = FilterBuildArguments(request.Args ?? Array.Empty<string>());
				return await BuildAndPublishHelper.BuildAndPublishProjectsAsync(base.Workspace, testRunnerService.Logger, PublishCallback, instance, affectedProjectIds, string.Empty, args, request.Configuration, forceBuildOfAllDependencies: false, request.VSCodeExtensionVersion, GetCustomTelemetryForRequest(requestId), base.ResponseQueue, cancellationToken, addProjectArgument: true).ConfigureAwait(continueOnCapturedContext: false);
			}
			finally
			{
				processedCodeunitIds.Free();
				affectedProjectIds.Free();
			}
		}

		private static IList<string> FilterBuildArguments(IList<string> args)
		{
			if (args == null || args.Count == 0)
			{
				return args;
			}
			List<string> list = new List<string>();
			foreach (string arg in args)
			{
				string text = arg.Trim().ToLowerInvariant();
				if (!text.StartsWith("/continuebuildonerror", StringComparison.OrdinalIgnoreCase) && !text.StartsWith("-continuebuildonerror", StringComparison.OrdinalIgnoreCase) && !text.StartsWith("/symbolusage", StringComparison.OrdinalIgnoreCase) && !text.StartsWith("-symbolusage", StringComparison.OrdinalIgnoreCase))
				{
					list.Add(arg);
				}
			}
			return list;
		}
	}
