		public override async Task HandleAsync(GetPackageDependenciesRequest request, int requestId, CancellationToken cancellationToken)
		{
			GetPackageDependenciesRequest request2 = request;
			Project defaultProject = base.Workspace.GetCurrentProject();
			if (defaultProject == null || !base.Workspace.AreAllProjectReferencesBound(defaultProject.Id))
			{
				base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId));
				return;
			}
			Compilation compilation = await base.Workspace.CurrentSolution.GetCompilationAsync(defaultProject.Id, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
			if (compilation == null)
			{
				base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId));
				return;
			}
			IModuleSymbol moduleSymbol;
			if (request2?.Name != null && !(request2.Name == defaultProject.Name))
			{
				moduleSymbol = compilation.ReferenceManager.GetLoadedModules().FirstOrDefault((IModuleSymbol m) => m.Name == request2.Name);
			}
			else
			{
				IModuleSymbol compiledModule = compilation.CompiledModule;
				moduleSymbol = compiledModule;
			}
			base.ResponseQueue.Add(ResponseFactory.CreatePackageDependenciesResponse(requestId, moduleSymbol?.ReferencedModules ?? Array.Empty<IModuleSymbol>()));
		}
	}
