	public class MultiProjectTestCodeCoverageCacheProvider
	{
		private readonly Dictionary<string, TestCodeCoverageCacheProvider> cacheProviders;

		private readonly Dictionary<Guid, string> appIdToWorkspaceFolderMap;

		private readonly IFileSystem fileSystem;

		private readonly CodeCoverageInformation mergedCachedData;

		public MultiProjectTestCodeCoverageCacheProvider(VsCodeWorkspace workspace, string cachePath, IFileSystem fileSystem = null)
		{
			this.fileSystem = fileSystem ?? FileSystem.Instance;
			cacheProviders = new Dictionary<string, TestCodeCoverageCacheProvider>();
			appIdToWorkspaceFolderMap = new Dictionary<Guid, string>();
			if (workspace == null || workspace.CurrentSolution.Projects.Count() == 0)
			{
				mergedCachedData = new CodeCoverageInformation
				{
					Tests = new List<CodeCoverageForTest>()
				};
				return;
			}
			foreach (Project project in workspace.CurrentSolution.Projects)
			{
				string directoryName = Path.GetDirectoryName(project.FilePath);
				string cacheDirectory = (Path.IsPathRooted(cachePath) ? cachePath : Path.Combine(directoryName, cachePath));
				cacheProviders[directoryName] = new TestCodeCoverageCacheProvider(cacheDirectory, this.fileSystem);
				if (project.ProjectDefinition != null)
				{
					Guid appId = project.ProjectDefinition.AppId;
					appIdToWorkspaceFolderMap[appId] = directoryName;
				}
			}
			mergedCachedData = MergeCachedDataFromProviders();
		}

		internal MultiProjectTestCodeCoverageCacheProvider(Dictionary<string, string> workspaceFolderCachePaths, Dictionary<Guid, string> appIdToFolderMap, IFileSystem fileSystem = null)
		{
			this.fileSystem = fileSystem ?? FileSystem.Instance;
			cacheProviders = new Dictionary<string, TestCodeCoverageCacheProvider>();
			appIdToWorkspaceFolderMap = appIdToFolderMap ?? new Dictionary<Guid, string>();
			if (workspaceFolderCachePaths == null || workspaceFolderCachePaths.Count == 0)
			{
				mergedCachedData = new CodeCoverageInformation
				{
					Tests = new List<CodeCoverageForTest>()
				};
				return;
			}
			foreach (KeyValuePair<string, string> workspaceFolderCachePath in workspaceFolderCachePaths)
			{
				string key = workspaceFolderCachePath.Key;
				string value = workspaceFolderCachePath.Value;
				string cacheDirectory = (Path.IsPathRooted(value) ? value : Path.Combine(key, value));
				cacheProviders[key] = new TestCodeCoverageCacheProvider(cacheDirectory, this.fileSystem);
			}
			mergedCachedData = MergeCachedDataFromProviders();
		}

		public CodeCoverageInformation GetCachedData()
		{
			return mergedCachedData;
		}

		public void SaveToCache(CodeCoverageInformation coverageInfo, DateTime timestamp)
		{
			if (coverageInfo == null || cacheProviders.Count == 0)
			{
				return;
			}
			if (coverageInfo.TestStatus != null && coverageInfo.TestStatus.Count > 0)
			{
				cacheProviders.Values.FirstOrDefault()?.SaveToCache(coverageInfo, timestamp);
			}
			if (coverageInfo.Tests == null || coverageInfo.Tests.Count == 0)
			{
				return;
			}
			Dictionary<string, List<CodeCoverageForTest>> dictionary = new Dictionary<string, List<CodeCoverageForTest>>();
			foreach (CodeCoverageForTest test in coverageInfo.Tests)
			{
				string workspaceFolderForApp = GetWorkspaceFolderForApp(test.OwningApp);
				if (workspaceFolderForApp != null)
				{
					if (!dictionary.TryGetValue(workspaceFolderForApp, out var value))
					{
						value = (dictionary[workspaceFolderForApp] = new List<CodeCoverageForTest>());
					}
					value.Add(test);
				}
			}
			foreach (KeyValuePair<string, List<CodeCoverageForTest>> item in dictionary)
			{
				string key = item.Key;
				List<CodeCoverageForTest> value2 = item.Value;
				if (cacheProviders.TryGetValue(key, out TestCodeCoverageCacheProvider value3))
				{
					CodeCoverageInformation coverageInfo2 = new CodeCoverageInformation
					{
						Tests = value2
					};
					value3.SaveToCache(coverageInfo2, timestamp);
				}
			}
		}

		private CodeCoverageInformation MergeCachedDataFromProviders()
		{
			Dictionary<(int, int, Guid), CodeCoverageForTest> dictionary = new Dictionary<(int, int, Guid), CodeCoverageForTest>();
			Dictionary<TestIdentifier, TestResultStatus> dictionary2 = new Dictionary<TestIdentifier, TestResultStatus>();
			foreach (TestCodeCoverageCacheProvider value2 in cacheProviders.Values)
			{
				CodeCoverageInformation cachedData = value2.GetCachedData();
				if (cachedData?.Tests != null)
				{
					foreach (CodeCoverageForTest test in cachedData.Tests)
					{
						(int, int, Guid) key = (test.MethodId, test.ApplicationObjectId, test.OwningApp);
						if (!dictionary.TryGetValue(key, out var value) || test.Timestamp > value.Timestamp)
						{
							dictionary[key] = test;
						}
					}
				}
				if (cachedData?.TestStatus == null)
				{
					continue;
				}
				foreach (KeyValuePair<TestIdentifier, TestResultStatus> item in cachedData.TestStatus)
				{
					dictionary2[item.Key] = item.Value;
				}
			}
			return new CodeCoverageInformation
			{
				Tests = dictionary.Values.ToList(),
				TestStatus = dictionary2
			};
		}

		private string GetWorkspaceFolderForApp(Guid owningApp)
		{
			if (appIdToWorkspaceFolderMap.TryGetValue(owningApp, out string value))
			{
				return value;
			}
			return cacheProviders.Keys.FirstOrDefault();
		}
	}
	internal static class RunTestHelpers
	{
		internal static TestPlan BuildTestPlan(TestItem[] tests)
		{
			Dictionary<int, List<string>> dictionary = new Dictionary<int, List<string>>();
			foreach (TestItem testItem in tests)
			{
				if (testItem.Scope == TestItemScope.Method)
				{
					DebugAssertHelper.AssertNotNull(testItem.CodeunitId, "TestItem of scope Method must have a CodeunitId");
					int value = testItem.CodeunitId.Value;
					if (!dictionary.TryGetValue(value, out var value2))
					{
						value2 = new List<string>();
						dictionary.Add(value, value2);
					}
					value2.Add(testItem.Name);
				}
			}
			List<CodeunitTestGroup> list = new List<CodeunitTestGroup>();
			foreach (KeyValuePair<int, List<string>> item in dictionary)
			{
				list.Add(new CodeunitTestGroup(item.Key, item.Value));
			}
			return new TestPlan(list);
		}
	}
	public class TestCodeCoverageCacheProvider
	{
		private class CoverageCache
		{
			[JsonPropertyName("schemaVersion")]
			public int SchemaVersion { get; set; }

			[JsonPropertyName("coverageData")]
			public List<CachedCoverageEntry> CoverageData { get; set; }

			[JsonPropertyName("testStatus")]
			public Dictionary<string, int> TestStatus { get; set; } = new Dictionary<string, int>();

		}

		private class CachedCoverageEntry
		{
			[JsonPropertyName("test")]
			public CodeCoverageForTest Test { get; set; }

			[JsonPropertyName("timestamp")]
			public DateTime Timestamp { get; set; }
		}

		private const string CacheFileName = "coverage.json";

		private const int CurrentSchemaVersion = 1;

		private readonly string cacheDirectory;

		private readonly IFileSystem fileSystem;

		private readonly CodeCoverageInformation cachedData;

		public TestCodeCoverageCacheProvider(string cacheDirectory, IFileSystem fileSystem = null)
		{
			this.cacheDirectory = cacheDirectory;
			this.fileSystem = fileSystem ?? FileSystem.Instance;
			cachedData = LoadFromCacheInternal();
		}

		public CodeCoverageInformation GetCachedData()
		{
			return cachedData;
		}

		public void SaveToCache(CodeCoverageInformation coverageInfo, DateTime timestamp)
		{
			if (coverageInfo == null || (coverageInfo.Tests == null && coverageInfo.TestStatus == null))
			{
				return;
			}
			try
			{
				string text = Path.Combine(cacheDirectory, "coverage.json");
				if (!fileSystem.DirectoryExists(cacheDirectory))
				{
					fileSystem.CreateDirectoryForFile(text);
				}
				using Stream stream = fileSystem.OpenFile(text, FileMode.OpenOrCreate, FileAccess.ReadWrite);
				CoverageCache coverageCache = ((stream.Length <= 0) ? CreateEmptyCoverageCache() : (System.Text.Json.JsonSerializer.Deserialize<CoverageCache>(stream) ?? CreateEmptyCoverageCache()));
				foreach (CodeCoverageForTest test2 in coverageInfo.Tests)
				{
					CodeCoverageForTest test = DeduplicateCoveredProcedures(test2);
					(int MethodId, int ApplicationObjectId, Guid OwningApp) testKey = GetTestIdentityKey(test);
					CachedCoverageEntry cachedCoverageEntry = coverageCache.CoverageData.FirstOrDefault(delegate(CachedCoverageEntry e)
					{
						(int, int, Guid) testIdentityKey = GetTestIdentityKey(e.Test);
						(int, int, Guid) tuple = testKey;
						return testIdentityKey.Item1 == tuple.Item1 && testIdentityKey.Item2 == tuple.Item2 && testIdentityKey.Item3 == tuple.Item3;
					});
					if (cachedCoverageEntry != null)
					{
						if (timestamp > cachedCoverageEntry.Timestamp)
						{
							cachedCoverageEntry.Test = test;
							cachedCoverageEntry.Timestamp = timestamp;
						}
					}
					else
					{
						coverageCache.CoverageData.Add(new CachedCoverageEntry
						{
							Test = test,
							Timestamp = timestamp
						});
					}
				}
				if (coverageInfo.TestStatus != null)
				{
					foreach (KeyValuePair<TestIdentifier, TestResultStatus> item in coverageInfo.TestStatus)
					{
						string key = $"{item.Key.CodeunitId}|{item.Key.MethodName}";
						coverageCache.TestStatus[key] = (int)item.Value;
					}
				}
				stream.SetLength(0L);
				stream.Seek(0L, SeekOrigin.Begin);
				JsonSerializerOptions options = new JsonSerializerOptions
				{
					WriteIndented = true,
					DefaultIgnoreCondition = JsonIgnoreCondition.Never
				};
				using StreamWriter streamWriter = new StreamWriter(stream, null, -1, leaveOpen: true);
				string value = System.Text.Json.JsonSerializer.Serialize(coverageCache, options);
				streamWriter.Write(value);
				streamWriter.Flush();
			}
			catch (Exception)
			{
			}
		}

		private CodeCoverageInformation LoadFromCacheInternal()
		{
			try
			{
				CoverageCache coverageCache = LoadCacheData();
				List<CodeCoverageForTest> tests = coverageCache.CoverageData.Select(delegate(CachedCoverageEntry e)
				{
					e.Test.Timestamp = e.Timestamp;
					return e.Test;
				}).ToList();
				Dictionary<TestIdentifier, TestResultStatus> dictionary = new Dictionary<TestIdentifier, TestResultStatus>();
				if (coverageCache.TestStatus != null)
				{
					foreach (KeyValuePair<string, int> item in coverageCache.TestStatus)
					{
						int num = item.Key.IndexOf('|');
						if (num > 0 && int.TryParse(item.Key.Substring(0, num), out var result))
						{
							string methodName = item.Key.Substring(num + 1);
							dictionary[new TestIdentifier(result, methodName)] = (TestResultStatus)item.Value;
						}
					}
				}
				return new CodeCoverageInformation
				{
					Tests = tests,
					TestStatus = dictionary
				};
			}
			catch (Exception ex)
			{
				LocalMachineLogger.LogException(ex);
				DebugAssertHelper.Fail("Failed to load coverage cache: " + ex.Message);
				return new CodeCoverageInformation
				{
					Tests = new List<CodeCoverageForTest>()
				};
			}
		}

		private CodeCoverageForTest DeduplicateCoveredProcedures(CodeCoverageForTest test)
		{
			if (test?.CoveredProcedures == null || test.CoveredProcedures.Count == 0)
			{
				return test;
			}
			List<CodeCoverageProcedure> list = new List<CodeCoverageProcedure>();
			HashSet<(int, int, int)> hashSet = new HashSet<(int, int, int)>();
			foreach (CodeCoverageProcedure coveredProcedure in test.CoveredProcedures)
			{
				if (hashSet.Add(GetProcedureKey(coveredProcedure)))
				{
					list.Add(coveredProcedure);
				}
			}
			return new CodeCoverageForTest
			{
				MethodId = test.MethodId,
				ApplicationObjectId = test.ApplicationObjectId,
				OwningApp = test.OwningApp,
				CoveredProcedures = list
			};
		}

		private CoverageCache LoadCacheData()
		{
			string path = Path.Combine(cacheDirectory, "coverage.json");
			if (!fileSystem.Exists(path))
			{
				return CreateEmptyCoverageCache();
			}
			try
			{
				using Stream utf8Json = fileSystem.OpenRead(path);
				return System.Text.Json.JsonSerializer.Deserialize<CoverageCache>(utf8Json) ?? CreateEmptyCoverageCache();
			}
			catch (Exception)
			{
				return CreateEmptyCoverageCache();
			}
		}

		private CoverageCache CreateEmptyCoverageCache()
		{
			return new CoverageCache
			{
				SchemaVersion = 1,
				CoverageData = new List<CachedCoverageEntry>()
			};
		}

		private (int MethodId, int ApplicationObjectId, Guid OwningApp) GetTestIdentityKey(CodeCoverageForTest test)
		{
			return (MethodId: test.MethodId, ApplicationObjectId: test.ApplicationObjectId, OwningApp: test.OwningApp);
		}

		private (int MethodId, int ObjectId, int ObjectType) GetProcedureKey(CodeCoverageProcedure procedure)
		{
			return (MethodId: procedure.MethodId, ObjectId: procedure.ObjectId, ObjectType: procedure.ObjectType);
		}
	}
	public class TestCodeCoverageManager
	{
		private Dictionary<(SymbolKind ObjectType, int ObjectId, int MethodId), HashSet<CodeCoverageForTest>> coverageTestsByMethod = new Dictionary<(SymbolKind, int, int), HashSet<CodeCoverageForTest>>();

		private MultiProjectTestCodeCoverageCacheProvider cacheProvider;

		private readonly string configuredCachePath;

		private readonly VsCodeWorkspace workspace;

		private readonly IFileSystem fileSystem;

		private readonly Dictionary<(int CodeunitId, string MethodName), TestResultStatus> testStatusByMethod = new Dictionary<(int, string), TestResultStatus>();

		public TestCodeCoverageManager(string testCoverageCachePath = null, VsCodeWorkspace workspace = null)
		{
			configuredCachePath = testCoverageCachePath;
			this.workspace = workspace;
			fileSystem = null;
			cacheProvider = null;
		}

		internal TestCodeCoverageManager(VsCodeWorkspace workspace, string testCoverageCachePath, IFileSystem fileSystem)
		{
			this.workspace = workspace;
			configuredCachePath = testCoverageCachePath;
			this.fileSystem = fileSystem;
			cacheProvider = null;
		}

		internal TestCodeCoverageManager(Dictionary<string, string> workspaceFolderCachePaths, IFileSystem fileSystem = null, Dictionary<Guid, string> appIdToFolderMap = null)
		{
			workspace = null;
			configuredCachePath = null;
			this.fileSystem = fileSystem;
			if (workspaceFolderCachePaths != null && workspaceFolderCachePaths.Count > 0)
			{
				cacheProvider = new MultiProjectTestCodeCoverageCacheProvider(workspaceFolderCachePaths, appIdToFolderMap, fileSystem);
				CodeCoverageInformation cachedData = cacheProvider.GetCachedData();
				if (cachedData != null && ((cachedData.Tests != null && cachedData.Tests.Count > 0) || (cachedData.TestStatus != null && cachedData.TestStatus.Count > 0)))
				{
					UpdateCodeCoverageInformationInternal(cachedData, saveToCache: false);
				}
			}
			else
			{
				cacheProvider = null;
			}
		}

		private void EnsureCacheProviderInitialized()
		{
			if (cacheProvider != null || string.IsNullOrEmpty(configuredCachePath) || workspace == null || workspace.CurrentSolution.Projects.Count() == 0)
			{
				return;
			}
			MultiProjectTestCodeCoverageCacheProvider multiProjectTestCodeCoverageCacheProvider = new MultiProjectTestCodeCoverageCacheProvider(workspace, configuredCachePath, fileSystem);
			if (Interlocked.CompareExchange(ref cacheProvider, multiProjectTestCodeCoverageCacheProvider, null) == null)
			{
				CodeCoverageInformation cachedData = multiProjectTestCodeCoverageCacheProvider.GetCachedData();
				if (cachedData != null && ((cachedData.Tests != null && cachedData.Tests.Count > 0) || (cachedData.TestStatus != null && cachedData.TestStatus.Count > 0)))
				{
					UpdateCodeCoverageInformationInternal(cachedData, saveToCache: false);
				}
			}
		}

		public void Clear()
		{
			coverageTestsByMethod.Clear();
			testStatusByMethod.Clear();
		}

		public void UpdateCodeCoverageInformation(CodeCoverageInformation codeCoverageInfo)
		{
			EnsureCacheProviderInitialized();
			UpdateCodeCoverageInformationInternal(codeCoverageInfo, saveToCache: true);
		}

		private void UpdateCodeCoverageInformationInternal(CodeCoverageInformation codeCoverageInfo, bool saveToCache)
		{
			if (codeCoverageInfo?.Tests == null)
			{
				return;
			}
			if (codeCoverageInfo.TestStatus != null)
			{
				foreach (KeyValuePair<TestIdentifier, TestResultStatus> item in codeCoverageInfo.TestStatus)
				{
					testStatusByMethod[(item.Key.CodeunitId, item.Key.MethodName)] = item.Value;
				}
			}
			foreach (CodeCoverageForTest test in codeCoverageInfo.Tests)
			{
				foreach (KeyValuePair<(SymbolKind, int, int), HashSet<CodeCoverageForTest>> item2 in coverageTestsByMethod)
				{
					item2.Value.Remove(test);
				}
				if (test.CoveredProcedures == null)
				{
					continue;
				}
				foreach (CodeCoverageProcedure coveredProcedure in test.CoveredProcedures)
				{
					(SymbolKind, int, int) key = (DebugHelper.MapToSymbolKind((ObjectTypeWrapper)coveredProcedure.ObjectType), coveredProcedure.ObjectId, coveredProcedure.MethodId);
					if (!coverageTestsByMethod.TryGetValue(key, out HashSet<CodeCoverageForTest> value))
					{
						value = new HashSet<CodeCoverageForTest>();
						coverageTestsByMethod[key] = value;
					}
					value.Add(test);
				}
			}
			MultiProjectTestCodeCoverageCacheProvider multiProjectTestCodeCoverageCacheProvider = cacheProvider;
			if (saveToCache)
			{
				multiProjectTestCodeCoverageCacheProvider?.SaveToCache(codeCoverageInfo, DateTime.UtcNow);
			}
		}

		public IEnumerable<CodeCoverageForTest> GetTestsCoveringThis(ISymbol symbolInfoSymbol)
		{
			EnsureCacheProviderInitialized();
			if (symbolInfoSymbol == null)
			{
				return Enumerable.Empty<CodeCoverageForTest>();
			}
			int? num = null;
			int? num2 = null;
			SymbolKind? symbolKind = null;
			if (symbolInfoSymbol.Kind == SymbolKind.Method)
			{
				num = Microsoft.Dynamics.Nav.CodeAnalysis.SymbolExtensions.CalculateMethodId((IMethodSymbol)symbolInfoSymbol);
				IApplicationObjectTypeSymbol containingApplicationObjectTypeSymbol = symbolInfoSymbol.GetContainingApplicationObjectTypeSymbol();
				if (containingApplicationObjectTypeSymbol != null)
				{
					num2 = containingApplicationObjectTypeSymbol.Id;
					symbolKind = containingApplicationObjectTypeSymbol.Kind;
				}
			}
			if (!num.HasValue || !num2.HasValue || !symbolKind.HasValue)
			{
				return Enumerable.Empty<CodeCoverageForTest>();
			}
			if (coverageTestsByMethod.TryGetValue((symbolKind.Value, num2.Value, num.Value), out HashSet<CodeCoverageForTest> value))
			{
				return new List<CodeCoverageForTest>(value);
			}
			return Enumerable.Empty<CodeCoverageForTest>();
		}

		public void UpdateTestStatus(int codeunitId, string methodName, TestResultStatus status)
		{
			if (!string.IsNullOrWhiteSpace(methodName))
			{
				testStatusByMethod[(codeunitId, methodName)] = status;
				MultiProjectTestCodeCoverageCacheProvider multiProjectTestCodeCoverageCacheProvider = cacheProvider;
				if (multiProjectTestCodeCoverageCacheProvider != null)
				{
					TestIdentifier key = new TestIdentifier(codeunitId, methodName);
					CodeCoverageInformation coverageInfo = new CodeCoverageInformation
					{
						TestStatus = new Dictionary<TestIdentifier, TestResultStatus> { { key, status } }
					};
					multiProjectTestCodeCoverageCacheProvider.SaveToCache(coverageInfo, DateTime.UtcNow);
				}
			}
		}

		public bool TryGetStatus(int codeunitId, string methodName, out TestResultStatus status)
		{
			status = TestResultStatus.Passed;
			if (string.IsNullOrWhiteSpace(methodName))
			{
				return false;
			}
			return testStatusByMethod.TryGetValue((codeunitId, methodName), out status);
		}

		public bool ContainsData()
		{
			EnsureCacheProviderInitialized();
			Dictionary<(SymbolKind ObjectType, int ObjectId, int MethodId), HashSet<CodeCoverageForTest>> dictionary = coverageTestsByMethod;
			if (dictionary == null)
			{
				return false;
			}
			return dictionary.Count > 0;
		}
	}
	internal class TestDiscoveryManager : IDisposable
	{
		private readonly double testRefreshIntervalInTicks;

		private double lastWorkspaceChangeTick = DateTime.MinValue.Ticks;

		private double lastUpdateChangeTick = DateTime.MinValue.Ticks;

		private readonly VsCodeWorkspace workspace;

		private IResponseQueue responseQueue;

		private AutoResetEvent? onTestsUpdatedEvent;

		private PeriodicTimer timer;

		private ConcurrentQueue<ProjectId> changedApps = new ConcurrentQueue<ProjectId>();

		private ConcurrentHashSet<ProjectId> processingApps = new ConcurrentHashSet<ProjectId>();

		public TestDiscoveryManager(VsCodeWorkspace workspace, IResponseQueue responseQueue, int testRefreshIntervalInMs = 3000, AutoResetEvent? onTestsUpdatedEvent = null)
		{
			this.workspace = workspace;
			this.responseQueue = responseQueue;
			testRefreshIntervalInTicks = System.TimeSpan.FromMilliseconds(testRefreshIntervalInMs).Ticks;
			this.onTestsUpdatedEvent = onTestsUpdatedEvent;
			this.workspace.WorkspaceChanged += OnWorkspaceChanged;
			timer = new PeriodicTimer(System.TimeSpan.FromMilliseconds(testRefreshIntervalInMs));
			StartAsync().ConfigureAwait(continueOnCapturedContext: false);
		}

		public void Dispose()
		{
			workspace.WorkspaceChanged -= OnWorkspaceChanged;
		}

		public async Task StartAsync()
		{
			try
			{
				while (await timer.WaitForNextTickAsync().ConfigureAwait(continueOnCapturedContext: false))
				{
					if (!(lastUpdateChangeTick < lastWorkspaceChangeTick))
					{
						continue;
					}
					try
					{
						ProjectId result;
						while (changedApps.TryDequeue(out result))
						{
							if (processingApps.Add(result))
							{
								TestItem[] result2 = DiscoverTests(result, CancellationToken.None).GetAwaiter().GetResult();
								if (result2 != null)
								{
									responseQueue.Add(ResponseFactory.UpdateTests(result2));
								}
							}
						}
						Interlocked.Exchange(ref lastUpdateChangeTick, lastWorkspaceChangeTick);
						onTestsUpdatedEvent?.Set();
					}
					finally
					{
						processingApps.Clear();
					}
				}
			}
			catch (OperationCanceledException)
			{
			}
			catch (Exception ex2)
			{
				LocalMachineLogger.LogException(ex2);
			}
		}

		private void OnWorkspaceChanged(object? sender, WorkspaceChangeEventArgs e)
		{
			switch (e.Kind)
			{
			case WorkspaceChangeKind.SolutionAdded:
			case WorkspaceChangeKind.ProjectAdded:
			case WorkspaceChangeKind.ProjectReloaded:
			case WorkspaceChangeKind.DocumentAdded:
			case WorkspaceChangeKind.DocumentRemoved:
			case WorkspaceChangeKind.DocumentChanged:
				if (e.ProjectId != null && !processingApps.Contains(e.ProjectId))
				{
					changedApps.Enqueue(e.ProjectId);
				}
				Interlocked.Exchange(ref lastWorkspaceChangeTick, DateTime.UtcNow.Ticks);
				break;
			}
		}

		public async Task<TestItem[]> DiscoverTests(CancellationToken cancellationToken)
		{
			using ArrayBuilder<TestItem> allAppItems = ArrayBuilder<TestItem>.GetInstance();
			foreach (Project project in workspace.CurrentSolution.Projects)
			{
				cancellationToken.ThrowIfCancellationRequested();
				TestItem[] array = await DiscoverTests(project.Id, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				if (array != null && array.Length != 0)
				{
					allAppItems.AddRange(array);
				}
			}
			return allAppItems.ToArray();
		}

		public async Task<TestItem[]> DiscoverTests(ProjectId projectId, CancellationToken cancellationToken)
		{
			Project project = workspace.CurrentSolution.GetProject(projectId);
			if (project != null && workspace.AreAllProjectReferencesBound(projectId))
			{
				ProjectDefinition projectDefinition = project.ProjectDefinition;
				int num;
				if ((object)projectDefinition == null)
				{
					num = 1;
				}
				else
				{
					_ = projectDefinition.AppId;
					num = 0;
				}
				if (num == 0)
				{
					string appId = project.ProjectDefinition.AppId.ToString();
					string projectName = project.ProjectDefinition?.Name ?? project.Name;
					Compilation compilation = await workspace.CurrentSolution.GetCompilationAsync(projectId, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
					if (compilation == null)
					{
						return Array.Empty<TestItem>();
					}
					using ArrayBuilder<TestItem> arrayBuilder = ArrayBuilder<TestItem>.GetInstance();
					foreach (IApplicationObjectTypeSymbol applicationObjectTypeSymbol in compilation.GetApplicationObjectTypeSymbols(SymbolKind.Codeunit))
					{
						cancellationToken.ThrowIfCancellationRequested();
						if (applicationObjectTypeSymbol.IsSourceSymbol())
						{
							SourceCodeunitTypeSymbol sourceCodeunitTypeSymbol = (SourceCodeunitTypeSymbol)applicationObjectTypeSymbol;
							if (sourceCodeunitTypeSymbol.GetCodeunitSubtype().GetValueOrDefault() == CodeunitSubtypeKind.Test)
							{
								TestItem item = CreateCodeunitTestItem(sourceCodeunitTypeSymbol, appId, project.ProjectFolder);
								arrayBuilder.Add(item);
							}
						}
					}
					TestItem[] array = arrayBuilder.ToArray();
					if (array.Length == 0)
					{
						return Array.Empty<TestItem>();
					}
					TestItem testItem = new TestItem
					{
						Name = projectName,
						AppId = appId,
						Scope = TestItemScope.App,
						Location = null,
						Children = array
					};
					return new TestItem[1] { testItem };
				}
			}
			return null;
		}

		private static TestItem CreateCodeunitTestItem(SourceCodeunitTypeSymbol codeunit, string appId, string projectFolder)
		{
			int id = codeunit.Id;
			using ArrayBuilder<TestItem> arrayBuilder = ArrayBuilder<TestItem>.GetInstance();
			ImmutableArray<Symbol>.Enumerator enumerator = codeunit.Members.GetMembers().GetEnumerator();
			while (enumerator.MoveNext())
			{
				Symbol current = enumerator.Current;
				if (current.Kind == SymbolKind.Method)
				{
					MethodSymbol methodSymbol = (MethodSymbol)current;
					if (methodSymbol.IsTest)
					{
						TestItem item = new TestItem
						{
							Name = methodSymbol.Name,
							AppId = appId,
							CodeunitId = id,
							Scope = TestItemScope.Method,
							Location = GetLocation(methodSymbol, projectFolder)
						};
						arrayBuilder.Add(item);
					}
				}
			}
			return new TestItem
			{
				Name = codeunit.Name,
				AppId = appId,
				CodeunitId = id,
				Scope = TestItemScope.Codeunit,
				Location = GetLocation(codeunit, projectFolder),
				Children = arrayBuilder.ToArray()
			};
		}

		private static TestLocation GetLocation(Symbol symbol, string projectFolder)
		{
			Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.Contract.Location symbolLocation = Microsoft.Dynamics.Nav.EditorServices.Protocol.Utility.SymbolExtensions.GetSymbolLocation(symbol, projectFolder);
			return new TestLocation
			{
				Source = symbolLocation.Uri,
				Range = symbolLocation.Range
			};
		}
	}
