	internal class VsCodeTestRunnerService : HubBasedTestRunnerService, ITestRunnerService
	{
		private readonly TestCodeCoverageManager codeCoverageManager;

		private readonly IResponseQueue responseQueue;

		public IEmitLogger Logger => logger;

		public VsCodeTestRunnerService(TestCodeCoverageManager codeCoverageManager, IResponseQueue responseQueue)
			: base(new TestExecutionLogger(responseQueue))
		{
			this.codeCoverageManager = codeCoverageManager;
			this.responseQueue = responseQueue;
			base.TestStarted += OnTestStarted;
			base.TestCompleted += OnTestCompleted;
			base.RunCompleted += OnRunCompleted;
			base.RunFinished += OnRunFinished;
		}

		void ITestRunnerService.SendMessage(string message)
		{
			logger?.Info(message);
		}

		public override void LogServerInfoMessage(string message)
		{
			base.LogServerInfoMessage(message);
			if (!string.IsNullOrEmpty(message))
			{
				responseQueue.Add(ResponseFactory.LogNotification(MessageType.Log, message));
			}
		}

		public override void LogServerMessage(string message)
		{
			base.LogServerMessage(message);
			if (!string.IsNullOrEmpty(message))
			{
				responseQueue.Add(ResponseFactory.LogNotification(MessageType.Log, message));
			}
		}

		private void OnTestStarted(int codeunitId, string methodName)
		{
			responseQueue.Add(ResponseFactory.TestExecutionTestStarted(codeunitId, methodName));
		}

		private void OnTestCompleted(int codeunitId, string methodName, TestResultStatus status, string output, long duration)
		{
			codeCoverageManager.UpdateTestStatus(codeunitId, methodName, status);
			responseQueue.Add(ResponseFactory.TestExecutionTestFinished(codeunitId, methodName, status, output, duration));
		}

		private void OnRunCompleted(CodeCoverageInformation data)
		{
			codeCoverageManager.UpdateCodeCoverageInformation(data);
		}

		private void OnRunFinished()
		{
			responseQueue.Add(ResponseFactory.TestExecutionRunFinished());
		}

		bool ITestRunnerService.get_IsConnectionOpen()
		{
			return base.IsConnectionOpen;
		}

		Task ITestRunnerService.SetupAndRunTests(ConnectionOptions connectionOptions, string startupCompany, TestPlan testPlan, string debuggingContext, CoverageMode coverageMode, CancellationToken cancellationToken)
		{
			return SetupAndRunTests(connectionOptions, startupCompany, testPlan, debuggingContext, coverageMode, cancellationToken);
		}

		Task ITestRunnerService.OpenConnectionAsync(string url, ConnectionOptions connectionOptions)
		{
			return OpenConnectionAsync(url, connectionOptions);
		}

		Task ITestRunnerService.RunTests(TestPlan testPlan, CancellationToken cancellationToken)
		{
			return RunTests(testPlan, cancellationToken);
		}

		Task ITestRunnerService.Initialize(string companyName, string debuggingContext, CoverageMode coverageMode, CancellationToken cancellationToken)
		{
			return Initialize(companyName, debuggingContext, coverageMode, cancellationToken);
		}

		Task ITestRunnerService.StopTestRunAsync(CancellationToken cancellationToken)
		{
			return StopTestRunAsync(cancellationToken);
		}
	}
