namespace Microsoft.Dynamics.Nav.EditorServices.Protocol.DebugAdapter
{
	public enum BreakOnNext
	{
		WebServiceClient,
		WebClient,
		Background,
		ClientService
	}
	[JsonObject]
	public class AttachOptions : IEquatable<AttachOptions>
	{
		[Newtonsoft.Json.JsonIgnore]
		private static readonly Lazy<AttachOptions> defaultOptions = new Lazy<AttachOptions>(() => new AttachOptions
		{
			BreakOnNextClient = BreakOnNext.WebClient
		});

		[Newtonsoft.Json.JsonIgnore]
		public static AttachOptions Default => defaultOptions.Value;

		[JsonProperty]
		public BreakOnNext BreakOnNextClient { get; set; }

		[JsonProperty]
		public int SessionId { get; set; }

		[JsonProperty]
		public string? UserId { get; set; }

		public override bool Equals(object? obj)
		{
			return Equals(obj as AttachOptions);
		}

		public bool Equals(AttachOptions? other)
		{
			if ((object)other != null && BreakOnNextClient == other.BreakOnNextClient && SessionId == other.SessionId)
			{
				return string.Equals(UserId, other.UserId, StringComparison.Ordinal);
			}
			return false;
		}

		public override int GetHashCode()
		{
			return Hash.Combine(BreakOnNextClient.GetHashCode(), SessionId.GetHashCode(), UserId?.GetHashCode() ?? 0);
		}

		public static bool operator ==(AttachOptions? left, AttachOptions? right)
		{
			if ((object)left != right)
			{
				return left?.Equals(right) ?? false;
			}
			return true;
		}

		public static bool operator !=(AttachOptions? left, AttachOptions? right)
		{
			return !(left == right);
		}

		public override string ToString()
		{
			return string.Format(CultureInfo.InvariantCulture, "ClientType: {0}, SessionId: {1}, UserId: {2}", BreakOnNextClient, SessionId, UserId ?? string.Empty);
		}

		public string GetKeyPart()
		{
			return string.Format(CultureInfo.InvariantCulture, "{0}_{1}_{2}", BreakOnNextClient, SessionId, UserId ?? string.Empty).ToUpperInvariant();
		}
	}
	[DebuggerDisplay("{ToString(), nq}")]
	internal class BreakpointInfo : IEquatable<BreakpointInfo>
	{
		internal BreakpointDefinition? BreakpointDefinition { get; set; }

		internal int HitCount { get; set; }

		internal bool IsSnapPoint { get; set; }

		public int BreakpointId
		{
			get
			{
				if (BreakpointDefinition != null)
				{
					return CreateId(BreakpointDefinition.ObjectId, BreakpointDefinition.SourceSpan.From.Line);
				}
				return 0;
			}
		}

		public BreakpointInfo(ApplicationObjectIdWrapper id, Microsoft.Dynamics.Nav.DebuggerService.SourcePosition position, string condition, int hitCount, bool isSnapPoint)
			: this(id, new Microsoft.Dynamics.Nav.DebuggerService.SourceSpan(position, new Microsoft.Dynamics.Nav.DebuggerService.SourcePosition(position.Line, (ushort)(position.Column + 1))), condition, hitCount, isSnapPoint)
		{
		}

		public BreakpointInfo(ApplicationObjectIdWrapper id, Microsoft.Dynamics.Nav.DebuggerService.SourceSpan span, string condition, int hitCount, bool isSnapPoint)
		{
			BreakpointDefinition = new BreakpointDefinition
			{
				ObjectId = id,
				SourceSpan = span,
				Condition = condition
			};
			HitCount = hitCount;
			IsSnapPoint = isSnapPoint;
		}

		public BreakpointInfo(BreakpointDefinition breakpointDefinition, int hitCount, bool isSnapPoint)
		{
			BreakpointDefinition = breakpointDefinition;
			HitCount = hitCount;
			IsSnapPoint = isSnapPoint;
		}

		public static int CreateId(ApplicationObjectIdWrapper id, int lineNumber)
		{
			return Hash.Combine(id.GetHashCode(), lineNumber.GetHashCode());
		}

		public bool Equals(BreakpointInfo? other)
		{
			if ((object)other == null)
			{
				return false;
			}
			if (BreakpointDefinition?.ObjectId == other.BreakpointDefinition?.ObjectId)
			{
				return BreakpointDefinition?.SourceSpan.From.Line == other.BreakpointDefinition?.SourceSpan.From.Line;
			}
			return false;
		}

		public override int GetHashCode()
		{
