		}

		public static bool operator !=(BreakpointInfo left, BreakpointInfo right)
		{
			return !(left == right);
		}

		public override bool Equals(object obj)
		{
			if (obj == null)
			{
				return false;
			}
			if (!(obj is BreakpointInfo other))
			{
				return false;
			}
			return Equals(other);
		}

		public override string ToString()
		{
			return string.Format(CultureInfo.InvariantCulture, "{0}:{1}:{2}:{3}:{4}", BreakpointDefinition?.ObjectId, BreakpointDefinition?.SourceSpan, BreakpointDefinition?.MethodName, IsSnapPoint, HitCount);
		}
	}
	internal class DebugAdapterAttachRequestHandler : DebugAdapterStartRequestHandler
	{
		public override string EndpointName => "attach";

		internal DebugAdapterAttachRequestHandler(IProxyBasedDebuggerService service, VsCodeWorkspace workspace, ResponseQueue responseQueue)
			: base(service, workspace, responseQueue)
		{
		}

		public override async Task HandleAsync(InitializeDebugAdapterRequest request, int requestId, CancellationToken cancellationToken)
		{
			InitializeDebugAdapterRequest request2 = request;
			base.Logger.Info(DeploymentResources.StartingDebuggingWithLaunchConfiguration, request2.Name);
			LogTelemetry(request2, requestId);
			await HandleAttachOrLaunchAsync(request2, requestId, cancellationToken, async delegate(ServerInfo serverInfo, ConnectionOptions connectionOptions)
			{
				if (serverInfo == null || serverInfo.ConnectionOptions == null)
				{
					AddErrorResponse(requestId, cancellationToken);
				}
				else
				{
					System.Version? debuggerVersion = serverInfo.DebuggerVersion;
					if ((object)debuggerVersion != null && debuggerVersion.Major < 3)
					{
						base.Logger.Info(ProtocolResources.DebuggerAttachRequestCannotbeUsedForThisServerVersion);
					}
					else
					{
						AttachOptions attachOptions = request2.AttachOptions();
						ClientConnectionInfo clientConnectionInfo = await GetClientConnectionInfo(serverInfo).ConfigureAwait(continueOnCapturedContext: false);
						if (clientConnectionInfo == null)
						{
							AddErrorResponse(requestId, cancellationToken);
						}
						else if (!(await StartDebugging(clientConnectionInfo, serverInfo, request2.DebugOptions(), attachOptions).ConfigureAwait(continueOnCapturedContext: false)))
						{
							AddErrorResponse(requestId, cancellationToken);
						}
						else
						{
							base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId), cancellationToken);
						}
					}
				}
			}).ConfigureAwait(continueOnCapturedContext: false);
		}

		private void AddErrorResponse(int requestId, CancellationToken cancellationToken)
		{
