	internal class DebugAdapterBreakpointRequestHandler : DebugAdapterRequestHandlerBase<DebugAdapterSetBreakpointsRequest>
	{
		private class BreakpointContext : IEquatable<BreakpointContext>
		{
			internal ApplicationObjectIdWrapper DeclaringApplicationObjectId { get; }

			internal SourceBreakpoint SourceBreakpoint { get; }

			internal string Path { get; }

			internal BreakpointContext(SourceBreakpoint sourceBreakpoint, string path, ApplicationObjectIdWrapper id)
			{
				SourceBreakpoint = sourceBreakpoint;
				Path = path.CreateUriFilePath();
				DeclaringApplicationObjectId = id;
			}

			public bool Equals(BreakpointContext other)
			{
				if ((object)this == other)
				{
					return true;
				}
				if (other != null && other.SourceBreakpoint == SourceBreakpoint && DeclaringApplicationObjectId == other.DeclaringApplicationObjectId)
				{
					return string.Equals(other.Path, Path, StringComparison.OrdinalIgnoreCase);
				}
				return false;
			}

			public override bool Equals(object obj)
			{
				return Equals(obj as BreakpointContext);
			}

			public static bool operator ==(BreakpointContext left, BreakpointContext right)
			{
				return object.Equals(left, right);
			}

			public static bool operator !=(BreakpointContext left, BreakpointContext right)
			{
				return !object.Equals(left, right);
			}

			public override int GetHashCode()
			{
				return Hash.Combine((!string.IsNullOrEmpty(Path)) ? Path.GetHashCode() : 0, (!(SourceBreakpoint == null)) ? SourceBreakpoint.GetHashCode() : 0, DeclaringApplicationObjectId.GetHashCode());
			}
		}

		private readonly ConcurrentDictionary<BreakpointContext, long> breakpoints = new ConcurrentDictionary<BreakpointContext, long>();

		private readonly ConcurrentSet<DebugAdapterSetBreakpointsRequest> requests = new ConcurrentSet<DebugAdapterSetBreakpointsRequest>();

		public override string EndpointName => "setbreakpoints";

		internal DebugAdapterBreakpointRequestHandler(IProxyBasedDebuggerService service, VsCodeWorkspace workspace, ResponseQueue responseQueue)
			: base(service, workspace, responseQueue)
		{
		}

		public override async Task HandleAsync(DebugAdapterSetBreakpointsRequest request, int requestId, CancellationToken cancellationToken)
		{
			try
			{
				if (request.Breakpoints == null || requests.Contains(request))
				{
					base.ResponseQueue.Add(ResponseFactory.DebugAdapterSetBreakpointsResponse(requestId, new Breakpoint[0]), cancellationToken);
					return;
				}
				requests.Add(request);
				IEnumerable<Breakpoint> enumerable = await AddOrUpdateBreakpointsAsync(request, requestId, cancellationToken);
				if (enumerable == null)
				{
					base.ResponseQueue.Add(ResponseFactory.ErrorResponse(new MessageError
					{
						Message = string.Format(CultureInfo.CurrentUICulture, ProtocolResources.MissingBreakpointRequestFile, request.Source.Path)
					}, "setbreakpoints", requestId), cancellationToken);
				}
				else
				{
					base.ResponseQueue.Add(ResponseFactory.DebugAdapterSetBreakpointsResponse(requestId, enumerable), cancellationToken);
				}
			}
			finally
			{
				requests.Remove(request);
			}
		}

		private async Task<IEnumerable<Breakpoint>> AddOrUpdateBreakpointsAsync(DebugAdapterSetBreakpointsRequest request, int requestId, CancellationToken cancellationToken)
		{
			DebugAdapterSetBreakpointsRequest request2 = request;
			HashSet<int> debuggerLines = new HashSet<int>(request2.Breakpoints.Select((SourceBreakpoint b) => b.Line));
			List<BreakpointContext> breakpointsOnTheSamePath = breakpoints.Keys.Where((BreakpointContext b) => string.Equals(b.Path.CreateUriFilePath(), request2.Source.Path.CreateUriFilePath(), StringComparison.OrdinalIgnoreCase)).ToList();
			PooledDictionary<int, Tuple<long, string>> existingLinesWithIdsAndCondition = PooledDictionary<int, Tuple<long, string>>.GetInstance();
			try
			{
				await RemoveRemovedBreakpointsAsync(debuggerLines, existingLinesWithIdsAndCondition, breakpointsOnTheSamePath);
				return await AddOrUpdateBreakpointsAsync(request2, existingLinesWithIdsAndCondition, cancellationToken);
			}
			finally
			{
				existingLinesWithIdsAndCondition.Free();
			}
		}

		private async Task<Breakpoint?> CreateBreakpointAsync(SourceBreakpoint sourceBp, Source source, CancellationToken cancellationToken)
		{
			Position position = Position.Create(sourceBp.Line, sourceBp.Column, DebugAdapterInitializeRequestHandler.Settings != null && DebugAdapterInitializeRequestHandler.Settings.LinesStartAt1);
			if (position == Position.InvalidPosition)
			{
				return null;
			}
			ApplicationObjectIdWrapper? applicationObjectId = null;
			string text = source.Path.CreateUriFilePath();
			Document document = base.Workspace.GetDocument(text);
			if (document != null)
			{
				(ApplicationObjectIdWrapper?, Position) tuple = await document.GetDeclaringApplicationObjectAndAdjustLineNumberFromDebugClientPositionsAsync(position, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				if (!tuple.Item1.HasValue || tuple.Item2 == null)
				{
					return null;
				}
				(applicationObjectId, position) = tuple;
			}
			else if (text.IsAlFile())
			{
				DocumentId documentId = null;
				base.Workspace.BufferManager.TryAddTransientDocument(base.Workspace.CurrentProjectId, text, null, handleRad: false, out documentId);
				document = base.Workspace.CurrentSolution.GetDocument(documentId);
				if (document != null)
				{
					(ApplicationObjectIdWrapper?, Position) tuple3 = await document.GetDeclaringApplicationObjectAndAdjustLineNumberFromDebugClientPositionsAsync(position, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
					if (!tuple3.Item1.HasValue || tuple3.Item2 == null)
					{
						return null;
					}
					(applicationObjectId, position) = tuple3;
				}
			}
			else
			{
				PreviewFileUrl previewFileUrl = new Uri(source.Path).ParsePreviewFileUrl();
				if (previewFileUrl == PreviewFileUrl.Empty || previewFileUrl.Id == 0)
				{
					return null;
				}
				ObjectTypeWrapper? objectTypeWrapper = DebugHelper.MapToObjectType(previewFileUrl.Kind);
				if (objectTypeWrapper.HasValue)
				{
					applicationObjectId = new ApplicationObjectIdWrapper(objectTypeWrapper.Value, previewFileUrl.Id);
				}
			}
			BreakpointDefinition breakpointDefinition = (applicationObjectId.HasValue ? (await base.DebuggerService.AddBreakpointAsync(applicationObjectId.Value, DebugHelper.SourcePosition(position), sourceBp.Condition).ConfigureAwait(continueOnCapturedContext: false)) : null);
			BreakpointDefinition breakpointDefinition2 = breakpointDefinition;
			Breakpoint result;
			if (breakpointDefinition2 != null)
			{
				result = Breakpoint.CreateFromSource(sourceBp, source, verified: true, breakpointDefinition2.BreakpointId);
				breakpoints.TryAdd(new BreakpointContext(sourceBp, source.Path, applicationObjectId.Value), breakpointDefinition2.BreakpointId);
			}
			else
			{
				result = Breakpoint.CreateFromSource(sourceBp, source, verified: false, 0L);
			}
			return result;
		}

		private async Task RemoveRemovedBreakpointsAsync(HashSet<int> debuggerLines, PooledDictionary<int, Tuple<long, string>> existingLinesWithIdsAndCondition, IEnumerable<BreakpointContext> breakpointsOnTheSamePath)
		{
			foreach (BreakpointContext item in breakpointsOnTheSamePath)
			{
				long num = breakpoints[item];
				if (debuggerLines.Contains(item.SourceBreakpoint.Line))
				{
					existingLinesWithIdsAndCondition[item.SourceBreakpoint.Line] = new Tuple<long, string>(num, item.SourceBreakpoint.Condition);
					continue;
				}
				breakpoints.TryRemove(item, out var _);
				await base.DebuggerService.RemoveBreakpointAsync(num);
			}
		}

		private async Task<IList<Breakpoint>> AddOrUpdateBreakpointsAsync(DebugAdapterSetBreakpointsRequest request, PooledDictionary<int, Tuple<long, string>> existingLinesWithIdsAndCondition, CancellationToken cancellationToken)
		{
			IList<Breakpoint> returnBreakpoints = new List<Breakpoint>();
			SourceBreakpoint[] array = request.Breakpoints;
			foreach (SourceBreakpoint sourceBreakpoint in array)
			{
				Breakpoint breakpoint;
				if (!existingLinesWithIdsAndCondition.ContainsKey(sourceBreakpoint.Line))
				{
					breakpoint = await CreateBreakpointAsync(sourceBreakpoint, request.Source, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
					if (breakpoint == null)
					{
						continue;
					}
				}
				else
				{
					Tuple<long, string> tuple = existingLinesWithIdsAndCondition[sourceBreakpoint.Line];
					long id = tuple.Item1;
					string item = tuple.Item2;
					if (!string.IsNullOrEmpty(sourceBreakpoint.Condition) && !string.Equals(item, sourceBreakpoint.Condition, StringComparison.OrdinalIgnoreCase))
					{
						await base.DebuggerService.UpdateBreakpointAsync(id, sourceBreakpoint.Condition).ConfigureAwait(continueOnCapturedContext: false);
					}
					breakpoint = Breakpoint.CreateFromSource(sourceBreakpoint, request.Source, verified: true, id);
				}
				if (breakpoint != null)
				{
					returnBreakpoints.Add(breakpoint);
				}
			}
			return returnBreakpoints;
		}
	}
