	internal class DebugAdapterEvaluateRequestHandler : DebugAdapterRequestHandlerBase<DebugAdapterEvaluateRequest>
	{
		private class EvaluateExpressionToServerDebugSyntax : SyntaxVisitor
		{
			private readonly StringBuilder serverDebugSyntax = new StringBuilder();

			public string ServerDebugSyntax => serverDebugSyntax.ToString();

			public override void VisitElementAccessExpression(ElementAccessExpressionSyntax node)
			{
				if (node.Expression.Kind == SyntaxKind.ArrayIndexExpression || node.Expression.Kind == SyntaxKind.IdentifierName)
				{
					Visit(node.Expression);
				}
				SeparatedSyntaxList<CodeExpressionSyntax>.Enumerator enumerator = node.ArgumentList.Arguments.GetEnumerator();
				while (enumerator.MoveNext())
				{
					CodeExpressionSyntax current = enumerator.Current;
					serverDebugSyntax.Append(".\"[");
					serverDebugSyntax.Append(current.ToFullString());
					serverDebugSyntax.Append("]\"");
				}
			}

			public override void VisitIdentifierName(IdentifierNameSyntax node)
			{
				serverDebugSyntax.Append(node?.GetIdentifierOrLiteralValue()?.QuoteIdentifierIfNeeded());
			}

			public override void VisitMemberAccessExpression(MemberAccessExpressionSyntax node)
			{
				Visit(node.Expression);
				serverDebugSyntax.Append(node.DotToken.ToString());
				serverDebugSyntax.Append(node?.Name.GetIdentifierOrLiteralValue()?.QuoteIdentifierIfNeeded());
			}
		}

		public override string EndpointName => "evaluate";

		internal DebugAdapterEvaluateRequestHandler(IProxyBasedDebuggerService service, VsCodeWorkspace workspace, ResponseQueue responseQueue)
			: base(service, workspace, responseQueue)
		{
		}

		public override async Task HandleAsync(DebugAdapterEvaluateRequest request, int requestId, CancellationToken cancellationToken)
		{
			if (!request.Context.HasValue || string.IsNullOrEmpty(request.Expression))
			{
				base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId), cancellationToken);
				return;
			}
			string expression = request.Expression;
			int result = 0;
			if (request.Expression.StartsWith("\"<Database Statistics>\"", StringComparison.OrdinalIgnoreCase))
			{
				string[] array = expression.Split(DebugAdapterVariablesRequestHandler.EvaluateNameSeparator.ToCharArray(), StringSplitOptions.RemoveEmptyEntries);
				if (array != null && array.Length != 0)
				{
					expression = array[0];
					if (array.Length == 2)
					{
						int.TryParse(array[1], out result);
					}
				}
			}
			if (request.Context == DebugAdapterEvaluateContext.Variables && result != 0)
			{
				EvaluteDatabaseStatistics(expression, result, request.FrameId, requestId, cancellationToken);
				return;
			}
			if (request.Context != DebugAdapterEvaluateContext.Variables && expression.Equals(Microsoft.Dynamics.Nav.EditorServices.Protocol.DebugAdapter.DebuggerService.ExceptionNodeName, StringComparison.Ordinal))
			{
				base.ResponseQueue.Add(ResponseFactory.DebugAdapterEvaluateResponse(requestId, string.IsNullOrEmpty(base.DebuggerService.CurrentError) ? ProtocolResources.WatchExpressionNotAvailable : base.DebuggerService.CurrentError), cancellationToken);
				return;
			}
			string serverDebugSyntax = MapExpressionToServerDebugSyntax(expression, cancellationToken);
			WatchOption watchOption = ((request.Context.GetValueOrDefault() == DebugAdapterEvaluateContext.Console) ? WatchOption.AllowLargeStrings : WatchOption.None);
			LocalNode node = await base.DebuggerService.GetWatchNodeAsync(request.FrameId, serverDebugSyntax, watchOption).ConfigureAwait(continueOnCapturedContext: false);
			int reference = 0;
			int childCount = 0;
			if (node != null && node.HasChildren)
			{
				string path = (serverDebugSyntax.Equals(expression) ? serverDebugSyntax.QuoteIdentifierIfNeeded() : serverDebugSyntax);
				LocalNodeContext value;
				if (node.Children != null)
				{
					value = new LocalNodeContext(request.FrameId, path, node.Children);
					childCount = node.Children.Count;
				}
				else
				{
					IList<LocalNode> nodes = await base.DebuggerService.ExpandNodeAsync(request.FrameId, path).ConfigureAwait(continueOnCapturedContext: false);
					value = new LocalNodeContext(request.FrameId, path, nodes);
				}
				reference = base.DebuggerService.ChildNodeHandles.Create(value);
			}
			else if (node == null)
			{
				base.ResponseQueue.Add(ResponseFactory.DebugAdapterEvaluateResponse(requestId, ProtocolResources.WatchExpressionNotAvailable), cancellationToken);
				return;
			}
			base.ResponseQueue.Add(ResponseFactory.DebugAdapterEvaluateResponse(requestId, node.Summary, node.TypeName, childCount, reference), cancellationToken);
		}

		private void EvaluteDatabaseStatistics(string expression, int variableId, int frameId, int requestId, CancellationToken cancellationToken)
		{
			LocalNodeContext localNodeContext = base.DebuggerService.ChildNodeHandles.Get(variableId);
			if (localNodeContext == null || localNodeContext.Nodes == null || localNodeContext.Nodes.Count == 0 || localNodeContext.StackFrameIndex != frameId)
			{
				base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId), cancellationToken);
				return;
			}
			string[] array = expression.Split(new char[1] { '.' }, StringSplitOptions.RemoveEmptyEntries);
			if (array == null || array.Length == 0)
			{
				base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId), cancellationToken);
				return;
			}
			string value = array[^1];
			foreach (LocalNode node in localNodeContext.Nodes)
			{
				string obj = node.Name?.QuoteIdentifierIfNeeded();
				if (obj != null && obj.Equals(value, StringComparison.OrdinalIgnoreCase))
				{
					base.ResponseQueue.Add(ResponseFactory.DebugAdapterEvaluateResponse(requestId, node.Summary, node.TypeName, node.Children?.Count ?? 0), cancellationToken);
					return;
				}
			}
			base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId), cancellationToken);
		}

		private static string MapExpressionToServerDebugSyntax(string expression, CancellationToken cancellationToken)
		{
			CodeExpressionSyntax codeExpressionSyntax = SyntaxFactory.ParseExpression(expression);
			if (codeExpressionSyntax == null || codeExpressionSyntax.ContainsDiagnostics)
			{
				return expression;
			}
			if (!codeExpressionSyntax.DescendantNodesAndSelf().Any((SyntaxNode n) => n.Kind == SyntaxKind.ArrayIndexExpression))
			{
				return expression;
			}
			EvaluateExpressionToServerDebugSyntax evaluateExpressionToServerDebugSyntax = new EvaluateExpressionToServerDebugSyntax();
			evaluateExpressionToServerDebugSyntax.Visit(codeExpressionSyntax);
			string serverDebugSyntax = evaluateExpressionToServerDebugSyntax.ServerDebugSyntax;
			if (!string.IsNullOrEmpty(serverDebugSyntax))
			{
				return serverDebugSyntax;
			}
			return expression;
		}
	}
