		public override bool ProfilePerformance => true;

		internal DebugAdapterLaunchRequestHandler(IProxyBasedDebuggerService service, VsCodeWorkspace workspace, ResponseQueue responseQueue, IClientStartup clientStartup, ITestRunnerService testRunnerService, IFileSystem fileSystem = null)
			: base(workspace, (IResponseQueue)responseQueue)
