		private DebugAdapterLaunchRequestHandlerBase GetDelegateHandler(InitializeDebugAdapterRequest request)
		{
			if (request.SnapshotFileName != null)
			{
				if (snapshotHandler == null)
				{
					Interlocked.CompareExchange(ref snapshotHandler, new DebugAdapterLaunchSnapshotHandler(debuggerService, base.Workspace, (ResponseQueue)base.ResponseQueue, fileSystem), null);
				}
				return snapshotHandler;
			}
			if (request.Tests != null)
			{
				if (testsHandler == null)
				{
					Interlocked.CompareExchange(ref testsHandler, new DebugAdapterLaunchTestsHandler(debuggerService, base.Workspace, (ResponseQueue)base.ResponseQueue, testRunnerService, fileSystem), null);
				}
				return testsHandler;
			}
			if (browserHandler == null)
			{
				Interlocked.CompareExchange(ref browserHandler, new DebugAdapterLaunchBrowserRequestHandler(debuggerService, base.Workspace, (ResponseQueue)base.ResponseQueue, clientStartup, fileSystem), null);
			}
			return browserHandler;
		}
	}
