	internal class DebugAdapterPublishRequestHandler : DebugAdapterRequestHandlerBase<DebugAdapterPublishRequest>
	{
		public override string EndpointName => "al/publish";

		public override bool ProfilePerformance => true;

		private Func<PublishOptions, Task<PublishResult>> PublishCallback { get; set; }

		internal DebugAdapterPublishRequestHandler(IProxyBasedDebuggerService service, VsCodeWorkspace workspace, ResponseQueue responseQueue, Func<PublishOptions, Task<PublishResult>> publishCallback = null)
		{
			IProxyBasedDebuggerService service2 = service;
			base..ctor(service2, workspace, responseQueue);
			DebugAdapterPublishRequestHandler debugAdapterPublishRequestHandler = this;
			if (publishCallback == null)
			{
				publishCallback = (PublishOptions options) => new Publisher(debugAdapterPublishRequestHandler.Logger).Publish(options, service2.CancellationToken);
			}
			PublishCallback = publishCallback;
		}

		public override async Task HandleAsync(DebugAdapterPublishRequest request, int requestId, CancellationToken cancellationToken)
		{
			if (request == null)
			{
				AddErrorResponse(requestId, cancellationToken);
				return;
			}
			string packageFileName = request.PackageFileName;
			if (string.IsNullOrEmpty(request.PackageFileName))
			{
				string path = Path.Combine(LanguageServerOptions.ProjectRoot, "app.json");
				List<Diagnostic> diagnostics = new List<Diagnostic>();
				ProjectManifestProps manifestProps = ProjectManifestProps.LoadFromFile(LanguageServerOptions.ProjectRoot, diagnostics);
				string text = ProjectManifest.ReadFromFile(path, manifestProps, diagnostics)?.AppManifest?.DefaultPackageName() + ".app";
				if (!ValidateManifestDiagnostics(diagnostics))
				{
					AddErrorResponse(requestId, cancellationToken);
					return;
				}
				packageFileName = text;
			}
			string projectRootedPath = DebugHelper.GetProjectRootedPath(request.Directory);
			PublishOptions arg = new PublishOptions
			{
				Directory = projectRootedPath,
				PackageFileName = packageFileName,
				Server = request.Server,
				Port = request.Port,
				ServerInstance = request.ServerInstance,
				Tenant = request.Tenant,
				ApplicationFamily = request.ApplicationFamily,
				Authentication = request.Authentication,
				Environment = request.Environment,
				SchemaUpdateMode = request.SchemaUpdateMode,
				IsRad = false,
				SandboxName = request.SandboxName,
				DependencyPublishingOption = DependencyPublishingOption.Ignore,
				DeploymentId = request.DeploymentId,
				ForceUpgrade = request.ForceUpgrade,
				DisableInstallDebugging = request.DisableInstallDebugging,
				EnvironmentName = request.EnvironmentName,
				UsePublicURLFromServer = request.UsePublicURLFromServer,
				ValidateServerCertificate = request.ValidateServerCertificate
			};
			GetCustomTelemetryForRequest(requestId).Dimensions.Add("Authentication", request.Authentication.ToString());
			GetCustomTelemetryForRequest(requestId).Dimensions.Add("Schema Update Mode", request.SchemaUpdateMode.ToString());
			GetCustomTelemetryForRequest(requestId).Dimensions.Add("Is Rad", request.IsRad.ToString());
			GetCustomTelemetryForRequest(requestId).Dimensions.Add("Environment Type", request.EnvironmentType.ToString());
			GetCustomTelemetryForRequest(requestId).Dimensions.Add("Force Upgrade", request.ForceUpgrade.ToString());
			using PooledStopwatch publishSw = PooledStopwatch.GetInstance();
			publishSw.Start();
			PublishResult publishResult = await PublishCallback(arg);
			publishSw.Stop();
			GetCustomTelemetryForRequest(requestId).Metrics.Add("Publish time (ms)", publishSw.ElapsedMilliseconds);
			GetCustomTelemetryForRequest(requestId).Metrics.Add("App File Size (bytes)", publishResult.FileSizeBytes);
			if (!publishResult.Success)
			{
				AddErrorResponse(requestId, cancellationToken);
			}
		}

		private void AddErrorResponse(int requestId, CancellationToken cancellationToken)
		{
			base.ResponseQueue.Add(ResponseFactory.ErrorResponse(new MessageError
			{
				Message = ProtocolResources.DeploymentError
			}, "launch", requestId), cancellationToken);
		}

		private bool ValidateManifestDiagnostics(IEnumerable<Diagnostic> diagnostics)
		{
			bool flag = false;
			foreach (Diagnostic diagnostic in diagnostics)
			{
				if (diagnostic.Severity == DiagnosticSeverity.Error)
				{
					base.Logger.Error(diagnostic.GetMessage());
					flag = true;
				}
				else if (diagnostic.Severity == DiagnosticSeverity.Warning)
				{
					base.Logger.Info(diagnostic.GetMessage());
				}
			}
			return !flag;
		}
	}
	internal abstract class DebugAdapterRequestHandlerBase<T> : RequestHandlerBase<T> where T : IRequest
	{
		protected DebugConsoleLogger Logger { get; }

		protected IProxyBasedDebuggerService DebuggerService { get; }

		public override string TelemetryEventName => FormattableString.Invariant($"Debugger - {EndpointName}");

		protected DebugAdapterRequestHandlerBase(IProxyBasedDebuggerService service, VsCodeWorkspace workspace, ResponseQueue responseQueue)
			: base(workspace, (IResponseQueue)responseQueue)
		{
			DebuggerService = service;
			Logger = new DebugConsoleLogger(base.ResponseQueue);
		}

		protected async Task<bool> AbortIfSessionIdDiffersAsync(int sessionId, Response response)
		{
			if (sessionId == DebuggerService.DebuggingSessionId)
			{
				return false;
			}
			await DebuggerService.ContinueAsync(BreakpointResponse.AbortActivity);
			base.ResponseQueue.Add(response);
			base.ResponseQueue.Add(ResponseFactory.DebugAdapterTerminatedEvent());
			return true;
		}

		protected async Task CloseConnection()
		{
			if (DebuggerService == null)
			{
				return;
			}
			try
			{
				await DebuggerService.CloseConnectionAsync().ConfigureAwait(continueOnCapturedContext: false);
			}
			catch (Exception ex)
			{
				LocalMachineLogger.LogException(ex);
				Logger.Exception(ex);
			}
			finally
			{
				DebuggerService.Dispose();
			}
		}
	}
