	internal class DebugAdapterStackTraceHandler : DebugAdapterRequestHandlerBase<DebugAdapterStackTraceRequest>
	{
		public override string EndpointName => "stacktrace";

		internal DebugAdapterStackTraceHandler(IProxyBasedDebuggerService service, VsCodeWorkspace workspace, ResponseQueue responseQueue)
			: base(service, workspace, responseQueue)
		{
		}

		public override async Task HandleAsync(DebugAdapterStackTraceRequest request, int requestId, CancellationToken cancellationToken)
		{
			if (await AbortIfSessionIdDiffersAsync(request.ThreadId, ResponseFactory.DebugAdapterStackTraceResponse(requestId, SpecializedCollections.EmptyArray<Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.DebugAdapterContract.StackFrame>(), 0)).ConfigureAwait(continueOnCapturedContext: false))
			{
				return;
			}
			if (base.DebuggerService.Frames == null)
			{
				base.ResponseQueue.Add(ResponseFactory.DebugAdapterContinuedEvent(base.DebuggerService.DebuggingSessionId), cancellationToken);
				base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId), cancellationToken);
				return;
			}
			IList<Microsoft.Dynamics.Nav.DebuggerService.StackFrame> currentFrames = base.DebuggerService.Frames;
			int num = (((request.StartFrame != 0 || request.Levels != 1) && request.Levels != 0) ? Math.Min(currentFrames.Count, request.Levels) : currentFrames.Count);
			if (request.StartFrame >= num)
			{
				base.ResponseQueue.Add(ResponseFactory.DebugAdapterStackTraceResponse(requestId, SpecializedCollections.EmptyArray<Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.DebugAdapterContract.StackFrame>(), 0), cancellationToken);
				return;
			}
			IList<Task<Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.DebugAdapterContract.StackFrame>> list = new List<Task<Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.DebugAdapterContract.StackFrame>>(num);
			for (int i = request.StartFrame; i < num; i++)
			{
				list.Add(ToStackFrameAsync(currentFrames[i], i, cancellationToken));
			}
			IList<Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.DebugAdapterContract.StackFrame> list2 = (await Task.WhenAll(list).ConfigureAwait(continueOnCapturedContext: false)).ToList();
			if (list2.Count > 0 && list2.Count == currentFrames.Count)
			{
				for (int j = 0; j < list2.Count; j++)
				{
					Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.DebugAdapterContract.StackFrame stackFrame = list2[j];
					Microsoft.Dynamics.Nav.DebuggerService.StackFrame stackFrame2 = currentFrames[j];
					IList<Range> lines = base.DebuggerService.ProvideLineDecorations(stackFrame2.ObjectId);
					base.ResponseQueue.Add(ResponseFactory.DebugAdapterProvideLineDecorationsEvent(stackFrame.Source.Path, lines));
				}
			}
			base.ResponseQueue.Add(ResponseFactory.DebugAdapterStackTraceResponse(requestId, list2, list2.Count), cancellationToken);
		}

		private async Task<Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.DebugAdapterContract.StackFrame> ToStackFrameAsync(Microsoft.Dynamics.Nav.DebuggerService.StackFrame frame, int index, CancellationToken cancellationToken)
		{
			if (frame == null)
			{
				return new Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.DebugAdapterContract.StackFrame();
			}
			Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.DebugAdapterContract.StackFrame stackFrame = new Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.DebugAdapterContract.StackFrame
			{
				Id = index,
				Name = frame.MethodName
			};
			if (string.IsNullOrEmpty(frame.ObjectName))
			{
				return stackFrame;
			}
			ApplicationObjectSyntax applicationObjectSyntax = await GetDeclaringSyntaxNode(frame.ObjectId, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
			int num = 0;
			Microsoft.Dynamics.Nav.CodeAnalysis.Text.Location location = null;
			if (applicationObjectSyntax != null)
			{
				location = applicationObjectSyntax.GetApplicationObjectFirstLocationIncludingTrivia();
				SyntaxNode parent = applicationObjectSyntax.Parent;
				if (parent == null || parent.Kind != SyntaxKind.CompilationUnit)
				{
					return stackFrame;
				}
				if (((CompilationUnitSyntax)applicationObjectSyntax.Parent).Objects.Count >= 2)
				{
					int? debuggerLineOffsetForNode = applicationObjectSyntax.GetDebuggerLineOffsetForNode();
					if (debuggerLineOffsetForNode.HasValue)
					{
						num = applicationObjectSyntax.Location.GetMappedLineSpan().StartLinePosition.Line - debuggerLineOffsetForNode.Value;
					}
				}
			}
			stackFrame.Source = CreateSourceAsync(location, frame);
			stackFrame.Line = frame.StatementSpan.From.Line.ConvertClientLineToDebuggerLine() + num;
			stackFrame.EndLine = frame.StatementSpan.To.Line.ConvertClientLineToDebuggerLine() + num;
			stackFrame.Column = frame.StatementSpan.From.Column.ConvertClientColumnToDebuggerColumn();
			stackFrame.EndColumn = frame.StatementSpan.To.Column.ConvertClientColumnToDebuggerColumn();
			if (applicationObjectSyntax == null)
			{
				stackFrame.EndColumn++;
				stackFrame.PresentationHint = StackFramePresentationHint.Subtle;
			}
			return stackFrame;
		}

		private async Task<ApplicationObjectSyntax?> GetDeclaringSyntaxNode(ApplicationObjectIdWrapper applicationObjectWrapper, CancellationToken cancellationToken)
		{
			if (base.Workspace.CurrentSolution == null)
			{
				return null;
			}
			SymbolKind kind = DebugHelper.MapToSymbolKind(applicationObjectWrapper.ObjectType);
			if (kind == SymbolKind.Undefined)
			{
				return null;
			}
			foreach (ProjectId projectId in base.Workspace.CurrentSolution.ProjectIds)
			{
				Compilation compilation = await base.Workspace.CurrentSolution.GetCompilationAsync(projectId, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				if (compilation != null)
				{
					ApplicationObjectTypeSymbol applicationObjectTypeSymbol = compilation.GetDeclaredApplicationObjectSymbols().FirstOrDefault((IApplicationObjectTypeSymbol s) => s.Id == applicationObjectWrapper.ObjectNumber && s.Kind == kind) as ApplicationObjectTypeSymbol;
					if (applicationObjectTypeSymbol != null && applicationObjectTypeSymbol.DeclaringSyntaxNode != null)
					{
						return applicationObjectTypeSymbol.DeclaringSyntaxNode as ApplicationObjectSyntax;
					}
				}
			}
			return null;
		}

		private Source CreateSourceAsync(Microsoft.Dynamics.Nav.CodeAnalysis.Text.Location? location, Microsoft.Dynamics.Nav.DebuggerService.StackFrame frame)
		{
			Source source = new Source
			{
				Name = frame.ObjectName,
				PresentationHint = SourcePresentationHint.Normal
			};
			if (location == null)
			{
				Project currentProject = base.Workspace.GetCurrentProject();
				if (currentProject != null)
				{
					source.Path = FilePathHelper.GetPreviewFileUri((currentProject == null) ? string.Empty : currentProject.ProjectFolder, frame.ObjectId.ObjectNumber, frame.ObjectName ?? frame.ObjectId.ObjectNumber.ToStringInvariant(), frame.ObjectId.ObjectType);
					source.Origin = "External";
				}
			}
			else
			{
				source.Path = location.GetLineSpan().Path;
			}
			return source;
		}
	}
	internal abstract class DebugAdapterStartRequestHandler : DebugAdapterRequestHandlerBase<InitializeDebugAdapterRequest>
	{
		private const string CloudDevEndpointSuffix = "dev";

		public override bool ProfilePerformance => true;

		protected DebugAdapterStartRequestHandler(IProxyBasedDebuggerService service, VsCodeWorkspace workspace, ResponseQueue responseQueue)
			: base(service, workspace, responseQueue)
		{
		}

		protected void LogExceptionAndAddErrorResponse(Exception e, int requestId, CancellationToken cancellationToken)
		{
			base.Logger.Exception(e);
			base.ResponseQueue.Add(ResponseFactory.ErrorResponse(new MessageError
			{
				Message = e.Message
			}, "launch", requestId), cancellationToken);
		}

		protected async Task<bool> StartDebugging(ClientConnectionInfo clientConnectionInfo, ServerInfo serverInfo, DebugOptions debugOptions, AttachOptions attachOptions = null)
		{
			ConnectionOptions connectionOptions = serverInfo.ConnectionOptions;
			(string, string, string) tuple = (connectionOptions.IsOnPremise() ? FindOnPremiseConfig(connectionOptions, base.Logger) : FindCloudConfig(connectionOptions, base.Logger));
			if (string.IsNullOrEmpty(tuple.Item2))
			{
				base.Logger.Info(ProtocolResources.DebuggerOptionsAreNotValidForTheRequestedServerVersion);
				return false;
			}
			if (!serverInfo.Supports(DevApiFeature.NetCoreSignalR))
			{
				base.Logger.Info(ProtocolResources.DebuggingNotValidForTheRequestedServerVersion, serverInfo.RuntimeVersionAsString);
				LocalMachineLogger.LogNormal("Connecting to servers older then v20: " + serverInfo.RuntimeVersionAsString + " is not supported by this version of the vsix package.");
				return false;
			}
			SetDebuggerStateAndValidateVersion(debugOptions, serverInfo.DebuggerVersion, attachOptions);
			await base.DebuggerService.OpenConnectionAsync(tuple.Item2, new DebuggerConnectionParameters
			{
				AuthenticationHeader = clientConnectionInfo.AuthenticationHeader,
				Tenant = tuple.Item1,
				DeploymentId = tuple.Item3,
				SessionId = attachOptions?.SessionId,
				UserId = attachOptions?.UserId
			}, null, serverInfo).ConfigureAwait(continueOnCapturedContext: false);
			return true;
		}

		protected void SetDebuggerStateAndValidateVersion(DebugOptions debugOptions, System.Version version, AttachOptions attachOptions)
		{
			base.DebuggerService.Version = version;
			base.DebuggerService.AttachOptions = attachOptions;
			DebugOptions debugOptions2 = debugOptions ?? DebugOptions.Default;
			if (version.Major < 2 && debugOptions != null)
			{
				base.Logger.Info(ProtocolResources.DebuggerOptionsAreNotValidForTheRequestedServerVersion);
				return;
			}
			if (version.Major < 5)
			{
				if (debugOptions2.BreakOnErrorBehaviour == BreakOnErrorBehaviour.ExcludeTry)
				{
					base.Logger.Info(ProtocolResources.DebugBehaviourNotSupported, BreakOnErrorBehaviour.ExcludeTry.ToString(), "BreakOnErrorBehaviour", BreakOnErrorBehaviour.All.ToString());
				}
				debugOptions2.BreakOnError = debugOptions2.BreakOnError ?? (debugOptions2.BreakOnErrorBehaviour != BreakOnErrorBehaviour.None);
				if (debugOptions2.BreakOnRecordWriteBehaviour == BreakOnRecordWriteBehaviour.ExcludeTemporary)
				{
					base.Logger.Info(ProtocolResources.DebugBehaviourNotSupported, BreakOnRecordWriteBehaviour.ExcludeTemporary.ToString(), "BreakOnRecordWriteBehaviour", BreakOnRecordWriteBehaviour.All.ToString());
				}
				debugOptions2.BreakOnRecordWrite = debugOptions2.BreakOnRecordWrite ?? (debugOptions2.BreakOnRecordWriteBehaviour == BreakOnRecordWriteBehaviour.All || debugOptions2.BreakOnRecordWriteBehaviour == BreakOnRecordWriteBehaviour.ExcludeTemporary);
			}
			else
			{
				if (debugOptions2.BreakOnRecordWrite.HasValue && debugOptions2.BreakOnRecordWriteBehaviour != 0)
				{
					base.Logger.Info(ProtocolResources.LegacyAndNewDebugPropertiesUsed, "BreakOnRecordWrite", "BreakOnRecordWriteBehaviour");
				}
				if (debugOptions2.BreakOnRecordWriteBehaviour == BreakOnRecordWriteBehaviour.Unspecified)
				{
					debugOptions2.BreakOnRecordWriteBehaviour = ((!debugOptions2.BreakOnRecordWrite.GetValueOrDefault()) ? BreakOnRecordWriteBehaviour.None : BreakOnRecordWriteBehaviour.All);
				}
				if (debugOptions2.BreakOnError.HasValue && debugOptions2.BreakOnErrorBehaviour != 0)
				{
					base.Logger.Info(ProtocolResources.LegacyAndNewDebugPropertiesUsed, "BreakOnError", "BreakOnErrorBehaviour");
				}
				if (debugOptions2.BreakOnErrorBehaviour == BreakOnErrorBehaviour.Unspecified)
				{
					if (!debugOptions2.BreakOnError.HasValue)
					{
						debugOptions2.BreakOnErrorBehaviour = BreakOnErrorBehaviour.All;
					}
					else
					{
						debugOptions2.BreakOnErrorBehaviour = ((!debugOptions2.BreakOnError.GetValueOrDefault()) ? BreakOnErrorBehaviour.None : BreakOnErrorBehaviour.All);
					}
				}
			}
			base.DebuggerService.DebugOptions = debugOptions2;
		}

		protected void SendNoDebugResponseMessages(CancellationToken cancellationToken)
		{
			base.ResponseQueue.Add(ResponseFactory.DebugAdapterInitializedEvent(), cancellationToken);
			base.ResponseQueue.Add(ResponseFactory.DebugAdapterTerminatedEvent(), cancellationToken);
		}

		protected static (string InternalTenantId, string DevEndpoint, string DeploymentId) FindOnPremiseConfig(ConnectionOptions options, IEmitLogger logger)
		{
			Uri uri = OnPremiseHttpClientFactory.Instance.Value.CreateBaseClientUri(options, logger);
			return (InternalTenantId: options.Tenant, DevEndpoint: uri.AbsoluteUri + "dev", DeploymentId: null);
		}

		protected static (string InternalTenantId, string DevEndpoint, string DeploymentId) FindCloudConfig(ConnectionOptions options, IEmitLogger logger)
		{
			Uri uri = CloudHttpClientFactory.Instance.Value.CreateBaseClientUri(options, logger);
			return (InternalTenantId: null, DevEndpoint: uri.AbsoluteUri + "dev", DeploymentId: options.DeploymentId);
		}

		protected async Task<ClientConnectionInfo> GetClientConnectionInfo(ServerInfo serverInfo)
		{
			ConnectionOptions connectionOptions = serverInfo.ConnectionOptions;
			try
			{
				return await new AppsApiClient(connectionOptions, base.Logger).GetClientConnectionInfo();
			}
			catch (UserNotAuthorizedException)
			{
				OnPremiseHttpClientFactory.Instance.Value.ClearCredentials(connectionOptions, base.Logger);
			}
			catch (IOException ex2)
			{
				base.Logger.Exception(ex2);
			}
			catch (UnauthorizedAccessException ex3)
			{
				base.Logger.Exception(ex3);
			}
			return null;
		}

		protected void InitializeDebugProject()
		{
			base.Workspace.AddOrUpdateProjectFromPath(new Settings
			{
				WorkspacePath = LanguageServerOptions.ProjectRoot
			}, forceCheckDependencies: false, out List<Diagnostic> _, out bool _);
		}

		protected async Task HandleAttachOrLaunchAsync(InitializeDebugAdapterRequest request, int requestId, CancellationToken cancellationToken, Func<ServerInfo, ConnectionOptions, Task> attachOrLaunch)
		{
			try
			{
				InitializeDebugProject();
				PublishEnvironment value = PublishEnvironmentParser.Parse(LanguageServerOptions.EnvironmentInfo?.Env);
				ConnectionOptions connectionOptions = request.CreateConnectionOptions(value);
				await attachOrLaunch(await ServerRegistry.DevInstance.GetServerInfo(connectionOptions, base.Logger).ConfigureAwait(continueOnCapturedContext: false), connectionOptions).ConfigureAwait(continueOnCapturedContext: false);
			}
			catch (OperationCanceledException e)
			{
				LogExceptionAndAddErrorResponse(e, requestId, cancellationToken);
			}
			catch (HttpRequestException)
			{
				base.ResponseQueue.Add(ResponseFactory.DebugAdapterTerminatedEvent(), cancellationToken);
			}
			catch (HubException e2)
			{
				LogExceptionAndAddErrorResponse(e2, requestId, cancellationToken);
				base.ResponseQueue.Add(ResponseFactory.DebugAdapterTerminatedEvent(), cancellationToken);
			}
			catch (IncompatibleExtensionException e3)
			{
				LogExceptionAndAddErrorResponse(e3, requestId, cancellationToken);
			}
			catch (UserSetupException e4)
			{
				LogExceptionAndAddErrorResponse(e4, requestId, cancellationToken);
			}
			catch (Exception ex2)
			{
				ExternalTelemetryLogger.TrackException(ex2);
				base.Logger.Error(DeploymentResources.InternalError);
				base.ResponseQueue.Add(ResponseFactory.ErrorResponse(new MessageError
				{
					Message = ProtocolResources.DeploymentError
				}, "launch", requestId), cancellationToken);
				base.ResponseQueue.Add(ResponseFactory.DebugAdapterTerminatedEvent(), cancellationToken);
			}
			finally
			{
				ExternalTelemetryLogger.TelemetryService.Flush();
			}
		}

		protected void LogTelemetry(InitializeDebugAdapterRequest request, int requestId)
		{
			GetCustomTelemetryForRequest(requestId).Dimensions.Add("Authentication", request.Authentication.ToString());
			GetCustomTelemetryForRequest(requestId).Dimensions.Add("Schema Update Mode", request.SchemaUpdateMode.ToString());
			GetCustomTelemetryForRequest(requestId).Dimensions.Add("Is Rad", request.IsRad.ToString());
			GetCustomTelemetryForRequest(requestId).Dimensions.Add("Environment Type", request.EnvironmentType.ToString());
			GetCustomTelemetryForRequest(requestId).Dimensions.Add("Request", request.Request ?? "default");
			GetCustomTelemetryForRequest(requestId).Dimensions.Add("Just Debug", request.JustDebug.ToString());
			GetCustomTelemetryForRequest(requestId).Dimensions.Add("Break On Error", request.BreakOnError?.ToString() ?? "null");
			GetCustomTelemetryForRequest(requestId).Dimensions.Add("Break On Record Write", request.BreakOnRecordWrite?.ToString() ?? "null");
			GetCustomTelemetryForRequest(requestId).Dimensions.Add("Break On Error Behaviour", request.BreakOnErrorBehaviour.ToString());
			GetCustomTelemetryForRequest(requestId).Dimensions.Add("Break On Record Write Behaviour", request.BreakOnRecordWriteBehaviour.ToString());
		}
	}
