	internal class DebugAdapterVariablesRequestHandler : DebugAdapterRequestHandlerBase<DebugAdapterVariablesRequest>
	{
		internal const string GlobalsPath = "<Globals>";

		internal const string DatabaseStatisticsPath = "<Database Statistics>";

		internal static string EvaluateNameSeparator = "::";

		public override string EndpointName => "variables";

		internal DebugAdapterVariablesRequestHandler(IProxyBasedDebuggerService service, VsCodeWorkspace workspace, ResponseQueue responseQueue)
			: base(service, workspace, responseQueue)
		{
		}

		public override async Task HandleAsync(DebugAdapterVariablesRequest request, int requestId, CancellationToken cancellationToken)
		{
			IList<Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.DebugAdapterContract.Variable> variables = SpecializedCollections.EmptyList<Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.DebugAdapterContract.Variable>();
			if (request.VariablesReference >= 262144)
			{
				if (base.DebuggerService.ChildNodeHandles.TryGet(request.VariablesReference, out LocalNodeContext value))
				{
					if (value.Nodes.Count == 0)
					{
						base.ResponseQueue.Add(ResponseFactory.DebugAdapterVariablesResponse(requestId, SpecializedCollections.EmptyList<Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.DebugAdapterContract.Variable>()), cancellationToken);
						return;
					}
					variables = await ToVariablesAsync(value, request.VariablesReference).ConfigureAwait(continueOnCapturedContext: false);
				}
			}
			else
			{
				VariableReferenceGroupIndex variableGroupIndex = VariableReferenceHelper.GetGroupIndexType(request.VariablesReference);
				int stackFrameIndex = VariableReferenceHelper.GetStackFrameIndex(request.VariablesReference);
				if (variableGroupIndex != 0)
				{
					IList<LocalNode> list = await GetVariablesForFrameAsync(stackFrameIndex).ConfigureAwait(continueOnCapturedContext: false);
					if (list != null && list.Count > 0)
					{
						switch (variableGroupIndex)
						{
						case VariableReferenceGroupIndex.Globals:
							variables = await GetGlobalsAsync(stackFrameIndex, list[0]).ConfigureAwait(continueOnCapturedContext: false);
							break;
						case VariableReferenceGroupIndex.DatabaseStatistics:
							if (list.Count > 1 && list[1].Name.StartsWith("<Database Statistics>", StringComparison.OrdinalIgnoreCase))
							{
								variables = await ToVariablesAsync(new LocalNode[1] { list[1] }, string.Empty, stackFrameIndex).ConfigureAwait(continueOnCapturedContext: false);
							}
							break;
						default:
							if (list.Count > 1)
							{
								int count = ((!list[1].Name.StartsWith("<Database Statistics>", StringComparison.OrdinalIgnoreCase)) ? 1 : 2);
								IEnumerable<LocalNode> localVariables = list.Skip(count);
								IEnumerable<LocalNode> nodes = AppendExceptionMessage(stackFrameIndex, localVariables);
								variables = await ToVariablesAsync(nodes, string.Empty, stackFrameIndex).ConfigureAwait(continueOnCapturedContext: false);
							}
							break;
						}
					}
				}
			}
			base.ResponseQueue.Add(ResponseFactory.DebugAdapterVariablesResponse(requestId, variables), cancellationToken);
		}

		private IEnumerable<LocalNode> AppendExceptionMessage(int stackFrameIndex, IEnumerable<LocalNode> localVariables)
		{
			LocalNode localNode = base.DebuggerService.MapAlExceptionToVariable(stackFrameIndex);
			if (localNode == null)
			{
				return localVariables;
			}
			PooledList<LocalNode> instance = PooledList<LocalNode>.GetInstance();
			try
			{
				foreach (LocalNode localVariable in localVariables)
				{
					if (Microsoft.Dynamics.Nav.EditorServices.Protocol.DebugAdapter.DebuggerService.ExceptionNodeName.Equals(localVariable.Name, StringComparison.OrdinalIgnoreCase))
					{
						return localVariables;
					}
					instance.Add(localVariable);
				}
				instance.Add(localNode);
				return instance.ToArray();
			}
			finally
			{
				instance.Free();
			}
		}

		private async Task<IList<LocalNode>> GetVariablesForFrameAsync(int frameId)
		{
			return (await base.DebuggerService.GetVariablesAsync(frameId).ConfigureAwait(continueOnCapturedContext: false))?.ToList();
		}

		private async Task<IList<Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.DebugAdapterContract.Variable>> GetGlobalsAsync(int stackFrameIndex, LocalNode globalNode)
		{
			List<Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.DebugAdapterContract.Variable> variables = new List<Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.DebugAdapterContract.Variable>();
			if (globalNode == null)
			{
				return variables;
			}
			if (globalNode.HasChildren)
			{
				IList<LocalNode> children = globalNode.Children;
				if (children == null)
				{
					if (stackFrameIndex != Microsoft.Dynamics.Nav.EditorServices.Protocol.DebugAdapter.DebuggerService.InvalidFrameId)
					{
						LocalNode[] expandedNodes = await base.DebuggerService.ExpandGlobalsAsync(stackFrameIndex).ConfigureAwait(continueOnCapturedContext: false);
						if (expandedNodes != null && expandedNodes.Length != 0)
						{
							LocalNode localNode = expandedNodes[0];
							if (localNode.Name.StartsWith("<Globals>", StringComparison.OrdinalIgnoreCase) && localNode.HasChildren && localNode.Children != null)
							{
								List<Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.DebugAdapterContract.Variable> list = variables;
								list.AddRange(await ToVariablesAsync(localNode.Children, string.Empty, stackFrameIndex).ConfigureAwait(continueOnCapturedContext: false));
								if (expandedNodes.Length > 1)
								{
									list = variables;
									list.AddRange(await ToVariablesAsync(expandedNodes.Skip(1), string.Empty, stackFrameIndex).ConfigureAwait(continueOnCapturedContext: false));
								}
							}
							else
							{
								string parentName = localNode.Name.QuoteIdentifierIfNeeded();
								List<Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.DebugAdapterContract.Variable> list = variables;
								list.AddRange(await ToVariablesAsync(expandedNodes, parentName, stackFrameIndex).ConfigureAwait(continueOnCapturedContext: false));
							}
						}
					}
				}
				else
				{
					List<Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.DebugAdapterContract.Variable> list = variables;
					list.AddRange(await ToVariablesAsync(children, string.Empty, stackFrameIndex).ConfigureAwait(continueOnCapturedContext: false));
				}
			}
			return variables;
		}

		private async Task<IList<Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.DebugAdapterContract.Variable>> ToVariablesAsync(LocalNodeContext context, int parentVariableReference)
		{
			return await ToVariablesAsync(context.Nodes, context.ParentPath, context.StackFrameIndex, parentVariableReference).ConfigureAwait(continueOnCapturedContext: false);
		}

		private async Task<IList<Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.DebugAdapterContract.Variable>> ToVariablesAsync(IEnumerable<LocalNode> nodes, string parentName, int stackFrameIndex, int? parentVariableReference = null)
		{
			IList<LocalNode> list = nodes.ToList();
			List<Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.DebugAdapterContract.Variable> variables = new List<Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.DebugAdapterContract.Variable>(list.Count);
			foreach (LocalNode item in list)
			{
				variables.Add(await ToVariableAsync(item, parentName, stackFrameIndex, parentVariableReference).ConfigureAwait(continueOnCapturedContext: false));
			}
			return variables;
		}

		private async Task<Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.DebugAdapterContract.Variable> ToVariableAsync(LocalNode localNode, string parentPath, int stackFrameIndex, int? parentVariableReference = null)
		{
			if (localNode == null)
			{
				return new Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.DebugAdapterContract.Variable();
			}
			string text = localNode.Summary ?? string.Empty;
			if (text != null && text.StartsWith(Environment.NewLine, StringComparison.OrdinalIgnoreCase))
			{
				text = text.Substring(Environment.NewLine.Length);
			}
			string text2 = localNode.Name.QuoteIdentifierIfNeeded();
			string path = ((!string.IsNullOrEmpty(parentPath)) ? (parentPath + '.' + text2) : text2);
			Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.DebugAdapterContract.Variable variable = new Microsoft.Dynamics.Nav.EditorServices.Protocol.MessageProtocol.DebugAdapterContract.Variable
			{
				Name = (localNode.Name ?? string.Empty),
				Type = (localNode.TypeName ?? string.Empty),
				Value = (text ?? string.Empty),
				EvaluateName = path
			};
			if (localNode.HasChildren)
			{
				if (localNode.Children != null)
				{
					LocalNodeContext value = new LocalNodeContext(stackFrameIndex, path, localNode.Children);
					variable.VariablesReference = base.DebuggerService.ChildNodeHandles.Create(value);
					variable.NamedVariables = localNode.Children.Count;
				}
				else
				{
					IList<LocalNode> list = await base.DebuggerService.ExpandNodeAsync(stackFrameIndex, path).ConfigureAwait(continueOnCapturedContext: false);
					if (list != null && list.Count > 0)
					{
						LocalNodeContext value2 = new LocalNodeContext(stackFrameIndex, path, list);
						variable.VariablesReference = base.DebuggerService.ChildNodeHandles.Create(value2);
						variable.NamedVariables = list.Count;
					}
				}
			}
			if (variable.EvaluateName.StartsWith("\"<Database Statistics>\"", StringComparison.OrdinalIgnoreCase))
			{
				if (parentVariableReference.HasValue)
				{
					variable.EvaluateName += $"{EvaluateNameSeparator}{parentVariableReference.Value}";
				}
				else if (variable.VariablesReference != 0)
				{
					variable.EvaluateName += $"{EvaluateNameSeparator}{variable.VariablesReference}";
				}
			}
			return variable;
		}
	}
