	internal sealed class DebuggerService : IDisposable, IProxyBasedDebuggerService, IDebuggerService
	{
		private class BreakContext
		{
			internal IList<Microsoft.Dynamics.Nav.DebuggerService.StackFrame> Frames { get; set; }

			internal string? CurrentError { get; set; }

			internal ApplicationObjectIdWrapper CurrentAppId { get; set; }

			public BreakContext()
			{
				Frames = SpecializedCollections.EmptyList<Microsoft.Dynamics.Nav.DebuggerService.StackFrame>();
				CurrentError = string.Empty;
			}
		}

		public static int InvalidFrameId = -1;

		public static int DefaultHubConnectionTimeout = 30000;

		public static readonly string ExceptionNodeName = "_ALException";

		private bool isDisposed;

		private readonly object mutex = new object();

		private BreakContext? currentContext;

		private DebuggerState currentState;

		private readonly ConcurrentDictionary<int, SourceContent> downloadedSources = new ConcurrentDictionary<int, SourceContent>();

		private IDebuggerService? debuggerProxyService;

		private CancellationTokenSource cancellationTokenSource { get; }

		public CancellationToken CancellationToken => cancellationTokenSource.Token;

		public DebugOptions DebugOptions { get; set; }

		public AttachOptions AttachOptions { get; set; }

		public int DebuggingSessionId => debuggerProxyService?.DebuggingSessionId ?? 0;

		public ResponseQueue ResponseQueue { get; set; }

		public Handle<LocalNodeContext> ChildNodeHandles { get; }

		public System.Version? Version { get; set; }

		public IDebuggerService? Proxy => debuggerProxyService;

		public IDictionary<int, SourceContent> DownloadedSources => downloadedSources;

		public IList<Microsoft.Dynamics.Nav.DebuggerService.StackFrame> Frames
		{
			get
			{
				if (currentContext != null)
				{
					return currentContext.Frames;
				}
				return SpecializedCollections.EmptyList<Microsoft.Dynamics.Nav.DebuggerService.StackFrame>();
			}
		}

		public string CurrentError
		{
			get
			{
				string text;
				if (currentContext != null)
				{
					text = currentContext.CurrentError;
					if (text == null)
					{
						return string.Empty;
					}
				}
				else
				{
					text = string.Empty;
				}
				return text;
			}
		}

		public ApplicationObjectIdWrapper CurrentAppId => currentContext?.CurrentAppId ?? default(ApplicationObjectIdWrapper);

		public DebuggerState CurrentState => currentState;

		internal DebuggerService(ResponseQueue responseQueue)
		{
			ChildNodeHandles = new Handle<LocalNodeContext>();
			ResponseQueue = responseQueue;
			DebugOptions = Microsoft.Dynamics.Nav.EditorServices.Protocol.DebugAdapter.DebugOptions.Default;
			AttachOptions = Microsoft.Dynamics.Nav.EditorServices.Protocol.DebugAdapter.AttachOptions.Default;
			currentState = DebuggerState.Disconnected;
			cancellationTokenSource = new CancellationTokenSource();
		}

		public void Connected()
		{
			ResponseQueue.Add(ResponseFactory.DebugAdapterInitializedEvent());
		}

		public void SetExecutionState(ApplicationObjectIdWrapper objectId, Microsoft.Dynamics.Nav.DebuggerService.StackFrame[] stack, string? errorMessage, DebuggerState state)
		{
			lock (mutex)
			{
				currentContext = new BreakContext
				{
					CurrentAppId = objectId,
					Frames = stack.ToList(),
					CurrentError = errorMessage
				};
				currentState = state;
			}
			if (state == DebuggerState.Break)
			{
				DebugAdapterStoppedReason debugAdapterStoppedReason = DebugAdapterStoppedReason.Step;
				if (!string.IsNullOrEmpty(errorMessage))
				{
					debugAdapterStoppedReason = DebugAdapterStoppedReason.Exception;
				}
				ResponseQueue.Add(ResponseFactory.DebugAdapterStoppedEvent(debugAdapterStoppedReason.ToString(), DebuggingSessionId));
			}
		}

		public async Task ContinueAsync(BreakpointResponse response)
		{
			if (currentState != 0 && CanHandleRequest())
			{
				lock (mutex)
				{
					currentContext = null;
					currentState = DebuggerState.AboutToContinue;
				}
				ChildNodeHandles.Reset();
				await debuggerProxyService.ContinueAsync(response).ConfigureAwait(continueOnCapturedContext: false);
			}
		}

		public async Task OpenConnectionAsync(string url, DebuggerConnectionParameters debuggerConnectionParameters, VsCodeWorkspace? workspace = null, ServerInfo? serverInfo = null)
		{
			if (debuggerProxyService != null)
			{
				debuggerProxyService.Dispose();
			}
			if (debuggerConnectionParameters.IsSnapshot)
			{
				debuggerProxyService = new SnapshotDebuggerService(this);
			}
			else
			{
				debuggerProxyService = new HubBasedDebuggerService(this);
			}
			await debuggerProxyService.OpenConnectionAsync(url, debuggerConnectionParameters, workspace, serverInfo).ConfigureAwait(continueOnCapturedContext: false);
		}

		public bool CanHandleRequest()
		{
			IDebuggerService? debuggerService = debuggerProxyService;
			int num;
			if (debuggerService == null)
			{
				num = 0;
			}
			else
			{
				num = (debuggerService.CanHandleRequest() ? 1 : 0);
				if (num != 0)
				{
					goto IL_003f;
				}
			}
			string text = CurrentError;
			if (!string.IsNullOrEmpty(text))
			{
				text = ProtocolResources.DebuggerConnectionClosed;
			}
			LogAndTerminateAsync(text).GetAwaiter().GetResult();
			goto IL_003f;
			IL_003f:
			return (byte)num != 0;
		}

		public async Task CloseConnectionAsync()
		{
			if (debuggerProxyService == null || currentState == DebuggerState.Disconnected)
			{
				return;
			}
			cancellationTokenSource.Cancel();
			await debuggerProxyService.CloseConnectionAsync();
			lock (mutex)
			{
				currentState = DebuggerState.Disconnected;
			}
		}

		public async Task ConfigurationDoneAsync()
		{
			if (CanHandleRequest())
			{
				await debuggerProxyService.ConfigurationDoneAsync().ConfigureAwait(continueOnCapturedContext: false);
			}
		}

