		public async Task<LocalNode[]> GetVariablesAsync(int frameId)
		{
			if (!CanHandleRequest())
			{
				return SpecializedCollections.EmptyArray<LocalNode>();
			}
			return await debuggerProxyService.GetVariablesAsync(frameId).ConfigureAwait(continueOnCapturedContext: false);
		}

		public async Task<SourceContent?> GetSourceAsync(ApplicationObjectIdWrapper id, string objectName)
		{
			if (!CanHandleRequest())
			{
				return null;
			}
			if (downloadedSources.TryGetValue(id.GetHashCode(), out SourceContent value))
			{
				return value;
			}
			value = await debuggerProxyService.GetSourceAsync(id, objectName).ConfigureAwait(continueOnCapturedContext: false);
			if (value != null)
			{
				downloadedSources.TryAdd(id.GetHashCode(), value);
			}
			return value;
		}

		public async Task<SourceContent?> GetSourceAsync(Uri previewFile)
		{
			if (!CanHandleRequest())
			{
				return null;
			}
			PreviewFileUrl previewFileUrl = previewFile.ParsePreviewFileUrl();
			if (previewFileUrl == PreviewFileUrl.Empty || previewFileUrl.Id == 0)
			{
				return null;
			}
			ObjectTypeWrapper? objectTypeWrapper = DebugHelper.MapToObjectType(previewFileUrl.Kind);
			if (!objectTypeWrapper.HasValue)
			{
				return SourceContent.Default;
			}
			return await GetSourceAsync(new ApplicationObjectIdWrapper(objectTypeWrapper.Value, previewFileUrl.Id), previewFileUrl.Name).ConfigureAwait(continueOnCapturedContext: false);
		}

