				return SpecializedCollections.EmptyArray<LocalNode>();
			}
			IList<LocalNode> list = await debuggerProxyService.ExpandNodeAsync(frameId, path).ConfigureAwait(continueOnCapturedContext: false);
			if (list == null || list.Count == 0)
			{
				return SpecializedCollections.EmptyArray<LocalNode>();
			}
			return list.ToList();
		}

