		public void Log(string message, bool isError = true)
		{
			if (!string.IsNullOrEmpty(message))
			{
				DebugConsoleLogger debugConsoleLogger = new DebugConsoleLogger(ResponseQueue);
				if (isError)
				{
					LocalMachineLogger.LogError(message);
					debugConsoleLogger.Error(message);
					Response item = ResponseFactory.ErrorResponse(new MessageError
					{
						Message = message
					}, string.Empty, 0);
					ResponseQueue.Add(item);
				}
				else
				{
					debugConsoleLogger.Info(message);
				}
			}
		}

		public async Task LogAndTerminateAsync(string message, bool isError = true)
		{
			Log(message, isError);
			await SendTerminatedEventAsync().ConfigureAwait(continueOnCapturedContext: false);
		}

		public void Dispose()
		{
			if (!isDisposed)
			{
				DisposeAsync().GetAwaiter().GetResult();
				isDisposed = true;
			}
		}

		public async Task SendTerminatedEventAsync()
		{
			try
			{
				await CloseConnectionAsync().ConfigureAwait(continueOnCapturedContext: false);
			}
			finally
			{
				ResponseQueue.Add(ResponseFactory.DebugAdapterTerminatedEvent());
			}
		}

		public LocalNode? MapAlExceptionToVariable(int frameId)
		{
			if (currentContext == null || string.IsNullOrEmpty(currentContext.CurrentError) || currentContext.Frames == null || currentContext.Frames.Count < frameId)
			{
				return null;
			}
			return new LocalNode(ExceptionNodeName, typeof(string).Name, currentContext.CurrentError, hasChildren: false, LocalNodeChangeState.New, SpecializedCollections.EmptyList<LocalNode>());
		}

		private async Task DisposeAsync()
		{
			try
			{
				await CloseConnectionAsync().ConfigureAwait(continueOnCapturedContext: false);
			}
			finally
			{
				debuggerProxyService?.Dispose();
			}
		}
	}
