		public async Task OpenConnectionAsync(string url, DebuggerConnectionParameters debuggerConnectionParameters, VsCodeWorkspace? workspace = null, ServerInfo? serverInfo = null)
		{
			if (hubConnection != null)
			{
				await hubConnection.DisposeAsync();
			}
			HubConnectionOptions connectionOptions = new HubConnectionOptions
			{
				Url = url
			};
			if (!string.IsNullOrEmpty(debuggerConnectionParameters.Tenant))
			{
				connectionOptions.QueryParameters.Add("tenant", debuggerConnectionParameters.Tenant);
			}
			if (!string.IsNullOrEmpty(debuggerConnectionParameters.DeploymentId))
			{
				connectionOptions.QueryParameters.Add("deploymentId", debuggerConnectionParameters.DeploymentId);
			}
			if (debuggerConnectionParameters.SessionId.HasValue && debuggerConnectionParameters.SessionId.GetValueOrDefault() != -1)
			{
				connectionOptions.QueryParameters.Add("sessionId", debuggerConnectionParameters.SessionId.ToString());
			}
			if (!string.IsNullOrEmpty(debuggerConnectionParameters.UserId))
			{
				connectionOptions.QueryParameters.Add("userid", debuggerConnectionParameters.UserId);
			}
			if (debuggerConnectionParameters.AuthenticationHeader == null)
			{
				connectionOptions.Credentials = CredentialCache.DefaultCredentials;
			}
			else
			{
				string value = debuggerConnectionParameters.AuthenticationHeader.ToString();
				connectionOptions.QueryParameters.Add("Authentication", value);
				connectionOptions.Headers.Add("Authorization", value);
			}
			await SetupConnection(connectionOptions, "/DebuggerHub").ConfigureAwait(continueOnCapturedContext: false);
			LocalMachineLogger.LogNormal("SignalR hub connection established with debugger context [" + hubConnection.ConnectionId + "]");
			LogQueryParameters(connectionOptions.QueryParameters);
			if (parentService.AttachOptions != null)
			{
				await Attach().ConfigureAwait(continueOnCapturedContext: false);
			}
		}

