				hubConnection.On("OnFatalDebuggerException", (Action<string>)OnFatalDebuggerException);
				hubConnection.On("IsAlive", (Action)IsAlive);
				hubConnection.On("Break", (Action<ApplicationObjectIdWrapper, Microsoft.Dynamics.Nav.DebuggerService.StackFrame[], string>)Break);
				base.RegisterHubCallbacks();
			}
		}

