	internal sealed class SnapshotDebuggerService : IDebuggerService, IDisposable
	{
		private enum Direction
		{
			NextLine,
			NextFrame,
			PreviousFrame,
			NextBreakpoint
		}

		private class WatchExpressionToVariableVisitor : SyntaxVisitor
		{
			private readonly LocalNode globals;

			private readonly IList<LocalNode> locals;

			private LocalNode? currentParent;

			public LocalNode? FoundNode => currentParent;

			public WatchExpressionToVariableVisitor(IList<LocalNode> startupVariables)
			{
				globals = startupVariables[0];
				PooledList<LocalNode> instance = PooledList<LocalNode>.GetInstance();
				for (int i = 1; i < startupVariables.Count; i++)
				{
					instance.Add(startupVariables[i]);
				}
				locals = instance.ToArrayAndFree();
			}

			public override void VisitIdentifierName(IdentifierNameSyntax node)
			{
				if (node != null)
				{
					string identifierOrLiteralValue = node.GetIdentifierOrLiteralValue();
					if (!string.IsNullOrEmpty(identifierOrLiteralValue))
					{
						SetCurrentParentNode(identifierOrLiteralValue);
					}
				}
			}

			public override void VisitMemberAccessExpression(MemberAccessExpressionSyntax node)
			{
				Visit(node.Expression);
				SetCurrentParentNode(node?.Name.GetIdentifierOrLiteralValue());
			}

			private void SetCurrentParentNode(string? identifierName)
			{
				if (currentParent != null)
				{
					currentParent = FindNode(currentParent.Children, identifierName);
				}
				if (currentParent == null)
				{
					currentParent = FindNode(globals.Children, identifierName);
					if (currentParent == null)
					{
						currentParent = FindNode(locals, identifierName);
					}
				}
			}

			private static LocalNode? FindNode(IList<LocalNode> startNode, string? identifierName)
			{
				if (startNode == null)
				{
					return null;
				}
				foreach (LocalNode item in startNode)
				{
					string name = item.Name;
					if (name != null && name.Equals(identifierName, StringComparison.OrdinalIgnoreCase))
					{
						return item;
					}
					string name2 = item.Name;
					if (name2 != null && name2.Equals(FieldsNodeName, StringComparison.OrdinalIgnoreCase))
					{
						return FindNode(item.Children, identifierName);
					}
				}
				return null;
			}
		}

		internal static readonly string MethodDebugContextFileExtension = ".mdc";

		private static readonly string SnapshotFiles = "snapshotfiles";

		private static readonly char ArchivePathSeparator = '%';

		private static readonly string EmptyNodeName = "EmptyNodeMessage";

		internal static readonly int UndefinedValue = -1;

		private static readonly string FieldsNodeName = "Fields";

		private readonly IProxyBasedDebuggerService parentService;

		private IList<BreakpointInfo> breakpoints = new List<BreakpointInfo>();

		private readonly ConcurrentHashSet<BreakpointInfo> breakpointsHit = new ConcurrentHashSet<BreakpointInfo>();

		private readonly ConcurrentDictionary<SnapshotLineDefinition, IList<SnapshotLineContext>> lineDefinitions = new ConcurrentDictionary<SnapshotLineDefinition, IList<SnapshotLineContext>>();

		private readonly ConcurrentDictionary<SnapshotLineDefinition, bool> entryLineDefinitions = new ConcurrentDictionary<SnapshotLineDefinition, bool>();

		private readonly ConcurrentStack<(int Index, int StatementNumberCounter, Microsoft.Dynamics.Nav.DebuggerService.SourceSpan StatementLine)> executionIndexStack = new ConcurrentStack<(int, int, Microsoft.Dynamics.Nav.DebuggerService.SourceSpan)>();

		private readonly IList<SnapshotLineDefinition> exceptions = new List<SnapshotLineDefinition>();

		private readonly IList<MethodContext> executionContext = new List<MethodContext>();

		private readonly string alFilesFolder;

		private readonly CancellationTokenSource tokenSource = new CancellationTokenSource();

		private VsCodeWorkspace? workspace;

		private BreakpointInfo? lastBreakpoint;

		private ZipArchive? archive;

		private bool isDisposed;

		private System.Version? version;

		private string snapshotFileUrl;

		public System.Version? Version
		{
			get
			{
				return version;
			}
			set
			{
				throw new InvalidOperationException();
			}
		}

		public int DebuggingSessionId { get; private set; }

		private MethodContext? TopOfStack
		{
			get
			{
				if (executionIndexStack.Count == 0)
				{
					return null;
				}
				int currentExecutionIndex = CurrentExecutionIndex;
				if (currentExecutionIndex == UndefinedValue)
				{
					return null;
				}
				if (currentExecutionIndex < executionContext.Count)
				{
					return executionContext[currentExecutionIndex];
				}
				return null;
			}
		}

		private int CurrentExecutionIndex
		{
			get
			{
				if (executionIndexStack.TryPeek(out (int, int, Microsoft.Dynamics.Nav.DebuggerService.SourceSpan) result))
				{
					return result.Item1;
				}
				return UndefinedValue;
			}
		}

		private int CurrentStatementNumberCounter
		{
			get
			{
				if (executionIndexStack.TryPeek(out (int, int, Microsoft.Dynamics.Nav.DebuggerService.SourceSpan) result))
				{
					return result.Item2;
				}
				return UndefinedValue;
			}
		}

		private Microsoft.Dynamics.Nav.DebuggerService.SourceSpan CurrentStatementSpan
		{
			get
			{
				if (!executionIndexStack.TryPeek(out (int, int, Microsoft.Dynamics.Nav.DebuggerService.SourceSpan) result))
				{
					return Microsoft.Dynamics.Nav.DebuggerService.SourceSpan.Default;
				}
				return result.Item3;
			}
		}

		internal SnapshotDebuggerService(IProxyBasedDebuggerService parentProxy)
		{
			parentService = parentProxy;
			executionIndexStack.Push((UndefinedValue, UndefinedValue, Microsoft.Dynamics.Nav.DebuggerService.SourceSpan.Default));
			alFilesFolder = CreateTempAlFilesFolder();
			snapshotFileUrl = string.Empty;
		}

		private Microsoft.Dynamics.Nav.DebuggerService.SourceSpan? GetStatementSpan(int executionIndex, int statementNumberCounter)
		{
			if (executionIndex < 0 || executionIndex >= executionContext.Count || statementNumberCounter < 0)
			{
				return null;
			}
			MethodContext methodContext = executionContext[executionIndex];
			if (statementNumberCounter >= methodContext.LineContextsLength)
			{
				return null;
			}
			Microsoft.Dynamics.Nav.AL.Common.SnapshotDebuggerSerializer.LineContext? lineContext = methodContext.LineContexts(statementNumberCounter);
			if (!lineContext.HasValue)
			{
				return null;
			}
			return lineContext.Value.StatementSpan.FromBufferedSourceSpan();
		}

		private SnapshotLineDefinition? GetCurrentLine()
		{
			Microsoft.Dynamics.Nav.DebuggerService.SourceSpan currentStatementSpan = CurrentStatementSpan;
			MethodContext? topOfStack = TopOfStack;
			if (topOfStack.HasValue && currentStatementSpan != Microsoft.Dynamics.Nav.DebuggerService.SourceSpan.Default)
			{
				return new SnapshotLineDefinition
				{
					Id = topOfStack.Value.Id.FromBufferedApplicationObjectId().Value,
					StatementSpan = currentStatementSpan
				};
			}
			return null;
		}

		public async Task OpenConnectionAsync(string url, DebuggerConnectionParameters debuggerConnectionParameters, VsCodeWorkspace? workspace = null, ServerInfo? serverInfo = null)
		{
			if (!File.Exists(url))
			{
				await parentService.LogAndTerminateAsync(string.Format(CultureInfo.CurrentCulture, ProtocolResources.DebuggerInitializationFailedWrongsnapshotFileParameter, url)).ConfigureAwait(continueOnCapturedContext: false);
				return;
			}
			try
			{
				archive = ZipFile.OpenRead(url);
			}
			catch (Exception ex) when (LogArchiveOpenException(ex))
			{
				await parentService.LogAndTerminateAsync(ex.Message).ConfigureAwait(continueOnCapturedContext: false);
				return;
			}
			if (workspace == null)
			{
				throw new ArgumentNullException("workspace");
			}
			this.workspace = workspace;
			snapshotFileUrl = url;
			DebuggingSessionId = url.GetHashCode();
			int index = 0;
			foreach (ZipArchiveEntry item in from e in archive.Entries
				where MethodDebugContextFileExtension.Equals(Path.GetExtension(e.FullName), StringComparison.OrdinalIgnoreCase)
				select e into entry
				orderby int.Parse(Path.GetFileNameWithoutExtension(entry.Name), CultureInfo.InvariantCulture)
				select entry)
			{
				MethodContext? context = await item.ReadContentAsync<MethodContext>((ByteBuffer byteBuffer) => MethodContext.GetRootAsMethodContext(byteBuffer), tokenSource.Token).ConfigureAwait(continueOnCapturedContext: false);
				if (context.HasValue)
				{
					string methodName = context.Value.MethodName;
					ApplicationObjectIdWrapper? appId = context.Value.Id.FromBufferedApplicationObjectId();
					if (!appId.HasValue || string.IsNullOrEmpty(methodName))
					{
						continue;
					}
					executionContext.Add(context.Value);
					await CreateLineDefinitionsAsync(index, context.Value, appId.Value, methodName).ConfigureAwait(continueOnCapturedContext: false);
					await AddExceptionSnappointAsync(context.Value, appId.Value).ConfigureAwait(continueOnCapturedContext: false);
				}
				index++;
			}
			if (executionContext.Count == 0)
			{
				await parentService.LogAndTerminateAsync(string.Format(CultureInfo.CurrentCulture, ProtocolResources.SnapshotDebuggingCannotStart, url)).ConfigureAwait(continueOnCapturedContext: false);
				return;
			}
			SortBreakpoints();
			version = await archive.GetVersionFromSnapshotFile(tokenSource.Token).ConfigureAwait(continueOnCapturedContext: false);
			await UpdateSnapppointsAsync().ConfigureAwait(continueOnCapturedContext: false);
			parentService.Connected();
		}

