		private async Task<Breakpoint?> CreateBreakpoint(BreakpointInfo info)
		{
			if (info?.BreakpointDefinition == null || !info.IsSnapPoint)
			{
				return null;
			}
			Microsoft.Dynamics.Nav.DebuggerService.SourcePosition position = new Microsoft.Dynamics.Nav.DebuggerService.SourcePosition(info.BreakpointDefinition.SourceSpan.From.Line, info.BreakpointDefinition.SourceSpan.From.Column);
			var (linePosition, syntaxTree) = await GetLinePositionAsync(info.BreakpointDefinition.ObjectId, position).ConfigureAwait(continueOnCapturedContext: false);
			if (syntaxTree == null)
			{
				return null;
			}
			return new Breakpoint
			{
				Id = info.BreakpointId,
				Source = new Source
				{
					Name = Path.GetFileNameWithoutExtension(syntaxTree.FilePath),
					Path = syntaxTree.FilePath
				},
				Line = (linePosition.HasValue ? linePosition.Value.Line : position.Line),
				Column = 0,
				Verified = true
			};
		}

		public async Task<BreakpointDefinition?> AddBreakpointAsync(ApplicationObjectIdWrapper id, Microsoft.Dynamics.Nav.DebuggerService.SourcePosition position, string condition)
		{
			BreakpointInfo info = new BreakpointInfo(id, position, condition, 0, isSnapPoint: false);
			BreakpointInfo breakpointInfo = breakpoints.FirstOrDefault((BreakpointInfo bp) => bp == info);
			if (breakpointInfo?.BreakpointDefinition != null)
			{
				return breakpointInfo.BreakpointDefinition;
			}
			IList<SnapshotLineContext> lineContexts = GetSnapshotLineContexts(id, info.BreakpointDefinition.SourceSpan);
			if (lineContexts == SpecializedCollections.EmptyList<SnapshotLineContext>())
			{
				return null;
			}
			Microsoft.Dynamics.Nav.DebuggerService.SourceSpan? sourceSpan = await GetRelativeSourceSpan(id, position);
			if (!sourceSpan.HasValue)
			{
				return null;
			}
			string text = string.Empty;
			foreach (SnapshotLineContext item in lineContexts)
			{
				MethodContext methodContext = executionContext[item.ExecutionIndex];
				if (string.IsNullOrEmpty(text))
				{
					text = methodContext.MethodName;
				}
				if (item.StatementNumberCounter >= methodContext.LineContextsLength)
				{
					continue;
				}
				Microsoft.Dynamics.Nav.AL.Common.SnapshotDebuggerSerializer.LineContext? lineContext = methodContext.LineContexts(item.StatementNumberCounter);
				if (!lineContext.HasValue || lineContext.Value.VariablesLength == 0)
				{
					continue;
				}
				lock (breakpoints)
				{
					BreakpointInfo breakpointInfo2 = breakpoints.FirstOrDefault(delegate(BreakpointInfo bp)
					{
						BreakpointDefinition? breakpointDefinition = bp.BreakpointDefinition;
						return breakpointDefinition != null && breakpointDefinition.ObjectId == id && bp.BreakpointDefinition?.SourceSpan.From.Line == position.Line;
					});
					if ((object)breakpointInfo2 != null && breakpointInfo2.BreakpointDefinition != null)
					{
						breakpointInfo2.BreakpointDefinition.RelativeSourceSpan = sourceSpan.Value;
						breakpointInfo2.IsSnapPoint = true;
						return breakpointInfo2.BreakpointDefinition;
					}
				}
			}
			if (string.IsNullOrEmpty(text))
			{
				return null;
			}
			info.BreakpointDefinition.BreakpointId = info.BreakpointId;
			info.BreakpointDefinition.MethodName = text;
			info.BreakpointDefinition.InternalMethodName = text;
			info.BreakpointDefinition.RelativeSourceSpan = sourceSpan.Value;
			lock (breakpoints)
			{
				breakpoints.Add(info);
				SortBreakpoints();
			}
			return info.BreakpointDefinition;
		}

		public Task RemoveBreakpointAsync(long breakpointId)
		{
			for (int i = 0; i < breakpoints.Count; i++)
			{
				BreakpointInfo breakpointInfo = breakpoints[i];
				BreakpointDefinition? breakpointDefinition = breakpointInfo.BreakpointDefinition;
				if (breakpointDefinition == null || breakpointDefinition.BreakpointId != breakpointId || IsBreakpointAnExceptionPoint(breakpointInfo))
				{
					continue;
				}
				lock (breakpoints)
				{
					if ((object)lastBreakpoint != null && lastBreakpoint == breakpointInfo)
					{
						lastBreakpoint = ((i > 0) ? breakpoints[i - 1] : null);
					}
					breakpoints.Remove(breakpointInfo);
					SortBreakpoints();
				}
				break;
			}
			return Task.CompletedTask;
		}

		public Task UpdateBreakpointAsync(long breakpointId, string condition)
		{
			for (int i = 0; i < breakpoints.Count; i++)
			{
				BreakpointInfo breakpointInfo = breakpoints[i];
				BreakpointDefinition? breakpointDefinition = breakpointInfo.BreakpointDefinition;
				if (breakpointDefinition != null && breakpointDefinition.BreakpointId == breakpointId)
