		public async Task ContinueAsync(BreakpointResponse response)
		{
			Direction direction;
			switch (response)
			{
			default:
				return;
			case BreakpointResponse.StepIn:
				direction = Direction.NextFrame;
				break;
			case BreakpointResponse.StepOver:
				direction = Direction.NextLine;
				break;
			case BreakpointResponse.Continue:
				direction = Direction.NextBreakpoint;
				break;
			case BreakpointResponse.StepOut:
				direction = Direction.PreviousFrame;
				break;
			case BreakpointResponse.AbortActivity:
				if (!isDisposed)
				{
					tokenSource.Cancel(throwOnFirstException: false);
				}
				return;
			case BreakpointResponse.ReleaseConnection:
				return;
			}
			await BreakAsync(direction).ConfigureAwait(continueOnCapturedContext: false);
		}

		public void Dispose()
		{
			if (isDisposed)
			{
				return;
			}
			tokenSource.Cancel();
			tokenSource.Dispose();
			archive?.Dispose();
			if (alFilesFolder != null && Directory.Exists(alFilesFolder))
			{
				try
				{
					Directory.Delete(alFilesFolder, recursive: true);
				}
				catch (IOException)
				{
				}
				catch (UnauthorizedAccessException)
				{
				}
			}
			isDisposed = true;
		}

