		public Task<LocalNode?> GetWatchNodeAsync(int frameId, string expression, WatchOption watchOptions)
		{
			LocalNode result = null;
			CodeExpressionSyntax codeExpressionSyntax = SyntaxFactory.ParseExpression(expression);
			if (codeExpressionSyntax == null || codeExpressionSyntax.ContainsDiagnostics)
			{
				return Task.FromResult(result);
			}
			IList<LocalNode> nodes = GetNodes(frameId, onlyGlobal: false);
			if (nodes.Count == 0)
			{
				return Task.FromResult(result);
			}
			WatchExpressionToVariableVisitor watchExpressionToVariableVisitor = new WatchExpressionToVariableVisitor(nodes);
			watchExpressionToVariableVisitor.Visit(codeExpressionSyntax);
			result = watchExpressionToVariableVisitor.FoundNode;
			return Task.FromResult(result);
		}

