		private (Microsoft.Dynamics.Nav.AL.Common.SnapshotDebuggerSerializer.LineContext?, SnapshotLineDefinition?) GetLineContextFromException(MethodContext context, ApplicationObjectIdWrapper appId)
		{
			if (!context.Exception.HasValue)
			{
				return (null, null);
			}
			if (context.Exception.Value.LineNumber >= context.LineContextsLength)
			{
				return (null, null);
			}
			Microsoft.Dynamics.Nav.AL.Common.SnapshotDebuggerSerializer.LineContext? lineContext = context.LineContexts(context.Exception.Value.LineNumber);
			if (!lineContext.HasValue)
			{
				return (null, null);
			}
			Microsoft.Dynamics.Nav.DebuggerService.SourceSpan? sourceSpan = lineContext.Value.StatementSpan.FromBufferedSourceSpan();
