		private async Task AddExceptionSnappointAsync(MethodContext context, ApplicationObjectIdWrapper appId)
		{
			if (!context.Exception.HasValue)
			{
				return;
			}
			var (lineContext, snapshotLineDefinition) = GetLineContextFromException(context, appId);
			if (lineContext.HasValue && (object)snapshotLineDefinition != null)
			{
				exceptions.Add(snapshotLineDefinition);
				if (lineContext.HasValue)
				{
					await AddSnappointAsync(appId, context.MethodName, lineContext.Value).ConfigureAwait(continueOnCapturedContext: false);
				}
			}
		}

		private async Task CreateLineDefinitionsAsync(int index, MethodContext context, ApplicationObjectIdWrapper appId, string methodName)
		{
			bool isEntryMethod = IsEntryMethod(index);
			for (int i = 0; i < context.LineContextsLength; i++)
			{
				Microsoft.Dynamics.Nav.AL.Common.SnapshotDebuggerSerializer.LineContext? lineContext = context.LineContexts(i);
				if (!lineContext.HasValue)
				{
					continue;
				}
				Microsoft.Dynamics.Nav.DebuggerService.SourceSpan? sourceSpan = lineContext.Value.StatementSpan.FromBufferedSourceSpan();
				if (!sourceSpan.HasValue)
				{
					continue;
				}
				SnapshotLineDefinition lineDefinition = new SnapshotLineDefinition
				{
					StatementSpan = sourceSpan.Value,
					Id = appId
				};
				SnapshotLineContext snapshotLineContext = new SnapshotLineContext
				{
					ExecutionIndex = index,
					StatementNumberCounter = i
				};
				if (lineDefinitions.TryGetValue(lineDefinition, out IList<SnapshotLineContext> value))
				{
					SnapshotLineContext snapshotLineContext2 = value[value.Count - 1];
					value.Add(snapshotLineContext);
					if (snapshotLineContext2.ExecutionIndex > snapshotLineContext.ExecutionIndex)
					{
						lineDefinitions[lineDefinition] = value.OrderBy((SnapshotLineContext l) => l.ExecutionIndex).ToList();
					}
				}
				else
				{
					lineDefinitions.Add(lineDefinition, new List<SnapshotLineContext> { snapshotLineContext });
					await AddSnappointAsync(appId, methodName, lineContext.Value).ConfigureAwait(continueOnCapturedContext: false);
				}
				if (isEntryMethod && !entryLineDefinitions.ContainsKey(lineDefinition))
				{
					bool value2 = await IsLineInLoopContextAsync(lineDefinition).ConfigureAwait(continueOnCapturedContext: false);
					entryLineDefinitions.Add(lineDefinition, value2);
				}
			}
		}

		private void SortBreakpoints()
		{
			if (breakpoints.Count != 0)
			{
				breakpoints = breakpoints.OrderBy(Compare).ToList();
			}
			int Compare(BreakpointInfo lhs, BreakpointInfo rhs)
			{
				if ((object)lhs == rhs)
				{
					return 0;
				}
				if ((object)rhs == null || rhs.BreakpointDefinition == null)
				{
					return 1;
				}
				if ((object)lhs == null || lhs.BreakpointDefinition == null)
				{
					return -1;
				}
				int line = lhs.BreakpointDefinition.SourceSpan.From.Line;
				int line2 = rhs.BreakpointDefinition.SourceSpan.From.Line;
				if (lhs.BreakpointDefinition.ObjectId == rhs.BreakpointDefinition.ObjectId)
				{
					string? methodName = lhs.BreakpointDefinition.MethodName;
					if (methodName != null && methodName.Equals(rhs.BreakpointDefinition.MethodName, StringComparison.OrdinalIgnoreCase))
					{
						return line - line2;
					}
				}
				IList<SnapshotLineContext> snapshotLineContextsForBreakpoint = GetSnapshotLineContextsForBreakpoint(lhs);
				IList<SnapshotLineContext> snapshotLineContextsForBreakpoint2 = GetSnapshotLineContextsForBreakpoint(rhs);
				bool flag = snapshotLineContextsForBreakpoint == SpecializedCollections.EmptyList<int>();
				bool flag2 = snapshotLineContextsForBreakpoint2 == SpecializedCollections.EmptyList<int>();
				if (flag && flag2)
				{
					return 0;
				}
				if (flag)
				{
					return 1;
				}
				if (flag2)
				{
					return -1;
				}
				SnapshotLineContext snapshotLineContext = snapshotLineContextsForBreakpoint[0];
				SnapshotLineContext snapshotLineContext2 = snapshotLineContextsForBreakpoint2[0];
				if (snapshotLineContext.ExecutionIndex == snapshotLineContext2.ExecutionIndex)
				{
					LocalMachineLogger.LogError(string.Format(CultureInfo.InvariantCulture, "Breakpoint {0} and breakpoint {1} are both on execution context {2} for the snapshot file {3}", lhs, rhs, snapshotLineContext2.ExecutionIndex, snapshotFileUrl));
					return line - line2;
				}
				return CompareCallStackValues(line, snapshotLineContext, line2, snapshotLineContext2);
			}
			int CompareCallStackValues(int leftLineNumber, SnapshotLineContext leftLineContext, int rightLineNumber, SnapshotLineContext rightLineContext)
			{
				PooledHashSet<SnapshotLineDefinition> instance = PooledHashSet<SnapshotLineDefinition>.GetInstance();
				PooledHashSet<SnapshotLineDefinition> instance2 = PooledHashSet<SnapshotLineDefinition>.GetInstance();
				try
				{
					IList<(int, int)> list = GetReveresedCallStack(leftLineContext.ExecutionIndex, instance).Reverse().ToList();
					list.Add((leftLineContext.ExecutionIndex, leftLineContext.StatementNumberCounter));
					IList<(int, int)> list2 = GetReveresedCallStack(rightLineContext.ExecutionIndex, instance2).Reverse().ToList();
					list2.Add((rightLineContext.ExecutionIndex, rightLineContext.StatementNumberCounter));
					if (list.Count == 0 || list2.Count == 0)
					{
						return leftLineContext.ExecutionIndex - rightLineContext.ExecutionIndex;
					}
					int num = 0;
					int num2 = 0;
					int num3 = UndefinedValue;
					int num4 = UndefinedValue;
					while (list[num].Item1 == list2[num2].Item1)
					{
						num3 = num;
						num4 = num2;
						num++;
						num2++;
						if (num >= list.Count || num2 >= list2.Count)
						{
							break;
						}
					}
					if (num3 == UndefinedValue || num4 == UndefinedValue)
					{
						return leftLineContext.ExecutionIndex - rightLineContext.ExecutionIndex;
					}
					(int, int) tuple = list[num3];
					Microsoft.Dynamics.Nav.DebuggerService.SourceSpan? statementSpan = GetStatementSpan(tuple.Item1, tuple.Item2);
					(int, int) tuple2 = list2[num4];
					Microsoft.Dynamics.Nav.DebuggerService.SourceSpan? statementSpan2 = GetStatementSpan(tuple2.Item1, tuple2.Item2);
					if (!statementSpan.HasValue || !statementSpan2.HasValue)
					{
						return leftLineContext.ExecutionIndex - rightLineContext.ExecutionIndex;
					}
					if (statementSpan.Value.From.Line == statementSpan2.Value.From.Line)
					{
						if (statementSpan.Value.From.Line == rightLineNumber)
						{
							return 1;
						}
						if (statementSpan.Value.From.Line == leftLineNumber)
						{
							return -1;
						}
						return 0;
					}
					return statementSpan.Value.From.Line - statementSpan2.Value.From.Line;
				}
				finally
				{
					instance.Free();
					instance2.Free();
				}
			}
		}

		private async Task AddSnappointAsync(ApplicationObjectIdWrapper id, string methodName, Microsoft.Dynamics.Nav.AL.Common.SnapshotDebuggerSerializer.LineContext lineContext)
		{
			if (lineContext.VariablesLength == 0)
			{
				return;
			}
			Microsoft.Dynamics.Nav.DebuggerService.SourceSpan? sourceSpan = lineContext.StatementSpan.FromBufferedSourceSpan();
			if (!sourceSpan.HasValue)
			{
				return;
			}
			BreakpointInfo info = new BreakpointInfo(id, sourceSpan.Value, string.Empty, 0, isSnapPoint: true);
			info.BreakpointDefinition.BreakpointId = info.BreakpointId;
			info.BreakpointDefinition.MethodName = methodName;
			info.BreakpointDefinition.InternalMethodName = methodName;
			lock (breakpoints)
			{
				BreakpointInfo breakpointInfo = breakpoints.FirstOrDefault((BreakpointInfo bp) => bp == info);
				if (breakpointInfo == null)
				{
					breakpoints.Add(info);
				}
				else
				{
					breakpointInfo.IsSnapPoint = true;
				}
			}
			await GetSourceAsync(id, methodName);
		}

		private Microsoft.Dynamics.Nav.DebuggerService.StackFrame[] GetCurrentFrame()
		{
			MethodContext? topOfStack = TopOfStack;
			if (!topOfStack.HasValue || topOfStack.Value.FramesLength == 0)
			{
				return SpecializedCollections.EmptyArray<Microsoft.Dynamics.Nav.DebuggerService.StackFrame>();
			}
			MethodContext value = topOfStack.Value;
			ArrayBuilder<Microsoft.Dynamics.Nav.DebuggerService.StackFrame> instance = ArrayBuilder<Microsoft.Dynamics.Nav.DebuggerService.StackFrame>.GetInstance();
			try
			{
				for (int i = 0; i < topOfStack.Value.FramesLength; i++)
				{
					Microsoft.Dynamics.Nav.DebuggerService.StackFrame stackFrame = FromBufferedFrame(value.Frames(i));
					if (stackFrame == null)
					{
						continue;
					}
					if (i == 0)
					{
						int currentStatementNumberCounter = CurrentStatementNumberCounter;
						if (currentStatementNumberCounter >= 1 && currentStatementNumberCounter < value.LineContextsLength)
						{
							stackFrame = AdjustLineNumbersBasedOnFrame(stackFrame);
						}
					}
					instance.Add(stackFrame);
				}
				return instance.ToArray();
			}
			finally
			{
				instance.Free();
			}
		}

		private IList<SnapshotLineContext> GetSnapshotLineContexts(ApplicationObjectIdWrapper id, Microsoft.Dynamics.Nav.DebuggerService.SourceSpan span)
		{
			SnapshotLineDefinition key = new SnapshotLineDefinition
			{
				Id = id,
				StatementSpan = span
			};
			if (!lineDefinitions.TryGetValue(key, out IList<SnapshotLineContext> value))
			{
				return SpecializedCollections.EmptyList<SnapshotLineContext>();
			}
			return value;
		}

		private Microsoft.Dynamics.Nav.DebuggerService.StackFrame AdjustLineNumbersBasedOnFrame(Microsoft.Dynamics.Nav.DebuggerService.StackFrame frame)
		{
			MethodContext value = TopOfStack.Value;
			Microsoft.Dynamics.Nav.DebuggerService.SourceSpan currentStatementSpan = CurrentStatementSpan;
			int currentStatementNumberCounter = CurrentStatementNumberCounter;
			if (value.LineContextsLength <= currentStatementNumberCounter)
			{
				return frame;
			}
			int line = currentStatementSpan.From.Line;
			int num = currentStatementSpan.To.Line;
			if (line > num)
			{
				num = line;
			}
			int column = currentStatementSpan.From.Column;
			int column2 = currentStatementSpan.To.Column;
			Microsoft.Dynamics.Nav.DebuggerService.SourcePosition from = new Microsoft.Dynamics.Nav.DebuggerService.SourcePosition((ushort)line, (ushort)column);
			Microsoft.Dynamics.Nav.DebuggerService.SourcePosition to = new Microsoft.Dynamics.Nav.DebuggerService.SourcePosition((ushort)num, (ushort)column2);
			return new Microsoft.Dynamics.Nav.DebuggerService.StackFrame(statementSpan: new Microsoft.Dynamics.Nav.DebuggerService.SourceSpan(from, to), objectId: frame.ObjectId, objectName: frame.ObjectName, methodName: frame.MethodName);
		}

		private IList<LocalNode> GetNodes(int frameId, bool onlyGlobal)
		{
			if (!TopOfStack.HasValue)
			{
				return SpecializedCollections.EmptyList<LocalNode>();
			}
			MethodContext value = TopOfStack.Value;
			if (value.FramesLength == 0 || frameId >= value.FramesLength)
			{
				return SpecializedCollections.EmptyList<LocalNode>();
			}
			Microsoft.Dynamics.Nav.AL.Common.SnapshotDebuggerSerializer.LineContext? lineContext = null;
			if (frameId > 0)
			{
				if (!value.Frames(frameId).HasValue)
				{
					return SpecializedCollections.EmptyList<LocalNode>();
				}
				PooledList<(int, int, Microsoft.Dynamics.Nav.DebuggerService.SourceSpan)> instance = PooledList<(int, int, Microsoft.Dynamics.Nav.DebuggerService.SourceSpan)>.GetInstance();
				try
				{
					instance.AddRange(executionIndexStack);
					(int, int, Microsoft.Dynamics.Nav.DebuggerService.SourceSpan) tuple = (UndefinedValue, UndefinedValue, Microsoft.Dynamics.Nav.DebuggerService.SourceSpan.Default);
					for (int num = instance.Count - 1; num >= 0; num--)
					{
						(int, int, Microsoft.Dynamics.Nav.DebuggerService.SourceSpan) tuple2 = instance[num];
						if (num == frameId)
						{
							tuple = tuple2;
							break;
						}
					}
					if (tuple.Item1 < executionContext.Count && tuple.Item1 >= 0)
					{
						MethodContext methodContext = executionContext[tuple.Item1];
						if (tuple.Item2 < methodContext.LineContextsLength)
						{
							lineContext = methodContext.LineContexts(tuple.Item2);
						}
					}
				}
				finally
				{
					instance.Free();
				}
			}
			else
			{
				lineContext = value.LineContexts(CurrentStatementNumberCounter);
			}
			if (!lineContext.HasValue)
			{
				return SpecializedCollections.EmptyList<LocalNode>();
			}
			return GetLocalNodes(lineContext, onlyGlobal);
		}

		private IList<LocalNode> GetLocalNodes(Microsoft.Dynamics.Nav.AL.Common.SnapshotDebuggerSerializer.LineContext? lineContext, bool onlyGlobal)
		{
			if (!lineContext.HasValue || !TopOfStack.HasValue)
			{
				return SpecializedCollections.EmptyList<LocalNode>();
			}
			if (lineContext.Value.VariablesLength == 0)
			{
				return ReturnEmptyListOrEmptyNode(lineContext.Value, onlyGlobal);
			}
			PooledList<LocalNode> pooledList = null;
			try
			{
				Microsoft.Dynamics.Nav.AL.Common.SnapshotDebuggerSerializer.Variable? variable = lineContext.Value.Variables(0);
				if (onlyGlobal)
				{
					if (!variable.HasValue || !"<Globals>".Equals(variable.Value.Name, StringComparison.OrdinalIgnoreCase))
					{
						return SpecializedCollections.EmptyList<LocalNode>();
					}
					LocalNode localNode = ExpandVariable(variable.Value);
					if (localNode == null)
					{
						return SpecializedCollections.EmptyList<LocalNode>();
					}
					return new List<LocalNode> { localNode };
				}
				pooledList = PooledList<LocalNode>.GetInstance();
				for (int i = 0; i < lineContext.Value.VariablesLength; i++)
				{
					Microsoft.Dynamics.Nav.AL.Common.SnapshotDebuggerSerializer.Variable? variable2 = lineContext.Value.Variables(i);
					if (variable2.HasValue)
					{
						LocalNode localNode2 = ExpandVariable(variable2.Value);
						if (localNode2 != null)
						{
							pooledList.Add(localNode2);
						}
					}
				}
				MethodContext? topOfStack = TopOfStack;
				if (topOfStack.HasValue && topOfStack.GetValueOrDefault().Exception.HasValue)
				{
					SnapshotLineDefinition item = new SnapshotLineDefinition
					{
						Id = TopOfStack.Value.Id.FromBufferedApplicationObjectId().Value,
						StatementSpan = lineContext.Value.StatementSpan.FromBufferedSourceSpan().Value
					};
					if (exceptions.Contains(item))
					{
						pooledList.Add(new LocalNode(DebuggerService.ExceptionNodeName, typeof(string).Name, TopOfStack.Value.Exception.Value.Message, hasChildren: false, LocalNodeChangeState.New, SpecializedCollections.EmptyList<LocalNode>()));
					}
				}
				return pooledList.ToList();
			}
			finally
			{
				pooledList?.Free();
			}
		}

		private IList<LocalNode> ReturnEmptyListOrEmptyNode(Microsoft.Dynamics.Nav.AL.Common.SnapshotDebuggerSerializer.LineContext lineContext, bool onlyGlobal)
		{
			SnapshotLineDefinition snapshotLineDefinition = new SnapshotLineDefinition
			{
				Id = TopOfStack.Value.Id.FromBufferedApplicationObjectId().Value,
				StatementSpan = lineContext.StatementSpan.FromBufferedSourceSpan().Value
			};
			LocalNode localNode = TryCreateEmptyLocalNode(snapshotLineDefinition);
			if (localNode == null)
			{
				return SpecializedCollections.EmptyList<LocalNode>();
			}
			List<LocalNode> children = new List<LocalNode> { localNode };
			LocalNode item = new LocalNode("<Globals>", typeof(string).Name, string.Empty, hasChildren: true, LocalNodeChangeState.New, children);
			List<LocalNode> list = new List<LocalNode> { item };
			if (onlyGlobal)
			{
				return list;
			}
			list.Add(localNode);
			return list;
		}

		private LocalNode? TryCreateEmptyLocalNode(SnapshotLineDefinition snapshotLineDefinition)
		{
			BreakpointInfo? breakpoint = GetBreakpoint(snapshotLineDefinition);
			if ((object)breakpoint != null && breakpoint.IsSnapPoint)
			{
				return null;
			}
			return new LocalNode(EmptyNodeName, typeof(string).Name, ProtocolResources.EmptyVariableMessage, hasChildren: false, LocalNodeChangeState.New, SpecializedCollections.EmptyList<LocalNode>());
		}

		private static LocalNode? ExpandVariable(Microsoft.Dynamics.Nav.AL.Common.SnapshotDebuggerSerializer.Variable variable)
		{
			if (variable.HasChildren)
			{
				PooledList<LocalNode> instance = PooledList<LocalNode>.GetInstance();
				try
				{
					for (int i = 0; i < variable.ChildrenLength; i++)
					{
						Microsoft.Dynamics.Nav.AL.Common.SnapshotDebuggerSerializer.Variable? variable2 = variable.Children(i);
						if (variable2.HasValue)
						{
							LocalNode localNode = ExpandVariable(variable2.Value);
							if (localNode != null)
							{
								instance.Add(new LocalNode(variable2.Value.Name, variable2.Value.Type, variable2.Value.Value, variable2.Value.HasChildren, LocalNodeChangeState.New, localNode.Children));
							}
						}
					}
					return new LocalNode(variable.Name, variable.Type, variable.Value, variable.HasChildren, LocalNodeChangeState.New, instance.ToList());
				}
				finally
				{
					instance.Free();
				}
			}
			return new LocalNode(variable.Name, variable.Type, variable.Value, variable.HasChildren, LocalNodeChangeState.New, SpecializedCollections.EmptyList<LocalNode>());
		}

		private async Task<(SourceContent?, string? Path)> GetSourceContentAsync(ApplicationObjectIdWrapper id)
		{
			string entryName = CreateArchiveFileName(id);
			ZipArchiveEntry entry = archive.GetEntry(entryName);
			if (entry == null)
			{
				return (null, Path: null);
			}
			var (text, item) = await entry.ExtractToTextContentAsync(alFilesFolder).ConfigureAwait(continueOnCapturedContext: false);
			if (text == null)
			{
				return (null, Path: null);
			}
			return (new SourceContent
			{
				IsALContent = true,
				Content = text
			}, Path: item);
		}

		private async Task BreakAsync(Direction direction)
		{
			await SetExecutionContextAsync(direction).ConfigureAwait(continueOnCapturedContext: false);
			if (CurrentExecutionIndex == UndefinedValue)
			{
				executionIndexStack.Clear();
				Microsoft.Dynamics.Nav.DebuggerService.SourceSpan? statementSpan = GetStatementSpan(executionContext.Count - 1, 0);
				if (!statementSpan.HasValue)
				{
					await parentService.LogAndTerminateAsync(ProtocolResources.SnapshotDebuggerNoMoreFrames, isError: false).ConfigureAwait(continueOnCapturedContext: false);
					return;
				}
				executionIndexStack.PushRange(new(int, int, Microsoft.Dynamics.Nav.DebuggerService.SourceSpan)[2]
				{
					(executionContext.Count - 1, UndefinedValue, Microsoft.Dynamics.Nav.DebuggerService.SourceSpan.Default),
					(executionContext.Count - 1, 0, statementSpan.Value)
				});
			}
			await BreakAsync().ConfigureAwait(continueOnCapturedContext: false);
		}

		private async Task SetExecutionContextAsync(Direction direction)
		{
			if (CurrentExecutionIndex >= executionContext.Count || await SetExecutionContextOnNextBreakpointAsync(direction).ConfigureAwait(continueOnCapturedContext: false))
			{
				return;
			}
			if (direction != Direction.NextBreakpoint)
			{
				if (!(await TrySetExecutionContextOnNextAvailableLineAsync(direction).ConfigureAwait(continueOnCapturedContext: false)))
				{
					await parentService.LogAndTerminateAsync(ProtocolResources.SnapshotDebuggingNavigationFailed).ConfigureAwait(continueOnCapturedContext: false);
				}
			}
			else
			{
				await parentService.LogAndTerminateAsync(ProtocolResources.SnapshotDebuggerNoMoreFrames, isError: false).ConfigureAwait(continueOnCapturedContext: false);
			}
		}

		private static SnapshotLineDefinition? GetCallerLine(MethodContext context)
		{
			Microsoft.Dynamics.Nav.AL.Common.SnapshotDebuggerSerializer.StackFrame? callerFrame = context.GetCallerFrame();
			if (callerFrame.HasValue)
			{
				return callerFrame.Value.CreateLineDefinitionFromFrame();
			}
			return null;
		}

		private int GetNextFrameIndex(int startIndex, int currentStatementNumberCounter)
		{
			Microsoft.Dynamics.Nav.DebuggerService.SourceSpan? statementSpan = GetStatementSpan(startIndex, currentStatementNumberCounter);
			if (!statementSpan.HasValue)
			{
				return UndefinedValue;
			}
			MethodContext methodContext = executionContext[startIndex];
			ApplicationObjectIdWrapper? applicationObjectIdWrapper = methodContext.Id.FromBufferedApplicationObjectId();
			if (!applicationObjectIdWrapper.HasValue)
			{
				return UndefinedValue;
			}
			if (startIndex + 1 >= executionContext.Count)
			{
				return startIndex + 1;
			}
			for (int i = startIndex + 1; i < executionContext.Count; i++)
			{
				MethodContext context = executionContext[i];
				Microsoft.Dynamics.Nav.AL.Common.SnapshotDebuggerSerializer.StackFrame? callerFrame = context.GetCallerFrame();
				if (!callerFrame.HasValue)
				{
					continue;
				}
				ApplicationObjectIdWrapper? applicationObjectIdWrapper2 = callerFrame.Value.Id.FromBufferedApplicationObjectId();
				if (!applicationObjectIdWrapper2.HasValue)
				{
					continue;
				}
				ApplicationObjectIdWrapper value = applicationObjectIdWrapper2.Value;
				ApplicationObjectIdWrapper? applicationObjectIdWrapper3 = applicationObjectIdWrapper;
				if (applicationObjectIdWrapper3.HasValue && value == applicationObjectIdWrapper3.GetValueOrDefault() && SemanticFacts.NameEqualityComparer.Equals(callerFrame.Value.MethodName, methodContext.MethodName) && callerFrame.Value.StatementSpan.FromBufferedSourceSpan() == statementSpan)
				{
					if (context.LineContextsLength == 0)
					{
						return UndefinedValue;
					}
					return i;
				}
			}
			return UndefinedValue;
		}

		private async Task StartOverAsync()
		{
			parentService.Log(ProtocolResources.SnapshotDebuggerNoMoreFramesStartingOver, isError: false);
			Interlocked.Exchange(ref lastBreakpoint, null);
			executionIndexStack.Clear();
			executionIndexStack.Push((UndefinedValue, UndefinedValue, Microsoft.Dynamics.Nav.DebuggerService.SourceSpan.Default));
			await PushValueOnExecutionIndexStackAsync(0, 0).ConfigureAwait(continueOnCapturedContext: false);
		}

		private async Task TerminateWithCorruptLineMessage(int index)
		{
			MethodContext methodContext = executionContext[index];
			ApplicationObjectIdWrapper? applicationObjectIdWrapper = methodContext.Id.FromBufferedApplicationObjectId();
			string message = (applicationObjectIdWrapper.HasValue ? string.Format(CultureInfo.CurrentCulture, ProtocolResources.SnapshotDebuggerCorruptLine, 0, methodContext.MethodName, applicationObjectIdWrapper.Value.ObjectType, applicationObjectIdWrapper.Value.ObjectNumber) : string.Format(CultureInfo.CurrentCulture, ProtocolResources.SnapshotDebuggerCorruptLine, 0, methodContext.MethodName, ProtocolResources.UndefinedApplicationObjectType, ProtocolResources.UndefinedApplicationObjectValue));
			await parentService.LogAndTerminateAsync(message).ConfigureAwait(continueOnCapturedContext: false);
		}

		private async Task SetExecutionContextOnLastMethodAsync()
		{
			Microsoft.Dynamics.Nav.DebuggerService.SourceSpan? statementSpan = GetStatementSpan(executionContext.Count - 1, 0);
			if (!statementSpan.HasValue)
			{
				await parentService.LogAndTerminateAsync(ProtocolResources.SnapshotDebuggerNoMoreFrames, isError: false).ConfigureAwait(continueOnCapturedContext: false);
			}
			else
			{
				executionIndexStack.Push((executionContext.Count - 1, 0, statementSpan.Value));
			}
		}

		private async Task<bool> TrySetExecutionContextOnNextAvailableLineAsync(Direction direction)
		{
			int currentExecutionIndex = CurrentExecutionIndex;
			if (currentExecutionIndex < 0)
			{
				await StartOverAsync().ConfigureAwait(continueOnCapturedContext: false);
				return true;
			}
			if (currentExecutionIndex >= executionContext.Count)
			{
				await SetExecutionContextOnLastMethodAsync().ConfigureAwait(continueOnCapturedContext: false);
				await parentService.LogAndTerminateAsync(ProtocolResources.SnapshotDebuggerNoMoreFrames, isError: false).ConfigureAwait(continueOnCapturedContext: false);
				return true;
			}
			return direction switch
			{
				Direction.NextFrame => await SetExecutionContextOnNexFrameAsync().ConfigureAwait(continueOnCapturedContext: false), 
				Direction.NextLine => await SetExecutionContextOnNextLineAsync().ConfigureAwait(continueOnCapturedContext: false), 
				Direction.PreviousFrame => await SetExecutionContextOnPreviousFrameAsync().ConfigureAwait(continueOnCapturedContext: false), 
				_ => false, 
			};
		}

		private async Task<bool> SetExecutionContextOnPreviousFrameAsync()
		{
			if (executionIndexStack.TryPop(out (int, int, Microsoft.Dynamics.Nav.DebuggerService.SourceSpan) result))
			{
				if (executionIndexStack.Count == 1 && executionIndexStack.TryPeek(out (int, int, Microsoft.Dynamics.Nav.DebuggerService.SourceSpan) result2) && result2.Item1 == UndefinedValue && result.Item1 == 0)
				{
					await parentService.LogAndTerminateAsync(ProtocolResources.SnapshotDebuggerNoMoreFrames, isError: false).ConfigureAwait(continueOnCapturedContext: false);
					return true;
				}
				return await TrySetExecutionContextOnNextAvailableLineAsync(Direction.NextLine).ConfigureAwait(continueOnCapturedContext: false);
			}
			await parentService.LogAndTerminateAsync(ProtocolResources.SnapshotDebuggerNoMoreFrames, isError: false).ConfigureAwait(continueOnCapturedContext: false);
			return true;
		}

		private async Task<bool> SetExecutionContextOnNextLineAsync()
		{
			int currentExecutionIndex = CurrentExecutionIndex;
			int currentStatementNumberCounter = CurrentStatementNumberCounter;
			MethodContext methodContext = executionContext[currentExecutionIndex];
			if (methodContext.LineContextsLength == 0)
			{
				await parentService.LogAndTerminateAsync(ProtocolResources.SnapshotDebuggerNoMoreFrames, isError: false).ConfigureAwait(continueOnCapturedContext: false);
				return false;
			}
			int num = currentStatementNumberCounter;
			if (++num < methodContext.LineContextsLength)
			{
				if (!methodContext.LineContexts(num).HasValue)
				{
					return false;
				}
				if (!executionIndexStack.TryPop(out (int, int, Microsoft.Dynamics.Nav.DebuggerService.SourceSpan) result))
				{
					return false;
				}
				await SetCurrentExecutionContextAsync(result.Item1, num).ConfigureAwait(continueOnCapturedContext: false);
				return true;
			}
			return await TrySetExecutionContextOnNextAvailableLineAsync(Direction.PreviousFrame).ConfigureAwait(continueOnCapturedContext: false);
		}

		private async Task<bool> SetExecutionContextOnNexFrameAsync()
		{
			int currentExecutionIndex = CurrentExecutionIndex;
			int currentStatementNumberCounter = CurrentStatementNumberCounter;
			int nextFrameIndex = GetNextFrameIndex(currentExecutionIndex, currentStatementNumberCounter);
			if (nextFrameIndex != UndefinedValue)
			{
				await SetCurrentExecutionContextAsync(nextFrameIndex, 0).ConfigureAwait(continueOnCapturedContext: false);
			}
			currentExecutionIndex = CurrentExecutionIndex;
			if (currentExecutionIndex < 0)
			{
				await StartOverAsync().ConfigureAwait(continueOnCapturedContext: false);
				return true;
			}
			if (currentExecutionIndex >= executionContext.Count)
			{
				await SetExecutionContextOnLastMethodAsync().ConfigureAwait(continueOnCapturedContext: false);
				await parentService.LogAndTerminateAsync(ProtocolResources.SnapshotDebuggerNoMoreFrames, isError: false).ConfigureAwait(continueOnCapturedContext: false);
				return true;
			}
			MethodContext methodContext = executionContext[currentExecutionIndex];
			if (!methodContext.Id.FromBufferedApplicationObjectId().HasValue)
			{
				return false;
			}
			currentStatementNumberCounter = CurrentStatementNumberCounter;
			if (currentStatementNumberCounter >= methodContext.LineContextsLength)
			{
				return await TrySetExecutionContextOnNextAvailableLineAsync(Direction.PreviousFrame).ConfigureAwait(continueOnCapturedContext: false);
			}
			return true;
		}

		private async Task<bool> SetExecutionContextOnNextBreakpointAsync(Direction direction)
		{
			if (breakpoints.Count == 0)
			{
				return false;
			}
			int currentExecutionIndex = CurrentExecutionIndex;
			if (currentExecutionIndex == UndefinedValue)
			{
				return await HandleEntryBreakpointAsync().ConfigureAwait(continueOnCapturedContext: false);
			}
			switch (direction)
			{
			case Direction.NextBreakpoint:
				await HandleNextBreakpointAsync().ConfigureAwait(continueOnCapturedContext: false);
				return true;
			case Direction.PreviousFrame:
				return false;
			default:
			{
				int currentStatementNumberCounter = CurrentStatementNumberCounter;
				int num = currentExecutionIndex;
				int statementNumberCounter = currentStatementNumberCounter;
				if (direction == Direction.NextFrame)
				{
					num = GetNextFrameIndex(currentExecutionIndex, currentStatementNumberCounter);
					if (num == UndefinedValue)
					{
						return true;
					}
					statementNumberCounter = 0;
				}
				if (num == UndefinedValue || num >= executionContext.Count)
				{
					await parentService.LogAndTerminateAsync(ProtocolResources.SnapshotDebuggerNoMoreFrames, isError: false).ConfigureAwait(continueOnCapturedContext: false);
					return true;
				}
				ApplicationObjectIdWrapper? applicationObjectIdWrapper = executionContext[num].Id.FromBufferedApplicationObjectId();
				if (!applicationObjectIdWrapper.HasValue)
				{
					return false;
				}
				SnapshotLineDefinition snapshotLineDefinition = GetSnapshotLineDefinition(num, applicationObjectIdWrapper.Value, statementNumberCounter);
				if ((object)snapshotLineDefinition == null)
				{
					return false;
				}
				return await SetExecutionContextIfWithinReachAsync(num, snapshotLineDefinition, rebuildExecutionIndexStack: false).ConfigureAwait(continueOnCapturedContext: false);
			}
			}
		}

		private async Task<bool> SetExecutionContextIfWithinReachAsync(int startIndex, SnapshotLineDefinition lineDefinition, bool rebuildExecutionIndexStack)
		{
			foreach (BreakpointInfo breakpoint in breakpoints)
			{
				if (await SetExecutionContextIfWithinReachAync(startIndex, lineDefinition, breakpoint, rebuildExecutionIndexStack).ConfigureAwait(continueOnCapturedContext: false))
				{
					return true;
				}
			}
			return false;
		}

		private async Task<bool> SetExecutionContextIfWithinReachAync(int index, SnapshotLineDefinition lineDefinition, BreakpointInfo breakpoint, bool rebuildExecutionIndexStack)
		{
			IList<SnapshotLineContext> snapshotLineContextsForBreakpoint = GetSnapshotLineContextsForBreakpoint(breakpoint);
			if (breakpoint.HitCount < snapshotLineContextsForBreakpoint.Count)
			{
				SnapshotLineContext snapshotLineContext = snapshotLineContextsForBreakpoint[breakpoint.HitCount];
				bool flag = index != snapshotLineContext.ExecutionIndex;
				if (flag)
				{
					flag = await SetCurrentExecutionContextAndLastBreakpointAsync(snapshotLineContext.ExecutionIndex, snapshotLineContext.StatementNumberCounter, lineDefinition, breakpoint, rebuildExecutionIndexStack).ConfigureAwait(continueOnCapturedContext: false);
				}
				if (flag)
				{
					return true;
				}
			}
			return false;
		}

		private async Task<bool> SetCurrentExecutionContextAndLastBreakpointAsync(int index, int statementNumberCounter, SnapshotLineDefinition lineDefinition, BreakpointInfo breakpoint, bool rebuildExecutionIndexStack)
		{
			if (CanExecutionContextBeReached(index, lineDefinition))
			{
				await SetCurrentExecutionContextAndLastBreakpointAsync(index, statementNumberCounter, breakpoint, rebuildExecutionIndexStack).ConfigureAwait(continueOnCapturedContext: false);
				return true;
			}
			return false;
		}

		private async Task HandleNextBreakpointAsync()
		{
			if (breakpoints.Count != 0 && !(await WalkExecutionStackAndSetNextBreakpointAsync().ConfigureAwait(continueOnCapturedContext: false)))
			{
				await SetFirstNotHitBreakpointAsync().ConfigureAwait(continueOnCapturedContext: false);
			}
		}

		private bool IsEntryMethod(int executionIndex)
		{
			if (executionContext.Count <= executionIndex)
			{
				return false;
			}
			return executionContext[executionIndex].FramesLength == 1;
		}

		private async Task<bool> ShouldStartOverOnCurrentEntryMethodAsync(int executionIndex)
		{
			if (!IsEntryMethod(executionIndex))
			{
				return false;
			}
			if (breakpoints.Count == 0)
			{
				return false;
			}
			MethodContext methodContext = executionContext[executionIndex];
			ApplicationObjectIdWrapper? applicationObjectIdWrapper = methodContext.Id.FromBufferedApplicationObjectId();
			if (!applicationObjectIdWrapper.HasValue)
			{
				return false;
			}
			string methodName = methodContext.MethodName;
			foreach (BreakpointInfo breakpoint in breakpoints)
			{
				if (breakpoint.BreakpointDefinition.MethodName.Equals(methodName, StringComparison.OrdinalIgnoreCase) && breakpoint.BreakpointDefinition.ObjectId.Equals(applicationObjectIdWrapper))
				{
					SnapshotLineDefinition snapshotLineDefinition = BreakpointAsSnapshotLine(breakpoint);
					if (snapshotLineDefinition == null)
					{
						return false;
					}
					if (lineDefinitions.TryGetValue(snapshotLineDefinition, out IList<SnapshotLineContext> value) && value.Count > 1 && breakpoint.HitCount < value.Count)
					{
						SnapshotLineContext snapshotLineContext = value[breakpoint.HitCount];
						await SetCurrentExecutionContextAndLastBreakpointAsync(snapshotLineContext.ExecutionIndex, snapshotLineContext.StatementNumberCounter, breakpoint, rebuildExecutionIndexStack: true).ConfigureAwait(continueOnCapturedContext: false);
						return true;
					}
				}
			}
			return false;
		}

		private async Task<bool> SetExecutionContextForLoopsAsync()
		{
			if (lastBreakpoint?.BreakpointDefinition == null)
			{
				return false;
			}
			SnapshotLineDefinition snapshotLineDefinition = BreakpointAsSnapshotLine(lastBreakpoint);
			if (snapshotLineDefinition == null)
			{
				return false;
			}
			if (lineDefinitions.TryGetValue(snapshotLineDefinition, out IList<SnapshotLineContext> value) && value.Count > 1)
			{
				if (AreThereAnyFramesCalledBeforeABreakpointIsHitInALoop())
				{
					return false;
				}
				BreakpointInfo breakpoint = GetBreakpoint(lastBreakpoint);
				if ((object)breakpoint == null)
				{
					return false;
				}
				int currentExecutionIndex = CurrentExecutionIndex;
				if (IsEntryMethod(currentExecutionIndex) && entryLineDefinitions.TryGetValue(snapshotLineDefinition, out var value2) && !value2)
				{
					return false;
				}
				if (await SetExecutionContextForLoopsAsync(currentExecutionIndex, breakpoint, value).ConfigureAwait(continueOnCapturedContext: false))
				{
					return true;
				}
			}
			return false;
		}

		private async Task<bool> SetExecutionContextForLoopsAsync(int currentExecutionIndex, BreakpointInfo lastBreakpointHit, IList<SnapshotLineContext> snapshotLineContextsForTheLastBreakpoint)
		{
			if (lastBreakpointHit.HitCount >= snapshotLineContextsForTheLastBreakpoint.Count)
			{
				return false;
			}
			SnapshotLineContext snapshotLineContext = snapshotLineContextsForTheLastBreakpoint[lastBreakpointHit.HitCount];
			if (snapshotLineContext.ExecutionIndex != currentExecutionIndex)
			{
				return false;
			}
			IList<SnapshotLineContext> lineContextsForIndex = GetLineContextsForIndex(currentExecutionIndex, snapshotLineContextsForTheLastBreakpoint);
			if (lineContextsForIndex.Count == 0)
			{
				return false;
			}
			int num = ((lineContextsForIndex.Count == 1) ? 1 : (lineContextsForIndex[1].StatementNumberCounter - lineContextsForIndex[0].StatementNumberCounter));
			int num2 = (snapshotLineContext.StatementNumberCounter - lineContextsForIndex[0].StatementNumberCounter) / num;
			for (int i = 0; i < lineContextsForIndex.Count; i++)
			{
				SnapshotLineContext snapshotLineContext2 = lineContextsForIndex[i];
				if (i == num2 && executionIndexStack.TryPop(out (int, int, Microsoft.Dynamics.Nav.DebuggerService.SourceSpan) _))
				{
					await SetCurrentExecutionContextAndLastBreakpointAsync(snapshotLineContext2.ExecutionIndex, snapshotLineContext2.StatementNumberCounter, lastBreakpointHit, rebuildExecutionIndexStack: true).ConfigureAwait(continueOnCapturedContext: false);
					return true;
				}
			}
			return false;
		}

		private bool AreThereAnyFramesCalledBeforeABreakpointIsHitInALoop()
		{
			if (!executionIndexStack.TryPeek(out (int, int, Microsoft.Dynamics.Nav.DebuggerService.SourceSpan) result))
			{
				return false;
			}
			MethodContext methodContext = executionContext[result.Item1];
			for (int i = result.Item1 + 1; i < executionContext.Count; i++)
			{
				SnapshotLineDefinition snapshotLineDefinition = executionContext[i].CreateLineDefinitionFromFrameIndex(1);
				if (!(snapshotLineDefinition != null))
				{
					continue;
				}
				for (int j = 0; j < result.Item2; j++)
				{
					if (GetSnapshotLineDefinition(result.Item1, methodContext.Id.FromBufferedApplicationObjectId().Value, j) == snapshotLineDefinition)
					{
						return true;
					}
				}
			}
			return false;
		}

		private async Task<bool> WalkExecutionStackAndSetNextBreakpointAsync()
		{
			SnapshotLineDefinition lastBreakpointAsSnapshotLineDefinition = BreakpointAsSnapshotLine(lastBreakpoint);
			if ((object)lastBreakpointAsSnapshotLineDefinition != null && await SetExecutionContextForLoopsAsync().ConfigureAwait(continueOnCapturedContext: false))
			{
				return true;
			}
			PooledHashSet<SnapshotLineDefinition> snapshotLines = MapBreakpointsToSnapshotLines((BreakpointInfo bp) => bp == lastBreakpoint);
			PooledList<(int Index, int StatementNumberCounter, Microsoft.Dynamics.Nav.DebuggerService.SourceSpan StatementLine)> executionIndexStackAsList = PooledList<(int, int, Microsoft.Dynamics.Nav.DebuggerService.SourceSpan)>.GetInstance();
			try
			{
				executionIndexStackAsList.AddRange(executionIndexStack);
				for (int i = 0; i < executionIndexStackAsList.Count - 1; i++)
				{
					(int Index, int StatementNumberCounter, Microsoft.Dynamics.Nav.DebuggerService.SourceSpan StatementLine) stackElement = executionIndexStackAsList[i];
					if (stackElement.Index == UndefinedValue)
					{
						continue;
					}
					MethodContext methodContext = executionContext[stackElement.Index];
					ApplicationObjectIdWrapper? wrapper = methodContext.Id.FromBufferedApplicationObjectId();
					if (!wrapper.HasValue)
					{
						continue;
					}
					SnapshotLineDefinition snapshotLineDefinition = GetSnapshotLineDefinition(stackElement.Index, wrapper.Value, stackElement.StatementNumberCounter);
					int num = stackElement.StatementNumberCounter + 1;
					if ((object)snapshotLineDefinition != null && (object)lastBreakpointAsSnapshotLineDefinition != null && snapshotLineDefinition == lastBreakpointAsSnapshotLineDefinition)
					{
						num--;
					}
					for (int j = num; j < methodContext.LineContextsLength; j++)
					{
						(bool, bool) tuple = await SetCurrentExecutionContextAndLastBreakpointAsync(stackElement.Index, wrapper.Value, j, snapshotLines).ConfigureAwait(continueOnCapturedContext: false);
						if (tuple.Item1)
						{
							return true;
						}
						if (tuple.Item2)
						{
							break;
						}
					}
				}
				if (executionIndexStackAsList.Count > 1)
				{
					int item = executionIndexStackAsList[executionIndexStackAsList.Count - 2].Index;
					return await ShouldStartOverOnCurrentEntryMethodAsync(item).ConfigureAwait(continueOnCapturedContext: false);
				}
				return false;
			}
			finally
			{
				snapshotLines.Free();
				executionIndexStackAsList.Free();
			}
		}

		private async Task<(bool Result, bool AbortLoop)> SetCurrentExecutionContextAndLastBreakpointAsync(int executionIndex, ApplicationObjectIdWrapper id, int statementCounter, PooledHashSet<SnapshotLineDefinition> breakpointLines)
		{
			SnapshotLineDefinition snapshotLineDefinition = GetSnapshotLineDefinition(executionIndex, id, statementCounter);
			if ((object)snapshotLineDefinition == null)
			{
				return (Result: false, AbortLoop: true);
			}
			if (breakpointLines.Contains(snapshotLineDefinition) && lineDefinitions.TryGetValue(snapshotLineDefinition, out IList<SnapshotLineContext> value))
			{
				BreakpointInfo breakpoint = GetBreakpoint(snapshotLineDefinition);
				if ((object)breakpoint != null && value.Count > breakpoint.HitCount)
				{
					SnapshotLineContext snapshotLineContext = value[breakpoint.HitCount];
					await SetCurrentExecutionContextAndLastBreakpointAsync(snapshotLineContext.ExecutionIndex, snapshotLineContext.StatementNumberCounter, breakpoint, rebuildExecutionIndexStack: true).ConfigureAwait(continueOnCapturedContext: false);
					return (Result: true, AbortLoop: true);
				}
			}
			if (await SetExecutionContextIfWithinReachAsync(executionIndex, snapshotLineDefinition, rebuildExecutionIndexStack: true).ConfigureAwait(continueOnCapturedContext: false))
			{
				return (Result: true, AbortLoop: true);
			}
			return (Result: false, AbortLoop: false);
		}

		private async Task SetFirstNotHitBreakpointAsync()
		{
			BreakpointInfo breakpointInfo = null;
			if ((object)lastBreakpoint == null)
			{
				breakpointInfo = breakpoints[0];
			}
			else
			{
				foreach (BreakpointInfo breakpoint in breakpoints)
				{
					if (!breakpointsHit.Contains(breakpoint))
					{
						breakpointInfo = breakpoint;
						break;
					}
				}
			}
			if ((object)breakpointInfo == null)
			{
				await parentService.LogAndTerminateAsync(ProtocolResources.SnapshotDebuggerNoMoreFrames, isError: false).ConfigureAwait(continueOnCapturedContext: false);
				return;
			}
			int currentExecutionIndex = CurrentExecutionIndex;
			IList<SnapshotLineContext> snapshotLineContextsForBreakpoint = GetSnapshotLineContextsForBreakpoint(breakpointInfo);
			if (snapshotLineContextsForBreakpoint.Count == 1)
			{
				await SetCurrentExecutionContextAndLastBreakpointAsync(snapshotLineContextsForBreakpoint[0].ExecutionIndex, snapshotLineContextsForBreakpoint[0].StatementNumberCounter, breakpointInfo, rebuildExecutionIndexStack: true).ConfigureAwait(continueOnCapturedContext: false);
				return;
			}
			int num = int.MaxValue;
			int index = 0;
			int statementNumberCounter = UndefinedValue;
			for (int i = 0; i < snapshotLineContextsForBreakpoint.Count; i++)
			{
				int executionIndex = snapshotLineContextsForBreakpoint[i].ExecutionIndex;
				int num2 = Math.Abs(executionIndex - currentExecutionIndex);
				if (num2 < num)
				{
					num = num2;
					index = executionIndex;
					statementNumberCounter = snapshotLineContextsForBreakpoint[i].StatementNumberCounter;
				}
			}
			await SetCurrentExecutionContextAndLastBreakpointAsync(index, statementNumberCounter, breakpointInfo, rebuildExecutionIndexStack: true).ConfigureAwait(continueOnCapturedContext: false);
		}

		private async Task<bool> HandleEntryBreakpointAsync()
		{
			if (breakpoints.Count == 0)
			{
				return false;
			}
			if (executionContext.Count == 0)
			{
				return false;
			}
			MethodContext firstMethod = executionContext[0];
			ApplicationObjectIdWrapper id = firstMethod.Id.FromBufferedApplicationObjectId().Value;
			PooledHashSet<SnapshotLineDefinition> snapshotLines = MapBreakpointsToSnapshotLines();
			try
			{
				for (int i = 0; i < firstMethod.LineContextsLength; i++)
				{
					(bool, bool) tuple = await SetCurrentExecutionContextAndLastBreakpointAsync(0, id, i, snapshotLines).ConfigureAwait(continueOnCapturedContext: false);
					if (tuple.Item1)
					{
						return true;
					}
					if (tuple.Item2)
					{
						break;
					}
				}
			}
			finally
			{
				snapshotLines.Free();
			}
			BreakpointInfo breakpointInfo = breakpoints[0];
			if ((object)breakpointInfo == null || breakpointInfo.BreakpointDefinition == null)
			{
				return false;
			}
			IList<SnapshotLineContext> snapshotLineContextsForBreakpoint = GetSnapshotLineContextsForBreakpoint(breakpointInfo);
			if (snapshotLineContextsForBreakpoint.Count == 0)
			{
				return false;
			}
			await SetCurrentExecutionContextAndLastBreakpointAsync(snapshotLineContextsForBreakpoint[0].ExecutionIndex, snapshotLineContextsForBreakpoint[0].StatementNumberCounter, breakpointInfo, rebuildExecutionIndexStack: true).ConfigureAwait(continueOnCapturedContext: false);
			return true;
		}

		private PooledHashSet<SnapshotLineDefinition> MapBreakpointsToSnapshotLines(Func<BreakpointInfo, bool>? filter = null)
		{
			PooledHashSet<SnapshotLineDefinition> instance = PooledHashSet<SnapshotLineDefinition>.GetInstance();
			foreach (BreakpointInfo breakpoint in breakpoints)
			{
				BreakpointDefinition breakpointDefinition = breakpoint.BreakpointDefinition;
				if (breakpointDefinition != null && (filter == null || !filter(breakpoint)))
				{
					SnapshotLineDefinition item = new SnapshotLineDefinition
					{
						Id = breakpointDefinition.ObjectId,
						StatementSpan = breakpointDefinition.SourceSpan
					};
					instance.Add(item);
				}
			}
			return instance;
		}

		private BreakpointInfo? GetBreakpoint(SnapshotLineDefinition snapshotLine)
		{
			foreach (BreakpointInfo breakpoint in breakpoints)
			{
				BreakpointDefinition breakpointDefinition = breakpoint.BreakpointDefinition;
				if (breakpointDefinition != null && new SnapshotLineDefinition
				{
					Id = breakpointDefinition.ObjectId,
					StatementSpan = breakpointDefinition.SourceSpan
				} == snapshotLine)
				{
					return breakpoint;
				}
			}
			return null;
		}

		private IList<SnapshotLineContext> GetSnapshotLineContextsForBreakpoint(BreakpointInfo breakpoint)
		{
			BreakpointDefinition breakpointDefinition = breakpoint.BreakpointDefinition;
			if (breakpointDefinition == null)
			{
				return SpecializedCollections.EmptyList<SnapshotLineContext>();
			}
			SnapshotLineDefinition key = new SnapshotLineDefinition
			{
				Id = breakpointDefinition.ObjectId,
				StatementSpan = breakpointDefinition.SourceSpan
			};
			if (!lineDefinitions.TryGetValue(key, out IList<SnapshotLineContext> value))
			{
				return SpecializedCollections.EmptyList<SnapshotLineContext>();
			}
			return value;
		}

		private bool CanExecutionContextBeReached(int index, SnapshotLineDefinition nextLine)
		{
			PooledHashSet<SnapshotLineDefinition> instance = PooledHashSet<SnapshotLineDefinition>.GetInstance();
			try
			{
				GetReveresedCallStack(index, instance);
				return instance.Contains(nextLine);
			}
			finally
			{
				instance.Free();
			}
		}

		private IList<(int ExecutionIndex, int StatementNumberCounter)> GetReveresedCallStack(int calledExecutionIndex, PooledHashSet<SnapshotLineDefinition> lineDefinitionsHashSet)
		{
			MethodContext context = executionContext[calledExecutionIndex];
			PooledList<(int, int)> instance = PooledList<(int, int)>.GetInstance();
			try
			{
				if (context.FramesLength <= 1)
				{
					return SpecializedCollections.EmptyList<(int, int)>();
				}
				SnapshotLineDefinition snapshotLineDefinition = context.CreateLineDefinitionFromFrameIndex(1);
				if ((object)snapshotLineDefinition == null)
				{
					return SpecializedCollections.EmptyList<(int, int)>();
				}
				if (!lineDefinitions.TryGetValue(snapshotLineDefinition, out IList<SnapshotLineContext> value))
				{
					return SpecializedCollections.EmptyList<(int, int)>();
				}
				if (!lineDefinitionsHashSet.Add(snapshotLineDefinition))
				{
					return SpecializedCollections.EmptyList<(int, int)>();
				}
				SnapshotLineDefinition snapshotLineDefinition2 = context.CreateLineDefinitionFromFrameIndex(2);
				if ((object)snapshotLineDefinition2 == null)
				{
					SnapshotLineContext snapshotLineContext = null;
					snapshotLineContext = ((value.Count == 1) ? value[0] : GetClosestSnapshotLineAndContext(calledExecutionIndex, value));
					if (snapshotLineContext == null)
					{
						return SpecializedCollections.EmptyList<(int, int)>();
					}
					instance.Add((snapshotLineContext.ExecutionIndex, snapshotLineContext.StatementNumberCounter));
					instance.AddRange(GetReveresedCallStack(snapshotLineContext.ExecutionIndex, lineDefinitionsHashSet));
				}
				else
				{
					foreach (SnapshotLineContext item in value)
					{
						SnapshotLineDefinition callerLine = GetCallerLine(executionContext[item.ExecutionIndex]);
						if ((object)snapshotLineDefinition2 != null && snapshotLineDefinition2.Equals(callerLine))
						{
							instance.Add((item.ExecutionIndex, item.StatementNumberCounter));
							instance.AddRange(GetReveresedCallStack(item.ExecutionIndex, lineDefinitionsHashSet));
							break;
						}
					}
				}
				return instance.ToList();
			}
			finally
			{
				instance.Free();
			}
		}

		private SnapshotLineContext? GetClosestSnapshotLineAndContext(int calledExecutionIndex, IList<SnapshotLineContext> callerLineContexts)
		{
			int num = calledExecutionIndex;
			SnapshotLineContext result = null;
			foreach (SnapshotLineContext callerLineContext in callerLineContexts)
			{
				if (callerLineContext.ExecutionIndex > calledExecutionIndex)
				{
					break;
				}
				int num2 = calledExecutionIndex - callerLineContext.ExecutionIndex;
				if (num2 < num)
				{
					num = num2;
					result = callerLineContext;
				}
			}
			return result;
		}

		private bool IsBreakpointAnExceptionPoint(BreakpointInfo info)
		{
			if (info?.BreakpointDefinition == null)
			{
				return false;
			}
			SnapshotLineDefinition snapshotLine = new SnapshotLineDefinition
			{
				Id = info.BreakpointDefinition.ObjectId,
				StatementSpan = info.BreakpointDefinition.SourceSpan
			};
			return exceptions.Any((SnapshotLineDefinition e) => e == snapshotLine);
		}

		private async Task SetCurrentExecutionContextAsync(int index, int statementNumberCounter)
		{
			await PushValueOnExecutionIndexStackAsync(index, statementNumberCounter).ConfigureAwait(continueOnCapturedContext: false);
			MethodContext methodContext = executionContext[index];
			if (statementNumberCounter >= methodContext.LineContextsLength)
			{
				return;
			}
			Microsoft.Dynamics.Nav.AL.Common.SnapshotDebuggerSerializer.LineContext? lineContext = methodContext.LineContexts(statementNumberCounter);
			if (!lineContext.HasValue)
			{
				return;
			}
			SnapshotLineDefinition snapshotLineDefinition = new SnapshotLineDefinition
			{
				Id = methodContext.Id.FromBufferedApplicationObjectId().Value,
				StatementSpan = lineContext.Value.StatementSpan.FromBufferedSourceSpan().Value
			};
			PooledHashSet<SnapshotLineDefinition> pooledHashSet = MapBreakpointsToSnapshotLines();
			try
			{
				foreach (SnapshotLineDefinition item in pooledHashSet)
				{
					if (!(item == snapshotLineDefinition))
					{
						continue;
					}
					BreakpointInfo breakpoint = GetBreakpoint(item);
					lock (breakpoints)
					{
						if (breakpoint != null)
						{
							breakpoint.HitCount++;
							if (breakpoint == lastBreakpoint)
							{
								lastBreakpoint.HitCount = breakpoint.HitCount;
							}
						}
						break;
					}
				}
			}
			finally
			{
				pooledHashSet.Free();
			}
		}

		private BreakpointInfo? GetBreakpoint(BreakpointInfo breakpoint)
		{
			foreach (BreakpointInfo breakpoint2 in breakpoints)
			{
				if (breakpoint2 == breakpoint)
				{
					return breakpoint;
				}
			}
			return null;
		}

		private async Task SetCurrentExecutionContextAndLastBreakpointAsync(int index, int statementNumberCounter, BreakpointInfo bp, bool rebuildExecutionIndexStack, int? hitCount = null)
		{
			SetLastBreakpointAndHitCount(bp, hitCount);
			if (rebuildExecutionIndexStack)
			{
				executionIndexStack.Clear();
				executionIndexStack.Push((UndefinedValue, UndefinedValue, Microsoft.Dynamics.Nav.DebuggerService.SourceSpan.Default));
				PooledHashSet<SnapshotLineDefinition> lineDefinitionsSet = PooledHashSet<SnapshotLineDefinition>.GetInstance();
				try
				{
					IList<(int ExecutionIndex, int StatementNumberCounter)> reveresedCallStack = GetReveresedCallStack(index, lineDefinitionsSet);
					for (int i = reveresedCallStack.Count - 1; i >= 0; i--)
					{
						(int, int) tuple = reveresedCallStack[i];
						if (!(await PushValueOnExecutionIndexStackAsync(tuple.Item1, tuple.Item2).ConfigureAwait(continueOnCapturedContext: false)))
						{
							return;
						}
					}
				}
				finally
				{
					lineDefinitionsSet.Free();
				}
			}
			await PushValueOnExecutionIndexStackAsync(index, statementNumberCounter).ConfigureAwait(continueOnCapturedContext: false);
		}

		private void SetLastBreakpointAndHitCount(BreakpointInfo bp, int? hitCount = null)
		{
			lock (breakpoints)
			{
				if (!hitCount.HasValue)
				{
					bp.HitCount++;
				}
				else
				{
					bp.HitCount = hitCount.Value;
				}
				lastBreakpoint = bp;
			}
			breakpointsHit.Add(bp);
		}

		private async Task<bool> PushValueOnExecutionIndexStackAsync(int index, int statementNumberCounter)
		{
			Microsoft.Dynamics.Nav.DebuggerService.SourceSpan? statementSpan = GetStatementSpan(index, statementNumberCounter);
			if (!statementSpan.HasValue)
			{
				if (index < executionContext.Count)
				{
					await TerminateWithCorruptLineMessage(index).ConfigureAwait(continueOnCapturedContext: false);
				}
				else
				{
					await parentService.LogAndTerminateAsync(ProtocolResources.SnapshotDebuggerNoMoreFrames).ConfigureAwait(continueOnCapturedContext: false);
				}
				return false;
			}
			executionIndexStack.Push((index, statementNumberCounter, statementSpan.Value));
			return true;
		}

		private async Task BreakAsync()
		{
			MethodContext? topOfStack = TopOfStack;
			if (!topOfStack.HasValue)
			{
				await parentService.ContinueAsync(BreakpointResponse.Continue).ConfigureAwait(continueOnCapturedContext: false);
				return;
			}
			ApplicationObjectIdWrapper? applicationObjectIdWrapper = topOfStack.Value.Id.FromBufferedApplicationObjectId();
			if (!applicationObjectIdWrapper.HasValue)
			{
				await parentService.ContinueAsync(BreakpointResponse.Continue).ConfigureAwait(continueOnCapturedContext: false);
				return;
			}
			Microsoft.Dynamics.Nav.DebuggerService.StackFrame[] currentFrame = GetCurrentFrame();
			parentService.SetExecutionState(applicationObjectIdWrapper.Value, currentFrame, topOfStack.Value.Exception?.Message, DebuggerState.Break);
		}

