		private static bool LogArchiveOpenException(Exception e)
		{
			if (!(e is IOException) && !(e is InvalidDataException))
			{
				return e is UnauthorizedAccessException;
			}
			return true;
		}

		private async Task<MethodOrTriggerDeclarationSyntax?> GetMethodOrTriggerDeclarationSyntax(ApplicationObjectIdWrapper id, Microsoft.Dynamics.Nav.DebuggerService.SourcePosition position)
		{
			return (await GetNodeAtPositionAsync(id, position).ConfigureAwait(continueOnCapturedContext: false))?.FirstAncestorOrSelf<MethodOrTriggerDeclarationSyntax>();
		}

		private async Task<bool> IsLineInLoopContextAsync(SnapshotLineDefinition line)
