		private async Task<SyntaxNode?> GetNodeAtPositionAsync(ApplicationObjectIdWrapper id, Microsoft.Dynamics.Nav.DebuggerService.SourcePosition position)
		{
			(LinePosition?, SyntaxTree) tuple = await GetLinePositionAsync(id, position).ConfigureAwait(continueOnCapturedContext: false);
			if (tuple.Item2 == null || !tuple.Item1.HasValue)
			{
				return null;
			}
			return await tuple.Item2.GetNodeAtPositionAsync(tuple.Item1.Value, tokenSource.Token).ConfigureAwait(continueOnCapturedContext: false);
		}

		private async Task<(LinePosition?, SyntaxTree?)> GetLinePositionAsync(ApplicationObjectIdWrapper id, Microsoft.Dynamics.Nav.DebuggerService.SourcePosition position)
		{
			int appIdHash = id.GetHashCode();
			string documentPath = null;
			if (!parentService.DownloadedSources.TryGetValue(appIdHash, out SourceContent value))
			{
				var (sourceContent, text) = await GetSourceContentAsync(id).ConfigureAwait(continueOnCapturedContext: false);
				if (sourceContent == null)
				{
					return (null, null);
				}
				value = sourceContent;
				parentService.DownloadedSources.Add(appIdHash, value);
				documentPath = text;
			}
			else
			{
				string path = CreateArchiveFileName(id);
				documentPath = Path.Combine(alFilesFolder, path);
			}
			DocumentId documentId;
			ApplicationObjectTypeSymbol applicationObjectTypeSymbol;
			(documentId, applicationObjectTypeSymbol) = await GetOrAddDocumentAsync(documentPath).ConfigureAwait(continueOnCapturedContext: false);
			if (applicationObjectTypeSymbol != null)
			{
				return (AdjustLineNumber(applicationObjectTypeSymbol), applicationObjectTypeSymbol.DeclaringSyntaxNode?.SyntaxTree);
			}
			if ((object)documentId == null)
			{
				return (null, null);
			}
			Document document = workspace.CurrentSolution.GetDocument(documentId);
			if (document == null)
			{
				return (null, null);
			}
			SymbolKind asSymbolKind = DebugHelper.MapToSymbolKind(id.ObjectType);
			ImmutableArray<IObjectTypeSymbol> immutableArray = await document.GetDeclaringObjectAsync(tokenSource.Token).ConfigureAwait(continueOnCapturedContext: false);
			for (int i = 0; i < immutableArray.Length; i++)
			{
				IObjectTypeSymbol objectTypeSymbol = immutableArray[i];
				if (objectTypeSymbol.Kind.IsApplicationObject())
				{
					applicationObjectTypeSymbol = (ApplicationObjectTypeSymbol)objectTypeSymbol;
					if (applicationObjectTypeSymbol.Kind == asSymbolKind && applicationObjectTypeSymbol.Id == id.ObjectNumber && applicationObjectTypeSymbol.DeclaringSyntaxNode != null)
					{
						return (AdjustLineNumber(applicationObjectTypeSymbol), applicationObjectTypeSymbol.DeclaringSyntaxNode?.SyntaxTree);
					}
				}
			}
			return (null, null);
			LinePosition? AdjustLineNumber(ApplicationObjectTypeSymbol appSymbol)
			{
				SyntaxTree syntaxTree = appSymbol.DeclaringSyntaxNode?.SyntaxTree ?? null;
				if (syntaxTree == null)
				{
					return null;
				}
				string text2 = documentPath?.CreateUriFilePath();
				string value2 = syntaxTree.FilePath?.CreateUriFilePath();
				if (text2 != null && text2.Equals(value2, StringComparison.OrdinalIgnoreCase))
				{
					return new LinePosition(position.Line, position.Column);
				}
				int? num = appSymbol.DeclaringSyntaxNode?.GetDebuggerLineOffsetForNode();
				if (num.HasValue)
				{
					int num2 = position.Line - num.Value;
					return new LinePosition(appSymbol.DeclaringSyntaxNode.Location.GetMappedLineSpan().StartLinePosition.Line + num2, position.Column);
				}
				return new LinePosition(position.Line, position.Column);
			}
		}

		private async Task<Microsoft.Dynamics.Nav.DebuggerService.SourceSpan?> GetRelativeSourceSpan(ApplicationObjectIdWrapper id, Microsoft.Dynamics.Nav.DebuggerService.SourcePosition position)
		{
			MethodOrTriggerDeclarationSyntax methodOrTriggerDeclarationSyntax = await GetMethodOrTriggerDeclarationSyntax(id, position).ConfigureAwait(continueOnCapturedContext: false);
			if (methodOrTriggerDeclarationSyntax == null)
			{
				return null;
			}
			int position2 = methodOrTriggerDeclarationSyntax.Body?.Position ?? methodOrTriggerDeclarationSyntax.Position;
			LinePosition linePosition = methodOrTriggerDeclarationSyntax.SyntaxTree.GetLinePosition(position2);
			int num = position.Line - linePosition.Line - 1;
			ushort line = (ushort)((num > 0) ? ((uint)num) : 0u);
			Microsoft.Dynamics.Nav.DebuggerService.SourcePosition from = new Microsoft.Dynamics.Nav.DebuggerService.SourcePosition(line, 0);
			return new Microsoft.Dynamics.Nav.DebuggerService.SourceSpan(from, new Microsoft.Dynamics.Nav.DebuggerService.SourcePosition(line, 1));
		}

		private async Task<(DocumentId? DocumentId, ApplicationObjectTypeSymbol? symbol)> GetOrAddDocumentAsync(string? path)
		{
			if (string.IsNullOrEmpty(path))
			{
				return (DocumentId: null, symbol: null);
			}
			string fileNameWithoutExtension = Path.GetFileNameWithoutExtension(path);
			ApplicationObjectIdWrapper? appId = ParseArchiveFilePath(fileNameWithoutExtension);
			if (!appId.HasValue)
			{
				return (DocumentId: null, symbol: null);
			}
			SymbolKind kind = DebugHelper.MapToSymbolKind(appId.Value.ObjectType);
			Compilation compilation = await workspace.CurrentSolution.GetCompilationAsync(workspace.CurrentProjectId, tokenSource.Token).ConfigureAwait(continueOnCapturedContext: false);
			if (compilation == null)
			{
				return (DocumentId: null, symbol: null);
			}
			string text = null;
			DocumentId documentId = null;
			ApplicationObjectTypeSymbol applicationObjectTypeSymbol = compilation.GetDeclaredApplicationObjectSymbols().FirstOrDefault((IApplicationObjectTypeSymbol s) => s.Id == appId.Value.ObjectNumber && s.Kind == kind) as ApplicationObjectTypeSymbol;
			if (tokenSource.IsCancellationRequested)
			{
				return (DocumentId: null, symbol: null);
			}
			Document document;
			if (applicationObjectTypeSymbol != null)
			{
				string text2 = applicationObjectTypeSymbol.DeclaringSyntaxNode?.SyntaxTree?.FilePath;
				if (text2 != null)
				{
					text = text2.CreateUriFilePath();
				}
				document = workspace.GetDocument(text);
				if (document != null)
				{
					return (DocumentId: document.Id, symbol: applicationObjectTypeSymbol);
				}
			}
			if (text == null)
			{
				text = path.CreateUriFilePath();
			}
			document = workspace.GetDocument(text);
			if (document == null)
			{
				workspace.BufferManager.TryAddTransientDocument(workspace.CurrentProjectId, text, null, handleRad: false, out documentId);
			}
			else
			{
				documentId = document.Id;
			}
			return (DocumentId: documentId, symbol: applicationObjectTypeSymbol);
		}

		private static string CreateArchiveFileName(ApplicationObjectIdWrapper id)
		{
			return string.Format(CultureInfo.InvariantCulture, "{0}{1}{2}.{3}", id.ObjectType, ArchivePathSeparator, id.ObjectNumber, "AL".ToLowerInvariant());
		}

		private static Microsoft.Dynamics.Nav.DebuggerService.StackFrame? FromBufferedFrame(Microsoft.Dynamics.Nav.AL.Common.SnapshotDebuggerSerializer.StackFrame? bufferedFrame)
		{
			if (!bufferedFrame.HasValue)
			{
				return null;
			}
			ApplicationObjectIdWrapper? applicationObjectIdWrapper = bufferedFrame.Value.Id.FromBufferedApplicationObjectId();
			if (!applicationObjectIdWrapper.HasValue)
			{
				return null;
			}
			string objectName = bufferedFrame.Value.ObjectName;
			string methodName = bufferedFrame.Value.MethodName;
			if (string.IsNullOrEmpty(methodName))
			{
				return null;
			}
			Microsoft.Dynamics.Nav.DebuggerService.SourceSpan? sourceSpan = bufferedFrame.Value.StatementSpan.FromBufferedSourceSpan();
			return new Microsoft.Dynamics.Nav.DebuggerService.StackFrame(applicationObjectIdWrapper.Value, objectName, methodName, sourceSpan.GetValueOrDefault());
		}

		private static string CreateTempAlFilesFolder()
		{
			string text = Path.Combine(Path.GetTempPath(), SnapshotFiles);
			DirectoryInfo directoryInfo = new DirectoryInfo(text);
			if (!directoryInfo.Exists)
			{
				directoryInfo.Create();
			}
			return text;
		}

		private static ApplicationObjectIdWrapper? ParseArchiveFilePath(string fileName)
		{
			string[] array = fileName.Split(ArchivePathSeparator);
			if (array == null)
			{
				return null;
			}
			if (!Enum.TryParse<ObjectTypeWrapper>(array[0], ignoreCase: true, out var result))
			{
				return null;
			}
			if (!int.TryParse(array[1], out var result2))
			{
				return null;
			}
			return new ApplicationObjectIdWrapper(result, result2);
		}

		private static IList<SnapshotLineContext> GetLineContextsForIndex(int executionIndex, IList<SnapshotLineContext> snapshotLineContexts)
		{
			PooledList<SnapshotLineContext> instance = PooledList<SnapshotLineContext>.GetInstance();
			try
			{
				foreach (SnapshotLineContext snapshotLineContext in snapshotLineContexts)
				{
					if (snapshotLineContext.ExecutionIndex == executionIndex)
					{
						instance.Add(snapshotLineContext);
					}
				}
				return instance.ToArray();
			}
			finally
			{
				instance.Free();
			}
		}
	}
