	public class Handle<T>
	{
		internal const int LastVariableGroupIndex = 3;

		public const int StartIndex = 262144;

		private int nextHandle = 262144;

		private readonly ConcurrentDictionary<int, T> handles = new ConcurrentDictionary<int, T>();

		public void Reset()
		{
			nextHandle = 262144;
			handles.Clear();
		}

		public int Create(T value)
		{
			int num = nextHandle++;
			handles[num] = value;
			return num;
		}

		public bool TryGet(int handle, out T value)
		{
			return handles.TryGetValue(handle, out value);
		}

		public T Get(int handle)
		{
			if (!handles.TryGetValue(handle, out var value))
			{
				return default(T);
			}
			return value;
		}
	}
	internal class DebugAdapterLaunchBrowserRequestHandler : DebugAdapterLaunchRequestHandlerBase
	{
		private readonly IClientStartup clientStartup;

		public DebugAdapterLaunchBrowserRequestHandler(IProxyBasedDebuggerService proxyBasedDebuggerService, VsCodeWorkspace workspace, ResponseQueue responseQueue, IClientStartup clientStartup, IFileSystem fileSystem = null)
			: base(proxyBasedDebuggerService, workspace, responseQueue, fileSystem)
		{
			this.clientStartup = clientStartup;
		}

		public override async Task HandleAsync(InitializeDebugAdapterRequest request, int requestId, CancellationToken cancellationToken)
		{
			InitializeDebugAdapterRequest request2 = request;
			if (!VerifyRequest(request2, cancellationToken))
			{
				return;
			}
			await HandleAttachOrLaunchAsync(request2, requestId, cancellationToken, async delegate(ServerInfo serverInfo, ConnectionOptions connectionOptions)
			{
				(bool, PublishResult) tuple = await PublishPackage(request2, requestId, serverInfo, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				bool didPublish = tuple.Item1;
				PublishResult publishResult = tuple.Item2;
				ClientConnectionInfo clientConnectionInfo = publishResult?.ClientConnectionInfo;
				if (clientConnectionInfo == null)
				{
					clientConnectionInfo = await GetClientConnectionInfo(serverInfo).ConfigureAwait(continueOnCapturedContext: false);
				}
				ClientConnectionInfo info = clientConnectionInfo;
				(bool, bool) obj = await StartDebugging(info, serverInfo, request2, requestId, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
				var (flag, _) = obj;
				if (!obj.Item2)
				{
					if (didPublish)
					{
						EmptyThisAndPublishedPackagesRadFiles(request2.DependencyPublishingOption, publishResult.PublishedProjectReferences, request2.ProjectReferenceDefinitions);
					}
					base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId), cancellationToken);
					IHubBasedDebuggerService hubBasedDebuggerService = base.DebuggerService.Proxy as IHubBasedDebuggerService;
					if (flag || !request2.LaunchBrowser.HasValue || request2.LaunchBrowser.GetValueOrDefault() || !request2.PublishOnly)
					{
						Uri webEndpointUri = serverInfo?.GetWebEndpointUrl();
						IClientStartup obj2 = clientStartup;
						DebugConsoleLogger logger = base.Logger;
						int? startupObjectId = request2.StartupObjectId;
						StartupObjectType? startupObjectType = request2.StartupObjectType;
						string? startupCompany = request2.StartupCompany;
						IDictionary<string, string> debuggingContext = hubBasedDebuggerService?.ConnectionContext;
						BrowserInfo browserInfo = LanguageServerOptions.BrowserInfo;
						obj2.OpenStartupObject(webEndpointUri, connectionOptions, logger, startupObjectId, startupObjectType, startupCompany, null, debuggingContext, browserInfo);
					}
					if (!flag)
					{
						SendNoDebugResponseMessages(cancellationToken);
					}
				}
			}).ConfigureAwait(continueOnCapturedContext: false);
		}
	}
	internal abstract class DebugAdapterLaunchRequestHandlerBase : DebugAdapterStartRequestHandler
	{
		public override string EndpointName => "launch";

		public override bool ProfilePerformance => true;

		internal IFileSystem? FileSystem { get; }

		protected DebugAdapterLaunchRequestHandlerBase(IProxyBasedDebuggerService proxyBasedDebuggerService, VsCodeWorkspace workspace, ResponseQueue responseQueue, IFileSystem fileSystem = null)
			: base(proxyBasedDebuggerService, workspace, responseQueue)
		{
			FileSystem = fileSystem ?? Microsoft.Dynamics.Nav.CodeAnalysis.FileSystem.Instance;
		}

		protected bool VerifyRequest(InitializeDebugAdapterRequest request, CancellationToken cancellationToken)
		{
			if (request == null)
			{
				base.Logger.Error(ProtocolResources.DebuggerInitializationFailedWrongInputParameter);
				base.ResponseQueue.Add(ResponseFactory.DebugAdapterTerminatedEvent(), cancellationToken);
				return false;
			}
			return true;
		}

		protected async Task<(bool, PublishResult?)> PublishPackage(InitializeDebugAdapterRequest request, int requestId, ServerInfo serverInfo, CancellationToken cancellationToken)
		{
			if (!request.JustDebug)
			{
				using (PooledStopwatch publishSw = PooledStopwatch.GetInstance())
				{
					publishSw.Start();
					PublishResult publishResult = await PublishPackage(request, requestId, serverInfo).ConfigureAwait(continueOnCapturedContext: false);
					if (!publishResult.Success)
					{
						base.ResponseQueue.Add(ResponseFactory.ErrorResponse(new MessageError
						{
							Message = ProtocolResources.DeploymentError
						}, "launch", requestId), cancellationToken);
					}
					publishSw.Stop();
					GetCustomTelemetryForRequest(requestId).Metrics.Add("Publish time (ms)", publishSw.ElapsedMilliseconds);
					return (true, publishResult);
				}
			}
			GetCustomTelemetryForRequest(requestId).Metrics.Add("Publish time (ms)", 0.0);
			return (false, null);
		}

		protected async Task<(bool, bool)> StartDebugging(ClientConnectionInfo? info, ServerInfo serverInfo, InitializeDebugAdapterRequest request, int requestId, CancellationToken cancellationToken)
		{
			bool shouldDebug = request.JustDebug || !request.PublishOnly;
			bool hasDebugError = false;
			if (shouldDebug)
			{
				if (info == null)
				{
					AddErrorResponse(requestId, cancellationToken);
					hasDebugError = true;
				}
				else
				{
					using PooledStopwatch debugAttachSw = PooledStopwatch.GetInstance();
					try
					{
						if (!(await StartDebugging(info, serverInfo, request.DebugOptions()).ConfigureAwait(continueOnCapturedContext: false)))
						{
							AddErrorResponse(requestId, cancellationToken);
							hasDebugError = true;
						}
					}
					finally
					{
						GetCustomTelemetryForRequest(requestId).Metrics.Add("Debug attach time (ms)", debugAttachSw.ElapsedMilliseconds);
					}
				}
			}
			return (shouldDebug, hasDebugError);
		}

		private async Task<PublishResult> PublishPackage(InitializeDebugAdapterRequest request, int requestId, ServerInfo serverInfo)
		{
			string path = Path.Combine(LanguageServerOptions.ProjectRoot, "app.json");
			List<Diagnostic> list = new List<Diagnostic>();
			ProjectManifestProps manifestProps = ProjectManifestProps.LoadFromFile(LanguageServerOptions.ProjectRoot, list);
			string text = ProjectManifest.ReadFromFile(path, manifestProps, list)?.AppManifest?.DefaultPackageName() + ".app";
			string packageFileName = ((request.ProjectReferenceDefinitions == null || request.ProjectReferenceDefinitions.Length == 0 || !serverInfo.Supports(DevApiFeature.ProjectReferencePublishing)) ? text : DependencyPackageOutputter.CreateDependentOutputFileName(text));
			string projectRootedPath = DebugHelper.GetProjectRootedPath(request.Directory);
			if (request.IsRad && !ValidateRadFile())
			{
				base.Logger.Info(ProtocolResources.EmptyRadFilePublishingWillStop);
				return new PublishResult(success: true, null, null, null, null, 0L);
			}
			PublishOptions options = new PublishOptions
			{
				Directory = projectRootedPath,
				PackageFileName = packageFileName,
				Server = request.Server,
				Port = request.Port,
				ServerInstance = request.ServerInstance,
				Tenant = request.Tenant,
				ApplicationFamily = request.ApplicationFamily,
				Authentication = request.Authentication,
				Environment = request.Environment,
				SchemaUpdateMode = request.SchemaUpdateMode,
				IsRad = request.IsRad,
				SandboxName = request.SandboxName,
				EnvironmentName = request.EnvironmentName,
				EnvironmentType = request.EnvironmentType,
				DependencyPublishingOption = request.DependencyPublishingOption,
				DeploymentId = request.DeploymentId,
				ForceUpgrade = request.ForceUpgrade,
				DisableInstallDebugging = request.DisableInstallDebugging,
				UsePublicURLFromServer = request.UsePublicURLFromServer,
				ValidateServerCertificate = request.ValidateServerCertificate,
				PrimaryTenantDomain = request.PrimaryTenantDomain
			};
			if (!ValidateManifestDiagnostics(list))
			{
				return new PublishResult(success: false, null, null, null, null, 0L);
			}
			if (request.IsRad && !serverInfo.Supports(DevApiFeature.Rad))
			{
				base.Logger.Error(ProtocolResources.RadOptionAreNotValidForTheRequestedServerVersion);
				return new PublishResult(success: false, null, null, null, null, 0L);
			}
			LogTelemetry(request, requestId);
			PublishResult publishResult = await new Publisher(base.Logger).Publish(options, base.DebuggerService.CancellationToken);
			GetCustomTelemetryForRequest(requestId).Metrics.Add("App File Size (bytes)", publishResult.FileSizeBytes);
			if (publishResult.Success)
			{
				DeleteDependencyFileIfAvailable(options.PackageFileName);
			}
			return publishResult;
			bool ValidateRadFile()
			{
				if (base.Workspace.ObjectChangeDocumentManager.ActiveObjectChangeManager == null)
				{
					ObjectChangeManager objectChangeManager = new ObjectChangeManager();
					string path2 = LanguageServerOptions.ProjectRoot.RadPath();
					objectChangeManager.Load(path2, FileSystem);
					IReadOnlyCollection<ObjectChangeContext> changes = objectChangeManager.Changes;
					if (changes == null)
					{
						return true;
					}
					return changes.Count != 0;
				}
				IReadOnlyCollection<ObjectChangeContext> changes2 = base.Workspace.ObjectChangeDocumentManager.ActiveObjectChangeManager.Changes;
				if (changes2 == null)
				{
					return true;
				}
				return changes2.Count != 0;
			}
		}

		internal void EmptyThisAndPublishedPackagesRadFiles(DependencyPublishingOption publishingOption, IList<ProjectModelDefinition> publishedReferences, IList<AlProjectDefinition> alProjectDefinitions)
		{
			IObjectChangeManager activeObjectChangeManager = base.Workspace.ObjectChangeDocumentManager.ActiveObjectChangeManager;
			string currentRadPath = base.Workspace.CurrentRadPath;
			FileSystem.EmptyRadFile(activeObjectChangeManager, currentRadPath);
			if (publishingOption == DependencyPublishingOption.Ignore || alProjectDefinitions == null || alProjectDefinitions.Count == 0 || publishedReferences == null || publishedReferences.Count == 0)
			{
				return;
			}
			ObjectChangeModelDefinition objectChangeModelDefinition = new ObjectChangeModelDefinition();
			objectChangeModelDefinition.Added = new ObjectChangeElement[0];
			objectChangeModelDefinition.Modified = new ObjectChangeElement[0];
			objectChangeModelDefinition.Removed = new ObjectChangeElement[0];
			ObjectChangeModelDefinition value = objectChangeModelDefinition;
			PooledHashSet<ProjectDefinition> instance = PooledHashSet<ProjectDefinition>.GetInstance();
			try
			{
				foreach (ProjectModelDefinition publishedReference in publishedReferences)
				{
					instance.Add((ProjectDefinition)publishedReference);
				}
				foreach (AlProjectDefinition alProjectDefinition in alProjectDefinitions)
				{
					if (alProjectDefinition?.ProjectDependencyDefinition == null)
					{
						continue;
					}
					ProjectDefinition item = new ProjectDefinition
					{
						AppId = new Guid(alProjectDefinition.ProjectDependencyDefinition.AppId),
						Name = alProjectDefinition.ProjectDependencyDefinition.Name,
						Publisher = alProjectDefinition.ProjectDependencyDefinition.Publisher,
						Version = new System.Version(alProjectDefinition.ProjectDependencyDefinition.Version)
					};
					if (!instance.Contains(item))
					{
						continue;
					}
					string path = alProjectDefinition.Path.RadPath();
					using Stream stream = FileSystem.CreateFile(path);
					using StreamWriter textWriter = new StreamWriter(stream, Encoding.UTF8, 1024, leaveOpen: true);
					Newtonsoft.Json.JsonSerializer.Create(SymbolReferenceJsonWriter.StandardSerializerSettings).Serialize(textWriter, value);
				}
			}
			finally
			{
				instance.Free();
			}
		}

		private bool ValidateManifestDiagnostics(List<Diagnostic> manifestDiagnostics)
		{
			bool flag = false;
			foreach (Diagnostic manifestDiagnostic in manifestDiagnostics)
			{
				if (manifestDiagnostic.Severity == DiagnosticSeverity.Error)
				{
					base.Logger.Error(manifestDiagnostic.GetMessage());
					flag = true;
				}
			}
			return !flag;
		}

		private void DeleteDependencyFileIfAvailable(string packageFileName)
		{
			string fileNameWithoutExtension = Path.GetFileNameWithoutExtension(packageFileName);
			if (fileNameWithoutExtension != null && Path.GetExtension(fileNameWithoutExtension) == ".dep")
			{
				try
				{
					FileSystem.DeleteFile(packageFileName);
				}
				catch (IOException ex)
				{
					base.Logger.Exception(ex);
				}
			}
		}

		private void AddErrorResponse(int requestId, CancellationToken cancellationToken)
		{
			base.ResponseQueue.Add(ResponseFactory.ErrorResponse(new MessageError
			{
				Message = ProtocolResources.DebugAttachError
			}, "launch", requestId), cancellationToken);
		}
	}
