		private async Task StartSnapshotDebugging(string snapshotFileName, CancellationToken cancellationToken)
		{
			if (!base.FileSystem.Exists(snapshotFileName))
			{
				base.Logger.Error(string.Format(CultureInfo.CurrentCulture, ProtocolResources.DebuggerInitializationFailedWrongsnapshotFileParameter, snapshotFileName));
				base.ResponseQueue.Add(ResponseFactory.DebugAdapterTerminatedEvent(), cancellationToken);
			}
			else
			{
				InitializeDebugProject();
				await base.DebuggerService.OpenConnectionAsync(snapshotFileName, new DebuggerConnectionParameters
				{
					IsSnapshot = true
				}, base.Workspace).ConfigureAwait(continueOnCapturedContext: false);
			}
		}
