				DebugAssertHelper.AssertNotNull(request2.Tests, "Request.Tests should not be null when launching tests.");
				DebugAssertHelper.Assert(request2.Tests.Length != 0, "Request.Tests should contain at least one test when launching tests.");
				if (!serverInfo.Supports(DevApiFeature.TestRunning))
