					}, "launch", requestId), cancellationToken);
				}
				else
				{
					(bool, PublishResult) tuple = await PublishPackage(request2, requestId, serverInfo, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
					bool didPublish = tuple.Item1;
					PublishResult publishResult = tuple.Item2;
