					ClientConnectionInfo info = clientConnectionInfo;
					(bool, bool) obj = await StartDebugging(info, serverInfo, request2, requestId, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
					var (flag, _) = obj;
					if (!obj.Item2)
