						if (didPublish)
						{
							EmptyThisAndPublishedPackagesRadFiles(request2.DependencyPublishingOption, publishResult.PublishedProjectReferences, request2.ProjectReferenceDefinitions);
						}
						base.ResponseQueue.Add(ResponseFactory.EmptyResponse(requestId), cancellationToken);
						if (request2.Tests != null && request2.Tests.Length != 0)
						{
							TestPlan testPlan = RunTestHelpers.BuildTestPlan(request2.Tests);
							IHubBasedDebuggerService hubBasedDebuggerService = base.DebuggerService.Proxy as IHubBasedDebuggerService;
							string debuggingContext = string.Empty;
							if (hubBasedDebuggerService?.ConnectionContext != null && hubBasedDebuggerService.ConnectionContext.TryGetValue("debuggingcontext", out string value))
							{
								debuggingContext = value ?? string.Empty;
							}
							testRunnerService.SetupAndRunTests(connectionOptions, request2.StartupCompany ?? string.Empty, testPlan, debuggingContext, CoverageMode.None, cancellationToken).ConfigureAwait(continueOnCapturedContext: false);
						}
						if (!flag)
						{
							SendNoDebugResponseMessages(cancellationToken);
						}
					}
				}
			}).ConfigureAwait(continueOnCapturedContext: false);
		}
	}
