	[DebuggerDisplay("{ToString(), nq}")]
	internal class SnapshotLineContext : IEquatable<SnapshotLineContext>
	{
		public static readonly SnapshotLineContext Default = new SnapshotLineContext
		{
			StatementNumberCounter = SnapshotDebuggerService.UndefinedValue,
			ExecutionIndex = SnapshotDebuggerService.UndefinedValue
		};

		internal int StatementNumberCounter { get; set; }

		internal int ExecutionIndex { get; set; }

		public bool Equals(SnapshotLineContext? other)
		{
			if ((object)other == null)
			{
				return false;
			}
			if (StatementNumberCounter == other.StatementNumberCounter)
			{
				return ExecutionIndex == other.ExecutionIndex;
			}
			return false;
		}

		public override int GetHashCode()
		{
			return Hash.Combine(StatementNumberCounter.GetHashCode(), ExecutionIndex.GetHashCode());
		}

		public static bool operator ==(SnapshotLineContext left, SnapshotLineContext right)
		{
			if ((object)left != right)
			{
				return left?.Equals(right) ?? false;
			}
			return true;
		}

		public static bool operator !=(SnapshotLineContext left, SnapshotLineContext right)
		{
			return !(left == right);
		}

		public override bool Equals(object obj)
		{
			if (obj == null)
			{
				return false;
			}
			if (!(obj is SnapshotLineContext other))
			{
				return false;
			}
			return Equals(other);
		}

		public override string ToString()
		{
			return string.Format(CultureInfo.InvariantCulture, "{0}:{1}", ExecutionIndex, StatementNumberCounter);
		}
	}
