	internal enum VariableReferenceGroupIndex
	{
		Undefined,
		Globals,
		Locals,
		DatabaseStatistics
	}
	internal static class VariableReferenceHelper
	{
		public const string Globals = "Globals";

		public const string Locals = "Locals";

		public const string DatabaseStatistics = "Database Statistics";

		internal static int CreateVariableReference(VariableReferenceGroupIndex variableGroupType, ushort stackFrameIndex)
		{
			return ((ushort)variableGroupType << 16) | stackFrameIndex;
		}

		internal static VariableReferenceGroupIndex GetGroupIndexType(int variableReference)
		{
			int num = variableReference >> 16;
			if (num <= 0 || num > 3)
			{
				return VariableReferenceGroupIndex.Undefined;
			}
			return (VariableReferenceGroupIndex)num;
		}

		internal static int GetStackFrameIndex(int variableReference)
		{
			return variableReference & 0xFFFF;
		}
	}
