	public abstract class ChannelBase
	{
		public MessageReader MessageReader { get; protected set; }

		public MessageWriter MessageWriter { get; protected set; }

		public RequestDispatcher RequestDispatcher { get; protected set; }

		public ResponseDispatcher ResponseDispatcher { get; protected set; }

		public DiagnosticService DiagnosticService { get; protected set; }

		public ExplorerService ExplorerService { get; protected set; }

		internal VsCodeWorkspace Workspace { get; set; }

		public void Start(MessageProtocolType messageProtocolType, ProtocolEndpointCompletionSource completionSource, ExtensionOptions extensionOptions)
		{
			IMessageSerializer messageSerializer = ((messageProtocolType != 0) ? ((IMessageSerializer)new V8MessageSerializer()) : ((IMessageSerializer)new JsonRpcMessageSerializer()));
			Initialize(messageSerializer);
			ResponseQueue responseQueue = new ResponseQueue();
			Workspace = new VsCodeWorkspace(null, background: true, responseQueue);
			DiagnosticService = new DiagnosticService(Workspace, responseQueue, extensionOptions.DiagnosticServiceOptions);
			ExplorerService = new ExplorerService(Workspace, responseQueue);
			Workspace.ProjectClosureCompilation = DiagnosticService;
			RequestRegistry requestRegistry = RegisterHandlers(messageProtocolType, completionSource, Workspace, responseQueue, extensionOptions);
			RequestDispatcher = new RequestDispatcher(MessageReader, requestRegistry);
			ResponseDispatcher = new ResponseDispatcher(MessageWriter, responseQueue);
			ResponseDispatcher.Start();
			RequestDispatcher.Start();
		}

		public void Stop()
		{
			RequestDispatcher.Stop();
			ResponseDispatcher.Stop();
			DiagnosticService.Dispose();
			Workspace.Dispose();
			Shutdown();
		}

		protected abstract void Initialize(IMessageSerializer messageSerializer);

		protected abstract void Shutdown();

