	public class ChannelFactory
	{
		public static ChannelBase CreateChannel(ProtocolConfiguration configuration)
		{
			if (configuration.HasInputPipeHandle() && configuration.HasOutputPipeHandle())
			{
				return new PipeServerChannel(configuration.InputPipeHandle, configuration.OutputPipeHandle);
			}
			return new StdioServerChannel();
		}
	}
	internal class PipeServerChannel : ChannelBase
	{
		private readonly Stream inputStream;

		private readonly Stream outputStream;

		public PipeServerChannel(string inputPipeHandle, string outputPipeHandle)
		{
			inputStream = new AnonymousPipeClientStream(PipeDirection.In, inputPipeHandle);
			outputStream = new AnonymousPipeClientStream(PipeDirection.Out, outputPipeHandle);
		}

		protected override void Initialize(IMessageSerializer messageSerializer)
		{
			base.MessageReader = new MessageReader(inputStream, messageSerializer);
			base.MessageWriter = new MessageWriter(outputStream, messageSerializer);
		}

		protected override void Shutdown()
		{
		}
	}
	internal class StdioServerChannel : ChannelBase
	{
		private Stream inputStream;

		private Stream outputStream;

		protected override void Initialize(IMessageSerializer messageSerializer)
		{
			Console.InputEncoding = Encoding.UTF8;
			Console.OutputEncoding = Encoding.UTF8;
			inputStream = Console.OpenStandardInput();
			outputStream = Console.OpenStandardOutput();
			base.MessageReader = new MessageReader(inputStream, messageSerializer);
			base.MessageWriter = new MessageWriter(outputStream, messageSerializer);
		}

		protected override void Shutdown()
		{
		}
	}
